class AtomExecutionStatus(str, Enum):
    COMPLETED = "completed"
    INTERRUPTED = "interrupted"
    FAILED = "failed"


@dataclass(frozen=True)
class AtomExecutionOutcome:
    stage_id: str
    atom_id: str
    contract_digest: str
    role: AtomRole
    status: AtomExecutionStatus
    candidate_output: str
    candidate_decision_id: str
    action_count: int
    model_request_count: int
    protocol_rejections: int
    actions: tuple[Mapping[str, Any], ...]
    artifacts: tuple[Mapping[str, Any], ...]
    write_roots: tuple[str, ...]
    error: str
    started_at: str
    ended_at: str
    tool_selection_handoffs: tuple[Mapping[str, Any], ...] = ()
    tool_selection_decision_bindings: tuple[Mapping[str, Any], ...] = ()

    def to_dict(self) -> dict[str, Any]:
        return {
            "stage_id": self.stage_id,
            "atom_id": self.atom_id,
            "contract_digest": self.contract_digest,
            "role": self.role.value,
            "status": self.status.value,
            "candidate_output": self.candidate_output,
            "candidate_output_sha256": hashlib.sha256(
                self.candidate_output.encode("utf-8")
            ).hexdigest(),
            "candidate_decision_id": self.candidate_decision_id,
            "action_count": self.action_count,
            "model_request_count": self.model_request_count,
            "protocol_rejections": self.protocol_rejections,
            "actions": [dict(item) for item in self.actions],
            "artifacts": [dict(item) for item in self.artifacts],
            "write_roots": list(self.write_roots),
            "error": self.error,
            "started_at": self.started_at,
            "ended_at": self.ended_at,
            "tool_selection_handoffs": [
                dict(item) for item in self.tool_selection_handoffs
            ],
            "tool_selection_decision_bindings": [
                dict(item) for item in self.tool_selection_decision_bindings
            ],
        }

    def to_supervisor_dict(self) -> dict[str, Any]:
        projected_actions: list[dict[str, Any]] = []
        operation_counts: dict[str, int] = {}
        for item in self.actions:
            operation = str(item.get("operation") or "")
            operation_counts[operation] = operation_counts.get(operation, 0) + 1
        for item in self.actions[-4:]:
            result = dict(item.get("result") or {})
            output_limit = 2400 if self.role == AtomRole.FINALIZER else 800
            result_projection = project_action_result(
                result,
                operation=str(item.get("operation") or ""),
                arguments=(
                    item.get("arguments")
                    if isinstance(item.get("arguments"), Mapping)
                    else {}
                ),
                max_exact_chars=output_limit,
                structured_budget=max(1200, output_limit),
                evidence_source_limit=1,
                evidence_span_chars=min(800, output_limit),
                structured_field_budget=min(800, output_limit),
            )
            projected_actions.append(
                {
                    "action_id": str(item.get("action_id") or ""),
                    "operation": str(item.get("operation") or ""),
                    "arguments": dict(item.get("arguments") or {}),
                    "status": str(item.get("status") or ""),
                    "result": result_projection,
                    "workspace_changed": bool(item.get("workspace_changed")),
                }
            )
        candidate = (
            self.candidate_output if self.role == AtomRole.FINALIZER else ""
        )
        return {
            "stage_id": self.stage_id,
            "atom_id": self.atom_id,
            "contract_digest": self.contract_digest,
            "role": self.role.value,
            "status": self.status.value,
            "candidate_output": candidate[:3000],
            "candidate_output_sha256": hashlib.sha256(
                candidate.encode("utf-8")
            ).hexdigest(),
            "action_count": self.action_count,
            "model_request_count": self.model_request_count,
            "protocol_rejections": self.protocol_rejections,
            "tool_selection_handoff_count": len(self.tool_selection_handoffs),
            "tool_selection_decision_binding_count": len(
                self.tool_selection_decision_bindings
            ),
            "operation_counts": operation_counts,
            "recent_actions": projected_actions,
            "artifacts": [dict(item) for item in self.artifacts[-32:]],
            "write_roots": list(self.write_roots),
            "error": self.error,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "AtomExecutionOutcome":
        raw_handoffs = value.get("tool_selection_handoffs") or ()
        if not isinstance(raw_handoffs, (list, tuple)) or any(
            not isinstance(item, Mapping) for item in raw_handoffs
        ):
            raise TypeError("tool_selection_handoffs must contain objects")
        raw_bindings = value.get("tool_selection_decision_bindings") or ()
        if not isinstance(raw_bindings, (list, tuple)) or any(
            not isinstance(item, Mapping) for item in raw_bindings
        ):
            raise TypeError(
                "tool_selection_decision_bindings must contain objects"
            )
        return cls(
            stage_id=str(value.get("stage_id") or ""),
            atom_id=str(value.get("atom_id") or ""),
            contract_digest=str(value.get("contract_digest") or ""),
            role=AtomRole(str(value.get("role") or "")),
            status=AtomExecutionStatus(str(value.get("status") or "")),
            candidate_output=str(value.get("candidate_output") or ""),
            candidate_decision_id=str(value.get("candidate_decision_id") or ""),
            action_count=int(value.get("action_count", 0) or 0),
            model_request_count=int(value.get("model_request_count", 0) or 0),
            protocol_rejections=int(value.get("protocol_rejections", 0) or 0),
            actions=tuple(
                dict(item)
                for item in value.get("actions") or ()
                if isinstance(item, Mapping)
            ),
            artifacts=tuple(
                dict(item)
                for item in value.get("artifacts") or ()
                if isinstance(item, Mapping)
            ),
            write_roots=tuple(str(item) for item in value.get("write_roots") or ()),
            error=str(value.get("error") or ""),
            started_at=str(value.get("started_at") or ""),
            ended_at=str(value.get("ended_at") or ""),
            tool_selection_handoffs=tuple(
                ToolSelectionRecord.from_dict(item).to_dict()
                for item in raw_handoffs
            ),
            tool_selection_decision_bindings=tuple(
                dict(item) for item in raw_bindings
            ),
        )


def _decision_selection_id(state: RunState, decision_id: str) -> str:
    decision = state.decisions.get(decision_id)
    if decision is None:
        raise StateRecoveryError("action references a missing Executor decision")
    candidates = {decision.tool_selection_id} if decision.tool_selection_id else set()
    for checkpoint_id in (
        decision.input_checkpoint_id,
        decision.output_checkpoint_id,
    ):
        checkpoint = state.model_states.get(checkpoint_id)
        metadata = checkpoint.native_state_metadata if checkpoint else None
        selection_id = str((metadata or {}).get("tool_selection_id") or "")
        if selection_id:
            candidates.add(selection_id)
    candidates.update(
        selection.selection_id
        for selection in state.tool_selections.values()
        if selection.consumed_decision_id == decision_id
    )
    if len(candidates) > 1:
        raise StateRecoveryError(
            "Executor decision carries conflicting exact tool selection identities"
        )
    return next(iter(candidates), "")


def _project_atom_actions(state: RunState) -> tuple[Mapping[str, Any], ...]:
    """Project actions without losing the Selector→Executor decision binding."""

    projected: list[Mapping[str, Any]] = []
    for action in sorted(state.actions.values(), key=lambda item: item.sequence):
        decision = state.decisions.get(action.decision_id)
        if decision is None or not decision.accepted:
            raise StateRecoveryError(
                "executed action has no accepted Executor decision"
            )
        selection_id = _decision_selection_id(state, action.decision_id)
        selection = state.tool_selections.get(selection_id)
        if state.tool_selections and selection is None:
            raise StateRecoveryError(
                "executed action has no exact Selector decision binding"
            )
        if selection is not None and (
            selection.selected_operation != action.action_type
            or selection.atom_execution_contract_digest
            != action.atom_execution_contract_digest
            or (
                decision.selected_operation
                and decision.selected_operation != selection.selected_operation
            )
            or (
                decision.atom_execution_contract_digest
                and decision.atom_execution_contract_digest
                != selection.atom_execution_contract_digest
            )
        ):
            raise StateRecoveryError(
                "executed action differs from its exact Selector binding"
            )
        projected.append(
            {
                "action_id": action.action_id,
                "sequence": action.sequence,
                "operation": action.action_type,
                "arguments": dict(action.arguments),
                "status": action.status.value,
                "result": dict(action.result or {}),
                "decision_id": action.decision_id,
                "request_id": action.request_id,
                "selection_id": selection.selection_id if selection else "",
                "selected_operation": (
                    selection.selected_operation if selection else ""
                ),
                "contract_digest": action.atom_execution_contract_digest,
                "artifact_refs": list(action.artifact_refs),
                "workspace_changed": bool(
                    action.workspace_digest_before
                    and action.workspace_digest_after
                    and action.workspace_digest_before
                    != action.workspace_digest_after
                ),
            }
        )
    return tuple(projected)


def _project_tool_selection_decision_bindings(
    state: RunState,
) -> tuple[Mapping[str, Any], ...]:
    """Bind every consumed Selector result to its exact Executor decision."""

    actions_by_decision = {action.decision_id: action for action in state.actions.values()}
    decisions_by_selection: dict[str, list[Any]] = {}
    for decision in state.decisions.values():
        selection_id = _decision_selection_id(state, decision.decision_id)
        if selection_id:
            decisions_by_selection.setdefault(selection_id, []).append(decision)
    projected: list[Mapping[str, Any]] = []
    for selection in sorted(
        state.tool_selections.values(),
        key=lambda item: (item.created_at, item.selection_id),
    ):
        decisions = sorted(
            decisions_by_selection.get(selection.selection_id, ()),
            key=lambda item: (item.created_at, item.decision_id),
        )
        if (
            not selection.consumed_decision_id
            or selection.consumed_decision_id
            not in {item.decision_id for item in decisions}
        ):
            raise StateRecoveryError(
                "consumed exact tool selection has no Executor decision"
            )
        for attempt_index, decision in enumerate(decisions, start=1):
            action = actions_by_decision.get(decision.decision_id)
            action_expected = bool(
                decision.accepted
                and selection.selected_operation != "final_answer"
            )
            if bool(action) != action_expected:
                raise StateRecoveryError(
                    "exact tool selection decision/action lifecycle is incomplete"
                )
            if (
                decision.selected_operation
                and decision.selected_operation != selection.selected_operation
            ) or (
                decision.atom_execution_contract_digest
                and decision.atom_execution_contract_digest
                != selection.atom_execution_contract_digest
            ):
                raise StateRecoveryError(
                    "Executor decision differs from its exact Selector binding"
                )
            if action is not None and (
                action.request_id != decision.request_id
                or action.action_type != selection.selected_operation
                or action.atom_execution_contract_digest
                != selection.atom_execution_contract_digest
            ):
                raise StateRecoveryError(
                    "exact tool selection decision/action identity differs"
                )
            projected.append(
                {
                    "selection_id": selection.selection_id,
                    "selected_operation": selection.selected_operation,
                    "attempt_index": attempt_index,
                    "consumed_decision_id": decision.decision_id,
                    "selection_consumption_decision": (
                        decision.decision_id
                        == selection.consumed_decision_id
                    ),
                    "decision_request_id": decision.request_id,
                    "decision_accepted": decision.accepted,
                    "decision_command_digest": decision.command_digest,
                    "decision_raw_output_sha256": hashlib.sha256(
                        decision.raw_output.encode("utf-8")
                    ).hexdigest(),
                    "action_id": action.action_id if action is not None else "",
                    "contract_digest": selection.atom_execution_contract_digest,
                }
            )
    return tuple(projected)


class AtomWorkerPool(Protocol):
    def run_stage(
        self,
        parent_goal: GoalState,
        stage: "AtomBatch",
        atoms: Sequence[SupervisorAtom],
        *,
        max_workers: int,
        max_transitions: int,
        completed_outcomes: Mapping[str, AtomExecutionOutcome],
    ) -> tuple[AtomExecutionOutcome, ...]: ...


class AtomBatch(Protocol):
    """Only the stable identity needed by an RWKV worker pool."""

    stage_id: str
    stage_index: int


def _relative_parts(value: Any) -> tuple[str, ...]:
    raw = str(value or "").strip().replace("\\", "/")
    path = PurePosixPath(raw)
    if not raw or path.is_absolute() or ".." in path.parts or "\x00" in raw:
        raise ScopeViolation(f"atom action path is not workspace-relative: {value}")
    return tuple(part for part in path.parts if part not in {"", "."})


class ScopedAtomHarness:
    """Delegate Harness operations while enforcing one atom's declared writes."""

    operation_order_authority = "controller_capability_projection"

    def __init__(
        self,
        base: ActionHarness,
        contract: AtomExecutionContract,
        action_lock: threading.RLock,
    ) -> None:
        self.base = base
        self.contract = contract
        self._action_lock = action_lock

    def __getattr__(self, name: str) -> Any:
        return getattr(self.base, name)

    def g1i_tool_definitions(
        self,
        action_types: tuple[str, ...] | list[str] | None = None,
    ) -> list[dict[str, Any]]:
        """Expose only operations compatible with the committed atom scope."""

        requested = (
            [str(item) for item in action_types]
            if action_types is not None
            else list(self.contract.atom.allowed_operations)
        )
        allowed: list[str] = []
        for name in requested:
            if name not in self.contract.atom.allowed_operations:
                continue
            definition = self.base.definition(name)
            if not definition.side_effect:
                allowed.append(name)
                continue
            if self.contract.atom.exclusive or (
                self.contract.atom.write_roots and name in PATH_MUTATION_ARGUMENTS
            ):
                allowed.append(name)
        return self.base.g1i_tool_definitions(allowed)

    @contextmanager
    def action_transaction(self, goal: GoalState):
        self._validate_goal_binding(goal)
        with self._action_lock:
            yield

    def execute(self, action: TaskAction, goal: GoalState):
        self._validate_goal_binding(goal)
        if action.action_type not in self.contract.atom.allowed_operations:
            raise ScopeViolation(
                f"atom {self.contract.atom.atom_id} attempted operation "
                f"{action.action_type!r} outside its Planner allowset"
            )
        definition = self.base.definition(action.action_type)
        if definition.side_effect:
            self._validate_mutation(action)
        return self.base.execute(action, goal)

    def _validate_mutation(self, action: TaskAction) -> None:
        argument_names = PATH_MUTATION_ARGUMENTS.get(action.action_type)
        if not argument_names:
            if self.contract.atom.exclusive:
                return
            raise ScopeViolation(
                f"atom {self.contract.atom.atom_id} must be exclusive for side-effecting "
                f"operation {action.action_type}"
            )
        if not self.contract.atom.write_roots:
            raise ScopeViolation(
                f"read-only atom {self.contract.atom.atom_id} attempted "
                f"{action.action_type}"
            )
        for argument_name in argument_names:
            target = _relative_parts(action.arguments.get(argument_name))
            allowed = any(
                path_is_within(target, root)
                for root in self.contract.atom.write_roots
            )
            if (
                not allowed
                and action.action_type == "make_directory"
                and target
            ):
                allowed = any(
                    tuple(PurePosixPath(root).parts)[: len(target)] == target
                    for root in self.contract.atom.write_roots
                    if root != "."
                )
            if not allowed:
                raise ScopeViolation(
                    f"atom {self.contract.atom.atom_id} attempted to mutate "
                    f"{argument_name}={action.arguments.get(argument_name)!r} outside "
                    f"write_roots={list(self.contract.atom.write_roots)!r}"
                )

    def _validate_goal_binding(self, goal: GoalState) -> None:
        binding = AtomExecutionBinding.from_goal(goal, required=True)
        if binding is None or (
            binding.contract.contract_digest != self.contract.contract_digest
        ):
            raise ScopeViolation(
                "Harness Goal execution contract differs from its scoped atom contract"
            )


ModelFactory = Callable[[AtomExecutionContract, ScopedAtomHarness], LongHorizonModel]


class ThreadedRWKVAtomPool:
    """Run ready atoms in isolated workspaces and commit only completed writes."""

    def __init__(
        self,
        root: str | Path,
        *,
        harness: ActionHarness,
        model_factory: ModelFactory,
    ) -> None:
        self.root = Path(root).resolve()
        self.root.mkdir(parents=True, exist_ok=True)
        self.harness = harness
        self.model_factory = model_factory
        self._workspace_lock = threading.RLock()

    def run_stage(
        self,
        parent_goal: GoalState,
        stage: AtomBatch,
        atoms: Sequence[SupervisorAtom],
        *,
        max_workers: int,
        max_transitions: int,
        completed_outcomes: Mapping[str, AtomExecutionOutcome],
    ) -> tuple[AtomExecutionOutcome, ...]:
        selected = tuple(atoms)
        if not selected:
            return ()
        workers = min(max(1, int(max_workers)), len(selected))
        outcomes: dict[str, AtomExecutionOutcome] = {}
        contracts = {
            atom.atom_id: AtomExecutionContract.create(
                immutable_request=parent_goal.request,
                atom=atom,
            )
            for atom in selected
        }
        atom_workspaces = {
            atom.atom_id: self._prepare_atom_workspace(
                parent_goal,
                stage,
                contracts[atom.atom_id],
            )
            for atom in selected
        }
        with ThreadPoolExecutor(
            max_workers=workers,
            thread_name_prefix=f"rwkv-atom-{stage.stage_index}",
        ) as executor:
            futures = {
                executor.submit(
                    self._run_atom,
                    parent_goal,
                    stage,
                    contracts[atom.atom_id],
                    atom_workspaces[atom.atom_id],
                    completed_outcomes,
                    max_transitions=max_transitions,
                ): atom
                for atom in selected
            }
            for future in as_completed(futures):
                atom = futures[future]
                try:
                    outcome = future.result()
                except BaseException as exc:
                    if getattr(exc, "rwkv_lh_process_loss", False):
                        raise
                    now = utc_now()
                    outcome = AtomExecutionOutcome(
                        stage_id=stage.stage_id,
                        atom_id=atom.atom_id,
                        contract_digest=(
                            contracts[atom.atom_id].contract_digest
                        ),
                        role=atom.role,
                        status=AtomExecutionStatus.FAILED,
                        candidate_output="",
                        candidate_decision_id="",
                        action_count=0,
                        model_request_count=0,
                        protocol_rejections=0,
                        actions=(),
                        artifacts=(),
                        write_roots=atom.write_roots,
                        error=f"{type(exc).__name__}: {exc}"[:2000],
                        started_at=now,
                        ended_at=now,
                    )
                outcomes[atom.atom_id] = outcome
        return tuple(outcomes[atom.atom_id] for atom in selected)

    def _run_atom(
        self,
        parent_goal: GoalState,
        stage: AtomBatch,
        contract: AtomExecutionContract,
        atom_workspace: Path,
        completed_outcomes: Mapping[str, AtomExecutionOutcome],
        *,
        max_transitions: int,
    ) -> AtomExecutionOutcome:
        scoped_harness = ScopedAtomHarness(
            self.harness,
            contract,
            threading.RLock(),
        )
        model = self.model_factory(contract, scoped_harness)
        try:
            return self._run_atom_with_model(
                model,
                scoped_harness,
                parent_goal,
                stage,
                contract,
                atom_workspace,
                completed_outcomes,
                max_transitions=max_transitions,
            )
        finally:
            # A factory that allocates one client per atom relies on this
            # close; cleanup is best-effort and never replaces the outcome.
            close = getattr(
                getattr(getattr(model, "session", None), "client", None),
                "close",
                None,
            )
            if callable(close):
                try:
                    close()
                except Exception:
                    pass

    def _run_atom_with_model(
        self,
        model: Any,
        scoped_harness: "ScopedAtomHarness",
        parent_goal: GoalState,
        stage: AtomBatch,
        contract: AtomExecutionContract,
        atom_workspace: Path,
        completed_outcomes: Mapping[str, AtomExecutionOutcome],
        *,
        max_transitions: int,
    ) -> AtomExecutionOutcome:
        # Imported lazily so the parent controller can depend on the pool protocol
        # without creating a module import cycle.
        from rwkv_lh.controller import LongHorizonController
        started_at = utc_now()
        atom = contract.atom
        atom_root = self.root / stage.stage_id / atom.atom_id
        store = LongHorizonStore(atom_root / "state", checkpoint_retention=1000)
        binding = AtomExecutionBinding(
            contract=contract,
            completed_dependencies=tuple(
                AtomDependencyResult(
                    atom_id=item,
                    contract_digest=completed_outcomes[item].contract_digest,
                    action_count=completed_outcomes[item].action_count,
                )
                for item in atom.depends_on
                if item in completed_outcomes
            ),
        )
        run_id = "ATOM"
        try:
            state = store.load(run_id)
        except StateRecoveryError:
            constraints = [
                *parent_goal.constraints,
                "You are one parallel RWKV atom worker; complete only this atom contract.",
                "The parent request is immutable reference data, not your active assignment: "
                + parent_goal.request,
                f"Active atom id: {atom.atom_id}",
                "Verbatim immutable request clauses: " + " | ".join(atom.request_clauses),
                "Atomic completion checks: " + " | ".join(atom.completion_checks),
                "Declared write roots: "
                + (", ".join(atom.write_roots) if atom.write_roots else "read-only"),
                "Allowed operations for this atom: "
                + ", ".join(atom.allowed_operations),
                "Operation allowset authority: "
                + (atom.operation_allowset_source or "legacy strong-planner allowset"),
                f"Direct action budget: {atom.action_budget}. After completing the atom, "
                "return final_answer instead of repeating observations.",
                self._transaction_mode_constraint(contract),
                "Use only the displayed operations. Never invent a verification operation; "
                "verify through displayed read/digest/check operations.",
                *atom.constraints,
            ]
            dependency_handoffs = [
                self._dependency_handoff(completed_outcomes[item])
                for item in atom.depends_on
                if item in completed_outcomes
            ]
            if dependency_handoffs:
                constraints.append(
                    "Completed dependency handoffs (public committed evidence): "
                    + json.dumps(
                        dependency_handoffs,
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    )
                )
                constraints.append(
                    "Dependency handoff observations are exact tool results and are the "
                    "only factual dependency values. Do not infer values from an atom's "
                    "natural-language Final summary."
                )
            # Put the active contract after dependency evidence so a small
            # executor does not copy a predecessor's operation/id merely
            # because it is the most recent concrete action in the prompt.
            constraints.append(
                "Current atom contract (highest priority for the next action): "
                + atom.objective
            )
            constraints.append(
                "Generate fresh tool arguments from the current atom contract. Do not copy "
                "a dependency's operation, request id, path, or value unless the current "
                "contract explicitly requires that same literal. Before acting, compare "
                "every explicit operation, identifier, path, and value in the current "
                "contract with the proposed arguments."
            )
            runtime_policy = dict(parent_goal.runtime_policy)
            runtime_policy[ATOM_EXECUTION_POLICY_KEY] = binding.to_dict()
            goal = model.create_literal_goal(
                atom.objective,
                str(atom_workspace),
                constraints=constraints,
                runtime_policy=runtime_policy,
            )
            state = store.create_run(goal, run_id)
        persisted_binding = AtomExecutionBinding.from_goal(
            state.goal,
            required=True,
        )
        if persisted_binding != binding:
            raise ValueError(
                "persisted atom execution binding differs from the dispatched contract"
            )
        controller = LongHorizonController(
            store,
            model=model,
            harness=scoped_harness,
            max_transitions=max_transitions,
        )
        result = controller.run(run_id)
        state = result.state
        status = (
            AtomExecutionStatus.COMPLETED
            if state.status == RunStatus.COMPLETED
            else AtomExecutionStatus.FAILED
            if state.status == RunStatus.FAILED
            else AtomExecutionStatus.INTERRUPTED
        )
        actions = _project_atom_actions(state)
        transaction_error = self._transaction_integrity_error(contract, actions)
        if status == AtomExecutionStatus.COMPLETED and transaction_error:
            status = AtomExecutionStatus.INTERRUPTED
        artifacts = tuple(
            {
                "artifact_id": artifact.artifact_id,
                "action_id": artifact.action_id,
                "path": artifact.path,
                "sha256": artifact.sha256,
                "media_type": artifact.media_type,
                "size_bytes": artifact.size_bytes,
                "summary": artifact.summary,
            }
            for artifact in state.artifacts.values()
        )
        error = ""
        if transaction_error:
            error = transaction_error
        elif status != AtomExecutionStatus.COMPLETED:
            error = str((state.errors[-1] if state.errors else {}).get("message") or "")
        elif atom.write_roots or atom.exclusive:
            self._commit_atom_workspace(
                Path(parent_goal.workspace_root).resolve(),
                atom_workspace,
                contract,
            )
        return AtomExecutionOutcome(
            stage_id=stage.stage_id,
            atom_id=atom.atom_id,
            contract_digest=contract.contract_digest,
            role=atom.role,
            status=status,
            candidate_output=result.final_output,
            candidate_decision_id=state.final_decision_id,
            action_count=len(actions),
            model_request_count=len(state.temp_decisions),
            protocol_rejections=state.protocol_rejections,
            actions=actions,
            artifacts=artifacts,
            write_roots=contract.atom.write_roots,
            error=error,
            started_at=started_at,
            ended_at=utc_now(),
            tool_selection_handoffs=tuple(
                selection.to_dict()
                for selection in sorted(
                    state.tool_selections.values(),
                    key=lambda item: (item.created_at, item.selection_id),
                )
            ),
            tool_selection_decision_bindings=(
                _project_tool_selection_decision_bindings(state)
            ),
        )

    @staticmethod
    def _transaction_mode_constraint(contract: AtomExecutionContract) -> str:
        if contract.atom.action_budget == 1:
            mode = (
                "Transaction mode: single action. Complete the one direct action, then "
                "return final_answer."
            )
        else:
            mode = (
                "Transaction mode: bounded multi-operation. Keep one RWKV state; "
                f"complete {contract.minimum_actions}-"
                f"{contract.atom.action_budget} direct actions and continue "
                "until the completion checks pass or the action budget is exhausted."
            )
        if contract.atom.write_roots and (
            set(contract.atom.allowed_operations) & PATH_MUTATION_OPERATIONS
        ):
            mode += (
                " Before final_answer, successful path mutations must cover every "
                "declared write root."
            )
        return mode

    @staticmethod
    def _transaction_integrity_error(
        contract: AtomExecutionContract,
        actions: tuple[Mapping[str, Any], ...],
    ) -> str:
        """Compatibility surface backed by the one canonical progress function."""

        return contract_integrity_error(contract, actions)

    def _prepare_atom_workspace(
        self,
        parent_goal: GoalState,
        stage: AtomBatch,
        contract: AtomExecutionContract,
    ) -> Path:
        parent_workspace = Path(parent_goal.workspace_root).resolve()
        atom_workspace = (
            self.root / stage.stage_id / contract.atom.atom_id / "workspace"
        ).resolve()
        if atom_workspace == parent_workspace or atom_workspace.is_relative_to(
            parent_workspace
        ) or parent_workspace.is_relative_to(atom_workspace):
            raise ValueError(
                "atom snapshot and authoritative workspace must not overlap"
            )
        with self._workspace_lock:
            if atom_workspace.exists():
                return atom_workspace
            atom_workspace.parent.mkdir(parents=True, exist_ok=True)
            shutil.copytree(
                parent_workspace,
                atom_workspace,
            )
        return atom_workspace

    @staticmethod
    def _dependency_handoff(outcome: AtomExecutionOutcome) -> dict[str, Any]:
        """Project committed dependency facts without replaying action choices.

        A dependent worker needs the predecessor's observed values and artifact
        identities, not the concrete operation/argument envelope that produced
        them.  Replaying that envelope creates a recency prior which can make a
        small persistent executor copy the predecessor's tool instead of acting
        on its own atom contract.
        """

        observations: list[dict[str, Any]] = []
        for item in outcome.actions[-4:]:
            result = dict(item.get("result") or {})
            projected = project_action_result(
                result,
                operation=str(item.get("operation") or ""),
                arguments=(
                    item.get("arguments")
                    if isinstance(item.get("arguments"), Mapping)
                    else {}
                ),
                max_exact_chars=800,
                structured_budget=1200,
                evidence_source_limit=1,
                evidence_span_chars=256,
                structured_field_budget=400,
            )
            result_artifacts = [
                {
                    "path": str(artifact.get("path") or ""),
                    "sha256": str(artifact.get("sha256") or ""),
                    "size_bytes": int(artifact.get("size_bytes", 0) or 0),
                    "media_type": str(artifact.get("media_type") or ""),
                }
                for artifact in result.get("artifacts") or ()
                if isinstance(artifact, Mapping)
            ]
            observations.append(
                {
                    "success": bool(result.get("success")),
                    "result_projection": projected,
                    "source_artifacts": result_artifacts[:8],
                    "full_result_digest": canonical_digest(result),
                    "full_result_persisted": True,
                }
            )
        return {
            "atom_id": outcome.atom_id,
            "status": outcome.status.value,
            "observations": observations,
            "artifacts": [
                {
                    "path": str(item.get("path") or ""),
                    "sha256": str(item.get("sha256") or ""),
                    "size_bytes": int(item.get("size_bytes", 0) or 0),
                    "media_type": str(item.get("media_type") or ""),
                }
                for item in outcome.artifacts[-8:]
            ],
        }

    def _commit_atom_workspace(
        self,
        parent_workspace: Path,
        atom_workspace: Path,
        contract: AtomExecutionContract,
    ) -> None:
        parent_workspace = parent_workspace.resolve()
        atom_workspace = atom_workspace.resolve()
        if parent_workspace == atom_workspace:
            raise ValueError(
                "an atom snapshot cannot be the authoritative workspace"
            )
        if contract.atom.exclusive:
            self._commit_exclusive_snapshot(parent_workspace, atom_workspace)
            return
        with self._workspace_lock:
            for root in contract.atom.write_roots:
                if root == ".":
                    for child in list(parent_workspace.iterdir()):
                        self._remove_path(child)
                    for child in atom_workspace.iterdir():
                        self._copy_path(child, parent_workspace / child.name)
                    continue
                parts = _relative_parts(root)
                source = atom_workspace.joinpath(*parts)
                target = parent_workspace.joinpath(*parts)
                self._remove_path(target)
                if source.exists() or source.is_symlink():
                    self._copy_path(source, target)

    def _commit_exclusive_snapshot(
        self,
        parent_workspace: Path,
        atom_workspace: Path,
    ) -> None:
        """Replace the authoritative workspace only after an exclusive success.

        Exclusive operations such as ``run_command`` can mutate undeclared paths.
        They therefore run in a complete snapshot.  A successful snapshot is
        staged beside the parent and swapped in with a recoverable backup; failed
        or interrupted snapshots never reach this method.
        """

        if not parent_workspace.is_dir() or not atom_workspace.is_dir():
            raise ValueError("exclusive commit requires two existing directories")
        if atom_workspace.is_relative_to(
            parent_workspace
        ) or parent_workspace.is_relative_to(atom_workspace):
            raise ValueError(
                "exclusive snapshot and authoritative workspace must not overlap"
            )
        with self._workspace_lock:
            transaction_root = Path(
                tempfile.mkdtemp(
                    prefix=".rwkv-lh-exclusive-commit-",
                    dir=str(parent_workspace.parent),
                )
            )
            replacement = transaction_root / "replacement"
            backup = transaction_root / "backup"
            try:
                shutil.copytree(atom_workspace, replacement)
                parent_workspace.rename(backup)
                try:
                    replacement.rename(parent_workspace)
                except BaseException:
                    backup.rename(parent_workspace)
                    raise
            finally:
                # If restoration itself failed, preserve the transaction directory
                # and its backup for manual recovery instead of deleting evidence.
                if parent_workspace.exists():
                    shutil.rmtree(transaction_root, ignore_errors=True)

    @staticmethod
    def _remove_path(path: Path) -> None:
        if path.is_symlink() or path.is_file():
            path.unlink(missing_ok=True)
        elif path.is_dir():
            shutil.rmtree(path)

    @staticmethod
    def _copy_path(source: Path, target: Path) -> None:
        target.parent.mkdir(parents=True, exist_ok=True)
        if source.is_dir() and not source.is_symlink():
            shutil.copytree(source, target)
        else:
            shutil.copy2(source, target, follow_symlinks=False)


__all__ = [
    "AtomBatch",
    "AtomExecutionOutcome",
    "AtomExecutionStatus",
    "AtomWorkerPool",
    "PATH_MUTATION_OPERATIONS",
    "ScopedAtomHarness",
    "ThreadedRWKVAtomPool",
]

rwkv_lh/operation_contracts.py:
"""Authoritative structural contracts shared by Harness and Selector feedback."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from dataclasses import dataclass


JSON_PATH_OPERATIONS = frozenset({"read_json", "write_json", "patch_json"})
TEXT_PATH_OPERATIONS = frozenset(
    {"read_file", "write_file", "replace_text", "remove_line", "append_file"}
)

WORKSPACE_TARGET_KINDS = frozenset(
    {
        "directory",
        "json_file",
        "text_file",
        "binary_file",
        "large_file",
        "missing",
        "other",
    }
)
# Content classifications are hints. Eligibility uses filesystem structure;
# parsing, encoding and mutation-specific conditions remain Harness outcomes.
_FILE_TARGET_KINDS = frozenset({"json_file", "text_file", "binary_file", "large_file"})
_CREATABLE_FILE_KINDS = frozenset({"missing", *_FILE_TARGET_KINDS})
_PATH_KINDS = {
    "list_directory": {"path": frozenset({"directory"})},
    "search_text": {"path": frozenset({"directory", *_FILE_TARGET_KINDS})},
    **{operation: {"path": _FILE_TARGET_KINDS} for operation in (
        "read_file", "read_json", "file_digest", "patch_json", "replace_text",
        "remove_line", "bind_evidence",
    )},
    **{operation: {"path": _CREATABLE_FILE_KINDS} for operation in (
        "write_file", "write_json", "append_file",
    )},
    "make_directory": {"path": frozenset({"missing", "directory"})},
    **{operation: {"source": _FILE_TARGET_KINDS, "destination": _CREATABLE_FILE_KINDS}
       for operation in ("copy_file", "move_file")},
    "delete_file": {"path": frozenset({"missing", "directory", *_FILE_TARGET_KINDS})},
}


@dataclass(frozen=True)
class PathArgumentContract:
    accepted_kinds: frozenset[str]
    access: str


# One declaration owns structural preconditions AND filesystem effects.
# All downstream projections, including Harness mutation accounting, derive here.
PATH_ARGUMENT_CONTRACTS = {
    operation: {
        name: PathArgumentContract(kinds,
            "read_write" if operation == "move_file" and name == "source"
            else "read" if operation in {"list_directory", "search_text", "read_file",
                "read_json", "file_digest", "bind_evidence"} or name == "source"
            else "write")
        for name, kinds in arguments.items()
    } for operation, arguments in _PATH_KINDS.items()
}
OPERATION_TARGET_ARGUMENTS = {op: tuple(args) for op, args in PATH_ARGUMENT_CONTRACTS.items()}
PATH_MUTATION_ARGUMENTS = {
    op: tuple(name for name, contract in args.items() if contract.access != "read")
    for op, args in PATH_ARGUMENT_CONTRACTS.items()
    if any(contract.access != "read" for contract in args.values())
}
PATH_MUTATION_OPERATIONS = frozenset(PATH_MUTATION_ARGUMENTS)
DISTINCT_PATH_ARGUMENTS = {operation: ("source", "destination") for operation in ("copy_file", "move_file")}


def path_within_roots(path: str, roots: Sequence[str]) -> bool:
    parts = tuple(p for p in str(path).replace("\\", "/").split("/") if p not in {"", "."})
    if ".." in parts or str(path).startswith("/"):
        return False
    for root in roots:
        parent = tuple(p for p in str(root).replace("\\", "/").split("/") if p not in {"", "."})
        if ".." not in parent and (not parent or parts[:len(parent)] == parent):
            return True
    return False


def project_argument_targets(*, operations: Sequence[str], roots: Sequence[str],
                             scope_roots: Sequence[str], descriptors: Sequence[Mapping],
                             discovery_complete: bool) -> dict:
    """Express each parameter independently; unknown discovery never proves absence."""
    result = {}
    for operation in operations:
        arguments = {}
        for name, spec in PATH_ARGUMENT_CONTRACTS.get(operation, {}).items():
            scope = (tuple(scope_roots) if spec.access == "read_write" else (".",)
                     if name == "source" else tuple(roots) or (".",))
            visible = [item for item in descriptors if path_within_roots(item["path"], scope)]
            candidates = list(compatible_target_paths(operation, visible, argument_name=name))
            directories = [item["path"] for item in visible if item["target_kind"] == "directory"]
            creatable = directories if "missing" in spec.accepted_kinds else []
            # Unexpanded/omitted directories may contain a usable path. A known
            # missing file, in contrast, is fully observed even if another scope is not.
            complete = discovery_complete or (not directories and bool(visible))
            arguments[name] = {"access": spec.access, "scope_roots": list(scope),
                "compatible_paths": candidates, "creatable_roots": creatable,
                "discovery_complete": complete,
                "availability": "available" if candidates or creatable else "unavailable" if complete else "unknown"}
        result[operation] = arguments
    return result


def eligible_target_operations(argument_targets: Mapping) -> tuple[str, ...]:
    selected = []
    for operation, arguments in argument_targets.items():
        if any(item["availability"] == "unavailable" for item in arguments.values()):
            continue
        pair = DISTINCT_PATH_ARGUMENTS.get(operation)
        if pair:
            left, right = (arguments[name] for name in pair)
            if (not left["creatable_roots"] and not right["creatable_roots"]
                and left["discovery_complete"] and right["discovery_complete"]
                and len(set(left["compatible_paths"]) | set(right["compatible_paths"])) < 2):
                continue
        selected.append(operation)
    return tuple(selected)


def summarize_operation_targets(argument_targets: Mapping) -> dict:
    """Selector needs preconditions and effects, not every possible argument."""
    return {op: {name: {"access": item["access"], "scope_roots": list(item["scope_roots"]),
        "availability": item["availability"], "compatible_path_count": len(item["compatible_paths"]),
        "creatable_root_count": len(item["creatable_roots"]), "discovery_complete": item["discovery_complete"]}
        for name, item in args.items()} for op, args in argument_targets.items()}


def operation_accepts_target_kind(
    operation: str,
    target_kind: str,
    *,
    argument_name: str = "path",
) -> bool:
    """Return the frozen Harness-level operation/target compatibility fact."""

    selected_operation = str(operation or "").strip()
    selected_kind = str(target_kind or "").strip()
    if selected_kind not in WORKSPACE_TARGET_KINDS:
        raise ValueError(f"unsupported workspace target kind: {selected_kind!r}")
    argument_contract = PATH_ARGUMENT_CONTRACTS.get(selected_operation)
    if argument_contract is None:
        return True
    allowed = argument_contract.get(str(argument_name or "").strip())
    return allowed is not None and selected_kind in allowed.accepted_kinds


def compatible_target_paths(
    operation: str,
    descriptors: Sequence[dict[str, object]],
    *,
    argument_name: str = "path",
) -> tuple[str, ...]:
    """Project typed Harness descriptors to compatible path candidates."""

    return tuple(
        dict.fromkeys(
            str(item.get("path") or "")
            for item in descriptors
            if str(item.get("path") or "")
            and operation_accepts_target_kind(
                operation,
                str(item.get("target_kind") or ""),
                argument_name=argument_name,
            )
        )
    )

# Planner steps declare only one coarse responsibility.  The Controller uses
# these fixed families to compile a smaller Selector menu without choosing the
# concrete operation on the model's behalf.
GOAL_STEP_PHASES = (
    "observe",
    "mutate",
    "execute",
    "derive_evidence",
)
LOCAL_OBSERVE_OPERATIONS = frozenset(
    {"list_directory", "search_text", "read_file", "read_json", "file_digest"}
)
EXTERNAL_OBSERVE_OPERATIONS = frozenset({"web_search", "connector_lookup"})
GOAL_STEP_PHASE_OPERATIONS: dict[str, frozenset[str]] = {
    "observe": LOCAL_OBSERVE_OPERATIONS | EXTERNAL_OBSERVE_OPERATIONS,
    "mutate": PATH_MUTATION_OPERATIONS,
    "execute": frozenset({"check_command", "run_command"}),
    "derive_evidence": frozenset(
        {"bind_evidence", "calculator", "date_diff", "current_time"}
    ),
}


def project_goal_step_operations(
    *,
    authorized_operations: Sequence[str],
    phase: str,
    read_roots: Sequence[str] = (),
    write_roots: Sequence[str] = (),
) -> tuple[str, ...]:
    """Apply the production Goal-step phase boundary without choosing a tool.

    The Controller and StateTune data builder must share this function.  It
    narrows the policy-authorized Harness registry to one responsibility
    family while preserving the caller's authoritative class order.
    """

    selected_phase = str(phase or "").strip()
    if selected_phase not in GOAL_STEP_PHASE_OPERATIONS:
        raise ValueError(f"unsupported Goal step phase: {selected_phase!r}")
    family = GOAL_STEP_PHASE_OPERATIONS[selected_phase]
    if selected_phase == "observe":
        family = LOCAL_OBSERVE_OPERATIONS if read_roots else EXTERNAL_OBSERVE_OPERATIONS
    elif selected_phase == "execute":
        family = frozenset({"run_command" if write_roots else "check_command"})
    return tuple(
        operation
        for operation in dict.fromkeys(str(item) for item in authorized_operations)
        if operation in family
    )


__all__ = [
    "GOAL_STEP_PHASES",
    "GOAL_STEP_PHASE_OPERATIONS",
    "EXTERNAL_OBSERVE_OPERATIONS",
    "JSON_PATH_OPERATIONS",
    "LOCAL_OBSERVE_OPERATIONS",
    "PATH_MUTATION_ARGUMENTS",
    "PATH_MUTATION_OPERATIONS",
    "OPERATION_TARGET_ARGUMENTS",
    "TEXT_PATH_OPERATIONS",
    "WORKSPACE_TARGET_KINDS",
    "compatible_target_paths",
    "operation_accepts_target_kind",
    "project_goal_step_operations",
]

rwkv_lh/read_only_agent.py:
"""Read-only execution using the production controller and original model answers."""
from dataclasses import dataclass
from pathlib import Path
import json
import hashlib
import math
import signal
import shutil
import threading
import time
import traceback

from .controller import LongHorizonController
from .harness import ActionHarness
from .model import LongHorizonModel
from .model_session import create_model_session
from .run_lifecycle import RUN_LIFECYCLE_POLICY_KEY, run_lifecycle_policy_document
from .schema import RunStatus, RunState
from .store import LongHorizonStore


@dataclass(frozen=True)
class ReadOnlyJob:
    task_id: str
    request: str
    workspace: str
    output_dir: str
    max_calls: int = 6
    max_seconds: float = 300
    tool_scope: str = 'files'
    reconsider_from: str = ''
    advice: str = ''
    advice_model: str = ''


class ReadOnlyHarness(ActionHarness):
    def __init__(self, *args, tool_scope='inspect', **kwargs):
        if tool_scope not in ('files', 'inspect'):
            raise ValueError('unknown read-only tool scope')
        super().__init__(*args, **kwargs)
        self.tool_scope = tool_scope

    def g1i_tool_definitions(self, action_types=None):
        return [item for item in super().g1i_tool_definitions(action_types)
                if self.definition(item['name']).read_only
                and not self.definition(item['name']).side_effect
                and (self.tool_scope == 'inspect' or item['name'] == 'read_file')]


class ReadOnlyBudgetExpired(TimeoutError):
    def __init__(self, message, reason='generation_budget_exhausted'):
        super().__init__(message)
        self.reason = reason


class _WallDeadlineExpired(BaseException):
    """Do not let protocol recovery or best-effort audit hooks swallow a deadline."""


class _BudgetedSession:
    def __init__(self, session, limit, deadline, audit_errors=()):
        self.session, self.limit, self.deadline = session, limit, deadline
        self.audit_errors = audit_errors
        self.calls = 0

    def __getattr__(self, name):
        return getattr(self.session, name)

    def generate(self, *args, **kwargs):
        if self.audit_errors:
            raise OSError('model trace persistence failed; generation stopped')
        if self.calls >= self.limit:
            raise ReadOnlyBudgetExpired('generation budget exhausted')
        if time.monotonic() >= self.deadline:
            raise ReadOnlyBudgetExpired('wall budget exhausted', 'wall_budget_exhausted')
        self.calls += 1
        return self.session.generate(*args, **kwargs)


class _ReadOnlyController(LongHorizonController):
    def _execute_decision(self, state, decision):
        definition = self.harness.definition(decision.command.name)
        if not definition.read_only or definition.side_effect:
            raise PermissionError('operation outside read-only permissions')
        if decision.command.name not in {d['name'] for d in self.harness.g1i_tool_definitions()}:
            raise PermissionError('operation outside selected read-only scope')
        return super()._execute_decision(state, decision)


def _save(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n')


def _prepare_reconsideration(job, workspace, output):
    previous = Path(job.reconsider_from).resolve(strict=True)
    raw_result = (previous / 'RESULT.json').read_bytes()
    result = json.loads(raw_result)
    snapshot = (previous / 'state_snapshot.json').read_bytes()
    state = RunState.from_dict(json.loads(snapshot))
    if result.get('tool_scope') != 'files' or job.tool_scope != 'files':
        raise ValueError('requested advice currently supports file-reading tasks only')
    if state.goal.request != job.request or Path(state.goal.workspace_root).resolve() != workspace:
        raise ValueError('advice cannot silently change the task or workspace')
    if (state.final_output or None) != result.get('final'):
        raise ValueError('parent answer and State do not agree')
    parent = state.lane_head('executor')
    if not parent:
        raise ValueError('no parent model State to continue')
    for action in state.actions.values():
        value = action.result or {}
        chunk = value.get('metadata', {}).get('chunk', {})
        if action.action_type == 'read_file' and value.get('success'):
            path = (workspace / chunk['source_ref']).resolve(strict=True)
            if not path.is_relative_to(workspace) or hashlib.sha256(path.read_bytes()).hexdigest() != chunk['source_sha256']:
                raise ValueError('source changed since the parent observation')
    # A finished job is immutable. Copy its local store and retain the original
    # model history separately; the new trace contains only the extra calls.
    shutil.copytree(previous / 'state', output / 'state')
    ancestor_trace = previous / 'PARENT_TRACE.jsonl'
    history = ancestor_trace.read_bytes() if ancestor_trace.exists() else b''
    (output / 'PARENT_TRACE.jsonl').write_bytes(
        history + (previous / 'model_trace.jsonl').read_bytes()
    )
    (output / 'PARENT_RESULT.json').write_bytes(raw_result)
    (output / 'PARENT_STATE_SNAPSHOT.json').write_bytes(snapshot)
    store = LongHorizonStore(output / 'state', checkpoint_retention=1000)
    copied = store.load(state.run_id)
    if copied.to_dict() != state.to_dict():
        raise ValueError('parent store is not the recorded immutable snapshot')
    info = {'directory': str(previous), 'result_sha256': hashlib.sha256(raw_result).hexdigest(),
            'state_sha256': hashlib.sha256(snapshot).hexdigest(), 'parent_checkpoint_id': parent,
            'parent_final_decision_id': state.final_decision_id,
            'parent_generation_started': result['generation_started'],
            'parent_elapsed_seconds': result['elapsed_seconds'], 'advice_model': job.advice_model}
    _save(output / 'CONTINUATION.json', info)
    return store, copied, info


def run_read_only_job(job, *, settings, session_factory=create_model_session):
    return _run_job(job, settings=settings, session_factory=session_factory,
                    harness_factory=lambda: ReadOnlyHarness(tool_scope=job.tool_scope),
                    controller_type=_ReadOnlyController, allowed_scopes=('files', 'inspect'))


def _run_job(job, *, settings, session_factory, harness_factory, controller_type, allowed_scopes,
             prepare_state=None, before_run=None):
    """Shared production execution and evidence collection; callers set tool permissions."""
    if (type(job.max_calls) is not int or job.max_calls < 1
            or type(job.max_seconds) not in (int, float)
            or not math.isfinite(job.max_seconds) or job.max_seconds <= 0):
        raise ValueError('positive integer calls and finite positive wall budget required')
    if job.tool_scope not in allowed_scopes:
        raise ValueError('unknown read-only tool scope or execution scope')
    advice_fields = (job.reconsider_from, job.advice, job.advice_model)
    if any(advice_fields) and not all(advice_fields):
        raise ValueError('reconsideration requires explicit advice and its model identity')
    if threading.current_thread() is not threading.main_thread():
        raise ValueError('run each job in a process main thread for deadline handling')
    workspace = Path(job.workspace).resolve(strict=True)
    if not workspace.is_dir():
        raise ValueError('workspace must be a directory')
    output = Path(job.output_dir).resolve()
    if job.reconsider_from:
        previous = Path(job.reconsider_from).resolve(strict=True)
        if previous == output or previous in output.parents or output in previous.parents:
            raise ValueError('reconsideration output must not overlap the parent run')
    if output == workspace or workspace in output.parents:
        raise ValueError('audit output must be outside the model workspace')
    output.mkdir(parents=True, exist_ok=False)
    records = []
    audit_errors = []
    trace_path = output / 'model_trace.jsonl'
    trace_path.touch(exist_ok=False)
    def audit(event):
        records.append(dict(event))
        try:
            with trace_path.open('a') as stream:
                stream.write(json.dumps(dict(event), ensure_ascii=False) + '\n')
        except Exception as exc:
            audit_errors.append({'event_type': event.get('type'), 'error': str(exc)})
            raise
    started = time.monotonic()
    state = None
    store = None
    continuation = None
    error = None
    termination = None
    termination_reason = None
    initial_causal_count = 0
    def deadline(signum, frame):
        raise _WallDeadlineExpired('wall budget exhausted')
    old_handler = signal.signal(signal.SIGALRM, deadline)
    old_timer = signal.setitimer(signal.ITIMER_REAL, job.max_seconds)
    try:
        if prepare_state is not None:
            if job.reconsider_from:
                raise ValueError('only one continuation source is allowed')
            store, state, continuation = prepare_state(workspace, output)
            initial_causal_count = len(state.causal_order)
        elif job.reconsider_from:
            store, state, continuation = _prepare_reconsideration(job, workspace, output)
            initial_causal_count = len(state.causal_order)
        harness = harness_factory()
        model = LongHorizonModel(session_factory(settings=settings, audit_hook=audit), harness=harness)
        model.session = _BudgetedSession(model.session, job.max_calls, started + job.max_seconds, audit_errors)
        if state is None:
            store = LongHorizonStore(output / 'state', checkpoint_retention=1000)
            goal = model.create_literal_goal(job.request, str(workspace), runtime_policy={
                RUN_LIFECYCLE_POLICY_KEY: run_lifecycle_policy_document('goal')})
            state = store.create_run(goal, run_id=job.task_id)
        controller = controller_type(store, model=model, harness=harness,
                                         max_transitions=job.max_calls, min_actions=0)
        _save(output / 'goal.json', state.goal.to_dict())
        if continuation is not None and job.reconsider_from:
            from .summary_advice import make_advice_event
            event = make_advice_event('ADVICE-' + job.task_id, job.advice, 'external_strong_model', job.advice_model)
            _save(output / 'ADVICE_EVENT.json', event.to_dict())
            state.status = RunStatus.RUNNING
            state.final_output = ''
            terminal_id = next((key for key in reversed(state.causal_order)
                                if state.causal_records[key].event_type in ('run_completed', 'run_interrupted')), '')
            controller._persist(state, 'run_started', {
                **continuation, 'reason': 'owner_requested_reconsideration',
                'resumed': True, 'supersedes_terminal_event_id': terminal_id})
            model._append_event(state, state.model_states[continuation['parent_checkpoint_id']], event, controller._persist_callback)
        if before_run is not None:
            before_run(state, controller, model)
        controller.run(state.run_id)
    except (Exception, _WallDeadlineExpired) as exc:
        termination = 'budget' if isinstance(exc, (ReadOnlyBudgetExpired, _WallDeadlineExpired)) else 'error'
        termination_reason = ('wall_budget_exhausted' if isinstance(exc, _WallDeadlineExpired)
                              else exc.reason if isinstance(exc, ReadOnlyBudgetExpired) else 'execution_error')
        error = {'type': type(exc).__name__, 'message': str(exc), 'traceback': traceback.format_exc()}
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, old_handler)
        if old_timer[0]:
            signal.setitimer(signal.ITIMER_REAL, max(.001, old_timer[0] - (time.monotonic()-started)), old_timer[1])
    if state is not None:
        state = store.load(state.run_id)
    generations = [r for r in records if r['type'] == 'model_session_generation_started']
    items = []
    for event in state.model_events.values() if state is not None else ():
        if event.event_type != 'action_result':
            continue
        consumed = [r['request_id'] for r in generations
                    if r['input_checkpoint_id'] in state.model_states
                    and event.event_id in state.model_states[r['input_checkpoint_id']].event_ids]
        items.append({'event': event.to_model_dict(), 'event_id': event.event_id,
                      'consumed_by_requests': consumed})
    final = (state.final_output or None) if state is not None else None
    if continuation is not None and state.final_decision_id == continuation['parent_final_decision_id']:
        final = None  # The old submission remains in PARENT_RESULT, not a new delivery.
    boundary = next((state.causal_records[key] for key in reversed(state.causal_order[initial_causal_count:])
                     if state.causal_records[key].event_type in
                     ('run_yielded', 'run_interrupted', 'run_completed', 'run_failed', 'run_blocked')), None) if state else None
    if termination_reason is None:
        termination_reason = ('answer_submitted' if state and state.status == RunStatus.COMPLETED
                              else str(boundary.payload.get('reason') or boundary.event_type) if boundary
                              else 'controller_returned_without_terminal_reason')
    commands = []
    for action in state.actions.values() if state else ():
        if action.action_type not in ('run_command', 'check_command') or not action.result:
            continue
        value = action.result
        code = value.get('exit_code')
        commands.append({'action_id': action.action_id, 'exit_code': code,
                         'execution_status': 'exited' if type(code) is int else
                         'not_started' if (value.get('error') or {}).get('type') == 'FileNotFoundError'
                         else 'unconfirmed', 'tool_success': value.get('success'), 'error': value.get('error')})
    result = {'id': job.task_id, 'final': final,
              'termination': termination or ('submitted' if state is not None and state.status == RunStatus.COMPLETED else 'budget'),
              'termination_reason': termination_reason,
              'termination_evidence': boundary.to_dict() if boundary and error is None else error,
              'command_executions': commands,
              'acceptance': 'unreviewable' if audit_errors else 'not_evaluated',
              'assistance': 'strong_advised' if continuation and continuation.get('advice_model') else 'rwkv_independent',
              'continuation': continuation,
              'error': error, 'status': state.status.value if state is not None else 'not_started',
              'trace_complete': not audit_errors, 'trace_errors': audit_errors, 'tool_scope': job.tool_scope,
              'generation_started': len(generations), 'protocol_rejections': state.protocol_rejections if state is not None else 0,
              'actions': [a.to_dict() for a in state.actions.values()] if state is not None else [],
              'elapsed_seconds': time.monotonic()-started}
    _save(output / 'MATERIALS.json', {'items': items})
    if state is not None:
        _save(output / 'state_snapshot.json', state.to_dict())
    _save(output / 'RESULT.json', result)
    return result


def _worker(arguments):
    job, settings = arguments
    return run_read_only_job(job, settings=settings)


def run_read_only_jobs(jobs, *, settings, concurrency=1):
    """Schedule whole independent tasks; never split a task or merge its State."""
    from concurrent.futures import ProcessPoolExecutor
    from multiprocessing import get_context
    jobs = list(jobs)
    if concurrency < 1:
        raise ValueError('positive concurrency required')
    if len({job.task_id for job in jobs}) != len(jobs):
        raise ValueError('duplicate task IDs')
    paths = [Path(job.output_dir).resolve() for job in jobs]
    for index, path in enumerate(paths):
        if path.exists():
            raise FileExistsError(path)
        if any(path == other or path in other.parents or other in path.parents
               for other in paths[:index]):
            raise ValueError('overlapping task outputs')
        if any(path == Path(job.workspace).resolve() or Path(job.workspace).resolve() in path.parents
               for job in jobs):
            raise ValueError('audit output overlaps a task workspace')
    if concurrency == 1:
        return [_worker((job, settings)) for job in jobs]
    with ProcessPoolExecutor(max_workers=concurrency, mp_context=get_context('spawn')) as pool:
        return list(pool.map(_worker, [(job, settings) for job in jobs]))

rwkv_lh/tokenizer.py:
"""RWKV's trie tokenizer, packaged locally for exact context accounting."""

from __future__ import annotations

import ast
from pathlib import Path


class Trie:
    __slots__ = ("character", "children", "values", "parent")

    def __init__(self, parent: "Trie | None" = None, character: int | None = None):
        self.character = character
        self.children: list[Trie | None] = [None] * 256
        self.values: set[tuple[bytes, int]] = set()
        self.parent = parent

    def add(self, key: bytes, index: int = 0, value: tuple[bytes, int] | None = None) -> "Trie":
        if index == len(key):
            if value is None:
                raise ValueError("token trie value is required")
            self.values.add(value)
            return self
        character = key[index]
        child = self.children[character]
        if child is None:
            child = Trie(parent=self, character=character)
            self.children[character] = child
        return child.add(key, index + 1, value)

    def find_longest(self, key: bytes, index: int) -> tuple[int, set[tuple[bytes, int]]]:
        node = self
        best_index = index
        best_values: set[tuple[bytes, int]] | None = None
        while index < len(key):
            child = node.children[key[index]]
            if child is None:
                break
            node = child
            index += 1
            if node.values:
                best_index = index
                best_values = node.values
        if best_values is None:
            raise ValueError(f"vocabulary cannot encode byte at offset {best_index}")
        return best_index, best_values


class RWKVTokenizer:
    """Official RWKV vocabulary semantics with deterministic local loading."""

    def __init__(self, file_name: str | Path | None = None):
        vocab_path = (
            Path(file_name)
            if file_name is not None
            else Path(__file__).resolve().parent / "data" / "rwkv_vocab_v20230424.txt"
        )
        if not vocab_path.is_file():
            raise FileNotFoundError(f"RWKV vocabulary not found: {vocab_path}")

        self.idx2token: dict[int, bytes] = {}
        for line in vocab_path.read_text(encoding="utf-8").splitlines():
            first_space = line.index(" ")
            last_space = line.rindex(" ")
            index = int(line[:first_space])
            token = ast.literal_eval(line[first_space:last_space])
            token = token.encode("utf-8") if isinstance(token, str) else token
            if not isinstance(token, bytes) or len(token) != int(line[last_space:]):
                raise ValueError(f"invalid RWKV vocabulary row: {index}")
            self.idx2token[index] = token

        self.token2idx = {token: index for index, token in self.idx2token.items()}
        self.root = Trie()
        for token, index in self.token2idx.items():
            self.root.add(token, value=(token, index))

    def encode_bytes(self, source: bytes) -> list[int]:
        index = 0
        tokens: list[int] = []
        while index < len(source):
            index, values = self.root.find_longest(source, index)
            _, token_id = next(iter(values))
            tokens.append(token_id)
        return tokens

    def decode_bytes(self, tokens: list[int]) -> bytes:
        return b"".join(self.idx2token[token] for token in tokens)

    def encode(self, source: str) -> list[int]:
        return self.encode_bytes(source.encode("utf-8"))

    def decode(self, tokens: list[int]) -> str:
        return self.decode_bytes(tokens).decode("utf-8", errors="replace")

__all__ = ["RWKVTokenizer", "Trie"]

