        "post_effect_crash_resumed",
        "priority_summary",
        "project_behavior",
        "resilient_shards",
        "resume_no_repeated_completed_attempts",
        "service_migration",
        "sha256_manifest",
    }
)


def _safe_relative(value: str) -> Path:
    path = Path(str(value or "").strip())
    if not str(path) or path.is_absolute() or ".." in path.parts:
        raise ValueError(f"unsafe relative path: {value!r}")
    return path


def _workspace_path(
    workspace: Path,
    value: str,
    *,
    must_exist: bool = False,
) -> Path:
    root = workspace.resolve(strict=True)
    candidate = (root / _safe_relative(value)).resolve(strict=must_exist)
    candidate.relative_to(root)
    return candidate


def _json_file(workspace: Path, value: str) -> Any:
    return json.loads(
        _workspace_path(workspace, value, must_exist=True).read_text(encoding="utf-8")
    )


def _event_count(events: Sequence[Mapping[str, Any]], event_type: str) -> int:
    return sum(1 for item in events if str(item.get("type") or "") == event_type)


def _nested_mappings(value: Any, *, depth: int = 0):
    """Yield JSON objects, including objects serialized in action output strings."""

    if depth > 32:
        return
    if isinstance(value, Mapping):
        yield value
        for item in value.values():
            yield from _nested_mappings(item, depth=depth + 1)
        return
    if isinstance(value, (list, tuple)):
        for item in value:
            yield from _nested_mappings(item, depth=depth + 1)
        return
    if isinstance(value, str):
        text = value.strip()
        if not text or text[0] not in "[{" or text[-1] not in "]}":
            return
        try:
            decoded = json.loads(text)
        except (TypeError, ValueError):
            return
        yield from _nested_mappings(decoded, depth=depth + 1)


def _valid_evidence_record(value: Mapping[str, Any]) -> tuple[str, str] | None:
    if str(value.get("schema_version") or "") != "rwkv-lh.evidence-record.v1":
        return None
    record_id = str(value.get("evidence_record_id") or "").strip()
    digest = str(value.get("snapshot_digest") or "").strip()
    url = str(value.get("url") or "").strip()
    parsed = urlparse(url)
    spans = value.get("exact_spans")
    structured = value.get("structured_fields")
    has_authority = (
        isinstance(spans, list) and bool(spans)
    ) or (
        isinstance(structured, Mapping) and bool(structured)
    )
    if (
        not record_id
        or len(digest) != 64
        or any(character not in "0123456789abcdef" for character in digest)
        or parsed.scheme not in {"http", "https"}
        or not parsed.hostname
        or not has_authority
    ):
        return None
    return record_id, url


def _host_matches(host: str, required_hosts: Sequence[str]) -> bool:
    normalized = str(host or "").strip().casefold().rstrip(".")
    return any(
        normalized == required or normalized.endswith(f".{required}")
        for required in required_hosts
    )


def check_spec(
    spec: Mapping[str, Any],
    workspace: Path,
    events: Sequence[Mapping[str, Any]],
    observations: Mapping[str, Any],
) -> CheckResult:
    """Evaluate one hidden acceptance rule against observable state only."""

    kind = str(spec.get("kind") or "")
    try:
        actual: Any
        target: Any
        if kind == "project_behavior":
            program, digest = _project_program(spec)
            program_path = Path(__file__).resolve().parent / "programs" / f"{digest}.py"
            if not program_path.is_file() or program_path.read_bytes().decode("utf-8") != program:
                raise ValueError("private project verifier was not staged by the isolated runner")
            environment = {
                "PATH": "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin",
                "LANG": os.environ.get("LANG", "C.UTF-8"),
                "PYTHONDONTWRITEBYTECODE": "1",
                "HOME": "/tmp/verifier-home",
                "TMPDIR": "/tmp",
            }
            if spec.get("browser") is True:
                environment.update({
                    "PYTHONPATH": "/opt/verifier-site",
                    "PLAYWRIGHT_BROWSERS_PATH": "/opt/verifier-browsers",
                })
            process = subprocess.Popen(
                [sys.executable, str(program_path.parent.parent / "project_driver.py"), str(program_path), str(workspace)],
                cwd=workspace,
                text=True,
                encoding="utf-8",
                errors="replace",
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                start_new_session=True,
                env=environment,
            )
            try:
                stdout, stderr = process.communicate(timeout=float(spec.get("timeout", 120)))
            except BaseException:
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                process.communicate()
                raise
            return CheckResult(kind, process.returncode == 0, {
                "program_sha256": digest,
                "actual_exit_code": process.returncode,
                "output": (stdout + stderr)[:10_000],
                "browser": spec.get("browser") is True,
            })
        if kind == "file_content":
            actual = _workspace_path(
                workspace, str(spec["path"]), must_exist=True
            ).read_text(encoding="utf-8")
            target = str(spec["content"])
            return CheckResult(
                kind,
                actual == target,
                {"path": spec["path"], "actual": actual, "target": target},
            )
        if kind == "file_contains":
            actual = _workspace_path(
                workspace, str(spec["path"]), must_exist=True
            ).read_text(encoding="utf-8")
            target = str(spec["text"])
            return CheckResult(
                kind,
                target in actual,
                {"path": spec["path"], "text": target},
            )
        if kind == "file_not_contains":
            actual = _workspace_path(
                workspace, str(spec["path"]), must_exist=True
            ).read_text(encoding="utf-8")
            target = str(spec["text"])
            return CheckResult(
                kind,
                target not in actual,
                {"path": spec["path"], "text": target},
            )
        if kind == "path_absent":
            path = _workspace_path(workspace, str(spec["path"]))
            exists = path.exists()
            return CheckResult(kind, not exists, {"path": spec["path"], "exists": exists})
        if kind == "json_equals":
            actual = _json_file(workspace, str(spec["path"]))
            target = spec["value"]
            return CheckResult(
                kind,
                actual == target,
                {"path": spec["path"], "actual": actual, "target": target},
            )
        if kind == "json_exact_keys":
            actual = _json_file(workspace, str(spec["path"]))
            actual_keys = sorted(actual) if isinstance(actual, dict) else []
            target = sorted(str(item) for item in spec.get("keys") or [])
            return CheckResult(
                kind,
                actual_keys == target,
                {"path": spec["path"], "actual": actual_keys, "target": target},
            )
        if kind == "files_equal":
            left = _workspace_path(
                workspace, str(spec["left"]), must_exist=True
            ).read_bytes()
            right = _workspace_path(
                workspace, str(spec["right"]), must_exist=True
            ).read_bytes()
            return CheckResult(
                kind,
                left == right,
                {
                    "left": spec["left"],
                    "right": spec["right"],
                    "left_sha256": hashlib.sha256(left).hexdigest(),
                    "right_sha256": hashlib.sha256(right).hexdigest(),
                },
            )
        if kind == "command_exit":
            argv = [str(item) for item in spec.get("argv") or []]
            if not argv:
                raise ValueError("command_exit requires argv")
            if argv[0] in {"python", "python3"}:
                argv[0] = sys.executable
            completed = subprocess.run(
                argv,
                cwd=workspace,
                shell=False,
                text=True,
                encoding="utf-8",
                errors="replace",
                capture_output=True,
                timeout=float(spec.get("timeout", 60)),
                check=False,
                start_new_session=True,
                env={
                    "PATH": "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin",
                    "LANG": os.environ.get("LANG", "C.UTF-8"),
                    "PYTHONDONTWRITEBYTECODE": "1",
                    "HOME": "/tmp/verifier-home",
                    "TMPDIR": "/tmp",
                },
            )
            target = int(spec.get("exit_code", 0))
            output = (completed.stdout or "") + (completed.stderr or "")
            return CheckResult(
                kind,
                completed.returncode == target,
                {
                    "argv": argv,
                    "actual_exit_code": completed.returncode,
                    "target_exit_code": target,
                    "output": output[:10_000],
                },
            )
        if kind == "sha256_manifest":
            source = _workspace_path(
                workspace, str(spec["source"]), must_exist=True
            )
            manifest = _json_file(workspace, str(spec["manifest"]))
            digest = hashlib.sha256(source.read_bytes()).hexdigest()
            passed = (
                manifest.get(str(spec["file_field"])) == str(spec["source"])
                and manifest.get(str(spec["digest_field"])) == digest
            )
            return CheckResult(
                kind,
                passed,
                {"source": spec["source"], "actual_digest": digest, "manifest": manifest},
            )
        if kind == "directory_file_set":
            directory = _workspace_path(
                workspace, str(spec["path"]), must_exist=True
            )
            actual = sorted(
                str(path.relative_to(directory))
                for path in directory.rglob("*")
                if path.is_file()
            )
            target = sorted(str(item) for item in spec.get("files") or [])
            return CheckResult(
                kind,
                actual == target,
                {"path": spec["path"], "actual": actual, "target": target},
            )
        if kind == "digest_map":
            directory = _workspace_path(
                workspace, str(spec["directory"]), must_exist=True
            )
            manifest = _json_file(workspace, str(spec["manifest"]))
            target = {}
            for name in spec.get("files") or []:
                path = (directory / _safe_relative(str(name))).resolve(strict=True)
                path.relative_to(directory.resolve(strict=True))
                target[str(name)] = hashlib.sha256(path.read_bytes()).hexdigest()
            return CheckResult(kind, manifest == target, {"manifest": manifest, "target": target})
        if kind == "aggregate_shards":
            directory = _workspace_path(
                workspace, str(spec["directory"]), must_exist=True
            )
            shards = sorted(directory.glob("*.json"))
            categories: dict[str, int | float] = {}
            item_count = 0
            value_total: int | float = 0
            for shard in shards:
                for item in json.loads(shard.read_text(encoding="utf-8"))["items"]:
                    category = str(item["category"])
                    value = item["value"]
                    item_count += 1
                    value_total += value
                    categories[category] = categories.get(category, 0) + value
            target = {
                "shard_count": len(shards),
                "item_count": item_count,
                "value_total": value_total,
                "categories": categories,
            }
            actual = _json_file(workspace, str(spec["path"]))
            return CheckResult(kind, actual == target, {"actual": actual, "target": target})
        if kind == "priority_summary":
            directory = _workspace_path(
                workspace, str(spec["directory"]), must_exist=True
            )
            target = {}
            for path in sorted(directory.glob("*.txt")):
                lines = path.read_text(encoding="utf-8").splitlines()
                if lines and lines[0] == "PRIORITY: yes":
                    target[path.name] = lines[1]
            actual = _json_file(workspace, str(spec["path"]))
            return CheckResult(kind, actual == target, {"actual": actual, "target": target})
        if kind == "resilient_shards":
            directory = _workspace_path(
                workspace, str(spec["directory"]), must_exist=True
            )
            fallback = _workspace_path(
                workspace, str(spec["fallback_directory"]), must_exist=True
            )
            count = int(spec["count"])
            sources: dict[str, str] = {}
            digests: dict[str, str] = {}
            value_total: int | float = 0
            recovered = 0
            for index in range(1, count + 1):
                name = f"shard_{index:02d}.json"
                primary = directory / name
                selected = primary
                source = f"{spec['directory']}/{name}"
                try:
                    value = json.loads(primary.read_text(encoding="utf-8"))
                except (FileNotFoundError, json.JSONDecodeError, UnicodeDecodeError):
                    selected = fallback / name
                    source = f"{spec['fallback_directory']}/{name}"
                    value = json.loads(selected.read_text(encoding="utf-8"))
                    recovered += 1
                value_total += sum(value["values"])
                sources[name] = source
                digests[name] = hashlib.sha256(selected.read_bytes()).hexdigest()
            target = {
                "shard_count": count,
                "primary_count": count - recovered,
                "recovered_count": recovered,
                "value_total": value_total,
                "sources": sources,
                "sha256": digests,
            }
            actual = _json_file(workspace, str(spec["path"]))
            return CheckResult(kind, actual == target, {"actual": actual, "target": target})
        if kind == "service_migration":
            directory = _workspace_path(
                workspace, str(spec["directory"]), must_exist=True
            )
            violations: list[str] = []
            files = sorted(directory.glob("service-*.json"))
            for path in files:
                value = json.loads(path.read_text(encoding="utf-8"))
                if value.get("schema_version") != 3:
                    violations.append(f"{path.name}: schema_version")
                if (value.get("runtime") or {}).get("channel") != "stable":
                    violations.append(f"{path.name}: runtime.channel")
                if (value.get("compat") or {}).get("api") != "v3":
                    violations.append(f"{path.name}: compat.api")
                if path.name == "service-03.json":
                    if "database" in value or value.get("storage") != {
                        "dsn": "postgres://billing",
                        "pool_size": 5,
                    }:
                        violations.append(f"{path.name}: special database migration")
                if path.name == "service-07.json":
                    if "auth" in value or value.get("security") != {
                        "session_ttl_seconds": 3600,
                        "provider": "local",
                    }:
                        violations.append(f"{path.name}: special auth migration")
            expected = int(spec.get("count", 8))
            if len(files) != expected:
                violations.append(f"service count={len(files)} expected={expected}")
            return CheckResult(
                kind,
                not violations,
                {"files": [path.name for path in files], "violations": violations},
            )
        if kind == "checkpoint_constraints":
            directory = _workspace_path(
                workspace, str(spec["path"]), must_exist=True
            )
            count = int(spec["count"])
            expected_constraints = spec["constraints"]
            violations: list[str] = []
            for index in range(1, count + 1):
                path = directory / f"step{index:02d}.json"
                try:
                    value = json.loads(path.read_text(encoding="utf-8"))
                except Exception as exc:
                    violations.append(f"{path.name}: {type(exc).__name__}")
                    continue
                if value != {"step": index, "constraints": expected_constraints}:
                    violations.append(f"{path.name}: content mismatch")
            actual_files = sorted(path.name for path in directory.glob("*.json"))
            expected_files = [f"step{index:02d}.json" for index in range(1, count + 1)]
            if actual_files != expected_files:
                violations.append("checkpoint file set mismatch")
            return CheckResult(
                kind,
                not violations,
                {"files": actual_files, "violations": violations},
            )
        if kind == "artifact_phase_checkpoints":
            directory = _workspace_path(
                workspace, str(spec["path"]), must_exist=True
            )
            phases = int(spec.get("count", 5))
            facts_per_phase = int(spec.get("facts_per_phase", 2))
            violations: list[str] = []
            for phase in range(1, phases + 1):
                path = directory / f"phase{phase:02d}.json"
                first_fact = (phase - 1) * facts_per_phase + 1
                expected = {
                    "phase": phase,
                    "fact_ids": [
                        f"F{index:02d}"
                        for index in range(first_fact, first_fact + facts_per_phase)
                    ],
                }
                try:
                    actual = json.loads(path.read_text(encoding="utf-8"))
                except Exception as exc:
                    violations.append(f"{path.name}: {type(exc).__name__}")
                    continue
                if actual != expected:
                    violations.append(f"{path.name}: content mismatch")
            return CheckResult(
                kind,
                not violations,
                {"phase_count": phases, "violations": violations},
            )
        if kind == "event_min_count":
            event_type = str(spec["event_type"])
            actual = _event_count(events, event_type)
            target = int(spec["count"])
            return CheckResult(
                kind,
                actual >= target,
                {"event_type": event_type, "actual": actual, "minimum": target},
            )
        if kind == "event_max_count":
            event_type = str(spec["event_type"])
            actual = _event_count(events, event_type)
            target = int(spec["count"])
            return CheckResult(
                kind,
                actual <= target,
                {"event_type": event_type, "actual": actual, "maximum": target},
            )
        if kind == "network_evidence_grounding":
            raw_operations = spec.get("operations") or [
                "web_search",
                "connector_lookup",
            ]
            if not isinstance(raw_operations, list) or not raw_operations:
                raise ValueError("network_evidence_grounding requires operations")
            operations = {
                str(item).strip() for item in raw_operations if str(item).strip()
            }
            raw_hosts = spec.get("required_hosts") or []
            if not isinstance(raw_hosts, list):
                raise ValueError("required_hosts must be an array")
            required_hosts = tuple(
                dict.fromkeys(
                    str(item).strip().casefold().rstrip(".")
                    for item in raw_hosts
                    if str(item).strip()
                )
            )
            raw_paths = spec.get("paths")
            if raw_paths is None and spec.get("path") is not None:
                raw_paths = [spec.get("path")]
            if not isinstance(raw_paths, list) or not raw_paths:
                raise ValueError("network_evidence_grounding requires paths")
            paths = [str(item) for item in raw_paths]
            artifact_text = "\n".join(
                _workspace_path(workspace, path, must_exist=True).read_text(
                    encoding="utf-8"
                )
                for path in paths
            )

            action_identities: set[str] = set()
            records: dict[str, str] = {}
            rejected_hosts: set[str] = set()
            for event in events:
                data = event.get("data") or {}
                for candidate in _nested_mappings(data):
                    operation = str(
                        candidate.get("operation")
                        or candidate.get("action_type")
                        or ""
                    ).strip()
                    if operation not in operations:
                        continue
                    result = candidate.get("result")
                    result_mapping = result if isinstance(result, Mapping) else {}
                    success = candidate.get("success") is True or result_mapping.get(
                        "success"
                    ) is True
                    status = str(candidate.get("status") or "").casefold()
                    if not success or status not in {
                        "",
                        "completed",
                        "success",
                        "succeeded",
                    }:
                        continue

                    route_ids = sorted(
                        {
                            str(item.get("route_id") or "")
                            for item in _nested_mappings(candidate)
                            if str(item.get("schema_version") or "")
                            == "rwkv-lh.external-evidence.v1"
                            and str(item.get("route_id") or "")
                        }
                    )
                    identity_payload = {
                        "operation": operation,
                        "routes": route_ids,
                        "attempt_id": str(candidate.get("attempt_id") or ""),
                        "action_id": str(candidate.get("action_id") or ""),
                        "arguments": candidate.get("arguments") or {},
                    }
                    if route_ids:
                        identity_payload = {
                            "operation": operation,
                            "routes": route_ids,
                        }
                    action_identities.add(
                        hashlib.sha256(
                            json.dumps(
                                identity_payload,
                                ensure_ascii=False,
                                sort_keys=True,
                                separators=(",", ":"),
                                default=str,
                            ).encode("utf-8")
                        ).hexdigest()
                    )
                    for item in _nested_mappings(candidate):
                        valid = _valid_evidence_record(item)
                        if valid is None:
                            continue
                        record_id, url = valid
                        host = str(urlparse(url).hostname or "").casefold()
                        if required_hosts and not _host_matches(host, required_hosts):
                            rejected_hosts.add(host)
                            continue
                        records[record_id] = url

            cited_urls = sorted({url for url in records.values() if url in artifact_text})
            minimum_actions = int(spec.get("min_successful_actions", 1))
            minimum_records = int(spec.get("min_records", 1))
            minimum_cited = int(spec.get("min_cited_urls", 1))
            passed = (
                len(action_identities) >= minimum_actions
                and len(records) >= minimum_records
                and len(cited_urls) >= minimum_cited
            )
            return CheckResult(
                kind,
                passed,
                {
                    "paths": paths,
                    "operations": sorted(operations),
                    "required_hosts": list(required_hosts),
                    "successful_action_count": len(action_identities),
                    "minimum_successful_actions": minimum_actions,
                    "valid_record_count": len(records),
                    "minimum_records": minimum_records,
                    "cited_url_count": len(cited_urls),
                    "minimum_cited_urls": minimum_cited,
                    "cited_urls": cited_urls,
                    "rejected_hosts": sorted(rejected_hosts),
                },
            )
        if kind == "command_exit_stages":
            target_argv = [str(item) for item in spec.get("argv") or []]
            command_attempts: set[str] = set()
            outputs: list[tuple[int | None, str]] = []
            for event in events:
                data = event.get("data") or {}
                if event.get("type") == "attempt_started" and [
                    str(item) for item in (data.get("arguments") or {}).get("argv") or []
                ] == target_argv:
                    command_attempts.add(str(data.get("attempt_id") or ""))
                elif (
                    event.get("type") == "action_returned"
                    and str(data.get("attempt_id") or "") in command_attempts
                ):
                    exit_code = data.get("exit_code")
                    outputs.append(
                        (
                            int(exit_code) if exit_code is not None else None,
                            str(data.get("output") or ""),
                        )
                    )
            expected_stages = [str(item) for item in spec.get("stages") or []]
            stage_index = 0
            success_after_stages = False
            for exit_code, output in outputs:
                if (
                    exit_code != 0
                    and stage_index < len(expected_stages)
                    and expected_stages[stage_index] in output
                ):
                    stage_index += 1
                    continue
                if exit_code == 0 and stage_index == len(expected_stages):
                    success_after_stages = True
            passed = bool(expected_stages) and stage_index == len(expected_stages)
            if bool(spec.get("require_success", True)):
                passed = passed and success_after_stages
            return CheckResult(
                kind,
                passed,
                {
                    "argv": target_argv,
                    "expected_stages": expected_stages,
                    "matched_stages": stage_index,
                    "success_after_stages": success_after_stages,
                    "attempt_count": len(outputs),
                },
            )
        if kind == "no_scope_violation_events":
            violations = [
                item
                for item in events
                if "ScopeViolation" in json.dumps(item, ensure_ascii=False)
            ]
            return CheckResult(kind, not violations, {"violation_count": len(violations)})
        if kind in {
            "resume_no_repeated_completed_attempts",
            "completed_resume_is_noop",
            "post_effect_crash_resumed",
            "mock_api_finalized",
            "agent_process_tree_closed",
        }:
            passed = bool(observations.get(kind))
            return CheckResult(kind, passed, {"observed": passed})
        if kind == "mock_api_state":
            actual = observations.get("mock_api_state")
            target = spec.get("value")
            return CheckResult(kind, actual == target, {"actual": actual, "target": target})
        raise ValueError(f"unsupported external checker kind: {kind}")
    except Exception as exc:
        return CheckResult(kind, False, {}, f"{type(exc).__name__}: {exc}"[:2000])


def verify_payload(payload: Mapping[str, Any], workspace: Path) -> IsolatedVerifierResult:
    acceptance = payload.get("acceptance")
    if not isinstance(acceptance, Mapping):
        raise ValueError("verifier payload has no acceptance object")
    events = payload.get("events") or []
    observations = payload.get("observations") or {}
    if not isinstance(events, list) or not isinstance(observations, Mapping):
        raise ValueError("invalid verifier observations")
    raw_checks = acceptance.get("checks")
    if (
        not isinstance(raw_checks, list)
        or not raw_checks
        or any(not isinstance(spec, Mapping) for spec in raw_checks)
    ):
        raise ValueError("verifier acceptance requires a non-empty checks array")
    checks = tuple(
        check_spec(spec, workspace, events, observations)
        for spec in raw_checks
    )
    return IsolatedVerifierResult(
        checks,
        {
            "backend": "bubblewrap",
            "acceptance_transport": "stdin",
            "workspace_mount": "read_only_snapshot",
            "network": "unshared",
            "pid_namespace": "private",
            "repository_mounted": False,
            "verifier_logs_exposed_to_agent": False,
        },
    )


def _disable_ptrace() -> None:
    """Prevent verifier-spawned workspace code from reading worker memory."""

    if sys.platform != "linux":
        return
    try:
        libc = ctypes.CDLL(None, use_errno=True)
        if libc.prctl(4, 0, 0, 0, 0) != 0:  # PR_SET_DUMPABLE
            raise OSError(ctypes.get_errno(), "prctl(PR_SET_DUMPABLE) failed")
    except Exception as exc:
        raise RuntimeError(f"could not harden verifier process: {exc}") from exc


def _secure_snapshot(source: Path, destination: Path) -> None:
    """Copy only directories and regular files; reject symlink-based escapes."""

    root = source.resolve(strict=True)
    destination.mkdir(parents=True, exist_ok=False)
    for current, directory_names, file_names in os.walk(root, followlinks=False):
        current_path = Path(current)
        relative = current_path.relative_to(root)
        target_directory = destination / relative
        target_directory.mkdir(parents=True, exist_ok=True)
        for name in list(directory_names):
            child = current_path / name
            mode = child.lstat().st_mode
            if stat.S_ISLNK(mode):
                raise ValueError(f"verifier snapshot rejects symlink directory: {child}")
            if not stat.S_ISDIR(mode):
                raise ValueError(f"verifier snapshot rejects special directory: {child}")
        for name in file_names:
            child = current_path / name
            mode = child.lstat().st_mode
            if not stat.S_ISREG(mode):
                raise ValueError(f"verifier snapshot rejects non-regular file: {child}")
            shutil.copy2(child, target_directory / name, follow_symlinks=False)


def _project_program(spec: Mapping[str, Any]) -> tuple[str, str]:
    program = spec.get("program")
    digest = str(spec.get("program_sha256") or "")
    if not isinstance(program, str) or not program.strip():
        raise ValueError("project behavior check requires a private Python program")
    if hashlib.sha256(program.encode("utf-8")).hexdigest() != digest:
        raise ValueError("private project program SHA-256 mismatch")
    return program, digest


def _browser_runtime_mounts() -> list[tuple[Path, str]]:
    """Expose only browser dependencies; never mount the repository or home."""
    mounts = []
    for name in ("playwright", "greenlet", "pyee", "typing_extensions"):
        spec = importlib.util.find_spec(name)
        if spec is None or spec.origin is None:
            raise RuntimeError("browser verification requires the benchmark-web extra")
        source = Path(spec.origin).resolve(strict=True)
        if spec.submodule_search_locations is not None:
            source = source.parent
            target = f"/opt/verifier-site/{name}"
        else:
            target = f"/opt/verifier-site/{source.name}"
        mounts.append((source, target))
    configured = os.environ.get("PLAYWRIGHT_BROWSERS_PATH", "")
    browser_root = Path(configured) if configured else Path.home() / ".cache/ms-playwright"
    if not browser_root.is_dir():
        raise RuntimeError("browser verification requires installed Playwright Chromium")
    mounts.append((browser_root.resolve(), "/opt/verifier-browsers"))
    return mounts


def _bubblewrap_worker_command(
    bubblewrap: str,
    workspace: Path,
    worker: Path,
    *,
    browser_mounts: Sequence[tuple[Path, str]] = (),
    candidate_python: Path | None = None,
) -> list[str]:
    executable = Path(sys.executable).resolve(strict=True)
    runtime_root: Path | None = None
    sandbox_python = executable
    if not executable.is_relative_to(Path("/usr")):
        runtime_root = executable.parent.parent
        sandbox_python = Path("/opt/verifier-python/bin") / executable.name
    command = [
        bubblewrap,
        "--die-with-parent",
        "--unshare-all",
        "--new-session",
        "--ro-bind",
        "/usr",
        "/usr",
        "--ro-bind",
        "/etc",
        "/etc",
        "--symlink",
        "usr/bin",
        "/bin",
        "--symlink",
        "usr/sbin",
        "/sbin",
        "--symlink",
        "usr/lib",
        "/lib",
        "--symlink",
        "usr/lib64",
        "/lib64",
        "--dir",
        "/opt",
        "--dir",
        "/opt/verifier",
        "--dir",
        "/opt/verifier-python",
        "--dir",
        "/workspace",
        "--dir",
        "/proc",
        "--dir",
        "/dev",
        "--dir",
        "/tmp",
        "--proc",
        "/proc",
        "--dev",
        "/dev",
        "--tmpfs",
        "/tmp",
        "--ro-bind",
        str(workspace),
        "/workspace",
        "--ro-bind",
        str(worker.parent),
        "/opt/verifier",
    ]
    if runtime_root is not None:
        command.extend(
            ["--ro-bind", str(runtime_root), "/opt/verifier-python"]
        )
    if browser_mounts:
        command.extend(["--dir", "/opt/verifier-site"])
        for source, target in browser_mounts:
            command.extend(["--ro-bind", str(source), target])
    if candidate_python is not None:
        command.extend(["--ro-bind", str(candidate_python), "/opt/candidate-python"])
    command.extend(
        [
            "--remount-ro",
            "/",
            "--setenv",
            "PYTHONDONTWRITEBYTECODE",
            "1",
            "--setenv",
            "HOME",
            "/tmp/verifier-home",
            "--setenv",
            "TMPDIR",
            "/tmp",
            "--chdir",
            "/workspace",
            str(sandbox_python),
            "/opt/verifier/worker.py",
            "--worker",
        ]
    )
    return command


def run_isolated_verifier(
    acceptance: Mapping[str, Any],
    workspace: Path,
    events: Sequence[Mapping[str, Any]],
    observations: Mapping[str, Any],
    *,
    private_root: Path,
    timeout_seconds: float = 180.0,
) -> IsolatedVerifierResult:
    """Run hidden checks in a fail-closed namespace after the Agent phase ends."""

    bubblewrap = shutil.which("bwrap")
    if not bubblewrap:
        raise RuntimeError("isolated E2E verification requires bubblewrap")
    private_root.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="verifier-", dir=private_root) as directory:
        root = Path(directory)
        snapshot = root / "workspace"
        _secure_snapshot(workspace, snapshot)
        worker_directory = root / "worker"
        worker_directory.mkdir()
        worker = worker_directory / "worker.py"
        shutil.copy2(Path(__file__).resolve(strict=True), worker)
        browser_required = False
        for check in acceptance.get("checks") or ():
            if check.get("kind") != "project_behavior":
                continue
            try:
                program, digest = _project_program(check)
            except ValueError:
                # The worker reports a failed check with the binding error.
                continue
            program_directory = worker_directory / "programs"
            program_directory.mkdir(exist_ok=True)
            (program_directory / f"{digest}.py").write_text(program, encoding="utf-8")
            browser_required = browser_required or check.get("browser") is True
        browser_mounts = _browser_runtime_mounts() if browser_required else ()
        candidate_python = None
        if (worker_directory / "programs").is_dir():
            # Only the trusted grader uses this wrapper as sys.executable.
            # Candidate processes get a fresh PID/mount namespace which hides
            # every private program, while sharing the outer isolated loopback
            # and temporary test inputs with the grader.
            candidate_python = root / "candidate-python"
            candidate_python.mkdir()
            executable = Path(sys.executable).resolve(strict=True)
            sandbox_python = (executable if executable.is_relative_to(Path("/usr"))
                              else Path("/opt/verifier-python/bin") / executable.name)
            command = ["/usr/bin/bwrap", "--die-with-parent", "--unshare-user", "--unshare-pid",
                       "--unshare-ipc", "--unshare-uts", "--new-session", "--bind", "/", "/",
                       "--bind", "/tmp", "/tmp", "--tmpfs", "/opt/verifier", "--proc", "/proc", "--dev", "/dev",
                       "--cap-drop", "ALL", str(sandbox_python)]
            wrapper = candidate_python / "python"
            wrapper.write_text("#!/bin/sh\nexec " + shlex.join(command) + ' "$@"\n', encoding="utf-8")
            wrapper.chmod(0o755)
            (worker_directory / "project_driver.py").write_text(
                "import runpy, sys\n"
                "sys.executable = '/opt/candidate-python/python'\n"
                "sys.argv = sys.argv[1:]\n"
                "runpy.run_path(sys.argv[0], run_name='__main__')\n",
                encoding="utf-8",
            )
        payload = json.dumps(
            {
                "acceptance": dict(acceptance),
                "events": [dict(item) for item in events],
                "observations": dict(observations),
            },
            ensure_ascii=False,
        )
        completed = subprocess.run(
            _bubblewrap_worker_command(bubblewrap, snapshot, worker, browser_mounts=browser_mounts,
                                      candidate_python=candidate_python),
            input=payload,
            text=True,
            encoding="utf-8",
            errors="replace",
            capture_output=True,
            timeout=max(1.0, float(timeout_seconds)),
            check=False,
            start_new_session=True,
            env={"LANG": os.environ.get("LANG", "C.UTF-8")},
        )
        if completed.returncode != 0:
            raise RuntimeError(
                "isolated verifier failed: "
                + ((completed.stderr or completed.stdout or "unknown error")[:4000])
            )
        raw = json.loads(completed.stdout)
        if not isinstance(raw, Mapping):
            raise RuntimeError("isolated verifier returned a non-object response")
        raw_checks = raw.get("checks")
        expected_checks = acceptance.get("checks")
        if not isinstance(raw_checks, list) or not isinstance(expected_checks, list):
            raise RuntimeError("isolated verifier response has no checks array")
        checks = tuple(CheckResult(**dict(item)) for item in raw_checks)
        expected_kinds = [str(item.get("kind") or "") for item in expected_checks]
        if len(checks) != len(expected_checks) or [item.kind for item in checks] != expected_kinds:
            raise RuntimeError("isolated verifier response does not match acceptance checks")
        metadata = dict(raw.get("metadata") or {})
        required_metadata = {
            "backend": "bubblewrap",
            "acceptance_transport": "stdin",
            "workspace_mount": "read_only_snapshot",
            "network": "unshared",
            "pid_namespace": "private",
            "repository_mounted": False,
            "verifier_logs_exposed_to_agent": False,
        }
        if any(metadata.get(key) != value for key, value in required_metadata.items()):
            raise RuntimeError("isolated verifier returned invalid isolation metadata")
        return IsolatedVerifierResult(checks, metadata)


def _worker_main() -> int:
    _disable_ptrace()
    payload = json.loads(sys.stdin.read())
    try:
        sys.stdin.close()
    except Exception:
        pass
    result = verify_payload(payload, Path("/workspace"))
    print(
        json.dumps(
            {
                "passed": result.passed,
                "checks": [item.to_dict() for item in result.checks],
                "metadata": result.metadata,
            },
            ensure_ascii=False,
        )
    )
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("--worker", action="store_true")
    arguments = parser.parse_args()
    if not arguments.worker:
        raise RuntimeError("benchmark verifier is an internal worker")
    return _worker_main()


if __name__ == "__main__":
    raise SystemExit(main())


__all__ = [
    "SUPPORTED_CHECK_KINDS",
    "CheckResult",
    "IsolatedVerifierResult",
    "check_spec",
    "run_isolated_verifier",
    "verify_payload",
]

rwkv_lh/contract_validation.py:
"""Single semantic validator for Planner-authored contract graph patches.

The OpenAI-compatible Planner adapter and the durable Controller must accept the
same patch language.  Keeping the complete validation here lets the adapter feed
every semantic failure back through its bounded repair loop without weakening the
Controller's fail-closed replay boundary.
"""

from __future__ import annotations

from typing import Any, Mapping, Sequence

from rwkv_lh.capability_projection import (
    CAPABILITY_PROJECTION_VERSION,
    project_contract_capabilities,
)
from rwkv_lh.contract_graph import (
    ContractGraphNode,
    ContractGraphPatch,
    ContractObligation,
    ObligationPhase,
    ResultCapsule,
    validate_content_mutation_dependencies,
)
from rwkv_lh.supervisor import AtomRole


def contract_scopes_overlap(
    left_roots: Sequence[str],
    right_roots: Sequence[str],
) -> bool:
    """Return whether two workspace-relative scope sets overlap."""

    for left in left_roots:
        for right in right_roots:
            if left == "." or right == ".":
                return True
            left_parts = tuple(part for part in left.split("/") if part)
            right_parts = tuple(part for part in right.split("/") if part)
            shared = min(len(left_parts), len(right_parts))
            if left_parts[:shared] == right_parts[:shared]:
                return True
    return False


def contract_scope_covers(read_root: str, write_root: str) -> bool:
    """Return whether one read root covers the complete write-root subtree."""

    if read_root == ".":
        return True
    if write_root == ".":
        return False
    read_parts = tuple(part for part in read_root.split("/") if part and part != ".")
    write_parts = tuple(
        part for part in write_root.split("/") if part and part != "."
    )
    return (
        len(read_parts) <= len(write_parts)
        and write_parts[: len(read_parts)] == read_parts
    )


def validate_contract_patch_semantics(
    patch: ContractGraphPatch,
    *,
    existing_obligations: Mapping[str, ContractObligation],
    existing_nodes: Mapping[str, ContractGraphNode],
    operation_catalog: Sequence[Mapping[str, Any]],
    capsules: Sequence[ResultCapsule],
    finalizer_required: bool,
    workspace_manifest: Mapping[str, Any],
    existing_node_statuses: Mapping[str, str] | None = None,
) -> None:
    """Validate the complete shared Planner/Controller patch contract."""

    if not patch.new_nodes:
        raise ValueError("every contract planner patch must add executable nodes")
    if patch.base_revision > 0 and patch.new_obligations:
        raise ValueError(
            "immutable obligations are frozen after the initial contract patch"
        )
    catalog = {
        str(item.get("name") or ""): str(item.get("scope_mode") or "")
        for item in operation_catalog
    }
    for node in patch.new_nodes:
        if node.atom.operation_allowset_source != CAPABILITY_PROJECTION_VERSION:
            raise ValueError(
                "new contract graph nodes require Controller capability projection"
            )
        projection = project_contract_capabilities(
            atom_kind=node.atom.atom_kind,
            effect_ceiling=node.atom.effect_ceiling,
            role=node.atom.role.value,
            operation_catalog=operation_catalog,
            write_roots=node.atom.write_roots,
            evidence_kinds=node.atom.evidence_kinds,
            source_preferences=node.atom.source_preferences,
        )
        if node.atom.allowed_operations != projection.operations:
            raise ValueError(
                f"contract node {node.node_id} operation allowset was not "
                "mechanically projected"
            )
        if node.atom.exclusive != projection.exclusive:
            raise ValueError(
                f"contract node {node.node_id} changed projected exclusivity"
            )
        if node.atom.minimum_actions != projection.minimum_actions:
            raise ValueError(
                f"contract node {node.node_id} changed projected minimum actions"
            )
        unknown = set(node.atom.allowed_operations) - set(catalog)
        if unknown:
            raise ValueError(
                f"contract node selected unavailable operations: {sorted(unknown)}"
            )
        modes = [catalog[operation] for operation in node.atom.allowed_operations]
        if node.atom.role == AtomRole.FINALIZER and any(
            mode != "read_only" for mode in modes
        ):
            raise ValueError("contract finalizer must use a read-only operation")
        if "path_mutation" in modes and not 1 <= len(node.atom.write_roots) <= 8:
            raise ValueError("contract path mutation requires one to eight roots")
        if "path_mutation" in modes and not (
            node.atom.minimum_actions <= node.atom.action_budget <= 12
        ):
            raise ValueError(
                "contract mutation transaction has an invalid action budget"
            )
        if "exclusive_side_effect" in modes and not node.atom.exclusive:
            raise ValueError(
                "contract external side effect requires projected exclusivity"
            )

    mutations = [
        node for node in patch.new_nodes if node.atom.atom_kind == "mutate"
    ]
    verifiers = [
        node for node in patch.new_nodes if node.atom.atom_kind == "verify"
    ]
    node_by_id = {
        **existing_nodes,
        **{node.node_id: node for node in patch.new_nodes},
    }
    statuses = {node_id: "pending" for node_id in existing_nodes}
    capsule_statuses: dict[str, str] = {}
    for capsule in capsules:
        if capsule.node_id not in existing_nodes:
            continue
        previous = capsule_statuses.get(capsule.node_id)
        if previous is not None and previous != capsule.node_status:
            raise ValueError(
                "result capsules disagree on an existing node status"
            )
        capsule_statuses[capsule.node_id] = capsule.node_status
    statuses.update(capsule_statuses)
    if existing_node_statuses is not None:
        supplied = {
            str(node_id): str(status)
            for node_id, status in existing_node_statuses.items()
        }
        unknown_statuses = set(supplied) - set(existing_nodes)
        if unknown_statuses:
            raise ValueError(
                "existing node statuses reference unknown nodes: "
                f"{sorted(unknown_statuses)}"
            )
        invalid_statuses = {
            node_id: status
            for node_id, status in supplied.items()
            if status not in {"pending", "completed", "failed", "interrupted"}
        }
        if invalid_statuses:
            raise ValueError(
                f"existing node statuses are invalid: {invalid_statuses}"
            )
        capsule_mismatches = {
            node_id: {
                "status": supplied[node_id],
                "capsule_status": capsule_status,
            }
            for node_id, capsule_status in capsule_statuses.items()
            if node_id in supplied and supplied[node_id] != capsule_status
        }
        if capsule_mismatches:
            raise ValueError(
                "existing node status differs from its result capsule: "
                f"{capsule_mismatches}"
            )
        statuses.update(supplied)

    if patch.base_revision > 0:
        blocked_dependencies = {
            node.node_id: {
                dependency: statuses[dependency]
                for dependency in node.atom.depends_on
                if dependency in existing_nodes
                and statuses[dependency] != "completed"
            }
            for node in patch.new_nodes
        }
        blocked_dependencies = {
            node_id: dependencies
            for node_id, dependencies in blocked_dependencies.items()
            if dependencies
        }
        if blocked_dependencies:
            raise ValueError(
                "correction nodes depend on non-completed existing nodes and "
                f"can never become ready: {blocked_dependencies}"
            )

    def descends_from(node_id: str, ancestor_id: str) -> bool:
        pending = [node_id]
        visited: set[str] = set()
        while pending:
            current = pending.pop()
            if current in visited:
                continue
            visited.add(current)
            node = node_by_id.get(current)
            if node is None:
                continue
            if ancestor_id in node.atom.depends_on:
                return True
            pending.extend(node.atom.depends_on)
        return False

    for mutation in mutations:
        if not any(
            descends_from(verifier.node_id, mutation.node_id)
            and (
                not mutation.atom.write_roots
                or all(
                    any(
                        contract_scope_covers(read_root, write_root)
                        for read_root in verifier.atom.read_roots
                    )
                    for write_root in mutation.atom.write_roots
                )
            )
            for verifier in verifiers
        ):
            raise ValueError(
                f"contract mutation {mutation.node_id} requires a downstream "
                "verify node over its write scope"
            )

    validate_content_mutation_dependencies(
        patch,
        existing_nodes=existing_nodes,
        result_capsules=capsules,
        visible_paths=tuple(
            str(item.get("path") or "")
            for item in workspace_manifest.get("entries") or ()
            if isinstance(item, Mapping) and str(item.get("path") or "")
        ),
    )

    finalizers = [
        node for node in patch.new_nodes if node.atom.role == AtomRole.FINALIZER
    ]
    work = [node for node in patch.new_nodes if node.atom.role == AtomRole.WORK]
    all_obligations = {
        **existing_obligations,
        **{item.obligation_id: item for item in patch.new_obligations},
    }
    required_ids = set(all_obligations)
    presentation_ids = {
        obligation_id
        for obligation_id, obligation in all_obligations.items()
        if obligation.phase == ObligationPhase.FINAL_PRESENTATION
    }
    invalid_work_bindings = {
        node.node_id: sorted(set(node.obligation_ids) & presentation_ids)
        for node in work
        if set(node.obligation_ids) & presentation_ids
    }
    if invalid_work_bindings:
        raise ValueError(
            "work nodes cannot bind final-presentation obligations: "
            f"{invalid_work_bindings}"
        )
    if patch.base_revision == 0:
        if not patch.new_obligations:
            raise ValueError("initial contract patch requires immutable obligations")
        if not work or len(finalizers) != 1:
            raise ValueError(
                "initial contract patch requires work and one frozen finalizer"
            )
        finalizer = finalizers[0]
        if not required_ids <= set(finalizer.obligation_ids):
            raise ValueError("initial finalizer must bind every obligation")
        initial_work_ids = {node.node_id for node in work}
        if not initial_work_ids <= set(finalizer.atom.depends_on):
            raise ValueError(
                "initial finalizer must depend on every initial work node"
            )
    elif finalizer_required:
        if work or len(finalizers) != 1:
            raise ValueError(
                "replacement finalizer patch must contain one finalizer only"
            )
        finalizer = finalizers[0]
        if not required_ids <= set(finalizer.obligation_ids):
            raise ValueError("replacement finalizer must bind every obligation")
        completed_work_ids = {
            node_id
            for node_id, node in existing_nodes.items()
            if node.atom.role == AtomRole.WORK
            and statuses.get(node_id) == "completed"
        }
        if not completed_work_ids <= set(finalizer.atom.depends_on):
            raise ValueError(
                "replacement finalizer must depend on every completed work node"
            )
    elif finalizers:
        raise ValueError(
            "correction patch cannot add a finalizer before evidence passes"
        )

    all_work_ids = {
        node_id
        for node_id, node in node_by_id.items()
        if node.atom.role == AtomRole.WORK
    }
    invalid_finalizer_dependencies = {
        node.node_id: sorted(set(node.atom.depends_on) - all_work_ids)
        for node in finalizers
        if set(node.atom.depends_on) - all_work_ids
    }
    if invalid_finalizer_dependencies:
        raise ValueError(
            "finalizers may depend only on work nodes: "
            f"{invalid_finalizer_dependencies}"
        )


__all__ = [
    "contract_scope_covers",
    "contract_scopes_overlap",
    "validate_contract_patch_semantics",
]

rwkv_lh/role_trace_labels.py:
"""Bind raw JSON-role targets to the one rebuilt production input contract.

These are structural/evidence checks, not label authority. The caller must still
prove an executed advancement, a unique eligible planner contract, or two bound
human reviews for a semantic or failure-recovery target. A review cannot bypass any check
here. Selector suffixes have their separate three-menu decoder validation.
"""

from __future__ import annotations

from collections.abc import Mapping
from copy import deepcopy
from typing import Any

from rwkv_lh.executor_provenance import validate_executor_argument_provenance
from rwkv_lh.goal_state_protocols import (
    auditor_final, auditor_step_v7, executor_args_v7, finalizer_answer,
)
from rwkv_lh.harness import HarnessError, TaskAction
from rwkv_lh.role_trace_inputs import _reconstruction_harness


_MODULES = {
    "executor_args": executor_args_v7,
    "auditor_step": auditor_step_v7,
    "auditor_final": auditor_final,
    "finalizer_answer": finalizer_answer,
}


class RoleTraceLabelError(ValueError):
    """A raw target does not satisfy its reconstructed production input."""


def validate_role_target(
    role: str, rebuilt: Mapping[str, Any], canonical_target: str, *, verifier_id: str,
) -> str:
    """Validate without supplying, repairing, or rewriting any target field.

    Executor arguments pass the same semantics-free interface normalization and
    exact-source provenance checks as production; the returned training target
    always retains its original wire arguments. The verifier id binds the source
    contract to an existing durable boundary; it does not grant label authority.
    """
    if role not in _MODULES:
        raise RoleTraceLabelError(f"unsupported JSON role: {role}")
    if not isinstance(verifier_id, str) or not verifier_id.strip():
        raise RoleTraceLabelError("an existing nonempty verifier_id is required")
    module = _MODULES[role]
    if rebuilt.get("protocol_version") != module.INPUT_SCHEMA_VERSION:
        raise RoleTraceLabelError("target requires the current rebuilt input protocol")
    prompt_source = rebuilt.get("prompt_source")
    if not isinstance(prompt_source, Mapping):
        raise RoleTraceLabelError("target requires a rebuilt prompt source")
    try:
        parsed = module.parse_target(canonical_target)
        if parsed.canonical != canonical_target:
            raise RoleTraceLabelError("target must already be canonical; rewriting is forbidden")
        source = deepcopy(dict(prompt_source))
        if role == "executor_args":
            source.update(
                command={"function": parsed.name, "params": dict(parsed.arguments)},
                fixture_id=verifier_id, execution_verifier_id=verifier_id,
            )
        elif role == "auditor_step":
            source.update(decision=dict(parsed.arguments), completion_verifier_id=verifier_id)
        elif role == "auditor_final":
            source.update(decision=dict(parsed.arguments), final_verifier_id=verifier_id)
        else:
            source.update(final_text=parsed.arguments["text"], fact_verifier_id=verifier_id)
        module.validate_source(source)
        if module.render_target(source) != canonical_target:
            raise RoleTraceLabelError("target differs from the source-bound canonical target")
        if role == "executor_args":
            if "bound_fact_records" not in rebuilt:
                raise RoleTraceLabelError("Executor target lacks reconstructed bound fact records")
            normalized, _trace = _reconstruction_harness().normalize_action_with_trace(
                TaskAction(parsed.name, dict(parsed.arguments)),
            )
            validate_executor_argument_provenance(
                normalized.action_type, normalized.arguments,
                immutable_goal=source["immutable_goal"],
                current_requirement=source["current_requirement"],
                fact_records=rebuilt["bound_fact_records"],
                execution_state=source["execution_state"],
            )
    except (ValueError, TypeError, KeyError, HarnessError) as exc:
        if isinstance(exc, RoleTraceLabelError):
            raise
        raise RoleTraceLabelError(str(exc)) from exc
    return canonical_target


__all__ = ["RoleTraceLabelError", "validate_role_target"]

rwkv_lh/web_ui.py:
"""Local, dependency-free web UI for transparent RWKV-LH manual runs."""

from __future__ import annotations

import argparse
import fcntl
import hashlib
import io
import json
import mimetypes
import os
import re
import secrets
import sqlite3
import subprocess
import sys
import threading
import urllib.error
import urllib.request
import zipfile
from datetime import datetime, timezone
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any, Mapping
from urllib.parse import parse_qs, unquote, urlparse

from rwkv_lh.runtime.openai_compat import OpenAICompatibleRWKVClient
from rwkv_lh.exact_tool_selector.native_network_client import (
    NativeNetworkSelectorSettings,
)
from rwkv_lh.retrieval import RetrievalRuntimeConfig
from rwkv_lh.runtime.settings import PROJECT_ROOT, get_runtime_settings
from rwkv_lh.store import LongHorizonStore, StateRecoveryError
from rwkv_lh.supervisor_openai import SupervisorAPISettings
from rwkv_lh.trace_projection import project_run_activity


SCHEMA_VERSION = "rwkv-lh.manual-web-run.v1"
ASSET_ROOT = Path(
    os.environ.get(
        "RWKV_LH_WEB_ASSET_ROOT",
        str(Path(__file__).resolve().parent / "goal_web_assets"),
    )
).expanduser().resolve()
RUN_ID_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,99}$")
TERMINAL_PHASES = {"finished", "failed", "stopped", "blocked"}
MAX_REQUEST_BYTES = 6 * 1024 * 1024
MAX_SEED_BYTES = 5 * 1024 * 1024
MAX_TEXT_PREVIEW_BYTES = 1024 * 1024


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds")


def read_json(path: Path, default: Any = None) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return default


def atomic_write_json(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.{secrets.token_hex(4)}.tmp")
    temporary.write_text(
        json.dumps(dict(payload), ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    os.replace(temporary, path)


def update_metadata(run_root: Path, **changes: Any) -> dict[str, Any]:
    path = run_root / "metadata.json"
    current = read_json(path, {})
    if not isinstance(current, dict):
        current = {}
    current.update(changes)
    current["updated_at"] = utc_now()
    atomic_write_json(path, current)
    return current


def normalize_run_id(value: str) -> str:
    run_id = str(value or "").strip()
    if not RUN_ID_PATTERN.fullmatch(run_id):
        raise ValueError("run_id must use 1-100 ASCII letters, digits, dot, underscore, or dash")
    return run_id


def normalize_relative_path(value: str) -> Path:
    raw = str(value or "").replace("\\", "/").strip()
    relative = Path(raw)
    if (
        not raw
        or relative.is_absolute()
        or re.match(r"^[A-Za-z]:/", raw)
        or ".." in relative.parts
        or "\x00" in raw
    ):
        raise ValueError("file path must be a non-empty workspace-relative path")
    return relative


def within(root: Path, relative: Path) -> Path:
    resolved_root = root.resolve()
    candidate = (resolved_root / relative).resolve()
    try:
        candidate.relative_to(resolved_root)
    except ValueError as exc:
        raise ValueError("path escapes the managed workspace") from exc
    return candidate


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


class ManualRunRepository:
    def __init__(self, root: str | Path):
        self.root = Path(root).expanduser().resolve()
        self.runs_root = self.root / "runs"
        self.runs_root.mkdir(parents=True, exist_ok=True)

    def run_root(self, run_id: str) -> Path:
        return self.runs_root / normalize_run_id(run_id)

    def create(self, payload: Mapping[str, Any]) -> dict[str, Any]:
        request = str(payload.get("request") or "").strip()
        if not request:
            raise ValueError("request must not be empty")
        if len(request) > 100_000:
            raise ValueError("request exceeds 100,000 characters")
        raw_constraints = payload.get("constraints") or []
        if not isinstance(raw_constraints, list) or len(raw_constraints) > 32:
            raise ValueError("constraints must be an array with at most 32 items")
        constraints = [str(item).strip() for item in raw_constraints if str(item).strip()]
        if any(len(item) > 5_000 for item in constraints):
            raise ValueError("one constraint exceeds 5,000 characters")
        raw_retrieval = payload.get("retrieval_policy") or {}
        if not isinstance(raw_retrieval, Mapping):
            raise ValueError("retrieval_policy must be an object")
        retrieval = RetrievalRuntimeConfig.from_dict(raw_retrieval)
        supervisor_mode = str(
            payload.get("supervisor_mode") or "stateful_goal"
        ).strip()
        if supervisor_mode != "stateful_goal":
            raise ValueError("supervisor_mode must be stateful_goal")
        if payload.get("state_router_shadow", False) is not False:
            raise ValueError("state_router_shadow is retired")
        try:
            max_transitions = int(payload.get("max_transitions", 200))
        except (TypeError, ValueError) as exc:
            raise ValueError("max_transitions must be an integer") from exc
        if not 1 <= max_transitions <= 500:
            raise ValueError("max_transitions must be between 1 and 500")
        raw_seed_files = payload.get("seed_files") or []
        if not isinstance(raw_seed_files, list) or len(raw_seed_files) > 100:
            raise ValueError("seed_files must be an array with at most 100 items")
        seed_files: list[dict[str, str]] = []
        total_seed_bytes = 0
        seen_paths: set[str] = set()
        for item in raw_seed_files:
            if not isinstance(item, Mapping):
                raise ValueError("every seed file must be an object")
            relative = normalize_relative_path(str(item.get("path") or ""))
            normalized_path = relative.as_posix()
            if normalized_path in seen_paths:
                raise ValueError(f"duplicate seed file path: {normalized_path}")
            seen_paths.add(normalized_path)
            content = str(item.get("content") or "")
            total_seed_bytes += len(content.encode("utf-8"))
            seed_files.append({"path": normalized_path, "content": content})
        if total_seed_bytes > MAX_SEED_BYTES:
            raise ValueError("seed file content exceeds 5 MiB")

        supplied_id = str(payload.get("run_id") or "").strip()
        run_id = normalize_run_id(supplied_id) if supplied_id else self.new_run_id()
        run_root = self.run_root(run_id)
        run_root.mkdir(parents=False, exist_ok=False)
        workspace = run_root / "workspace"
        workspace.mkdir()
        (run_root / "state").mkdir()
        for item in seed_files:
            target = within(workspace, Path(item["path"]))
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(item["content"], encoding="utf-8")
        request_document = {
            "schema_version": SCHEMA_VERSION,
            "source": "local web UI user input",
            "version": "manual-v1",
            "purpose": "Run one transparent, workspace-scoped RWKV-LH manual test.",
            "generated_at": utc_now(),
            "run_id": run_id,
            "request": request,
            "constraints": constraints,
            "retrieval_policy": retrieval.to_dict(),
            "supervisor_mode": supervisor_mode,
            "execution_mode": "goal",
            "max_transitions": max_transitions,
            "seed_files": [
                {
                    "path": item["path"],
                    "size_bytes": len(item["content"].encode("utf-8")),
                    "sha256": hashlib.sha256(item["content"].encode("utf-8")).hexdigest(),
                }
                for item in seed_files
            ],
        }
        atomic_write_json(run_root / "request.json", request_document)
        metadata = {
            "schema_version": SCHEMA_VERSION,
            "run_id": run_id,
            "created_at": utc_now(),
            "updated_at": utc_now(),
            "phase": "queued",
            "active": False,
            "pid": None,
            "resume_count": 0,
            "request_preview": request[:240],
            "max_transitions": max_transitions,
            "state_created": False,
            "error": "",
        }
        atomic_write_json(run_root / "metadata.json", metadata)
        return metadata

    @staticmethod
    def new_run_id() -> str:
        stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
        return f"UI-{stamp}-{secrets.token_hex(3)}"

    def list_runs(self) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        for path in self.runs_root.iterdir():
            if not path.is_dir() or not RUN_ID_PATTERN.fullmatch(path.name):
                continue
            metadata = read_json(path / "metadata.json", {})
            if isinstance(metadata, dict) and metadata:
                rows.append(metadata)
        rows.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
        return rows

    def metadata(self, run_id: str) -> dict[str, Any]:
        path = self.run_root(run_id) / "metadata.json"
        metadata = read_json(path)
        if not isinstance(metadata, dict):
            raise FileNotFoundError(f"unknown run: {run_id}")
        return metadata

    def request_document(self, run_id: str) -> dict[str, Any]:
        document = read_json(self.run_root(run_id) / "request.json")
        if not isinstance(document, dict):
            raise FileNotFoundError(f"request document missing: {run_id}")
        return document

    def store(self, run_id: str) -> LongHorizonStore:
        return LongHorizonStore(self.run_root(run_id) / "state", checkpoint_retention=100_000)

    def summary(self, run_id: str) -> dict[str, Any]:
        metadata = self.metadata(run_id)
        output: dict[str, Any] = {"metadata": metadata, "request": self.request_document(run_id)}
        if metadata.get("state_created"):
            try:
                state = self.store(run_id).load(run_id)
            except StateRecoveryError as exc:
                output["state_error"] = f"{type(exc).__name__}: {exc}"
            else:
                activity = project_run_activity(state)
                output["state"] = {
                    "run_id": state.run_id,
                    "revision": state.revision,
                    "status": state.status.value,
                    "request": state.goal.request,
                    "goal_digest": state.goal.digest,
                    "actions": activity["actions"],
                    "direct_action_count": len(activity["direct_actions"]),
                    "atom_action_count": len(activity["atom_actions"]),
                    "artifact_count": len(state.artifacts),
                    "causal_record_count": len(state.causal_order),
                    "model_request_count": activity["rwkv_model_requests"],
                    "direct_model_request_count": activity[
                        "direct_model_requests"
                    ],
                    "atom_model_request_count": activity["atom_model_requests"],
                    "errors": state.errors[-8:],
                    "final_output": state.final_output,
                }
        result = read_json(self.run_root(run_id) / "result.json")
        if isinstance(result, dict):
            output["result"] = result
        return output

    def full_state(self, run_id: str) -> dict[str, Any]:
        metadata = self.metadata(run_id)
        if not metadata.get("state_created"):
            return {"run_id": run_id, "state": None}
        return {"run_id": run_id, "state": self.store(run_id).load(run_id).to_dict()}

    def events(self, run_id: str, *, after: int = 0, limit: int = 500) -> dict[str, Any]:
        metadata = self.metadata(run_id)
        if not metadata.get("state_created"):
            return {"events": [], "last_event_id": after}
        records = [
            item for item in self.store(run_id).event_records(run_id) if int(item["event_id"]) > after
        ][: max(1, min(limit, 2_000))]
        return {
            "events": records,
            "last_event_id": int(records[-1]["event_id"]) if records else after,
        }

    def trace(self, run_id: str, *, after: int = 0, limit: int = 300) -> dict[str, Any]:
        self.metadata(run_id)
        path = self.run_root(run_id) / "model_trace.jsonl"
        if not path.is_file():
            return {"events": [], "next_offset": after, "total": 0}
        lines = path.read_text(encoding="utf-8").splitlines()
        start = max(0, int(after))
        selected = lines[start : start + max(1, min(limit, 1_000))]
        records = []
        for line in selected:
            try:
                value = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(value, dict):
                records.append(value)
        return {"events": records, "next_offset": start + len(selected), "total": len(lines)}

    def files(self, run_id: str) -> list[dict[str, Any]]:
        self.metadata(run_id)
        workspace = self.run_root(run_id) / "workspace"
        rows = []
        for path in sorted(workspace.rglob("*")):
            if not path.is_file() or path.is_symlink():
                continue
            relative = path.relative_to(workspace).as_posix()
            rows.append(
                {
                    "path": relative,
                    "size_bytes": path.stat().st_size,
                    "sha256": file_sha256(path),
                    "media_type": mimetypes.guess_type(path.name)[0] or "application/octet-stream",
                }
            )
        return rows

    def file_bytes(self, run_id: str, relative_value: str) -> tuple[bytes, str]:
        self.metadata(run_id)
        workspace = self.run_root(run_id) / "workspace"
        path = within(workspace, normalize_relative_path(relative_value))
        if not path.is_file() or path.is_symlink():
            raise FileNotFoundError(relative_value)
        return path.read_bytes(), mimetypes.guess_type(path.name)[0] or "application/octet-stream"

    def export_zip(self, run_id: str) -> bytes:
        run_root = self.run_root(run_id)
        self.metadata(run_id)
        buffer = io.BytesIO()
        with zipfile.ZipFile(buffer, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            for path in sorted(run_root.rglob("*")):
                if (
                    not path.is_file()
                    or path.is_symlink()
                    or path.name == "long_horizon.db"
                    or path.name.endswith(("-wal", "-shm"))
                ):
                    continue
                archive.write(path, arcname=f"{run_id}/{path.relative_to(run_root).as_posix()}")
            database = run_root / "state" / "long_horizon.db"
            if database.is_file():
                source = sqlite3.connect(f"file:{database}?mode=ro", uri=True)
                snapshot = sqlite3.connect(":memory:")
                try:
                    source.backup(snapshot)
                    archive.writestr(
                        f"{run_id}/state/long_horizon.db",
                        snapshot.serialize(),
                    )
                    state = self.store(run_id).load(run_id)
                    archive.writestr(
                        f"{run_id}/state-export.json",
                        json.dumps(state.to_dict(), ensure_ascii=False, indent=2) + "\n",
                    )
                    archive.writestr(
                        f"{run_id}/events-export.json",
                        json.dumps(self.store(run_id).event_records(run_id), ensure_ascii=False, indent=2)
                        + "\n",
                    )
                except StateRecoveryError:
                    pass
                finally:
                    snapshot.close()
                    source.close()
        return buffer.getvalue()


class ManualRunManager:
    def __init__(self, repository: ManualRunRepository):
        self.repository = repository
        self._processes: dict[str, subprocess.Popen[bytes]] = {}
        self._lock = threading.Lock()

    def launch(self, run_id: str, *, resume: bool = False) -> dict[str, Any]:
        run_root = self.repository.run_root(run_id)
        # The child retains this claim across UI restarts, including a parent
        # crash between Popen and PID publication. Closing the parent's copy
        # must not unlock the shared open-file description held by the worker.
        with self._lock, (run_root / "worker.lock").open("a+b") as claim:
            try:
                fcntl.flock(claim.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as exc:
                raise RuntimeError("run is already active") from exc
            metadata = self.repository.metadata(run_id)
            process = self._processes.get(run_id)
            if ((process is not None and process.poll() is None)
                    or self._managed_pid_alive(run_id, metadata.get("pid"))):
                raise RuntimeError("run is already active")
            request = self.repository.request_document(run_id)
            update_metadata(
                run_root,
                active=True,
                phase="resuming" if resume else "starting",
                pid=None,
                error="",
                resume_count=int(metadata.get("resume_count", 0)) + int(resume),
            )
            command = [
                sys.executable,
                "-m",
                "rwkv_lh.web_worker",
                "--run-root",
                str(run_root),
                "--max-transitions",
                str(int(request["max_transitions"])),
            ]
            if resume:
                command.append("--resume")
            with (run_root / "worker.log").open("ab", buffering=0) as log:
                process = subprocess.Popen(
                    command,
                    cwd=str(PROJECT_ROOT),
                    env=os.environ.copy(),
                    stdout=log,
                    stderr=subprocess.STDOUT,
                    start_new_session=True,
                    pass_fds=(claim.fileno(),),
                )
            self._processes[run_id] = process
            current = self.repository.metadata(run_id)
            if current.get("phase") not in TERMINAL_PHASES:
                return update_metadata(run_root, active=True, pid=process.pid)
            return current

    def active(self, run_id: str) -> bool:
        with self._lock:
            process = self._processes.get(run_id)
            if process is not None:
                return process.poll() is None
        metadata = self.repository.metadata(run_id)
        return self._managed_pid_alive(run_id, metadata.get("pid"))

    def _managed_pid_alive(self, run_id: str, raw_pid: Any) -> bool:
        try:
            pid = int(raw_pid)
        except (TypeError, ValueError):
            return False
        if pid < 2:
            return False
        try:
            command = Path(f"/proc/{pid}/cmdline").read_bytes().replace(b"\x00", b" ").decode(
                "utf-8", errors="replace"
            )
        except OSError:
            return False
        expected_root = str(self.repository.run_root(run_id))
        return "rwkv_lh.web_worker" in command and expected_root in command

    def refresh_metadata(self, run_id: str) -> dict[str, Any]:
        metadata = self.repository.metadata(run_id)
        with self._lock:
            process = self._processes.get(run_id)
            if process is not None:
                code = process.poll()
                if code is not None and metadata.get("active"):
                    phase = metadata.get("phase")
                    if phase not in TERMINAL_PHASES:
                        metadata = update_metadata(
                            self.repository.run_root(run_id),
                            active=False,
                            pid=None,
                            phase="finished" if code == 0 else "failed",
                            exit_code=code,
                        )
            elif metadata.get("active") and not self._managed_pid_alive(
                run_id, metadata.get("pid")
            ):
                metadata = update_metadata(
                    self.repository.run_root(run_id),
                    active=False,
                    pid=None,
                    phase="failed",
                    error="manual UI worker process is no longer present",
                )
        return metadata


class WebServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(
        self,
        server_address: tuple[str, int],
        handler: type[BaseHTTPRequestHandler],
        repository: ManualRunRepository,
        manager: ManualRunManager,
    ):
        super().__init__(server_address, handler)
        self.repository = repository
        self.manager = manager


class WebHandler(BaseHTTPRequestHandler):
    server: WebServer
    protocol_version = "HTTP/1.1"

    def log_message(self, format: str, *args: Any) -> None:
        sys.stderr.write(f"{self.log_date_time_string()} {format % args}\n")

    def _headers(self, status: int, media_type: str, length: int, **extra: str) -> None:
        self.send_response(status)
        self.send_header("Content-Type", media_type)
        self.send_header("Content-Length", str(length))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header(
            "Content-Security-Policy",
            "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; "
            "connect-src 'self'; frame-ancestors 'none'",
        )
        for key, value in extra.items():
            self.send_header(key.replace("_", "-"), value)
        self.end_headers()

    def send_bytes(self, body: bytes, media_type: str, status: int = 200, **headers: str) -> None:
        self._headers(status, media_type, len(body), **headers)
        self.wfile.write(body)

    def send_json(self, payload: Any, status: int = 200) -> None:
        self.send_bytes(
            json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8"),
            "application/json; charset=utf-8",
            status,
        )

    def send_error_json(self, status: int, message: str) -> None:
        self.send_json({"error": message}, status)

    def read_body_json(self) -> dict[str, Any]:
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError as exc:
            raise ValueError("invalid Content-Length") from exc
        if length < 1 or length > MAX_REQUEST_BYTES:
            raise ValueError("request body must be between 1 byte and 6 MiB")
        raw = self.rfile.read(length)
        value = json.loads(raw.decode("utf-8"))
        if not isinstance(value, dict):
            raise ValueError("JSON request body must be an object")
        return value

    def do_GET(self) -> None:  # noqa: N802
        parsed = urlparse(self.path)
        path = parsed.path
        try:
            if path == "/api/capabilities":
                settings = get_runtime_settings()
                self.send_json(
                    {
                        "product": "RWKV Goal Studio",
                        "experimental": True,
                        "validation_status": "awaiting_all_zero_baseline",
                        "runtime": {
                            "model": settings.model,
                            "endpoint": settings.base_url,
                            "backend_profile": settings.backend_profile,
                            "max_model_len": settings.max_model_len,
                        },
                        "can": [
                            "可以尝试：隔离工作区内的 bug 修复、小中型项目创建、受限命令与公开检索",
                            "可以审计：查看当前任务的模型调用、Harness 结果、文件变化和终止原因",
                            "可以恢复：根据持久化任务记录恢复执行",
                        ],
                        "cannot": [
                            "当前统一协议尚未建立两遍 all-zero 基线，不能视为可靠 Agent 发布版本",
                            "不能稳定闭环通用 bug 修复或中型网页项目；真实轨迹仍会误选工具并漏写文件",
                            "联网检索成功不等于联网项目成功；证据到项目文件的执行链仍未通过",
                            "不能操作浏览器或隐式外发工作区数据；敏感数据和未知来源策略拒绝",
                            "不能直接管理真实 Git 仓库、提交、PR、部署或云服务",
                            "不能处理图片、PDF、Word、Excel、幻灯片等专用文档工作流",
                            "不能安装系统软件，也不能任意执行 shell 或访问隔离工作区外文件",
                            "不能在运行中向用户追问并根据新回答继续多轮协作",
                            "不能用其他模型替 RWKV 修复协议、判断答案或改写最终输出",
                        ],
                        "latest_formal": None,
                        "latest_diagnostic": None,
                    }
                )
                return
            if path == "/api/runtime/health":
                client = OpenAICompatibleRWKVClient()
                try:
                    health = client.health().to_dict()
                finally:
                    client.close()
                self.send_json(health)
                return
            if path == "/api/runtime/topology":
                executor_client = OpenAICompatibleRWKVClient()
                try:
                    executor = executor_client.health().to_dict()
                finally:
                    executor_client.close()
                selector_settings = NativeNetworkSelectorSettings.from_env()
                selector: dict[str, Any]
                if selector_settings is None:
                    selector = {
                        "available": False,
                        "error": "Selector identity is not configured",
                    }
                else:
                    try:
                        with urllib.request.urlopen(
                            selector_settings.base_url.rstrip("/") + "/healthz",
                            timeout=3,
                        ) as response:
                            selector_health = json.loads(
                                response.read().decode("utf-8")
                            )
                        actual_identity = selector_health.get("runtime_identity")
                        expected_identity = selector_settings.runtime_identity()
                        selector = {
                            "available": (
                                selector_health.get("status") == "ok"
                                and actual_identity == expected_identity
                            ),
                            "model": selector_settings.model,
                            "profile": selector_settings.state_profile_id,
                            "input_protocol": selector_settings.input_protocol,
                            "identity_verified": actual_identity == expected_identity,
                        }
                    except (OSError, ValueError, urllib.error.URLError) as exc:
                        selector = {
                            "available": False,
                            "model": selector_settings.model,
                            "error": f"{type(exc).__name__}: {exc}",
                        }
                try:
                    supervisor_settings = SupervisorAPISettings.from_env()
                    supervisor = {
                        "configured": True,
                        "model": supervisor_settings.model,
                        "mode": "stateful_goal",
                        "fallback_count": len(supervisor_settings.fallback_models),
                    }
                except (OSError, ValueError) as exc:
                    supervisor = {
                        "configured": False,
                        "error": f"{type(exc).__name__}: {exc}",
                    }
                self.send_json(
                    {
                        "schema_version": "rwkv-lh.goal-ui-topology.v1",
                        "supervisor": supervisor,
                        "selector": {
                            **selector,
                            "device": os.environ.get(
                                "RWKV_LH_SELECTOR_DEVICE_LABEL", "local GPU0"
                            ),
                        },
                        "executor": {
                            **executor,
                            "profile": os.environ.get(
                                "RWKV_STATE_PROFILE_ID", ""
                            ),
                            "device": os.environ.get(
                                "RWKV_LH_EXECUTOR_DEVICE_LABEL", "remote GPU0"
                            ),
                        },
                        "harness": {
                            "available": True,
                            "scope": "isolated workspace",
                            "audit": "append-only CausalEvent",
                        },
                    }
                )
                return
            if path == "/api/runs":
                rows = []
                for item in self.server.repository.list_runs():
                    rows.append(self.server.manager.refresh_metadata(str(item["run_id"])))
                self.send_json({"runs": rows})
                return
            match = re.fullmatch(r"/api/runs/([^/]+)(?:/(.*))?", path)
            if match:
                run_id = normalize_run_id(unquote(match.group(1)))
                suffix = match.group(2) or ""
                self.server.manager.refresh_metadata(run_id)
                query = parse_qs(parsed.query)
                if not suffix:
                    self.send_json(self.server.repository.summary(run_id))
                elif suffix == "state":
                    self.send_json(self.server.repository.full_state(run_id))
                elif suffix == "events":
                    self.send_json(
                        self.server.repository.events(
                            run_id,
                            after=int(query.get("after", ["0"])[0]),
                            limit=int(query.get("limit", ["500"])[0]),
                        )
                    )
                elif suffix == "trace":
                    self.send_json(
                        self.server.repository.trace(
                            run_id,
                            after=int(query.get("after", ["0"])[0]),
                            limit=int(query.get("limit", ["300"])[0]),
                        )
                    )
                elif suffix == "files":
                    self.send_json({"files": self.server.repository.files(run_id)})
                elif suffix.startswith("file/"):
                    body, media_type = self.server.repository.file_bytes(
                        run_id, unquote(suffix.removeprefix("file/"))
                    )
                    self.send_bytes(body, media_type)
                elif suffix == "export":
                    body = self.server.repository.export_zip(run_id)
                    self.send_bytes(
                        body,
                        "application/zip",
                        Content_Disposition=f'attachment; filename="{run_id}-audit.zip"',
                    )
                else:
                    self.send_error_json(404, "unknown run resource")
                return
            if path in {"/", "/index.html"}:
                self.send_asset("index.html")
                return
            if path.startswith("/assets/"):
                self.send_asset(path.removeprefix("/assets/"))
                return
            self.send_error_json(404, "not found")
        except FileNotFoundError as exc:
            self.send_error_json(404, str(exc))
        except (ValueError, json.JSONDecodeError) as exc:
            self.send_error_json(400, str(exc))
        except Exception as exc:
            self.send_error_json(500, f"{type(exc).__name__}: {exc}"[:500])

    def do_POST(self) -> None:  # noqa: N802
        path = urlparse(self.path).path
        try:
            if path == "/api/runs":
                metadata = self.server.repository.create(self.read_body_json())
                launched = self.server.manager.launch(str(metadata["run_id"]))
                self.send_json({"run": launched}, HTTPStatus.CREATED)
                return
            match = re.fullmatch(r"/api/runs/([^/]+)/resume", path)
            if not match:
                self.send_error_json(404, "not found")
                return
            run_id = normalize_run_id(unquote(match.group(1)))
            self.send_json({"run": self.server.manager.launch(run_id, resume=True)})
        except FileNotFoundError as exc:
            self.send_error_json(404, str(exc))
        except (ValueError, json.JSONDecodeError) as exc:
            self.send_error_json(400, str(exc))
        except RuntimeError as exc:
            self.send_error_json(409, str(exc))
        except Exception as exc:
            self.send_error_json(500, f"{type(exc).__name__}: {exc}"[:500])

    def send_asset(self, name: str) -> None:
        relative = normalize_relative_path(name)
        path = within(ASSET_ROOT, relative)
        if not path.is_file():
            raise FileNotFoundError(name)
        media_type = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
        self.send_bytes(path.read_bytes(), media_type)


def build_server(host: str, port: int, root: Path) -> WebServer:
    repository = ManualRunRepository(root)
    manager = ManualRunManager(repository)
    return WebServer((host, port), WebHandler, repository, manager)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Run the local RWKV-LH manual test UI")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8766)
    parser.add_argument(
        "--data-root",
        default=str(PROJECT_ROOT / "data" / "goal_ui_preview"),
    )
    parser.add_argument(
        "--allow-remote",
        action="store_true",
        help="Allow a non-loopback bind. No authentication is provided.",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    if args.host not in {"127.0.0.1", "::1", "localhost"} and not args.allow_remote:
        raise SystemExit("refusing non-loopback bind without --allow-remote")
    server = build_server(args.host, args.port, Path(args.data_root))
    print(
        json.dumps(
            {
                "url": f"http://{args.host}:{server.server_port}",
                "data_root": str(server.repository.root),
                "authentication": False,
                "scope": "local-only" if not args.allow_remote else "explicit-remote-bind",
            },
            ensure_ascii=False,
        ),
        flush=True,
    )
    try:
        server.serve_forever(poll_interval=0.25)
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0


__all__ = [
    "ManualRunManager",
    "ManualRunRepository",
    "WebHandler",
    "build_server",
    "main",
]


if __name__ == "__main__":
    raise SystemExit(main())

rwkv_lh/role_trace_context.py:
"""Reconstruct consumed context from checkpoint and session audit evidence.

Native checkpoints contain deltas, including display text that can omit a
generated stop.  A historical parent of a rollover is not a consumed prefix.
This module verifies those distinctions before exposing any reconstructed text.
Locally computed IDs are explicitly separate from unrecorded server input IDs.
"""

from __future__ import annotations

import hashlib
from collections import defaultdict
from dataclasses import dataclass
from functools import lru_cache
from typing import Any, Mapping, Sequence

from rwkv_lh.model_io import JSON_CALL_STOP_SUFFIXES
from rwkv_lh.runtime.native_state import NATIVE_STATE_PROTOCOL_VERSION, NativeStateCacheBinding
from rwkv_lh.schema import ModelCheckpoint, ModelCheckpointStatus
from rwkv_lh.token_budget import VOCAB_PATH, tokenizer


class TraceContextError(ValueError):
    """The supplied trace cannot prove the requested consumed context."""

    def __init__(self, reason: str, checkpoint_id: str):
        self.reason = reason
        self.checkpoint_id = checkpoint_id
        super().__init__(f"{reason}: {checkpoint_id}")


def _fail(reason: str, checkpoint_id: str) -> None:
    raise TraceContextError(reason, checkpoint_id)


def _sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _digest(value: Any) -> bool:
    return isinstance(value, str) and len(value) == 64 and all(c in "0123456789abcdef" for c in value)


def _advance(parent: str, delta: str) -> str:
    return _sha(parent + "\0" + _sha(delta))


@lru_cache(maxsize=1)
def _tokenizer_sha() -> str:
    return hashlib.sha256(VOCAB_PATH.read_bytes()).hexdigest()


_CREATION_TYPES = {
    "model_session_bootstrapped",
    "model_session_rolled_over",
    "model_session_event_appended",
    "model_session_tool_disclosed",
    "model_session_projected_event_acknowledged",
    "model_session_forked",
    "model_session_generation_returned",
}
_RESET_TYPES = {"model_session_bootstrapped", "model_session_rolled_over"}


@dataclass(frozen=True)
class _Node:
    checkpoint: ModelCheckpoint
    index: int
    event: Mapping[str, Any]
    binding: NativeStateCacheBinding | None


def _audit_identity(event: Mapping[str, Any], checkpoint: ModelCheckpoint) -> None:
    if event.get("lane_id") != checkpoint.lane_id or event.get("state_transport") != checkpoint.transport:
        _fail("audit_identity_mismatch", checkpoint.checkpoint_id)
    if "lane_kind" in event and event["lane_kind"] != checkpoint.lane_kind.value:
        _fail("audit_lane_kind_mismatch", checkpoint.checkpoint_id)


def _identity(checkpoint: ModelCheckpoint) -> dict[str, str]:
    metadata = checkpoint.native_state_metadata or {}
    model_sha = metadata.get("model_sha256")
    if (
        not checkpoint.model or not _digest(model_sha)
        or not checkpoint.state_profile_id or not _digest(checkpoint.state_profile_sha256)
    ):
        _fail("missing_model_or_initial_state_identity", checkpoint.checkpoint_id)
    return {
        "model": checkpoint.model,
        "model_sha256": model_sha,
        "state_profile_id": checkpoint.state_profile_id,
        "state_profile_sha256": checkpoint.state_profile_sha256,
        "state_profile_delivery": str(metadata.get("state_profile_delivery") or ""),
    }


def _binding(checkpoint: ModelCheckpoint) -> NativeStateCacheBinding:
    key = checkpoint.checkpoint_id
    metadata = checkpoint.native_state_metadata or {}
    try:
        binding = NativeStateCacheBinding.from_mapping(metadata["cache_binding"])
    except (KeyError, ValueError, TypeError, AttributeError) as exc:
        raise TraceContextError("missing_or_invalid_native_binding", key) from exc
    expected = (
        checkpoint.lane_id, checkpoint.lane_kind.value, checkpoint.model,
        metadata.get("model_sha256"), checkpoint.state_profile_id,
        checkpoint.state_profile_sha256, _sha("\0".join(checkpoint.event_ids)),
        checkpoint.transcript_digest,
    )
    observed = (
        binding.lane_id, binding.lane_kind, binding.model, binding.model_sha256,
        binding.state_profile_id, binding.state_profile_sha256,
        binding.event_ids_digest, binding.delta_digest,
    )
    if expected != observed or metadata.get("cache_binding_digest") != binding.digest:
        _fail("native_binding_identity_or_digest_mismatch", key)
    if (
        metadata.get("cache_role") != "disposable_acceleration"
        or metadata.get("authoritative") is not False
        or metadata.get("protocol_version") != NATIVE_STATE_PROTOCOL_VERSION
        or not metadata.get("server_build") or not metadata.get("tokenizer_build")
        or not _digest(checkpoint.native_state_digest) or not checkpoint.native_state_ref
        or not isinstance(checkpoint.native_state_export, Mapping) or not checkpoint.native_state_export
    ):
        _fail("invalid_native_snapshot_evidence", key)
    return binding


class _Evidence:
    def __init__(self, checkpoints: Mapping[str, Any], events: Sequence[Mapping[str, Any]]):
        self.checkpoints = checkpoints
        self.created: dict[str, list[tuple[int, Mapping[str, Any]]]] = defaultdict(list)
        self.started: dict[str, list[tuple[int, Mapping[str, Any]]]] = defaultdict(list)
        self.committed: dict[str, list[tuple[int, Mapping[str, Any]]]] = defaultdict(list)
        self.rolled_back: set[str] = set()
        for index, event in enumerate(events):
            if not isinstance(event, Mapping):
                _fail("invalid_audit_event", "")
            kind = event.get("type")
            if kind in _CREATION_TYPES:
                field = "candidate_checkpoint_id" if kind == "model_session_generation_returned" else "checkpoint_id"
                self.created[str(event.get(field) or "")].append((index, event))
            elif kind == "model_session_generation_started":
                self.started[str(event.get("request_id") or "")].append((index, event))
            elif kind == "model_session_candidate_committed":
                self.committed[str(event.get("checkpoint_id") or "")].append((index, event))
            elif kind == "model_session_candidate_rolled_back":
                self.rolled_back.add(str(event.get("candidate_checkpoint_id") or ""))

    @staticmethod
    def unique(items: Sequence[Any], reason: str, checkpoint_id: str):
        if len(items) != 1:
            _fail(reason, checkpoint_id)
        return items[0]

    def node(self, key: str) -> _Node:
        value = self.checkpoints.get(key)
        if value is None:
            _fail("missing_checkpoint", key)
        raw = value.to_dict() if isinstance(value, ModelCheckpoint) else value
        if not isinstance(raw, Mapping):
            _fail("invalid_checkpoint_record", key)
        if (
            not isinstance(raw.get("transcript"), str)
            or not isinstance(raw.get("token_count"), int)
            or isinstance(raw.get("token_count"), bool)
            or raw.get("token_count", -1) < 0
            or raw.get("transport") not in {"native_rwkv", "prompt_replay"}
        ):
            _fail("invalid_checkpoint_fields", key)
        try:
            checkpoint = ModelCheckpoint.from_dict(raw)
        except (ValueError, TypeError) as exc:
            raise TraceContextError("invalid_checkpoint_fields", key) from exc
        if checkpoint.checkpoint_id != key or checkpoint.parent_checkpoint_id == key:
            _fail("checkpoint_key_or_cycle_mismatch", key)
        if checkpoint.status != ModelCheckpointStatus.COMMITTED or key in self.rolled_back:
            _fail("checkpoint_not_committed", key)
        if checkpoint.transcript_digest != _sha(checkpoint.transcript):
            _fail("checkpoint_transcript_digest_mismatch", key)
        if checkpoint.token_count != len(tokenizer().encode(checkpoint.transcript)):
            _fail("checkpoint_token_count_mismatch", key)
        _identity(checkpoint)
        index, event = self.unique(self.created[key], "missing_or_ambiguous_creation_audit", key)
        _audit_identity(event, checkpoint)
        for field, expected in (
            ("transcript_digest", checkpoint.transcript_digest),
            ("state_digest", checkpoint.native_state_digest),
            ("token_count", checkpoint.token_count),
            ("visible_event_ids", checkpoint.event_ids),
        ):
            if field in event and event[field] != expected:
                _fail("creation_audit_checkpoint_mismatch", key)
        binding = _binding(checkpoint) if checkpoint.transport == "native_rwkv" else None
        return _Node(checkpoint, index, event, binding)

    def generation(self, node: _Node, parent: ModelCheckpoint, parent_ready: int) -> tuple[dict[str, Any], int]:
        checkpoint = node.checkpoint
        key = checkpoint.checkpoint_id
        event = node.event
        request = event.get("request_id")
        if not isinstance(request, str) or not request:
            _fail("missing_generation_request_id", key)
        started_index, started = self.unique(self.started[request], "missing_or_ambiguous_generation_start", key)
        committed_index, committed = self.unique(self.committed[key], "missing_or_ambiguous_generation_commit", key)
        _audit_identity(started, parent)
        _audit_identity(committed, checkpoint)
        native = checkpoint.transport == "native_rwkv"
        if (
            not parent_ready < started_index < node.index < committed_index
            or started.get("input_checkpoint_id") != parent.checkpoint_id
            or started.get("input_digest") != (parent.native_state_digest if native else parent.transcript_digest)
            or event.get("candidate_digest") != (checkpoint.native_state_digest if native else checkpoint.transcript_digest)
            or committed.get("candidate_id") != event.get("candidate_id")
            or (native and committed.get("state_digest") != checkpoint.native_state_digest)
        ):
            _fail("generation_lineage_or_order_mismatch", key)
        raw = event.get("raw_generation")
        if not isinstance(raw, Mapping):
            _fail("missing_raw_generation", key)
        output = event.get("raw_output")
        expected_text = checkpoint.transcript if native else checkpoint.transcript[len(parent.transcript):]
        if (
            not isinstance(output, str) or output != expected_text
            or raw.get("raw_output") != output or raw.get("raw_output_sha256") != _sha(output)
            or raw.get("raw_output_utf8_bytes") != len(output.encode("utf-8"))
            or raw.get("request_id") != request or raw.get("candidate_id") != event.get("candidate_id")
            or raw.get("finish_reason") != event.get("finish_reason")
            or raw.get("postprocessed") is not False
            or raw.get("state_profile_id") != checkpoint.state_profile_id
            or raw.get("state_profile_sha256") != checkpoint.state_profile_sha256
            or raw.get("sampling") != started.get("sampling")
            or raw.get("max_output_tokens") != started.get("max_tokens")
            or raw.get("response_model") not in {"", checkpoint.model}
        ):
            _fail("raw_generation_identity_mismatch", key)
        token_ids = raw.get("raw_token_ids")
        if not isinstance(token_ids, (list, tuple)) or any(
            not isinstance(item, int) or isinstance(item, bool) or item < 0 for item in token_ids
        ):
            _fail("invalid_raw_generation_token_ids", key)
        consumed_text = output
        removed_suffix = ""
        if native:
            if not token_ids:
                _fail("missing_native_generation_token_ids", key)
            try:
                consumed_text = tokenizer().decode_bytes(list(token_ids)).decode("utf-8")
            except (KeyError, UnicodeError, ValueError) as exc:
                raise TraceContextError("native_generation_tokens_not_decodable", key) from exc
            if consumed_text != output:
                if not consumed_text.startswith(output):
                    _fail("native_generation_token_text_mismatch", key)
                removed_suffix = consumed_text[len(output):]
                if raw.get("finish_reason") != "stop" or not any(
                    removed_suffix.startswith(stop) for stop in JSON_CALL_STOP_SUFFIXES
                ):
                    _fail("unattested_transport_suffix", key)
        return {
            "text": consumed_text,
            "raw_output": output,
            "raw_output_sha256": raw["raw_output_sha256"],
            "raw_token_ids": list(token_ids),
            "transport_removed_suffix": removed_suffix,
            "request_id": request,
            "candidate_id": event.get("candidate_id"),
            "generation_started_index": started_index,
            "generation_committed_index": committed_index,
        }, committed_index


def reconstruct_context(
    checkpoint_id: str,
    checkpoints: Mapping[str, ModelCheckpoint | Mapping[str, Any]],
    events: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Return proven consumed text and local token reconstruction, or fail.

    ``events`` must contain the original session audit mappings in causal order,
    without merging request IDs or deduplicating distinct events.  All consumed
    checkpoints must be committed.  A rollover's archived parent is explicitly
    excluded from the physical input and need not be present for reconstruction.

    ``reconstructed_token_ids`` excludes unrecorded BOS/special input tokens.
    Native input deltas are encoded separately; generated segments keep original
    token IDs, including a proven transport-removed stop.  Prompt replay encodes
    the single complete request text.  Neither is asserted to be a recorded
    server input token stream: ``token_ids`` is None until that is collected by
    the runtime.  Unknown special output IDs are rejected rather than guessed.
    """
    evidence = _Evidence(checkpoints, events)
    reverse: list[_Node] = []
    visited: set[str] = set()
    key = checkpoint_id
    while True:
        if key in visited:
            _fail("checkpoint_cycle", key)
        visited.add(key)
        node = evidence.node(key)
        reverse.append(node)
        if node.event["type"] in _RESET_TYPES:
            break
        parent_id = node.checkpoint.parent_checkpoint_id
        if not parent_id:
            _fail("missing_checkpoint_parent", key)
        key = parent_id
    nodes = list(reversed(reverse))
    root = nodes[0].checkpoint
    initial_state = {**_identity(root), "reset_checkpoint_id": root.checkpoint_id}
    segments: list[dict[str, Any]] = []
    chain: list[dict[str, Any]] = []
    ready_index = -1
    reconstructed_ids: list[int] = []
    for position, node in enumerate(nodes):
        checkpoint = node.checkpoint
        key = checkpoint.checkpoint_id
        event = node.event
        kind = event["type"]
        parent = nodes[position - 1].checkpoint if position else None
        if _identity(checkpoint) != _identity(root) or checkpoint.transport != root.transport:
            _fail("context_model_or_state_identity_changed", key)
        if node.index <= ready_index:
            _fail("checkpoint_audit_order_mismatch", key)
        operation = kind.removeprefix("model_session_")
        segment: dict[str, Any] = {
            "checkpoint_id": key, "operation": operation, "text": checkpoint.transcript,
            "raw_token_ids": [], "transport_removed_suffix": "",
        }
        record: dict[str, Any] = {
            "checkpoint_id": key, "parent_checkpoint_id": checkpoint.parent_checkpoint_id,
            "operation": operation, "audit_index": node.index,
            "transcript_digest": checkpoint.transcript_digest,
            "state_digest": checkpoint.native_state_digest,
            "event_ids": list(checkpoint.event_ids),
        }
        if parent is None:
            if kind == "model_session_bootstrapped":
                if checkpoint.parent_checkpoint_id is not None:
                    _fail("bootstrap_has_parent", key)
                for field, value in _identity(checkpoint).items():
                    if event.get(field) != value:
                        _fail("bootstrap_initial_identity_mismatch", key)
            elif (
                not checkpoint.parent_checkpoint_id
                or event.get("source_checkpoint_id") != checkpoint.parent_checkpoint_id
                or not event.get("rollover_id") or event.get("semantic_request_count") != 0
            ):
                _fail("invalid_rollover_reset_evidence", key)
            else:
                record["discarded_parent_checkpoint_id"] = checkpoint.parent_checkpoint_id
            if node.binding and (
                node.binding.parent_state_digest
                or node.binding.state_chain_digest != _advance("", checkpoint.transcript)
            ):
                _fail("native_reset_binding_mismatch", key)
        else:
            if kind != "model_session_generation_returned" and event.get("parent_checkpoint_id") != parent.checkpoint_id:
                _fail("audit_parent_checkpoint_mismatch", key)
            if kind != "model_session_forked" and (
                checkpoint.lane_id != parent.lane_id or checkpoint.lane_kind != parent.lane_kind
            ):
                _fail("continuation_changed_lane", key)
            if root.transport == "prompt_replay":
                if not checkpoint.transcript.startswith(parent.transcript):
                    _fail("replay_continuation_prefix_mismatch", key)
                segment["text"] = checkpoint.transcript[len(parent.transcript):]
            if node.binding:
                parent_binding = nodes[position - 1].binding
                if (
                    not parent_binding or node.binding.parent_state_digest != parent.native_state_digest
                    or node.binding.state_chain_digest != _advance(parent_binding.state_chain_digest, checkpoint.transcript)
                ):
                    _fail("native_parent_or_state_chain_mismatch", key)
            if kind == "model_session_generation_returned":
                generated, committed_index = evidence.generation(node, parent, ready_index)
                segment.update(generated)
                record["generation_started_index"] = generated["generation_started_index"]
                record["generation_committed_index"] = committed_index
                ready_index = committed_index
            if kind == "model_session_projected_event_acknowledged" and segment["text"] != "":
                _fail("acknowledgement_changed_input_text", key)
            if kind in {"model_session_generation_returned", "model_session_tool_disclosed"}:
                expected_events = parent.event_ids
            else:
                # Native fork audits identify the checkpoint, whose binding
                # attests the appended event ID; they do not repeat that ID.
                if kind == "model_session_forked" and node.binding:
                    event_id = checkpoint.event_ids[-1] if checkpoint.event_ids else None
                elif kind == "model_session_forked":
                    event_id = event.get("assignment_event_id")
                else:
                    event_id = event.get("event_id")
                if not isinstance(event_id, str) or not event_id:
                    _fail("missing_appended_event_id", key)
                expected_events = parent.event_ids + [event_id]
            if checkpoint.event_ids != expected_events:
                _fail("checkpoint_event_lineage_mismatch", key)
        ready_index = max(ready_index, node.index)
        if node.binding:
            record["cache_binding_digest"] = node.binding.digest
            record["state_chain_digest"] = node.binding.state_chain_digest
            record["parent_state_digest"] = node.binding.parent_state_digest
        segment_ids = (
            segment["raw_token_ids"] if root.transport == "native_rwkv" and kind == "model_session_generation_returned"
            else tokenizer().encode(segment["text"])
        )
        segment["reconstructed_token_ids"] = list(segment_ids)
        segment["text_sha256"] = _sha(segment["text"])
        reconstructed_ids.extend(segment_ids)
        segments.append(segment)
        chain.append(record)
    prompt_text = "".join(segment["text"] for segment in segments)
    if root.transport == "prompt_replay":
        if prompt_text != nodes[-1].checkpoint.transcript:
            _fail("replay_reconstruction_mismatch", checkpoint_id)
        reconstructed_ids = tokenizer().encode(prompt_text)
    return {
        "checkpoint_id": checkpoint_id,
        "transport": root.transport,
        "prompt_text": prompt_text,
        "prompt_sha256": _sha(prompt_text),
        "initial_state": initial_state,
        "segments": segments,
        "chain_evidence": chain,
        "token_ids": None,
        "token_ids_complete": False,
        "token_ids_limitation": "server_input_token_ids_and_bos_not_recorded",
        "reconstructed_token_ids": reconstructed_ids,
        "reconstructed_token_ids_include_bos": False,
        "local_tokenizer_sha256": _tokenizer_sha(),
    }


def bind_server_input_tokens(context: Mapping[str, Any], evidence: Mapping[str, Any]) -> dict[str, Any]:
    """Bind returned full input IDs, keeping absent/delta-only evidence explicit.

    The BOS count is the frozen transport's count. BOS IDs themselves come from
    the server trace; this never prepends a guessed special token to local IDs.
    Native generation must explicitly attest full_context, since /generate has
    no prompt and a delta token list cannot describe the parent recurrent State.
    """
    result = dict(context)
    ids = evidence.get("prompt_token_ids")
    if ids is None:
        return result
    if not isinstance(ids, (list, tuple)) or any(type(token) is not int or token < 0 for token in ids):
        _fail("invalid_server_input_token_ids", str(context.get("checkpoint_id", "")))
    scope = evidence.get("prompt_token_ids_scope")
    if scope not in {"full_prompt", "full_context"} or (
        context.get("transport") == "native_rwkv" and scope != "full_context"
    ):
        result["server_reported_input_token_ids"] = list(ids)
        result["token_ids_limitation"] = "server_input_scope_is_not_full_context"
        return result
    bos_count = evidence.get("input_bos_token_count")
    if type(bos_count) is not int or bos_count < 0:
        _fail("missing_server_input_bos_count", str(context.get("checkpoint_id", "")))
    reconstructed = context["reconstructed_token_ids"]
    if len(ids) != bos_count + len(reconstructed) or list(ids[bos_count:]) != reconstructed:
        _fail("server_input_token_ids_reconstruction_mismatch", str(context.get("checkpoint_id", "")))
    result.update(token_ids=list(ids), token_ids_complete=True, token_ids_source="server_returned",
                  input_bos_token_ids=list(ids[:bos_count]), token_ids_limitation=None)
    return result


__all__ = ["TraceContextError", "reconstruct_context", "bind_server_input_tokens"]

rwkv_lh/rwkv7_layout.py:
"""RWKV7 tensor geometry shared by artifact and StateTune adapters."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping


@dataclass(frozen=True)
class RWKV7Layout:
    layers: int
    width: int
    heads: int
    head_size: int
    intermediate: int
    vocab: int
    decay_rank: int
    a_rank: int
    v_rank: int
    gate_rank: int
    dtype: str

    def __post_init__(self) -> None:
        for name, value in vars(self).items():
            if name != "dtype" and (type(value) is not int or value <= 0):
                raise ValueError(f"RWKV7 {name} must be a positive integer")
        if self.width != self.heads * self.head_size:
            raise ValueError("RWKV7 head geometry differs from hidden width")
        if self.dtype not in {"float32", "float16", "bfloat16"}:
            raise ValueError("unsupported RWKV7 parameter dtype")

    @property
    def portable_state_shape(self) -> tuple[int, int, int, int]:
        """Layer, head, value, key; recurrent kernels use key, value instead."""
        return self.layers, self.heads, self.head_size, self.head_size

    @classmethod
    def from_native_weights(cls, weights: Mapping[str, Any]) -> "RWKV7Layout":
        def shape(name: str) -> tuple[int, ...]:
            if name not in weights:
                raise ValueError(f"RWKV7 layout is missing {name}")
            return tuple(int(size) for size in weights[name].shape)

        layers = sorted({int(name.split(".")[1]) for name in weights if name.startswith("blocks.")})
        if not layers or layers != list(range(len(layers))):
            raise ValueError("RWKV7 layer identities must be contiguous from zero")
        embedding = shape("emb.weight")
        if len(embedding) != 2 or shape("head.weight") != embedding:
            raise ValueError("RWKV7 embedding/output dimensions disagree")
        vocab, width = embedding
        heads = shape("blocks.0.att.r_k")
        ffn = shape("blocks.0.ffn.key.weight")
        if len(heads) != 2 or len(ffn) != 2 or ffn[1] != width:
            raise ValueError("RWKV7 head/FFN tensor geometry is invalid")

        def rank(layer: int, name: str) -> int:
            dimensions = shape(f"blocks.{layer}.att.{name}1")
            if len(dimensions) != 2 or dimensions[0] != width:
                raise ValueError(f"RWKV7 {name} rank tensor differs from hidden width")
            return dimensions[1]

        return cls(len(layers), width, heads[0], heads[1], ffn[0], vocab,
            rank(0, "w"), rank(0, "a"), rank(1 if len(layers) > 1 else 0, "v"),
            rank(0, "g"), str(weights["emb.weight"].dtype).removeprefix("torch."))

    @classmethod
    def from_config(cls, config: Mapping[str, Any]) -> "RWKV7Layout":
        return cls(config["num_hidden_layers"], config["hidden_size"], config["num_attention_heads"],
            config["head_size"], config["intermediate_size"], config["vocab_size"],
            config["decay_low_rank_dim"], config["a_low_rank_dim"], config["v_low_rank_dim"],
            config["gate_low_rank_dim"], config["torch_dtype"])

    def artifact_config(self, *, context_length: int, source_sha256: str,
                        bos_token_id: int = 0, eos_token_id: int = 0) -> dict[str, Any]:
        if type(context_length) is not int or context_length < 1:
            raise ValueError("RWKV7 context length must be explicitly positive")
        if len(source_sha256) != 64 or any(char not in "0123456789abcdef" for char in source_sha256):
            raise ValueError("RWKV7 source SHA-256 is invalid")
        if any(type(token) is not int or not 0 <= token < self.vocab for token in (bos_token_id, eos_token_id)):
            raise ValueError("RWKV7 special token is outside the actual vocabulary")
        return {
            "architectures": ["Rwkv7ForCausalLM"], "model_type": "rwkv7",
            "num_hidden_layers": self.layers, "hidden_size": self.width,
            "num_attention_heads": self.heads, "head_size": self.head_size,
            "intermediate_size": self.intermediate, "vocab_size": self.vocab,
            "decay_low_rank_dim": self.decay_rank, "a_low_rank_dim": self.a_rank,
            "v_low_rank_dim": self.v_rank, "gate_low_rank_dim": self.gate_rank,
            "torch_dtype": self.dtype, "context_length": context_length,
            "max_position_embeddings": context_length, "bos_token_id": bos_token_id,
            "eos_token_id": eos_token_id, "pad_token_id": eos_token_id,
            "embedding_layer_norm_fused": False, "tie_word_embeddings": False,
            "rwkv_source_sha256": source_sha256,
        }

rwkv_lh/role_trace_artifacts.py:
"""Deterministic audit artifacts for already verified production-trace samples.

This module does not extract role examples, invent labels, read regression files,
freeze datasets, or authorize training. The caller must prove provenance, rebuild
inputs with the production builders, and derive the coverage flags from durable
facts before passing samples here. Every written record is an audit candidate.
"""

from __future__ import annotations

from collections import Counter
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
import ctypes
import errno
import hashlib
import json
import math
import os
from pathlib import Path
import shutil
import tempfile
from typing import Any


ROLES = (
    "selector_intent", "executor_args", "auditor_step", "finalizer_answer",
    "auditor_final",
)
SPLITS = ("train", "dev", "confirmation")
SPLIT_SALT = "rwkv-lh-role-trace-family-v1"
SPLIT_BUCKETS = 10_000
SPLIT_BOUNDARIES = (8_000, 9_000, 10_000)
REQUIRED_COVERAGE = (
    "failed_last_action", "nonempty_error_type", "directory_target", "py_root",
    "json_root", "directory_root", "mutate", "execute", "missing_target",
)
SIMILARITY_THRESHOLD = 0.95
NGRAM_BYTES = 5
ARTIFACT_SCHEMA = "rwkv-lh-role-trace-artifacts-v1"
REGRESSION_SCHEMA = "rwkv-lh-role-trace-regression-candidate-v1"


@dataclass(frozen=True)
class ArtifactBundle:
    samples_by_split: dict[str, list[dict[str, Any]]]
    manifest: dict[str, Any]
    regression_candidate: dict[str, Any] | None


def _canonical_bytes(value: Any) -> bytes:
    try:
        return json.dumps(
            value, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError("artifact values must be finite UTF-8 JSON") from exc


def _copy_json(value: Any) -> Any:
    return json.loads(_canonical_bytes(value))


def _sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def split_project_family(project_family: str) -> str:
    """Assign an exact family id to the fixed 80/10/10 SHA-256 partition."""
    if not isinstance(project_family, str) or not project_family.strip():
        raise ValueError("project_family must be nonempty text")
    digest = hashlib.sha256(
        SPLIT_SALT.encode("utf-8") + b"\0" + project_family.encode("utf-8")
    ).hexdigest()
    bucket = int(digest, 16) % SPLIT_BUCKETS
    for split, end in zip(SPLITS, SPLIT_BOUNDARIES, strict=True):
        if bucket < end:
            return split
    raise AssertionError("split boundaries do not cover every bucket")


def _split_algorithm() -> dict[str, Any]:
    return {
        "name": "sha256_project_family_modulo",
        "salt": SPLIT_SALT,
        "input": "UTF8(salt) + 0x00 + UTF8(exact_project_family)",
        "digest_integer": "unsigned big-endian, full 256-bit digest",
        "modulo": SPLIT_BUCKETS,
        "bucket_ranges": {
            "train": [0, 7999], "dev": [8000, 8999], "confirmation": [9000, 9999],
        },
        "ratios": {"train": 0.8, "dev": 0.1, "confirmation": 0.1},
    }


def _grams(text: str) -> Counter[bytes]:
    raw = text.encode("utf-8")
    return Counter(raw[index:index + NGRAM_BYTES] for index in range(len(raw) - NGRAM_BYTES + 1))


def _cosine_parts(left: Counter[bytes], right: Counter[bytes]) -> tuple[int, int, int]:
    if len(left) > len(right):
        left, right = right, left
    dot = sum(count * right.get(gram, 0) for gram, count in left.items())
    return dot, sum(count * count for count in left.values()), sum(count * count for count in right.values())


def byte_5gram_cosine(left: str, right: str) -> float:
    """Cosine of unpadded UTF-8 byte 5-gram counts; identical short inputs are 1."""
    dot, left_sq, right_sq = _cosine_parts(_grams(left), _grams(right))
    if not left_sq or not right_sq:
        return float(left == right)
    return min(1.0, dot / math.sqrt(left_sq * right_sq))


def _validated_row(raw: Mapping[str, Any]) -> dict[str, Any]:
    if not isinstance(raw, Mapping):
        raise ValueError("each sample must be a JSON object")
    row = _copy_json(dict(raw))
    for field in ("sample_id", "role", "project_family", "input_text", "target_text"):
        if not isinstance(row.get(field), str) or not row[field].strip():
            raise ValueError(f"sample field {field} must be nonempty text")
    if row["role"] not in ROLES:
        raise ValueError(f"unknown sample role: {row['role']}")
    coverage = row.get("coverage")
    if not isinstance(coverage, dict) or any(
        type(coverage.get(flag)) is not bool for flag in REQUIRED_COVERAGE
    ):
        raise ValueError("coverage must contain every required flag as a boolean")
    expected_split = split_project_family(row["project_family"])
    if "split" in row and row["split"] != expected_split:
        raise ValueError("sample split disagrees with fixed project-family assignment")
    row["split"] = expected_split
    return row


def validate_coverage_requirements(value: Any, roles: list[str]) -> dict[str, list[str]]:
    if not isinstance(value, Mapping) or set(value) != set(roles):
        raise ValueError("coverage requirements must name exactly the requested roles")
    result = {}
    for role, flags in value.items():
        if (role not in ROLES or not isinstance(flags, list) or not flags
                or any(not isinstance(flag, str) or flag not in REQUIRED_COVERAGE for flag in flags)
                or len(flags) != len(set(flags))):
            raise ValueError("coverage requirements must contain nonempty unique known flags")
        result[role] = sorted(flags)
    return dict(sorted(result.items()))


def _regression_candidate(samples_by_split: Mapping[str, list[dict[str, Any]]], roles: list[str],
                          coverage_requirements: Mapping[str, list[str]], collection_condition: Mapping) -> dict[str, Any]:
    payload = {
        "schema": REGRESSION_SCHEMA,
        "purpose": "candidate_only_owner_freeze_required",
        "roles": roles,
        "coverage_requirements": _copy_json(coverage_requirements),
        "collection_condition": _copy_json(collection_condition),
        "split_algorithm": _split_algorithm(),
        "samples_by_split": {
            split: _copy_json(samples_by_split[split]) for split in ("dev", "confirmation")
        },
    }
    return {**payload, "fingerprint": _sha256(_canonical_bytes(payload))}


def _validate_prior(prior: Mapping[str, Any], expected: str | None) -> dict[str, Any]:
    if not isinstance(expected, str) or len(expected) != 64:
        raise ValueError("a pinned expected_regression_fingerprint is required for reuse")
    copied = _copy_json(dict(prior))
    fingerprint = copied.pop("fingerprint", None)
    if fingerprint != expected or _sha256(_canonical_bytes(copied)) != expected:
        raise ValueError("regression fingerprint mismatch; dev/confirmation are immutable")
    if copied.get("schema") != REGRESSION_SCHEMA or copied.get("split_algorithm") != _split_algorithm():
        raise ValueError("regression schema or split algorithm differs")
    roles = copied.get("roles")
    if not isinstance(roles, list) or not roles or roles != sorted(set(roles)) or any(role not in ROLES for role in roles):
        raise ValueError("regression roles are malformed")
    validate_coverage_requirements(copied.get("coverage_requirements"), roles)
    splits = copied.get("samples_by_split")
    if not isinstance(splits, dict) or set(splits) != {"dev", "confirmation"}:
        raise ValueError("regression requires the complete dev/confirmation identity")
    for split, rows in splits.items():
        if not isinstance(rows, list):
            raise ValueError("regression rows must be lists")
        for raw in rows:
            checked = _validated_row(raw)
            if checked != raw or checked["split"] != split or checked["role"] not in roles:
                raise ValueError("regression row identity or split changed")
        if any(not any(row["role"] == role for row in rows) for role in roles):
            raise ValueError("regression requires nonempty dev/confirmation for each role")
    copied["fingerprint"] = fingerprint
    return copied


def _similarity_audit(rows: list[dict[str, Any]]) -> dict[str, Any]:
    vectors = [_grams(row["input_text"]) for row in rows]
    comparisons = 0
    violations = []
    for left_index, left in enumerate(rows):
        for right_index in range(left_index + 1, len(rows)):
            right = rows[right_index]
            if left["role"] != right["role"] or left["split"] == right["split"]:
                continue
            comparisons += 1
            dot, left_sq, right_sq = _cosine_parts(vectors[left_index], vectors[right_index])
            if not left_sq or not right_sq:
                exceeds = left["input_text"] == right["input_text"]
                score = float(exceeds)
            else:
                # Exact integer comparison avoids float drift at the fixed 0.95 boundary.
                exceeds = dot * dot * 10_000 >= 9_025 * left_sq * right_sq
                score = min(1.0, dot / math.sqrt(left_sq * right_sq))
            if exceeds:
                violations.append({
                    "role": left["role"], "left_sample_id": left["sample_id"],
                    "right_sample_id": right["sample_id"], "left_split": left["split"],
                    "right_split": right["split"], "cosine": round(score, 12),
                })
    return {"compared_pairs": comparisons, "violations": violations}


def build_artifacts(
    samples: Iterable[Mapping[str, Any]], *, provenance: Mapping[str, Any],
    prior_regression: Mapping[str, Any] | None = None,
    expected_regression_fingerprint: str | None = None,
    coverage_requirements: Mapping[str, list[str]] | None = None,
) -> ArtifactBundle:
    """Audit verified rows; later rounds may add train rows and reuse pinned regression.

    Required row fields are sample_id, role, project_family, input_text (the full
    reconstructed context), target_text, and coverage (all REQUIRED_COVERAGE bools).
    Additional provenance/evidence fields are preserved in the row's identity.
    The optional prior regression is passed in memory: this function never opens
    held-out data. Its independent fingerprint must come from the prior freeze's
    registration, not be recomputed from the supplied rows.
    """
    rows = [_validated_row(row) for row in samples]
    provenance_copy = _copy_json(dict(provenance))
    prior = None
    if prior_regression is not None:
        prior = _validate_prior(prior_regression, expected_regression_fingerprint)
        if any(row["split"] != "train" for row in rows):
            raise ValueError("later rounds may add only train samples")
        if any(row["role"] not in prior["roles"] for row in rows):
            raise ValueError("later rounds cannot change regression roles")
        rows += [row for split in ("dev", "confirmation") for row in prior["samples_by_split"][split]]
    elif expected_regression_fingerprint is not None:
        raise ValueError("expected_regression_fingerprint requires prior_regression")
    ids = [row["sample_id"] for row in rows]
    if len(set(ids)) != len(ids):
        raise ValueError("sample_id must be globally unique")
    rows.sort(key=lambda row: (row["role"], row["project_family"], row["sample_id"]))
    roles = sorted({row["role"] for row in rows})
    requested_roles = provenance_copy.get("requested_roles", roles)
    if (not isinstance(requested_roles, list) or any(role not in ROLES for role in requested_roles)
            or len(set(requested_roles)) != len(requested_roles)):
        raise ValueError("requested_roles must be a role list")
    requirements = validate_coverage_requirements(
        coverage_requirements if coverage_requirements is not None else
        {role: list(REQUIRED_COVERAGE) for role in requested_roles}, requested_roles,
    )
    if prior is not None and requirements != prior["coverage_requirements"]:
        raise ValueError("coverage requirements are immutable with the frozen regression")
    contracts = {_canonical_bytes(row.get("role_data_collection")) for row in provenance_copy.get("source_runs", [])}
    if len(contracts) > 1:
        raise ValueError("one role dataset cannot mix different frozen upstream State conditions")
    collection_condition = {
        "coverage_scope_sha256": provenance_copy.get("coverage_scope_sha256"),
        "role_data_collection": json.loads(next(iter(contracts))) if contracts else None,
    }
    if prior is not None and collection_condition != prior.get("collection_condition"):
        raise ValueError("collection conditions are immutable with the frozen regression")
    samples_by_split = {split: [row for row in rows if row["split"] == split] for split in SPLITS}
    counts = {role: {split: sum(row["role"] == role for row in samples_by_split[split]) for split in SPLITS} for role in roles}
    coverage = {
        role: {flag: sum(row["coverage"][flag] for row in rows if row["role"] == role) for flag in REQUIRED_COVERAGE}
        for role in roles
    }
    similarity = _similarity_audit(rows)
    gates = {
        "nonempty_samples": bool(rows),
        "requested_roles_present": bool(requested_roles) and set(requested_roles) == set(roles),
        "nonempty_role_splits": bool(roles) and all(count > 0 for splits in counts.values() for count in splits.values()),
        "required_coverage_per_role": bool(requirements) and all(
            coverage.get(role, {}).get(flag, 0) > 0 for role, flags in requirements.items() for flag in flags),
        "cross_split_similarity": not similarity["violations"],
    }
    valid = all(gates.values())
    candidate = _regression_candidate(samples_by_split, roles, requirements, collection_condition) if valid else None
    if prior is not None and candidate is not None and candidate != prior:
        raise ValueError("reused regression fingerprint changed")
    manifest = {
        "schema": ARTIFACT_SCHEMA, "purpose": "audit_candidate_only",
        "status": "valid" if valid else "invalid", "provenance": provenance_copy,
        "recomputed_row_count": provenance_copy.get("recomputed_rows"),
        "row_count": len(rows), "counts_by_role": counts,
        "label_authority_counts_by_role": {
            role: dict(sorted(Counter(row.get("label_authority", "unreported")
                                      for row in rows if row["role"] == role).items()))
            for role in roles
        },
        "split_algorithm": _split_algorithm(),
        "similarity_parameters": {
            "name": "count_vector_cosine", "encoding": "utf-8", "ngram_bytes": NGRAM_BYTES,
            "padding": False, "text_field": "input_text", "comparison_scope": "same_role_cross_split",
            "threshold": SIMILARITY_THRESHOLD, "rejection_comparison": ">=",
            "zero_norm": "exact_text_equal_is_one_otherwise_zero",
        },
        "similarity_audit": similarity, "coverage_audit": coverage,
        "required_coverage": list(REQUIRED_COVERAGE), "quality_gates": gates,
        "coverage_requirements": requirements,
        "regression_reused": prior is not None,
        "regression_fingerprint": candidate["fingerprint"] if candidate is not None else None,
    }
    return ArtifactBundle(samples_by_split, manifest, candidate)


def _publish_no_replace(staging: Path, output: Path) -> None:
    """Linux atomic directory publication with RENAME_NOREPLACE (also race-safe)."""
    libc = ctypes.CDLL(None, use_errno=True)
    renameat2 = getattr(libc, "renameat2", None)
    if renameat2 is None:
        raise OSError(errno.ENOSYS, "atomic no-replace directory rename is required")
    renameat2.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
    renameat2.restype = ctypes.c_int
    if renameat2(-100, os.fsencode(staging), -100, os.fsencode(output), 1) != 0:
        error = ctypes.get_errno()
        raise OSError(error, os.strerror(error), str(output))


def write_artifacts(output_dir: str | Path, bundle: ArtifactBundle) -> dict[str, Any]:
    """Write an audit directory atomically; an existing path is never replaced."""
    output = Path(output_dir).absolute()
    if os.path.lexists(output):
        raise FileExistsError(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    staging = Path(tempfile.mkdtemp(prefix=f".{output.name}.staging-", dir=output.parent))
    try:
        rows = [row for split in SPLITS for row in bundle.samples_by_split[split]]
        files = {"candidates.jsonl": b"".join(_canonical_bytes(row) + b"\n" for row in rows)}
        if bundle.regression_candidate is not None:
            files["regression_candidate.json"] = _canonical_bytes(bundle.regression_candidate) + b"\n"
        manifest = _copy_json(bundle.manifest)
        review_queue = []
        for exclusion in manifest.get("provenance", {}).get("exclusions", []):
            row = exclusion.pop("review_candidate", None)
            if row is not None:
                review_queue.append(row)
                exclusion["review_candidate_id"] = row["sample_id"]
        if review_queue:
            files["review_queue.jsonl"] = b"".join(_canonical_bytes(row) + b"\n" for row in review_queue)
        manifest["review_candidate_counts_by_role"] = dict(sorted(Counter(row["role"] for row in review_queue).items()))
        manifest["files"] = {
            filename: {"sha256": _sha256(content), "bytes": len(content)}
            for filename, content in sorted(files.items())
        }
        files["manifest.json"] = _canonical_bytes(manifest) + b"\n"
        files["manifest.sha256"] = (_sha256(files["manifest.json"]) + "  manifest.json\n").encode("ascii")
        for filename, content in files.items():
            with (staging / filename).open("xb") as handle:
                handle.write(content)
                handle.flush()
                os.fsync(handle.fileno())
        directory_fd = os.open(staging, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
        _publish_no_replace(staging, output)
        return manifest
    finally:
        if staging.exists():
            shutil.rmtree(staging)

rwkv_lh/token_budget.py:
"""RWKV-token-aware counting and bounded text projection."""

from __future__ import annotations

from functools import lru_cache
from pathlib import Path

from rwkv_lh.tokenizer import RWKVTokenizer


VOCAB_PATH = Path(__file__).resolve().parent / "data" / "rwkv_vocab_v20230424.txt"


@lru_cache(maxsize=1)
def tokenizer() -> RWKVTokenizer:
    return RWKVTokenizer(str(VOCAB_PATH))


def get_token_count(text: str) -> int:
    return len(tokenizer().encode(str(text or ""))) if text else 0


def smart_truncate(text: str, max_tokens: int) -> tuple[str, str]:
    value = str(text or "")
    limit = max(1, int(max_tokens))
    tokens = tokenizer().encode(value)
    if len(tokens) <= limit:
        return value, ""
    prefix = tokenizer().decode_bytes(tokens[:limit]).decode("utf-8", errors="ignore")
    split = max(prefix.rfind("\n"), prefix.rfind(" "), prefix.rfind("。"))
    if split >= len(prefix) // 2:
        prefix = prefix[: split + 1]
    return prefix, value[len(prefix) :]


__all__ = ["VOCAB_PATH", "get_token_count", "smart_truncate", "tokenizer"]

rwkv_lh/role_feedback.py:
"""Pure projections of durable feedback, shared by runtime and trace replay."""

from __future__ import annotations

from collections.abc import Mapping
from copy import deepcopy
from typing import Any

from rwkv_lh.goal_state_protocols.feedback import validate_feedback
from rwkv_lh.goal_loop_protocol import GoalAuditDecision, rolling_goal_plan
from rwkv_lh.goal_state_protocols.execution_failures import build_rejections


def step_rejections(state: Any, step_id: str, step_revision: int) -> list[dict]:
    """Restore pre-execution failures since the last action on this exact step.

    Keep the semantic audit feedback separately: an invalid parameter call does
    not supersede the Auditor's still-unresolved task criterion.
    """
    plan = rolling_goal_plan(state)
    if step_id not in plan.steps or plan.step_revisions.get(step_id, 1) != step_revision:
        raise ValueError("rejections require the current committed step revision")
    records = []
    for event in _events(state):
        payload = event.payload
        if event.event_type == "action_started":
            break
        if event.event_type != "protocol_rejection_recorded" or payload.get("protocol_scope") != "action":
            continue
        if (payload.get("active_step_id"), payload.get("active_step_revision")) != (step_id, step_revision):
            continue
        if not payload.get("selection_id") or not payload.get("selected_operation"):
            continue
        records.append({"event_id": event.event_id, "selection_id": payload["selection_id"],
            "step_id": step_id, "step_revision": step_revision,
            "selected_operation": payload["selected_operation"],
            "rejected_arguments": payload.get("rejected_arguments") or {},
            "error_kind": str(payload.get("error_kind") or ""), "error": payload["error"],
            "action_executed": False})
    return build_rejections(list(reversed(records)))


def _events(state):
    return (state.causal_records[key] for key in reversed(state.causal_order))


def _copy(value, *, recipient=None):
    checked = validate_feedback(value, recipient=recipient)
    return deepcopy(dict(checked)) if checked is not None else None


def feedback_for_audit(state: Any, audit_id: str) -> dict | None:
    for event in _events(state):
        if event.event_type == "goal_audit_accepted" and event.payload.get("audit_id") == audit_id:
            feedback = event.payload.get("feedback")
            if feedback is None and (event.payload.get("audit") or {}).get("verdict") == "repair":
                raise ValueError("accepted repair is missing its current feedback contract")
            return _copy(feedback)
    raise ValueError("feedback requires a durable accepted audit")


def step_feedback(state: Any, step_id: str, step_revision: int) -> dict | None:
    plan = rolling_goal_plan(state)
    if plan.step_revisions.get(step_id, 1) != step_revision:
        raise ValueError("feedback requires the current step revision")
    boundaries = {event.subject_id: event.payload for event in _events(state)
                  if event.event_type == "goal_audit_boundary_opened"}
    for event in _events(state):
        if event.event_type != "goal_audit_accepted":
            continue
        bound = boundaries.get(event.payload.get("audit_boundary_id"), {})
        if (bound.get("active_step_id"), bound.get("active_step_revision")) != (step_id, step_revision):
            continue
        feedback = feedback_for_audit(state, event.payload["audit_id"])
        if feedback is not None and (feedback["step_id"], feedback["step_revision"]) != (step_id, step_revision):
            raise ValueError("audit feedback and boundary disagree on step identity")
        return feedback
    return None


def protocol_feedback(state: Any, role: str, boundary_id: str) -> dict | None:
    for event in _events(state):
        if event.event_type == "protocol_rejection_recorded":
            value = event.payload.get("feedback")
            if isinstance(value, Mapping) and value.get("source_role") == role and value.get("boundary_id") == boundary_id:
                return _copy(value, recipient=role)
    return None


def rejected_audit_output(state: Any, request_id: str, boundary_id: str) -> str:
    """Recover the exact rejected generation from its durable audit boundary."""
    if not request_id:
        # A pre-generation contract failure has no rejected model output.
        return ""
    for event in _events(state):
        payload = event.payload
        if (event.event_type == "goal_audit_recorded"
            and payload.get("request_id") == request_id
            and payload.get("audit_boundary_id") == boundary_id):
            raw = (payload.get("raw_generation") or {}).get("raw_output")
            if not isinstance(raw, str):
                raise ValueError("rejected audit generation lacks its raw output")
            return raw
    raise ValueError("rejected audit request has no matching durable boundary")


def audit_protocol_rejections(state: Any, boundary_id: str) -> int:
    count = 0
    for event in _events(state):
        if event.event_type == "run_started" and event.payload.get("protocol_rejection_budget_reset"):
            break
        if event.event_type == "protocol_rejection_recorded" and event.payload.get("audit_boundary_id") == boundary_id:
            count += 1
    return count


def finalizer_feedback(state: Any) -> dict | None:
    revision = len(rolling_goal_plan(state).patch_ids)
    for event in _events(state):
        if event.event_type == "goal_plan_patch_committed":
            break
        if event.event_type == "goal_final_rejected":
            value = event.payload.get("feedback")
            if isinstance(value, Mapping) and value.get("plan_revision") == revision and "finalizer_answer" in value.get("recipient_roles", ()):
                return _copy(value, recipient="finalizer_answer")
    return None


def finalizer_retry_feedback(state: Any) -> dict | None:
    revision = len(rolling_goal_plan(state).patch_ids)
    for event in _events(state):
        if event.event_type in {"goal_plan_patch_committed", "goal_final_rejected"}:
            break
        if event.event_type == "model_call_accepted" and event.payload.get("model_role") == "finalizer_answer":
            break
        if event.event_type == "protocol_rejection_recorded":
            value = event.payload.get("feedback")
            if isinstance(value, Mapping) and value.get("plan_revision") == revision and value.get("source_role") == "finalizer_answer":
                return _copy(value, recipient="finalizer_answer")
    return None


def pending_final_execution_repair(state: Any) -> tuple[GoalAuditDecision, dict] | None:
    revision = len(rolling_goal_plan(state).patch_ids)
    consumed = {event.payload.get("source_audit_id") for event in _events(state)
                if event.event_type == "goal_plan_patch_committed"}
    for event in _events(state):
        if event.event_type != "goal_final_rejected":
            continue
        feedback = event.payload.get("feedback")
        if not isinstance(feedback, Mapping) or feedback.get("plan_revision") != revision:
            continue
        if "planner" not in feedback.get("recipient_roles", ()) or event.payload.get("audit_id") in consumed:
            return None
        checked = _copy(feedback, recipient="planner")
        for accepted in _events(state):
            if accepted.event_type == "goal_audit_accepted" and accepted.payload.get("audit_id") == event.payload.get("audit_id"):
                return GoalAuditDecision.from_dict(accepted.payload["audit"]), checked
        raise ValueError("final execution repair lacks an accepted audit")
    return None

rwkv_lh/trace_comparator_v2.py:
"""Deterministic current-run trace comparison without semantic guesswork.

The comparator identifies role errors only from mechanical invariants or a
pre-frozen local checkpoint oracle. An external task failure without such a
link remains unattributed; it is never back-filled as a Selector error.
"""

from __future__ import annotations

import hashlib
import json
from collections import Counter
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping, Sequence


TRACE_COMPARISON_SCHEMA = "rwkv-lh.trace-comparison.v2"
TRACE_ORACLE_SCHEMA = "rwkv-lh.trace-checkpoint-oracle.v2"


def sha256_path(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def _mapping(value: Any) -> Mapping[str, Any]:
    return value if isinstance(value, Mapping) else {}


def _event_data(event: Mapping[str, Any]) -> Mapping[str, Any]:
    return _mapping(event.get("data") or event.get("payload"))


def _event_position(event: Mapping[str, Any], fallback: int) -> tuple[int, int]:
    event_id = event.get("event_id")
    revision = event.get("revision")
    return (
        int(event_id) if isinstance(event_id, int) else fallback,
        int(revision) if isinstance(revision, int) else fallback,
    )


def _rejection_identities(data: Mapping[str, Any]) -> frozenset[str]:
    """Return stable identities shared by transient and durable rejection events."""

    return frozenset(
        str(value)
        for value in (data.get("request_id"), data.get("decision_id"))
        if str(value or "")
    )


def _planner_failure_recovered_before_action(
    events: Sequence[Mapping[str, Any]], event_index: int
) -> bool:
    """A rejected draft is not an Agent anomaly when its repair commits first.

    Strong Planner validation can reject a draft and immediately request one
    semantic repair.  The rejected draft never becomes executable state.  It
    is therefore diagnostic, rather than the first causal error, when a valid
    plan is committed before any action session or terminal boundary.
    """

    action_or_terminal_boundaries = {
        "action_session_started",
        "exact_tool_selection_staged",
        "model_call_accepted",
        "action_started",
        "run_blocked",
        "run_completed",
        "run_failed",
        "run_yielded",
    }
    for later in events[event_index + 1 :]:
        event_type = str(later.get("type") or "")
        if event_type == "goal_plan_patch_committed":
            return True
        if event_type in action_or_terminal_boundaries:
            return False
    return False


@dataclass(frozen=True)
class CheckpointOracle:
    step_id: str
    step_revision: int | None
    occurrence: int
    acceptable_operations: tuple[str, ...]
    expected_executor_params: Mapping[str, Any] | None
    expected_step_completed: bool | None

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "CheckpointOracle":
        operations = tuple(str(item) for item in value.get("acceptable_operations") or ())
        if not operations or len(set(operations)) != len(operations):
            raise ValueError("oracle acceptable_operations must be non-empty and unique")
        revision = value.get("step_revision")
        expected_params = value.get("expected_executor_params")
        if expected_params is not None and not isinstance(expected_params, Mapping):
            raise ValueError("expected_executor_params must be an object")
        expected_completed = value.get("expected_step_completed")
        if expected_completed is not None and not isinstance(expected_completed, bool):
            raise ValueError("expected_step_completed must be boolean")
        result = cls(
            step_id=str(value.get("step_id") or ""),
            step_revision=(int(revision) if revision is not None else None),
            occurrence=int(value.get("occurrence", 1)),
            acceptable_operations=operations,
            expected_executor_params=(dict(expected_params) if expected_params is not None else None),
            expected_step_completed=expected_completed,
        )
        if not result.step_id or result.occurrence < 1:
            raise ValueError("oracle checkpoint identity is invalid")
        return result


def load_oracle(path: Path | None) -> tuple[dict[str, tuple[CheckpointOracle, ...]], str]:
    if path is None:
        return {}, ""
    path = path.resolve()
    value = _read_json(path)
    if value.get("schema_version") != TRACE_ORACLE_SCHEMA:
        raise ValueError("unsupported trace checkpoint oracle")
    cases = value.get("cases")
    if not isinstance(cases, Mapping):
        raise ValueError("trace oracle cases must be an object")
    result: dict[str, tuple[CheckpointOracle, ...]] = {}
    for task_id, raw in cases.items():
        if not isinstance(raw, list):
            raise ValueError(f"trace oracle case must be an array: {task_id}")
        checkpoints = tuple(CheckpointOracle.from_dict(_mapping(item)) for item in raw)
        identities = [
            (item.step_id, item.step_revision, item.occurrence) for item in checkpoints
        ]
        if len(identities) != len(set(identities)):
            raise ValueError(f"duplicate trace oracle checkpoint: {task_id}")
        result[str(task_id)] = checkpoints
    return result, sha256_path(path)


def _selection_payload(data: Mapping[str, Any]) -> Mapping[str, Any]:
    selection = _mapping(data.get("selection"))
    raw = _mapping(selection.get("raw_selection"))
    if raw:
        return raw
    attestation = _mapping(data.get("selector_attestation"))
    return _mapping(attestation.get("raw_selection")) or selection or data


def _frontier_payload(event: Mapping[str, Any]) -> Mapping[str, Any] | None:
    if str(event.get("type") or "") != "action_observation_appended":
        return None
    model_event = _mapping(_event_data(event).get("model_event"))
    if str(model_event.get("event_type") or "") != "goal_frontier_assignment":
        return None
    return _mapping(_mapping(model_event.get("payload")).get("active_step"))


def _find_oracle(
    checkpoints: Sequence[CheckpointOracle],
    *,
    step_id: str,
    step_revision: int | None,
    occurrence: int,
) -> CheckpointOracle | None:
    for checkpoint in checkpoints:
        if (
            checkpoint.step_id == step_id
            and checkpoint.occurrence == occurrence
            and (
                checkpoint.step_revision is None
                or checkpoint.step_revision == step_revision
            )
        ):
            return checkpoint
    return None


def _anomaly(
    *,
    role: str,
    kind: str,
    event: Mapping[str, Any],
    event_index: int,
    evidence: Mapping[str, Any],
) -> dict[str, Any]:
    event_id, revision = _event_position(event, event_index + 1)
    return {
        "role": role,
        "kind": kind,
        "confidence": "exact",
        "event_index": event_index,
        "event_id": event_id,
        "revision": revision,
        "event_type": str(event.get("type") or ""),
        "evidence": dict(evidence),
    }


def analyze_case(
    *,
    task_id: str,
    result: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
    oracle: Sequence[CheckpointOracle] = (),
) -> dict[str, Any]:
    frontier: Mapping[str, Any] = {}
    frontier_occurrences: Counter[tuple[str, int | None]] = Counter()
    selection_count = 0
    selection_records: list[dict[str, Any]] = []
    anomalies: list[dict[str, Any]] = []
    active_selection: dict[str, Any] | None = None
    started_actions: dict[str, tuple[int, Mapping[str, Any]]] = {}
    finished_actions: set[str] = set()
    repeated_selections: Counter[tuple[str, str]] = Counter()
    repeated_results: Counter[str] = Counter()
    audit_gap_count = 0
    audit_decision_count = 0
    audit_repair_count = 0
    audit_reported_gap_count = 0
    protocol_rejection_count = 0
    action_protocol_rejection_count = 0
    audit_protocol_rejection_count = 0
    recovered_planner_failures: list[dict[str, Any]] = []
    durable_rejection_identities = {
        identity
        for event in events
        if str(event.get("type") or "") == "protocol_rejection_recorded"
        for identity in _rejection_identities(_event_data(event))
    }

    for index, event in enumerate(events):
        event_type = str(event.get("type") or "")
        data = _event_data(event)
        new_frontier = _frontier_payload(event)
        if new_frontier is not None:
            frontier = new_frontier
            continue
        if event_type in {"strong_planner_patch_rejected", "strong_planner_call_failed"}:
            if _planner_failure_recovered_before_action(events, index):
                event_id, revision = _event_position(event, index + 1)
                recovered_planner_failures.append(
                    {
                        "event_index": index,
                        "event_id": event_id,
                        "revision": revision,
                        "event_type": event_type,
                        "recovered_before_action": True,
                    }
                )
                continue
            anomalies.append(
                _anomaly(
                    role="planner",
                    kind=event_type,
                    event=event,
                    event_index=index,
                    evidence={"error": data.get("error"), "reason": data.get("reason")},
                )
            )
            continue
        if event_type == "protocol_rejection_recorded":
            protocol_rejection_count += 1
            protocol_scope = str(data.get("protocol_scope") or "")
            if protocol_scope == "goal_audit":
                role = "auditor"
                kind = "auditor_protocol_rejected"
                audit_protocol_rejection_count += 1
            else:
                role = "executor"
                kind = "executor_protocol_rejected"
                action_protocol_rejection_count += 1
            anomalies.append(
                _anomaly(
                    role=role,
                    kind=kind,
                    event=event,
                    event_index=index,
                    evidence={
                        "protocol_scope": protocol_scope,
                        "request_id": data.get("request_id"),
                        "decision_id": data.get("decision_id"),
                        "selected_operation": data.get("selected_operation"),
                        "reason": data.get("reason"),
                        "error": data.get("error"),
                    },
                )
            )
            continue
        if event_type in {"model_protocol_rejected", "model_call_rejected"}:
            # A model_call_rejected event is the transient half of the durable
            # protocol_rejection_recorded event when request/decision IDs match.
            # Count and attribute the durable event exactly once.
            if _rejection_identities(data) & durable_rejection_identities:
                continue
            protocol_rejection_count += 1
            anomalies.append(
                _anomaly(
                    role="executor",
                    kind="executor_protocol_rejected_without_durable_record",
                    event=event,
                    event_index=index,
                    evidence={"reason": data.get("reason"), "error": data.get("error")},
                )
            )
            continue
        if event_type == "exact_tool_selection_rejected":
            protocol_rejection_count += 1
            anomalies.append(
                _anomaly(
                    role="selector",
                    kind="selector_selection_rejected",
                    event=event,
                    event_index=index,
                    evidence={"reason": data.get("reason"), "error": data.get("error")},
                )
            )
            continue
        if event_type == "exact_tool_selection_staged":
            selection_count += 1
            step_id = str(frontier.get("step_id") or "")
            raw_revision = frontier.get("step_revision")
            step_revision = int(raw_revision) if raw_revision is not None else None
            identity = (step_id, step_revision)
            frontier_occurrences[identity] += 1
            occurrence = frontier_occurrences[identity]
            selection = _selection_payload(data)
            selected = str(
                selection.get("selected_operation")
                or data.get("selected_operation")
                or ""
            )
            eligible = tuple(str(item) for item in selection.get("eligible_labels") or ())
            matched = _find_oracle(
                oracle,
                step_id=step_id,
                step_revision=step_revision,
                occurrence=occurrence,
            )
            record = {
                "selection_index": selection_count,
                "event_index": index,
                "step_id": step_id,
                "step_revision": step_revision,
                "occurrence": occurrence,
                "objective": str(frontier.get("objective") or ""),
                "selected_operation": selected,
                "eligible_labels": list(eligible),
                "selector_profile_id": str(
                    selection.get("profile_id")
                    or _mapping(data.get("selection")).get("selector_profile_id")
                    or ""
                ),
                "selector_profile_sha256": str(
                    selection.get("profile_sha256")
                    or _mapping(data.get("selection")).get("selector_profile_sha256")
                    or ""
                ),
                "selector_decoder_id": str(
                    selection.get("decoder_id")
                    or _mapping(data.get("selection")).get("selector_decoder_id")
                    or ""
                ),
                "selector_decoder_sha256": str(
                    selection.get("decoder_sha256")
                    or _mapping(data.get("selection")).get(
                        "selector_decoder_sha256"
                    )
                    or ""
                ),
                "selector_decoder_protocol": str(
                    selection.get("decoder_protocol")
                    or _mapping(data.get("selection")).get(
                        "selector_decoder_protocol"
                    )
                    or ""
                ),
                "oracle_matched": matched is not None,
                "acceptable_operations": (
                    list(matched.acceptable_operations) if matched is not None else []
                ),
            }
            selection_records.append(record)
            active_selection = {"record": record, "oracle": matched}
            repeated_selections[(step_id, selected)] += 1
            if matched is not None:
                allowed = set(matched.acceptable_operations)
                if not (allowed & set(eligible)):
                    anomalies.append(
                        _anomaly(
                            role="controller",
                            kind="required_operation_absent_from_eligibility",
                            event=event,
                            event_index=index,
                            evidence={
                                "step_id": step_id,
                                "acceptable_operations": sorted(allowed),
                                "eligible_labels": list(eligible),
                            },
                        )
                    )
                elif selected not in allowed:
                    anomalies.append(
                        _anomaly(
                            role="selector",
                            kind="selected_operation_outside_oracle_set",
                            event=event,
                            event_index=index,
                            evidence={
                                "step_id": step_id,
                                "selected_operation": selected,
                                "acceptable_operations": sorted(allowed),
                            },
                        )
                    )
            continue
        if event_type == "model_call_accepted":
            operation = str(data.get("operation") or "")
            if active_selection is not None:
                selected = active_selection["record"]["selected_operation"]
                if operation != selected:
                    anomalies.append(
                        _anomaly(
                            role="executor",
                            kind="executor_changed_selected_operation",
                            event=event,
                            event_index=index,
                            evidence={"selected_operation": selected, "executor_operation": operation},
                        )
                    )
                checkpoint = active_selection["oracle"]
                if checkpoint is not None and checkpoint.expected_executor_params is not None:
                    normalized = _mapping(
                        _mapping(data.get("argument_normalization")).get("normalized_action")
                    )
                    actual_params = _mapping(normalized.get("arguments"))
                    if dict(actual_params) != dict(checkpoint.expected_executor_params):
                        anomalies.append(
                            _anomaly(
                                role="executor",
                                kind="executor_params_differ_from_oracle",
                                event=event,
                                event_index=index,
                                evidence={
                                    "expected_params": dict(checkpoint.expected_executor_params),
                                    "actual_params": dict(actual_params),
                                },
                            )
                        )
            continue
        if event_type == "action_started":
            action_id = str(data.get("action_id") or "")
            if action_id:
                started_actions[action_id] = (index, event)
            continue
        if event_type == "action_finished":
            action_id = str(data.get("action_id") or "")
            finished_actions.add(action_id)
            digest = str(data.get("result_digest") or "")
            if digest:
                repeated_results[digest] += 1
            continue
        if event_type == "goal_step_evidence_gap_recorded":
            audit_gap_count += 1
            continue
        if event_type == "goal_audit_recorded":
            audit_decision_count += 1
            audit = _mapping(data.get("audit"))
            verdict = str(audit.get("verdict") or "")
            gaps = tuple(str(item) for item in audit.get("gaps") or ())
            audit_reported_gap_count += len(gaps)
            if verdict == "repair":
                audit_repair_count += 1
            if active_selection is None:
                continue
            checkpoint = active_selection["oracle"]
            audited_step_id = str(audit.get("step_id") or "")
            selected_step_id = str(active_selection["record"].get("step_id") or "")
            if (
                checkpoint is not None
                and checkpoint.expected_step_completed is not None
                and audited_step_id == selected_step_id
            ):
                completed_steps = {
                    str(_mapping(item).get("step_id") or "")
                    for item in audit.get("completed_steps") or ()
                }
                actual = audited_step_id in completed_steps
                if actual != checkpoint.expected_step_completed:
                    anomalies.append(
                        _anomaly(
                            role="auditor",
                            kind="audit_completion_differs_from_oracle",
                            event=event,
                            event_index=index,
                            evidence={
                                "expected_step_completed": checkpoint.expected_step_completed,
                                "actual_step_completed": actual,
                                "verdict": verdict,
                                "gaps": list(gaps),
                            },
                        )
                    )
            continue

    for action_id, (index, event) in started_actions.items():
        if action_id not in finished_actions:
            anomalies.append(
                _anomaly(
                    role="harness",
                    kind="started_action_has_no_terminal_event",
                    event=event,
                    event_index=index,
                    evidence={"action_id": action_id},
                )
            )
    anomalies.sort(key=lambda item: (item["event_index"], item["role"], item["kind"]))
    first = anomalies[0] if anomalies else None
    first_index = int(first["event_index"]) if first is not None else -1
    amplification: list[dict[str, Any]] = []
    if first is not None:
        for index, event in enumerate(events):
            if index <= first_index:
                continue
            event_type = str(event.get("type") or "")
            data = _event_data(event)
            if event_type in {
                "action_started",
                "action_finished",
                "goal_step_evidence_gap_recorded",
                "goal_audit_boundary_resolved",
                "run_blocked",
                "run_yielded",
            }:
                event_id, revision = _event_position(event, index + 1)
                amplification.append(
                    {
                        "event_index": index,
                        "event_id": event_id,
                        "revision": revision,
                        "event_type": event_type,
                        "action_id": str(data.get("action_id") or ""),
                        "reason": str(data.get("reason") or ""),
                        "step_completed": data.get("step_completed"),
                    }
                )
    repeated_selection_count = sum(
        count - 1 for count in repeated_selections.values() if count > 1
    )
    repeated_result_count = sum(
        count - 1 for count in repeated_results.values() if count > 1
    )
    unattributed_failure = bool(
        not result.get("passed") and first is None
    )
    return {
        "task_id": task_id,
        "passed": bool(result.get("passed")),
        "agent_completed": bool(result.get("agent_completed")),
        "external_passed": bool(result.get("external_passed")),
        "status": str(result.get("status") or ""),
        "event_count": len(events),
        "action_count": int(result.get("action_count") or 0),
        "selection_count": selection_count,
        "oracle_checkpoint_count": len(oracle),
        "oracle_matched_selection_count": sum(
            bool(item["oracle_matched"]) for item in selection_records
        ),
        "protocol_rejection_count": max(
            protocol_rejection_count,
            int(result.get("protocol_rejection_count") or 0),
        ),
        "action_protocol_rejection_count": action_protocol_rejection_count,
        "audit_protocol_rejection_count": audit_protocol_rejection_count,
        "audit_decision_count": audit_decision_count,
        "audit_repair_count": audit_repair_count,
        "audit_reported_gap_count": audit_reported_gap_count,
        "audit_evidence_gap_count": audit_gap_count,
        "recovered_planner_failure_count": len(recovered_planner_failures),
        "recovered_planner_failures": recovered_planner_failures,
        "repeated_step_operation_count": repeated_selection_count,
        "repeated_result_digest_count": repeated_result_count,
        "selections": selection_records,
        "verified_anomalies": anomalies,
        "first_verified_anomaly": first,
        "amplification_chain": amplification,
        "unattributed_failure": unattributed_failure,
        "attribution_policy": (
            "mechanical_or_frozen_oracle_only; external failure alone is unattributed"
        ),
    }


def analyze_run(
    *,
    name: str,
    run_directory: Path,
    oracle: Mapping[str, Sequence[CheckpointOracle]],
) -> dict[str, Any]:
    run_directory = run_directory.resolve()
    results_path = run_directory / "results.json"
    payload = _read_json(results_path)
    if payload.get("schema_version") != "rwkv-e2e.results.v1":
        raise ValueError(f"unsupported results schema: {results_path}")
    cases = []
    for result in payload.get("results") or []:
        task_id = str(result["task_id"])
        event_path = run_directory / "cases" / task_id / "event_log.json"
        events = _read_json(event_path)
        if not isinstance(events, list) or any(not isinstance(item, Mapping) for item in events):
            raise ValueError(f"invalid event log: {event_path}")
        cases.append(
            analyze_case(
                task_id=task_id,
                result=result,
                events=events,
                oracle=oracle.get(task_id, ()),
            )
        )
    roles = Counter(
        str(case["first_verified_anomaly"]["role"])
        for case in cases
        if case["first_verified_anomaly"] is not None
    )
    return {
        "name": name,
        "run_directory": str(run_directory),
        "results_sha256": sha256_path(results_path),
        "case_count": len(cases),
        "passed_count": sum(case["passed"] for case in cases),
        "agent_completed_count": sum(case["agent_completed"] for case in cases),
        "external_passed_count": sum(case["external_passed"] for case in cases),
        "action_count": sum(case["action_count"] for case in cases),
        "protocol_rejection_count": sum(case["protocol_rejection_count"] for case in cases),
        "repeated_step_operation_count": sum(
            case["repeated_step_operation_count"] for case in cases
        ),
        "audit_evidence_gap_count": sum(case["audit_evidence_gap_count"] for case in cases),
        "unattributed_failure_count": sum(case["unattributed_failure"] for case in cases),
        "first_verified_anomaly_roles": dict(sorted(roles.items())),
        "cases": cases,
    }


def compare_runs(
    *,
    runs: Sequence[tuple[str, Path]],
    oracle_path: Path | None,
) -> dict[str, Any]:
    if len(runs) < 2 or len({name for name, _ in runs}) != len(runs):
        raise ValueError("trace comparison requires at least two uniquely named runs")
    oracle, oracle_sha256 = load_oracle(oracle_path)
    analyzed = [
        analyze_run(name=name, run_directory=path, oracle=oracle)
        for name, path in runs
    ]
    task_sets = [{case["task_id"] for case in run["cases"]} for run in analyzed]
    if any(task_set != task_sets[0] for task_set in task_sets[1:]):
        raise ValueError("paired trace runs contain different task ids")
    by_run = {
        run["name"]: {case["task_id"]: case for case in run["cases"]}
        for run in analyzed
    }
    paired_cases = []
    for task_id in sorted(task_sets[0]):
        values = {name: by_run[name][task_id] for name, _ in runs}
        paired_cases.append(
            {
                "task_id": task_id,
                "runs": {
                    name: {
                        "passed": value["passed"],
                        "status": value["status"],
                        "action_count": value["action_count"],
                        "protocol_rejection_count": value["protocol_rejection_count"],
                        "repeated_step_operation_count": value[
                            "repeated_step_operation_count"
                        ],
                        "first_verified_anomaly_role": (
                            value["first_verified_anomaly"]["role"]
                            if value["first_verified_anomaly"] is not None
                            else None
                        ),
                        "unattributed_failure": value["unattributed_failure"],
                    }
                    for name, value in values.items()
                },
            }
        )
    return {
        "schema_version": TRACE_COMPARISON_SCHEMA,
        "oracle_path": str(oracle_path.resolve()) if oracle_path is not None else "",
        "oracle_sha256": oracle_sha256,
        "semantic_attribution_enabled": bool(oracle_path),
        "historical_root_cause_prior_used": False,
        "planner_variability": {
            "ignored": True,
            "ignored_fields": [
                "exact_plan_text",
                "step_count",
                "step_ids",
                "phase_or_stage_labels",
                "step_order",
            ],
            "comparison_basis": [
                "goal_obligation_coverage",
                "harness_valid_actions",
                "task_completion",
                "external_verifier_acceptance",
            ],
        },
        "run_count": len(analyzed),
        "paired_task_count": len(paired_cases),
        "runs": analyzed,
        "paired_cases": paired_cases,
    }


__all__ = [
    "TRACE_COMPARISON_SCHEMA",
    "TRACE_ORACLE_SCHEMA",
    "CheckpointOracle",
    "analyze_case",
    "analyze_run",
    "compare_runs",
    "load_oracle",
]

rwkv_lh/capability_projection.py:
"""Deterministic Contract Graph v3 capability projection.

The strong Planner authors an atom kind, effect ceiling, evidence needs and
workspace scopes.  It never names a concrete Harness operation.  This module
mechanically projects the authoritative ActionDefinition metadata into the
operation menu from which RWKV makes the actual selection.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any, Mapping, Sequence


CAPABILITY_PROJECTION_VERSION = "controller_capability_projection.v3"
LEGACY_CAPABILITY_PROJECTION_VERSIONS = frozenset(
    {
        "controller_capability_projection.v1",
        "controller_capability_projection.v2",
    }
)
SUPPORTED_CAPABILITY_PROJECTION_VERSIONS = frozenset(
    {CAPABILITY_PROJECTION_VERSION, *LEGACY_CAPABILITY_PROJECTION_VERSIONS}
)


class AtomKind(str, Enum):
    INVESTIGATE = "investigate"
    MUTATE = "mutate"
    VERIFY = "verify"
    SYNTHESIZE = "synthesize"


class EffectCeiling(str, Enum):
    LOCAL_READ_ONLY = "local_read_only"
    PUBLIC_READ_ONLY = "public_read_only"
    WORKSPACE_MUTATION = "workspace_mutation"
    LOCAL_PROCESS_READ_ONLY = "local_process_read_only"
    LOCAL_PROCESS_MUTATION = "local_process_mutation"


@dataclass(frozen=True)
class CapabilityProjection:
    atom_kind: AtomKind
    effect_ceiling: EffectCeiling
    operations: tuple[str, ...]
    exclusive: bool
    minimum_actions: int
    source: str = CAPABILITY_PROJECTION_VERSION

    def to_dict(self) -> dict[str, Any]:
        return {
            "version": self.source,
            "atom_kind": self.atom_kind.value,
            "effect_ceiling": self.effect_ceiling.value,
            "operations": list(self.operations),
            "exclusive": self.exclusive,
            "minimum_actions": self.minimum_actions,
        }


def _normalized_catalog(
    operation_catalog: Sequence[Mapping[str, Any]],
) -> tuple[dict[str, Any], ...]:
    entries: list[dict[str, Any]] = []
    names: set[str] = set()
    required = {
        "name",
        "capability_class",
        "network_access",
        "side_effect_class",
        "scope_mode",
    }
    for index, item in enumerate(operation_catalog):
        if not isinstance(item, Mapping):
            raise ValueError(f"operation_catalog[{index}] must be an object")
        missing = sorted(required - set(item))
        if missing:
            raise ValueError(
                f"operation_catalog[{index}] lacks authoritative metadata: {missing}"
            )
        selected = {key: str(item.get(key) or "").strip() for key in required}
        if any(not selected[key] for key in required):
            raise ValueError(
                f"operation_catalog[{index}] has empty authoritative metadata"
            )
        name = selected["name"]
        if name in names:
            raise ValueError(f"operation catalog contains duplicate action {name}")
        names.add(name)
        entries.append({**dict(item), **selected})
    if not entries:
        raise ValueError("capability projection requires a non-empty operation catalog")
    return tuple(entries)


def _validate_kind_ceiling(kind: AtomKind, ceiling: EffectCeiling, role: str) -> None:
    selected_role = str(role or "").strip()
    if selected_role not in {"work", "finalizer"}:
        raise ValueError(f"unsupported atom role: {selected_role}")
    if selected_role == "finalizer":
        if kind != AtomKind.SYNTHESIZE:
            raise ValueError("a finalizer atom must use kind=synthesize")
        if ceiling != EffectCeiling.LOCAL_READ_ONLY:
            raise ValueError("a finalizer atom must use local_read_only")
        return
    allowed: dict[AtomKind, set[EffectCeiling]] = {
        AtomKind.INVESTIGATE: {
            EffectCeiling.LOCAL_READ_ONLY,
            EffectCeiling.PUBLIC_READ_ONLY,
            EffectCeiling.LOCAL_PROCESS_READ_ONLY,
        },
        AtomKind.MUTATE: {
            EffectCeiling.WORKSPACE_MUTATION,
            EffectCeiling.LOCAL_PROCESS_MUTATION,
        },
        AtomKind.VERIFY: {
            EffectCeiling.LOCAL_READ_ONLY,
            EffectCeiling.PUBLIC_READ_ONLY,
            EffectCeiling.LOCAL_PROCESS_READ_ONLY,
        },
        AtomKind.SYNTHESIZE: {EffectCeiling.LOCAL_READ_ONLY},
    }
    if ceiling not in allowed[kind]:
        raise ValueError(
            f"atom kind {kind.value} cannot request effect ceiling {ceiling.value}"
        )


def project_contract_capabilities(
    *,
    atom_kind: AtomKind | str,
    effect_ceiling: EffectCeiling | str,
    role: str,
    operation_catalog: Sequence[Mapping[str, Any]],
    write_roots: Sequence[str] = (),
    evidence_kinds: Sequence[str] = (),
    source_preferences: Sequence[str] = (),
) -> CapabilityProjection:
    """Project one Planner-authored semantic atom to an RWKV operation menu."""

    kind = atom_kind if isinstance(atom_kind, AtomKind) else AtomKind(str(atom_kind))
    ceiling = (
        effect_ceiling
        if isinstance(effect_ceiling, EffectCeiling)
        else EffectCeiling(str(effect_ceiling))
    )
    _validate_kind_ceiling(kind, ceiling, role)
    catalog = _normalized_catalog(operation_catalog)

    def applicable(item: Mapping[str, Any]) -> bool:
        capability = str(item["capability_class"])
        network = str(item["network_access"])
        effect = str(item["side_effect_class"])
        local_read = capability == "local.workspace_read" and network == "none"
        deterministic = capability.startswith("deterministic.") and network == "none"
        workspace_mutation = (
            capability == "local.workspace_mutation"
            and effect == "workspace_mutation"
            and network == "none"
        )
        process_read = capability == "local.process_read" and network == "none"
        process_mutation = (
            capability == "local.process_mutation" and network == "none"
        )
        public_external = (
            network in {"public_web", "structured_source"}
            and effect == "external_read_only"
        )

        if str(role) == "finalizer":
            return local_read
        # For v2 read-only work, the Planner ceilings effects, not information
        # source. If network actions survived system policy and registration,
        # RWKV alone chooses local, deterministic, web, or structured evidence.
        # The old local/public names remain wire-compatible but no longer let the
        # Planner make the browse decision indirectly.
        if ceiling in {
            EffectCeiling.LOCAL_READ_ONLY,
            EffectCeiling.PUBLIC_READ_ONLY,
        }:
            return local_read or deterministic or public_external
        if ceiling == EffectCeiling.WORKSPACE_MUTATION:
            return local_read or deterministic or workspace_mutation
        if ceiling == EffectCeiling.LOCAL_PROCESS_READ_ONLY:
            return local_read or deterministic or public_external or process_read
        if ceiling == EffectCeiling.LOCAL_PROCESS_MUTATION:
            return (
                local_read
                or deterministic
                or workspace_mutation
                or process_read
                or process_mutation
            )
        return False

    applicable_entries = [item for item in catalog if applicable(item)]
    hints = " ".join(
        str(item or "").strip().casefold().replace("-", "_").replace(" ", "_")
        for item in (*evidence_kinds, *source_preferences)
    )

    def rank(item: Mapping[str, Any], index: int) -> tuple[int, int, int]:
        capability = str(item["capability_class"])
        network = str(item["network_access"])
        name = str(item["name"])
        external = network in {"public_web", "structured_source"}
        deterministic = capability.startswith("deterministic.")
        if ceiling == EffectCeiling.PUBLIC_READ_ONLY:
            group = 0 if external else 1 if deterministic else 2
        else:
            group = 0 if not external and not deterministic else 1 if deterministic else 2

        hint_rank = 0
        if "structured_registry" in hints and network == "structured_source":
            hint_rank = -20
        elif "public_web" in hints and network == "public_web":
            hint_rank = -20
        elif "workspace_directory" in hints and name == "list_directory":
            hint_rank = -20
        elif "workspace_file" in hints:
            hint_rank = {
                "read_file": -20,
                "read_json": -19,
                "file_digest": -18,
                "bind_evidence": -17,
            }.get(name, 0)
        elif "deterministic_compute" in hints and deterministic:
            hint_rank = -20
        return group, hint_rank, index

    applicable_entries = [
        item
        for _, item in sorted(
            enumerate(applicable_entries),
            key=lambda pair: rank(pair[1], pair[0]),
        )
    ]
    operations = tuple(str(item["name"]) for item in applicable_entries)
    if not operations:
        raise ValueError(
            f"capability projection produced no operations for {kind.value}/"
            f"{ceiling.value}"
        )
    exclusive = "." in {str(item or "").strip() for item in write_roots} or any(
        str(item["name"]) in operations
        and str(item["scope_mode"]) == "exclusive_side_effect"
        for item in catalog
    )
    minimum_actions = 1
    if kind == AtomKind.MUTATE and write_roots:
        # Every non-overlapping declared write root needs a direct mutation
        # opportunity.  The action budget is validated later when the
        # SupervisorAtom is constructed, so an infeasible Planner patch fails
        # closed before any RWKV request is made.
        minimum_actions = len(tuple(write_roots))
    return CapabilityProjection(
        atom_kind=kind,
        effect_ceiling=ceiling,
        operations=operations,
        exclusive=exclusive,
        # A finalizer's candidate becomes the exact user-visible answer.  It
        # therefore needs one current-workspace observation; accepted work
        # evidence remains the source of execution truth.
        minimum_actions=minimum_actions,
    )


__all__ = [
    "AtomKind",
    "CAPABILITY_PROJECTION_VERSION",
    "LEGACY_CAPABILITY_PROJECTION_VERSIONS",
    "CapabilityProjection",
    "EffectCeiling",
    "SUPPORTED_CAPABILITY_PROJECTION_VERSIONS",
    "project_contract_capabilities",
]

rwkv_lh/goal_loop_protocol.py:
"""Frozen structured protocol used by the RWKV Stateful Goal Loop.

The protocol is deliberately small.  It records a rolling plan and one
evidence-bound audit verdict; it does not introduce another execution graph or
grant a model output authority over Harness facts.
"""

from __future__ import annotations

import json
from copy import deepcopy
from dataclasses import dataclass, field
from enum import Enum
from pathlib import PurePosixPath
from typing import Any, Mapping, Sequence

from rwkv_lh.model_io import (
    ModelIOError,
    canonical_digest,
    parse_model_command_with_trace,
)
from rwkv_lh.operation_contracts import (
    GOAL_STEP_PHASES,
    PATH_MUTATION_ARGUMENTS,
    PATH_MUTATION_OPERATIONS,
)
from rwkv_lh.schema import ActionStatus, RunState


GOAL_AUDIT_SCHEMA_VERSION = "rwkv-lh.goal-audit-decision.v1"
GOAL_AUDIT_INPUT_PROTOCOL = "rwkv-lh.role-pure-goal-audit.v2"
GOAL_AUDIT_OPERATION = "audit_decision"
GOAL_PLAN_PATCH_SCHEMA_VERSION = "rwkv-lh.goal-plan-patch.v4"
GOAL_STAGE_REVIEW_SCHEMA_VERSION = "rwkv-lh.goal-stage-review.v1"


class GoalPlanResponseError(ValueError):
    """A complete Planner object failed validation and can be sent back for repair.

    Preserve the actual model value before a typed patch exists. Transport and
    incomplete JSON errors are separate; this exception never supplies missing
    fields or grants a rejected object authority to change the rolling plan.
    """

    def __init__(self, message: str, *, rejected_patch: Mapping[str, Any]) -> None:
        super().__init__(message)
        self.rejected_patch = deepcopy(dict(rejected_patch))


def _plan_field_difference(
    actual: Mapping[str, Any], required: set[str], *, allowed: set[str] | None = None,
) -> str:
    return (
        f"missing={sorted(required - set(actual))}; "
        f"unexpected={sorted(set(actual) - (allowed if allowed is not None else required))}"
    )


GOAL_AUDIT_DEFINITION: dict[str, Any] = {
