"""Native RWKV7 StateTune: exact serving forward and derivatives of the same equations."""
import json
from pathlib import Path
from types import SimpleNamespace
import torch
from torch import nn
from torch.nn import functional as F
from torch.utils.checkpoint import checkpoint
from rwkv_lh.rwkv7_layout import RWKV7Layout

def mix(x, weight):
    previous = F.pad(x[:, :-1], (0, 0, 1, 0))
    return torch.addcmul(x.float(), previous.float() - x.float(), weight.float()).half()

class Attention(nn.Module):

    def __init__(self, width, heads, ranks, index):
        super().__init__()
        self.index, self.heads = (index, heads)
        for name in ('x_r', 'x_w', 'x_k', 'x_v', 'x_a', 'x_g', 'w0', 'a0', 'v0', 'k_k', 'k_a'):
            self.register_parameter(name, nn.Parameter(torch.empty(1, 1, width)))
        for prefix, rank in zip(('w', 'a', 'v', 'g'), ranks):
            self.register_parameter(prefix + '1', nn.Parameter(torch.empty(width, rank)))
            self.register_parameter(prefix + '2', nn.Parameter(torch.empty(rank, width)))
        self.r_k = nn.Parameter(torch.empty(heads, width // heads))
        self.time_state = nn.Parameter(torch.empty(heads, width // heads, width // heads))
        for name in ('receptance', 'key', 'value', 'output'):
            setattr(self, name, nn.Linear(width, width, bias=False))
        self.ln_x = nn.GroupNorm(heads, width, eps=0.00064)

class ChannelMix(nn.Module):

    def __init__(self, width, intermediate):
        super().__init__()
        self.x_k = nn.Parameter(torch.empty(1, 1, width))
        self.key = nn.Linear(width, intermediate, bias=False)
        self.value = nn.Linear(intermediate, width, bias=False)

    def forward(self, x):
        up = self.key(mix(x, self.x_k))
        return self.value(F.relu(up.float()).square().half())

class Block(nn.Module):

    def __init__(self, width, heads, ranks, index, intermediate):
        super().__init__()
        if index == 0:
            self.ln0 = nn.LayerNorm(width)
        self.ln1, self.ln2 = (nn.LayerNorm(width), nn.LayerNorm(width))
        self.att = Attention(width, heads, ranks, index)
        self.ffn = ChannelMix(width, intermediate)

class NativeStateModel(nn.Module):

    def __init__(self, layout: RWKV7Layout):
        super().__init__()
        if layout.head_size != 64:
            raise ValueError('compiled Native recurrence requires head_size=64')
        width = layout.width
        ranks = (layout.decay_rank, layout.a_rank, layout.v_rank, layout.gate_rank)
        self.emb = nn.Embedding(layout.vocab, width)
        self.blocks = nn.ModuleList((Block(width, layout.heads, ranks, i, layout.intermediate) for i in range(layout.layers)))
        self.ln_out = nn.LayerNorm(width)
        self.head = nn.Linear(width, layout.vocab, bias=False)
        self.layout = layout

def norm_float(x, module):
    return F.layer_norm(x.float(), (x.shape[-1],), module.weight.float(), module.bias.float(), module.eps)

def pure_producer(x, first, att):
    batch, tokens, width = x.shape
    shape = (batch, tokens, att.heads, width // att.heads)
    xr, xw, xk, xv, xa, xg = (mix(x, getattr(att, 'x_' + n)) for n in ('r', 'w', 'k', 'v', 'a', 'g'))
    r, k, v = (att.receptance(xr), att.key(xk), att.value(xv))
    w1, a1, g1 = (xw @ att.w1, xa @ att.a1, xg @ att.g1)
    fused = width >= 1024 and batch * tokens <= 4
    w = (torch.tanh(w1.float()) @ att.w2.float()).half() if fused else torch.tanh(w1.float()).half() @ att.w2
    a12 = a1 @ att.a2
    g = (torch.sigmoid(g1.float()) @ att.g2.float()).half() if fused else torch.sigmoid(g1.float()).half() @ att.g2
    if att.index == 0:
        first = v
    else:
        v1 = xv @ att.v1
        v12 = v1.float() @ att.v2.float() if fused else v1 @ att.v2
        gate = torch.sigmoid(v12.float() + att.v0.float())
        v = torch.addcmul(v.float(), first.float() - v.float(), gate).half()
    gate = torch.sigmoid(a12.float() + att.a0.float())
    kk = F.normalize((k.float() * att.k_k.float()).reshape(shape), dim=-1, eps=1e-12).reshape_as(k)
    new_k = (k.float() * (1 + (gate - 1) * att.k_a.float())).half()
    return (r, w, new_k, v, (-kk).half(), (kk * gate).half(), g, first)

def native_producer(x, first, att, native, pre_mix=None):
    from vllm.model_executor.models.rwkv7 import select_path, use_tmix_mix6_3d
    batch, tokens, width = x.shape
    p = f'blocks.{att.index}.att.'
    z = native.z
    if pre_mix is None:
        ops = torch.ops.vllm_rwkv7_fast_ops_fp16
        op = ops.tmix_mix6_3d if use_tmix_mix6_3d(batch, tokens, width) else ops.tmix_mix6
        pre_mix = op(batch, tokens, width, x.contiguous(), torch.zeros(batch, width, device=x.device, dtype=x.dtype), *(z[p + 'x_' + n] for n in ('r', 'w', 'k', 'v', 'a', 'g')))
    return native._project_tmix(att.index, *pre_mix, first, p, select_path(batch, tokens), batch_size=batch, time_steps=tokens)

def differentiate(ctx, fn, upstream):
    """Recompute the same equation and its actual derivative; never a detached bypass."""
    saved = ctx.saved_tensors
    with torch.enable_grad():
        inputs = [value.detach().requires_grad_(ctx.needs_input_grad[i]) for i, value in enumerate(saved)]
        outputs = fn(*inputs)
        if isinstance(outputs, torch.Tensor):
            outputs = (outputs,)
        pairs = [(out, grad) for out, grad in zip(outputs, upstream) if out.requires_grad and grad is not None]
        active = [value for value in inputs if value.requires_grad]
        grads = torch.autograd.grad([x for x, _ in pairs], active, [g.to(x) for x, g in pairs], allow_unused=True) if pairs else [None] * len(active)
    iterator = iter(grads)
    return tuple((next(iterator) if value.requires_grad else None for value in inputs))

class Producer(torch.autograd.Function):

    @staticmethod
    def forward(ctx, x, first, att, native):
        ctx.set_materialize_grads(False)
        ctx.save_for_backward(x, first)
        ctx.att = att
        return native_producer(x, first, att, native)

    @staticmethod
    def backward(ctx, *grads):
        return (*differentiate(ctx, lambda x, f: pure_producer(x, f, ctx.att), grads), None, None)

class NextProducer(torch.autograd.Function):

    @staticmethod
    def forward(ctx, x, ffn, first, block, native):
        from vllm.model_executor.models.rwkv7 import use_ln1_tmix_fusion
        ctx.set_materialize_grads(False)
        ctx.save_for_backward(x, ffn, first)
        ctx.block = block
        batch, tokens, width = x.shape
        p = f'blocks.{block.att.index}.'
        z = native.z
        if use_ln1_tmix_fusion(batch, tokens):
            values = torch.ops.rwkv7_v3a_ops.add_layer_norm_tmix_mix6_f16(x.contiguous(), ffn.contiguous(), torch.zeros(batch, width, device=x.device, dtype=x.dtype), z[p + 'ln1.weight'], z[p + 'ln1.bias'], *(z[p + 'att.x_' + n] for n in ('r', 'w', 'k', 'v', 'a', 'g')))
            residual, pre_mix = (values[0], values[1:])
            produced = native_producer(residual, first, block.att, native, pre_mix)
        else:
            residual, normalized = native.add_ln(x, ffn, z[p + 'ln1.weight'], z[p + 'ln1.bias'])
            produced = native_producer(normalized, first, block.att, native)
        return (residual, *produced)

    @staticmethod
    def backward(ctx, *grads):

        def equation(x, ffn, first):
            summed = x.float() + ffn.float()
            return (summed.half(), *pure_producer(norm_float(summed, ctx.block.ln1).half(), first, ctx.block.att))
        return (*differentiate(ctx, equation, grads), None, None)

class Post(torch.autograd.Function):

    @staticmethod
    def forward(ctx, y, r, k, v, g, att, native):
        from vllm.model_executor.models.rwkv7 import use_tmix_lnx_warp
        ctx.set_materialize_grads(False)
        ctx.save_for_backward(y, r, k, v, g)
        ctx.att = att
        batch, tokens, width = r.shape
        heads = att.heads
        p = f'blocks.{att.index}.att.'
        z = native.z
        ops = torch.ops.vllm_rwkv7_fast_ops_fp16
        op = ops.tmix_lnx_rkvres_xg_warp if use_tmix_lnx_warp(batch, tokens, width, heads) else ops.tmix_lnx_rkvres_xg
        value = op(batch, tokens, width, heads, y.contiguous(), r.contiguous(), k.contiguous(), v.contiguous(), z[p + 'r_k'], z[p + 'ln_x.weight'], z[p + 'ln_x.bias'], g.contiguous())
        return native.linear_att_c2c(value, z[p + 'output.weight'], batch * tokens)

    @staticmethod
    def backward(ctx, *grads):

        def equation(y, r, k, v, g):
            att = ctx.att
            batch, tokens, width = r.shape
            shape = (batch, tokens, att.heads, width // att.heads)
            normalized = F.group_norm(y.float().reshape(batch * tokens, width), att.heads, att.ln_x.weight.float(), att.ln_x.bias.float(), att.ln_x.eps).reshape(shape)
            residual = (r.float().reshape(shape) * k.float().reshape(shape) * att.r_k.float()).sum(-1, keepdim=True) * v.float().reshape(shape)
            return att.output(((normalized + residual).reshape_as(g) * g.float()).half())
        return (*differentiate(ctx, equation, grads), None, None)

class ResidualFFN(torch.autograd.Function):

    @staticmethod
    def forward(ctx, x, attention, block, native):
        from vllm.model_executor.models.rwkv7 import select_path
        ctx.set_materialize_grads(False)
        ctx.save_for_backward(x, attention)
        ctx.block = block
        batch, tokens, width = x.shape
        p = f'blocks.{block.att.index}.'
        z = native.z
        shift = torch.zeros(2, batch, width, device=x.device, dtype=x.dtype)
        if tokens == 1:
            residual, mixed = torch.ops.rwkv7_v3a_ops.add_layer_norm_cmix_mix_f16(x.contiguous(), attention.contiguous(), shift[1], z[p + 'ln2.weight'], z[p + 'ln2.bias'], z[p + 'ffn.x_k'])
            out = native.cmix_from_mixed(mixed, p + 'ffn.', select_path(batch, tokens))
        else:
            residual, normalized = native.add_ln(x, attention, z[p + 'ln2.weight'], z[p + 'ln2.bias'])
            out = native.cmix(normalized, shift, p + 'ffn.', select_path(batch, tokens))
        return (residual, out)

    @staticmethod
    def backward(ctx, *grads):

        def equation(x, attention):
            summed = x.float() + attention.float()
            normalized = norm_float(summed, ctx.block.ln2).half()
            return (summed.half(), ctx.block.ffn(normalized))
        return (*differentiate(ctx, equation, grads), None, None)

class Head(torch.autograd.Function):

    @staticmethod
    def forward(ctx, x, ffn, model, native):
        ctx.set_materialize_grads(False)
        ctx.save_for_backward(x, ffn)
        ctx.model = model
        hidden = native.ln(native.add(x, ffn), native.z['ln_out.weight'], native.z['ln_out.bias'])
        return native.project_logits_fp32(hidden)

    @staticmethod
    def backward(ctx, *grads):

        def equation(x, ffn):
            hidden = norm_float((x.float() + ffn.float()).half(), ctx.model.ln_out).half()
            return F.linear(hidden.float(), ctx.model.head.weight.float())
        return (*differentiate(ctx, equation, grads), None, None)

class NativeGradientModel(NativeStateModel):

    def layer(self, x, previous_ffn, first, index):
        from rwkv_lh.statetune_native_recurrence import recurrent
        block = self.blocks[index]
        native = self.native
        if index == 0:
            normalized = native.ln(x, native.z['blocks.0.ln1.weight'], native.z['blocks.0.ln1.bias'])
            values = Producer.apply(normalized, first, block.att, native)
        else:
            values = NextProducer.apply(x, previous_ffn, first, block, native)
            x, values = (values[0], values[1:])
        r, w, k, v, aa, b, g, first = values
        batch, tokens, width = r.shape
        shape = (batch, tokens, block.att.heads, width // block.att.heads)
        state = block.att.time_state.transpose(-1, -2).unsqueeze(0).expand(batch, -1, -1, -1).contiguous()
        y, _ = recurrent(*(value.reshape(shape).contiguous() for value in (r, w, k, v, aa, b)), initial_state=state, decay_bias=block.att.w0.reshape(shape[-2:]).contiguous())
        attention = Post.apply(y.reshape_as(r), r, k, v, g, block.att, native)
        x, ffn = ResidualFFN.apply(x, attention, block, native)
        return (x, ffn, first)

    def forward(self, tokens):
        if (tokens.ndim != 2 or tokens.shape[0] != 1 or tokens.shape[1] < 1
                or tokens.shape[1] > getattr(self, 'context_tokens', tokens.shape[1])):
            raise ValueError('Native StateTune supports one complete independent sample per forward')
        x = self.native.embed(tokens)
        first = x
        ffn = torch.zeros_like(x)
        for i in range(len(self.blocks)):
            function = lambda x, ffn, first, i=i: self.layer(x, ffn, first, i)
            x, ffn, first = checkpoint(function, x, ffn, first, use_reentrant=False) if torch.is_grad_enabled() else function(x, ffn, first)
        return Head.apply(x, ffn, self, self.native)

def build(spec):
    from rwkv_lh import statetune_core as a
    from vllm.config.compilation import CompilationConfig, CompilationMode
    from vllm.config.vllm import set_current_vllm_config
    from vllm.model_executor.models import rwkv7
    from vllm.transformers_utils.configs.rwkv7 import RWKV7Config
    import vllm.rwkv7_ops
    rwkv7.get_tensor_model_parallel_world_size = lambda: 1
    rwkv7.get_tensor_model_parallel_rank = lambda: 0
    config_values = json.loads((Path(spec['model_artifact']) / 'config.json').read_text())
    layout = RWKV7Layout.from_config(config_values)
    context_tokens = spec['context_tokens']
    a.require(type(context_tokens) is int and 0 < context_tokens <= config_values['context_length'],
              'Native training context exceeds the model artifact')
    a.require(layout.dtype == 'bfloat16', 'Native weight preprocessing currently validates BF16 checkpoints')
    config = RWKV7Config(**config_values)
    vc = SimpleNamespace(compilation_config=CompilationConfig(mode=CompilationMode.NONE), model_config=SimpleNamespace(hf_config=config, enforce_eager=True, dtype=torch.bfloat16, head_dtype=None), quant_config=None, parallel_config=None)
    with set_current_vllm_config(vc):
        native = rwkv7.RWKV7ForCausalLM(vllm_config=vc)
    with torch.device('meta'):
        model = NativeGradientModel(layout)
    a.load_frozen_base(model, spec['base']['path'], spec['base']['sha256'], layers=layout.layers)
    initial = a.state_parameters(model, layers=layout.layers)
    raw = {name: value.detach() for name, value in model.named_parameters() if name not in initial}
    native._preprocess_weights(raw)
    native.z = raw
    for name, parameter in list(model.named_parameters()):
        module, key = name.rsplit('.', 1)
        if name in initial:
            value = torch.zeros(parameter.shape, device='cuda:0', dtype=torch.float32)
        elif name == 'emb.weight':
            value = parameter.detach().to(device='cuda:0', dtype=torch.float16)
        else:
            value = native.z[name]
            if not rwkv7.is_lowrank_weight(name) and any((part in name for part in ('key.weight', 'value.weight', 'receptance.weight', 'output.weight', 'head.weight'))):
                value = value.t()
            value = value.reshape(parameter.shape)
        model.get_submodule(module)._parameters[key] = nn.Parameter(value, requires_grad=name in initial)
    object.__setattr__(model, 'native', native)
    model.context_tokens = context_tokens
    a.freeze_for_state_tuning(model, layers=layout.layers)
    model.eval()
    return model

rwkv_lh/trace_projection.py:
"""Read-only projections of direct and child-atom activity from one run ledger."""

from __future__ import annotations

from typing import Any, Mapping

from rwkv_lh.schema import RunState


def unresolved_supervisor_pending(
    state: RunState,
) -> tuple[Mapping[str, Any], ...]:
    """Fold pending/resolved supervisor events into the current retry set."""

    unresolved: dict[str, Mapping[str, Any]] = {}
    for event_id in state.causal_order:
        event = state.causal_records[event_id]
        if event.event_type == "supervisor_call_pending":
            pending_id = str(event.payload.get("pending_id") or "")
            if pending_id:
                unresolved[pending_id] = dict(event.payload)
        elif event.event_type == "supervisor_call_resolved":
            pending_id = str(event.payload.get("pending_id") or "")
            if pending_id:
                unresolved.pop(pending_id, None)
    return tuple(unresolved.values())


def _network_policy_rejected(
    *,
    outcome_type: str = "",
    error: Mapping[str, Any] | None = None,
    result: Mapping[str, Any] | None = None,
) -> bool:
    selected_result = result if isinstance(result, Mapping) else {}
    result_error = selected_result.get("error")
    error_types = {
        str(item.get("type") or "")
        for item in (error, result_error)
        if isinstance(item, Mapping)
    }
    if "NetworkPolicyRejected" in error_types:
        return True
    return str(outcome_type or selected_result.get("outcome_type") or "") == (
        "policy_rejected"
    )


def project_run_activity(state: RunState) -> dict[str, Any]:
    """Fold parent and atom execution without creating a second mutable ledger."""

    direct_actions = [
        {
            "activity_id": action.action_id,
            "origin": "direct",
            "action_id": action.action_id,
            "sequence": action.sequence,
            "operation": action.action_type,
            "status": action.status.value,
            "artifact_refs": list(action.artifact_refs),
            "atom_id": "",
            "stage_id": "",
            "network_policy_rejected": _network_policy_rejected(
                outcome_type=action.outcome_type,
                error=action.error,
                result=action.result,
            ),
        }
        for action in sorted(state.actions.values(), key=lambda item: item.sequence)
    ]
    atom_actions: list[dict[str, Any]] = []
    atom_model_requests = 0
    for event_id in state.causal_order:
        event = state.causal_records[event_id]
        if event.event_type != "atom_outcome_committed":
            continue
        outcome = event.payload.get("outcome")
        if not isinstance(outcome, Mapping):
            continue
        stage_id = str(outcome.get("stage_id") or "")
        atom_id = str(outcome.get("atom_id") or "")
        atom_model_requests += int(outcome.get("model_request_count", 0) or 0)
        for action in outcome.get("actions") or ():
            if not isinstance(action, Mapping):
                continue
            action_id = str(action.get("action_id") or "")
            activity_id = f"{stage_id}:{atom_id}:{action_id}"
            atom_actions.append(
                {
                    "activity_id": activity_id,
                    "origin": "atom",
                    "action_id": action_id,
                    "sequence": int(action.get("sequence", 0) or 0),
                    "operation": str(action.get("operation") or ""),
                    "status": str(action.get("status") or ""),
                    "artifact_refs": list(action.get("artifact_refs") or ()),
                    "atom_id": atom_id,
                    "stage_id": stage_id,
                    "network_policy_rejected": _network_policy_rejected(
                        outcome_type=str(action.get("outcome_type") or ""),
                        error=(
                            action.get("error")
                            if isinstance(action.get("error"), Mapping)
                            else None
                        ),
                        result=(
                            action.get("result")
                            if isinstance(action.get("result"), Mapping)
                            else None
                        ),
                    ),
                }
            )
    direct_model_requests = len(state.temp_decisions)
    return {
        "actions": [*direct_actions, *atom_actions],
        "direct_actions": direct_actions,
        "atom_actions": atom_actions,
        "direct_model_requests": direct_model_requests,
        "atom_model_requests": atom_model_requests,
        "rwkv_model_requests": direct_model_requests + atom_model_requests,
    }


def projected_tool_outputs(state: RunState) -> tuple[str, ...]:
    """Return committed tool output text across direct and atom execution."""

    outputs: list[str] = []
    for action in state.actions.values():
        result = action.result
        if isinstance(result, Mapping):
            output = result.get("output")
            if isinstance(output, str) and output.strip():
                outputs.append(output)
    for event_id in state.causal_order:
        event = state.causal_records[event_id]
        if event.event_type != "atom_outcome_committed":
            continue
        outcome = event.payload.get("outcome")
        if not isinstance(outcome, Mapping):
            continue
        for action in outcome.get("actions") or ():
            if not isinstance(action, Mapping):
                continue
            result = action.get("result")
            if not isinstance(result, Mapping):
                continue
            output = result.get("output")
            if isinstance(output, str) and output.strip():
                outputs.append(output)
    return tuple(outputs)


__all__ = [
    "project_run_activity",
    "projected_tool_outputs",
    "unresolved_supervisor_pending",
]

rwkv_lh/ultradata.py:
"""Inspect external UltraData records and prepare std-I/O development tasks.

External text is never relabeled as a production role trace. Candidate execution
uses the existing isolated benchmark verifier, including its private-test boundary.
"""
from __future__ import annotations

from collections import Counter
import hashlib
import json
import math
from pathlib import Path
import re
from typing import Any, Mapping


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def _json(text):
    return json.loads(text, object_pairs_hook=_unique_object,
                      parse_constant=lambda value: (_ for _ in ()).throw(ValueError(f"nonfinite JSON: {value}")))


def read_frozen_range(path: Path, expected_sha256: str) -> tuple[list[dict], dict]:
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("source range SHA-256 mismatch")
    lines = raw.split(b"\n")
    tail = lines.pop()
    records = []
    offset = 0
    for number, line in enumerate(lines, 1):
        record = {"line_number": number, "byte_offset": offset, "bytes": len(line),
                  "row_sha256": hashlib.sha256(line).hexdigest()}
        offset += len(line) + 1
        try:
            row = _json(line)
            if not isinstance(row, dict):
                raise ValueError("row must be an object")
            record["row"] = row
        except (ValueError, UnicodeError) as error:
            record["error"] = str(error)
        records.append(record)
    return records, {"complete_rows": len(records), "invalid_rows": sum("error" in x for x in records),
                     "trailing_bytes": len(tail), "tail_sha256": hashlib.sha256(tail).hexdigest()}


def audit_trajectory(row: Mapping[str, Any]) -> dict:
    """Structural observations only: tool output and final text are not truth labels."""
    result = {"uuid": row.get("uuid"), "domain": row.get("domain"), "source": row.get("source"),
              "role_training_eligible": False, "independently_verified_success": None,
              "environment_reproduced": False, "review_reasons": [],
              "message_count": 0, "tool_calls": 0, "tool_results": 0,
              "masked_assistant_turns": 0, "unmasked_assistant_turns": 0,
              "unspecified_loss_assistant_turns": 0, "pending_calls": 0,
              "orphan_results": 0, "undefined_tool_calls": [], "terminal_kind": "unknown"}
    messages, tools = row.get("messages"), row.get("tools")
    if not isinstance(messages, list) or not isinstance(tools, list) or not messages:
        result["review_reasons"].append("invalid_messages_or_tools")
        return result
    defined = {}
    for tool in tools:
        function = tool.get("function", {}) if isinstance(tool, dict) else {}
        if not isinstance(function, dict) or not isinstance(function.get("name"), str):
            result["review_reasons"].append("invalid_tool_definition")
            continue
        name = function["name"]
        if name in defined:
            result["review_reasons"].append("duplicate_tool_definition")
        defined[name] = function
    result["tool_names"] = sorted(defined)
    result["possible_model_assistance_tools"] = sorted(name for name, tool in defined.items()
        if re.search(r"cloud_assist|stronger.{0,30}model|language model|LLM|模型", name + " " + str(tool.get("description", "")), re.I))
    counts, pending = Counter(), []
    observed_calls = []
    for index, message in enumerate(messages):
        if not isinstance(message, dict):
            result["review_reasons"].append("invalid_message")
            continue
        role = message.get("role")
        counts[str(role)] += 1
        if role not in {"system", "user", "assistant", "tool"}:
            result["review_reasons"].append("unknown_message_role")
        if role == "assistant":
            if "loss" not in message:
                result["unspecified_loss_assistant_turns"] += 1
            elif message["loss"] is False:
                result["masked_assistant_turns"] += 1
            elif message["loss"] is True:
                result["unmasked_assistant_turns"] += 1
            else:
                result["review_reasons"].append("invalid_loss_mask")
            calls = message.get("tool_calls") or []
            if not isinstance(calls, list):
                result["review_reasons"].append("invalid_tool_calls")
                continue
            if pending:
                result["review_reasons"].append("assistant_before_pending_results")
            for call in calls:
                function = call.get("function", {}) if isinstance(call, dict) else {}
                if not isinstance(function, dict) or not isinstance(function.get("name"), str):
                    result["review_reasons"].append("malformed_tool_call")
                    continue
                name = function["name"]
                result["tool_calls"] += 1
                observed_calls.append(name)
                if name not in defined:
                    result["undefined_tool_calls"].append(name)
                args = function.get("arguments")
                try:
                    decoded = _json(args) if isinstance(args, str) else args
                    if not isinstance(decoded, dict):
                        raise ValueError("arguments not an object")
                except ValueError:
                    result["review_reasons"].append("invalid_arguments_json")
                pending.append(call.get("id"))
        elif role == "tool":
            result["tool_results"] += 1
            call_id = message.get("tool_call_id")
            if not pending:
                result["orphan_results"] += 1
            elif call_id is not None:
                if call_id in pending:
                    pending.remove(call_id)
                else:
                    result["orphan_results"] += 1
                    result["review_reasons"].append("unmatched_tool_call_id")
            else:
                pending.pop(0)
                result["review_reasons"].append("positional_pairing_without_call_ids")
    result.update(message_count=len(messages), role_counts=dict(counts), pending_calls=len(pending),
                  called_tools=dict(Counter(observed_calls)),
                  serialized_utf8_bytes=len(json.dumps(row, ensure_ascii=False).encode()),
                  possible_model_assistance_calls=sorted(set(observed_calls) & set(result["possible_model_assistance_tools"])))
    last = messages[-1] if isinstance(messages[-1], dict) else {}
    result["terminal_kind"] = ("pending_tool" if pending else
        "assistant_text_unverified" if last.get("role") == "assistant" and last.get("content") and not last.get("tool_calls") else
        "tool_result" if last.get("role") == "tool" else "other")
    result["review_reasons"] = sorted(set(result["review_reasons"]))
    result["undefined_tool_calls"] = sorted(set(result["undefined_tool_calls"]))
    return result


_CODE_VERIFIER = r'''
import json, math, os, pathlib, resource, signal, subprocess, sys, tempfile
CONFIG = json.loads(__CONFIG__)
workspace = pathlib.Path(sys.argv[1])
def limits():
    resource.setrlimit(resource.RLIMIT_CPU, (math.ceil(CONFIG['case_timeout']) + 1,) * 2)
    resource.setrlimit(resource.RLIMIT_AS, (512 * 1024 * 1024,) * 2)
    resource.setrlimit(resource.RLIMIT_FSIZE, (CONFIG['output_limit'],) * 2)
results = []
for index, (input_text, expected) in enumerate(zip(CONFIG['inputs'], CONFIG['outputs'])):
    with tempfile.TemporaryFile() as stdout, tempfile.TemporaryFile() as stderr:
        process = subprocess.Popen([sys.executable, '-I', str(workspace / 'main.py')],
            cwd=workspace, stdin=subprocess.PIPE, stdout=stdout, stderr=stderr,
            env={'PATH':'/usr/bin:/bin', 'LANG':'C.UTF-8', 'PYTHONDONTWRITEBYTECODE':'1'},
            start_new_session=True, preexec_fn=limits)
        timeout = False
        try:
            process.communicate(input=input_text.encode('utf-8'), timeout=CONFIG['case_timeout'])
        except subprocess.TimeoutExpired:
            timeout = True
            try: os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError: pass
            process.communicate()
        stdout.seek(0)
        output = stdout.read(CONFIG['output_limit'] + 1)
        try:
            same = output.decode('utf-8').rstrip() == expected.rstrip()
        except UnicodeDecodeError:
            same = False
        passed = not timeout and process.returncode == 0 and len(output) <= CONFIG['output_limit'] and same
        results.append({'case':index, 'passed':passed, 'timeout':timeout, 'exit_code':process.returncode})
print(json.dumps({'cases':len(results), 'passed':sum(x['passed'] for x in results), 'results':results}))
sys.exit(0 if all(x['passed'] for x in results) else 1)
'''


def compile_code_task(row: Mapping[str, Any], *, case_timeout: float = 3.0) -> tuple[dict, dict]:
    """Compile one external std-I/O task, with tests exclusively in private acceptance."""
    identity, query, truth = row.get("uuid"), row.get("query"), row.get("ground_truth")
    if not isinstance(identity, str) or not re.fullmatch(r"[A-Za-z0-9_-]+", identity):
        raise ValueError("unsafe or missing task identity")
    if row.get("domain") != "Code" or not isinstance(query, str) or not query.strip():
        raise ValueError("non-Code domain or empty task")
    if not isinstance(truth, dict) or truth.get("call_type") != "std" or truth.get("fn_name") is not None:
        raise ValueError("only explicit std-I/O tasks are supported")
    inputs, outputs = truth.get("inputs"), truth.get("outputs")
    if not isinstance(inputs, list) or not inputs or not isinstance(outputs, list) or len(inputs) != len(outputs):
        raise ValueError("nonempty equal-length I/O arrays required")
    if any(not isinstance(x, str) for x in inputs + outputs):
        raise ValueError("I/O values must be strings")
    seen = {}
    for source, target in zip(inputs, outputs):
        if source in seen and seen[source] != target.rstrip():
            raise ValueError("conflicting targets for identical input")
        seen[source] = target.rstrip()
    if isinstance(case_timeout, bool) or not math.isfinite(case_timeout) or case_timeout <= 0:
        raise ValueError("finite positive timeout required")
    output_limit = max(1024 * 1024, max(len(x.encode()) for x in outputs) + 65536)
    if output_limit > 16 * 1024 * 1024:
        raise ValueError("expected output exceeds bounded pilot verifier capacity")
    config = dict(inputs=inputs, outputs=outputs, case_timeout=case_timeout, output_limit=output_limit)
    program = _CODE_VERIFIER.replace("__CONFIG__", repr(json.dumps(config, ensure_ascii=True)))
    task = {"task_id": "ULTRA-" + identity, "level": "external_code", "user_request": query +
            "\n\nSubmission contract: Implement main.py in Python 3 using the standard library. "
            "Read one test case from stdin and write the specified answer to stdout. "
            "The verifier runs each test in a fresh process, comparing UTF-8 output after removing trailing whitespace only. "
            f"Limits per test: {case_timeout:g} seconds wall time, 512 MiB address space. "
            "Create and run your own checks before delivering.\n",
            "capabilities": ["file_read", "file_write", "command_exec"], "workspace_files": []}
    acceptance = {"runner_control": {"network_policy": "offline"}, "checks": [{"kind": "project_behavior",
                  "program": program, "program_sha256": hashlib.sha256(program.encode()).hexdigest(),
                  "timeout": 180, "browser": False}]}
    return task, acceptance

rwkv_lh/executor_provenance.py:
"""Mechanical provenance checks for observation-conditioned Executor arguments.

The model may use a summary to navigate, but a summary cannot authorize an exact
path, cursor, read-modify-write base revision, or source literal.  This module
checks those fields against the exact Harness projections that were actually in
the Executor fact scope and returns a compact, content-addressed audit record.
"""

from __future__ import annotations

import hashlib
import json
import re
from copy import deepcopy
from typing import Any, Mapping, Sequence

from rwkv_lh.model_io import canonical_digest
from rwkv_lh.goal_state_protocols import executor_args_v7
from rwkv_lh.observation_funnel import OBSERVATION_PROJECTION_VERSION


EXECUTOR_ARGUMENT_PROVENANCE_VERSION = (
    "rwkv-lh.executor-argument-provenance.v2"
)
RMW_OPERATIONS = frozenset({"patch_json", "replace_text", "remove_line"})
READ_OPERATIONS = frozenset({"read_file", "read_json"})
PAGED_OPERATIONS = frozenset({"list_directory", "search_text"})
COMMAND_OPERATIONS = frozenset({"check_command", "run_command"})
_SHA256_RE = re.compile(r"[0-9a-f]{64}")


class ExecutorProvenanceError(ValueError):
    """An exact Executor argument has no matching authoritative observation."""


def _sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _is_sha256(value: Any) -> bool:
    return isinstance(value, str) and _SHA256_RE.fullmatch(value) is not None


def _pointer_token(value: str) -> str:
    return value.replace("~", "~0").replace("/", "~1")


def _fact_projection(fact: Mapping[str, Any]) -> Mapping[str, Any]:
    operation = str(fact.get("operation") or "")
    if not operation:
        raise ExecutorProvenanceError(
            f"bound fact {fact.get('action_id')!r} has no operation identity"
        )
    result = fact.get("result")
    if not isinstance(result, Mapping):
        raise ExecutorProvenanceError(
            f"bound fact {fact.get('action_id')!r} has no projected result"
        )
    observation = result.get("observation")
    if not isinstance(observation, Mapping):
        raise ExecutorProvenanceError(
            f"bound fact {fact.get('action_id')!r} has no typed observation"
        )
    if observation.get("projection_version") != OBSERVATION_PROJECTION_VERSION:
        raise ExecutorProvenanceError(
            f"bound fact {fact.get('action_id')!r} uses another projection version"
        )
    if observation.get("summary_fact_authority") is not False:
        raise ExecutorProvenanceError(
            f"bound fact {fact.get('action_id')!r} grants authority to a summary"
        )
    if (
        result.get("action_type") != operation
        or observation.get("operation") != operation
    ):
        raise ExecutorProvenanceError(
            f"bound fact {fact.get('action_id')!r} has conflicting operation identities"
        )
    if not _is_sha256(observation.get("raw_result_sha256")):
        raise ExecutorProvenanceError(
            f"bound fact {fact.get('action_id')!r} has no raw-result identity"
        )
    return result


def _validated_fragment(
    action_id: str,
    span: Mapping[str, Any],
    *,
    content_key: str = "content",
    digest_key: str = "content_sha256",
    span_id_key: str = "span_id",
) -> dict[str, Any] | None:
    content = span.get(content_key)
    if not isinstance(content, str) or not content:
        return None
    content_sha256 = str(span.get(digest_key) or "")
    if content_sha256 != _sha256_text(content):
        raise ExecutorProvenanceError(
            f"bound fact {action_id!r} contains a fragment with invalid content SHA-256"
        )
    source_ref = str(span.get("source_ref") or "")
    snapshot_sha256 = str(span.get("snapshot_sha256") or "")
    raw_start_byte = span.get("start_byte")
    raw_end_byte = span.get("end_byte")
    if (
        isinstance(raw_start_byte, bool)
        or not isinstance(raw_start_byte, int)
        or isinstance(raw_end_byte, bool)
        or not isinstance(raw_end_byte, int)
    ):
        raise ExecutorProvenanceError(
            f"bound fact {action_id!r} contains a fragment without an exact byte range"
        )
    start_byte = raw_start_byte
    end_byte = raw_end_byte
    if (
        not source_ref
        or not _is_sha256(snapshot_sha256)
        or start_byte < 0
        or end_byte < start_byte
        or end_byte - start_byte != len(content.encode("utf-8"))
    ):
        raise ExecutorProvenanceError(
            f"bound fact {action_id!r} contains an invalid exact fragment locator"
        )
    identity = {
        "source_ref": source_ref,
        "snapshot_sha256": snapshot_sha256,
        "start_byte": start_byte,
        "end_byte": end_byte,
        "content_sha256": content_sha256,
    }
    span_id = str(span.get(span_id_key) or "")
    expected_span_id = f"OBS-SPAN-{canonical_digest(identity)[:20]}"
    if span_id != expected_span_id:
        raise ExecutorProvenanceError(
            f"bound fact {action_id!r} contains a fragment with an invalid span ID"
        )
    return {
        "action_id": action_id,
        "span_id": span_id,
        **identity,
        "content": content,
    }


def _fragments(fact: Mapping[str, Any]) -> tuple[dict[str, Any], ...]:
    action_id = str(fact.get("action_id") or "")
    result = _fact_projection(fact)
    observation = result["observation"]
    selected: list[dict[str, Any]] = []
    for span in observation.get("exact_spans") or ():
        if isinstance(span, Mapping):
            fragment = _validated_fragment(action_id, span)
            if fragment is not None:
                selected.append(fragment)
    for span in result.get("exact_spans") or ():
        if isinstance(span, Mapping):
            fragment = _validated_fragment(action_id, span)
            if fragment is not None:
                selected.append(fragment)
    structured = result.get("structured_output")
    if (
        str(fact.get("operation") or "") == "search_text"
        and isinstance(structured, Mapping)
    ):
        source_snapshots = structured.get("source_snapshots")
        if not isinstance(source_snapshots, Mapping):
            raise ExecutorProvenanceError(
                f"bound fact {action_id!r} search result has no source snapshots"
            )
        for match in structured.get("matches") or ():
            if not isinstance(match, Mapping):
                continue
            path = str(match.get("path") or "")
            line_text = match.get("line_text")
            line_sha256 = str(match.get("line_text_sha256") or "")
            snapshot_sha256 = str(match.get("source_snapshot_sha256") or "")
            span_id = str(match.get("source_span_id") or "")
            try:
                start_byte = int(match["line_text_start_byte"])
                end_byte = int(match["line_text_end_byte"])
            except (KeyError, TypeError, ValueError) as exc:
                raise ExecutorProvenanceError(
                    f"bound fact {action_id!r} search match lacks an exact byte range"
                ) from exc
            identity = {
                "source_ref": path,
                "snapshot_sha256": snapshot_sha256,
                "start_byte": start_byte,
                "end_byte": end_byte,
                "content_sha256": line_sha256,
            }
            if (
                not path
                or not isinstance(line_text, str)
                or not line_text
                or line_sha256 != _sha256_text(line_text)
                or not _is_sha256(snapshot_sha256)
                or source_snapshots.get(path) != snapshot_sha256
                or start_byte < 0
                or end_byte - start_byte != len(line_text.encode("utf-8"))
                or span_id != f"OBS-SPAN-{canonical_digest(identity)[:20]}"
            ):
                raise ExecutorProvenanceError(
                    f"bound fact {action_id!r} search match failed exact lineage validation"
                )
            selected.append(
                {
                    "action_id": action_id,
                    "span_id": span_id,
                    **identity,
                    "content": line_text,
                }
            )
    for stream in result.get("command_streams") or ():
        if not isinstance(stream, Mapping):
            continue
        stream_name = str(stream.get("stream") or "")
        stream_sha256 = str(stream.get("stream_sha256") or "")
        for span in stream.get("exact_spans") or ():
            if not isinstance(span, Mapping):
                continue
            fragment = _validated_fragment(action_id, span)
            if fragment is None:
                continue
            if (
                fragment["source_ref"]
                != f"command:{fact.get('operation')}:{stream_name}"
                or fragment["snapshot_sha256"] != stream_sha256
            ):
                raise ExecutorProvenanceError(
                    f"bound fact {action_id!r} command fragment has conflicting stream identity"
                )
            fragment["stream"] = stream_name
            selected.append(fragment)
    return tuple(selected)


def _narrow_fragment(
    fragment: Mapping[str, Any],
    literal: str,
    *,
    line_exact: bool = False,
) -> dict[str, Any] | None:
    if not literal:
        return None
    content = str(fragment["content"])
    character_start = -1
    if line_exact:
        cursor = 0
        for physical_line in content.splitlines(keepends=True):
            line = physical_line.rstrip("\r\n")
            if line == literal:
                character_start = cursor
                break
            cursor += len(physical_line)
        if character_start < 0 and content and not content.endswith(("\n", "\r")):
            tail_start = content.rfind("\n") + 1
            if content[tail_start:] == literal:
                character_start = tail_start
    else:
        character_start = content.find(literal)
    if character_start < 0:
        return None
    character_end = character_start + len(literal)
    match_start = int(fragment["start_byte"]) + len(
        content[:character_start].encode("utf-8")
    )
    match_end = int(fragment["start_byte"]) + len(
        content[:character_end].encode("utf-8")
    )
    return {
        "action_id": str(fragment["action_id"]),
        "parent_span_id": str(fragment["span_id"]),
        "source_ref": str(fragment["source_ref"]),
        "snapshot_sha256": str(fragment["snapshot_sha256"]),
        "start_byte": match_start,
        "end_byte": match_end,
        "content_sha256": _sha256_text(literal),
        "match_mode": "complete_line" if line_exact else "exact_substring",
    }


def _find_literal(
    facts: Sequence[Mapping[str, Any]],
    literal: str,
    *,
    action_id: str = "",
    line_exact: bool = False,
    source_ref: str = "",
    snapshot_sha256: str = "",
) -> dict[str, Any] | None:
    for fact in reversed(facts):
        if action_id and str(fact.get("action_id") or "") != action_id:
            continue
        for fragment in _fragments(fact):
            if source_ref and fragment["source_ref"] != source_ref:
                continue
            if (
                snapshot_sha256
                and fragment["snapshot_sha256"] != snapshot_sha256
            ):
                continue
            locator = _narrow_fragment(fragment, literal, line_exact=line_exact)
            if locator is not None:
                return locator
    return None


def _artifact_identity(
    fact: Mapping[str, Any],
    path: str,
    base_sha256: str,
) -> dict[str, Any] | None:
    result = _fact_projection(fact)
    if result.get("success") is not True:
        return None
    observation = result["observation"]
    artifact = observation.get("source_artifact")
    if isinstance(artifact, Mapping):
        if artifact.get("path") != path or artifact.get("sha256") != base_sha256:
            return None
        size_bytes = artifact.get("size_bytes")
        if (
            not _is_sha256(base_sha256)
            or isinstance(size_bytes, bool)
            or not isinstance(size_bytes, int)
            or size_bytes < 0
        ):
            raise ExecutorProvenanceError(
                f"bound fact {fact.get('action_id')!r} has an invalid source artifact identity"
            )
        return {
            "action_id": str(fact.get("action_id") or ""),
            "source_ref": path,
            "snapshot_sha256": base_sha256,
            "size_bytes": size_bytes,
            "authority": "harness_file_artifact_identity",
        }

    if str(fact.get("operation") or "") != "search_text":
        return None
    structured = result.get("structured_output")
    if not isinstance(structured, Mapping):
        return None
    snapshots = structured.get("source_snapshots")
    if not isinstance(snapshots, Mapping) or snapshots.get(path) != base_sha256:
        return None
    matching_fragments = [
        fragment
        for fragment in _fragments(fact)
        if fragment["source_ref"] == path
        and fragment["snapshot_sha256"] == base_sha256
    ]
    if not matching_fragments or not _is_sha256(base_sha256):
        return None
    return {
        "action_id": str(fact.get("action_id") or ""),
        "source_ref": path,
        "snapshot_sha256": base_sha256,
        "observed_span_ids": [item["span_id"] for item in matching_fragments],
        "authority": "harness_search_source_snapshot_identity",
    }


def _binding(
    pointer: str,
    value: Any,
    authority: str,
    locator: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        "argument_pointer": pointer,
        "argument_value_sha256": canonical_digest(value),
        "authority": authority,
        "locator": deepcopy(dict(locator)),
    }


def _require_literal(
    facts: Sequence[Mapping[str, Any]],
    literal: str,
    *,
    pointer: str,
    action_id: str = "",
    line_exact: bool = False,
    source_ref: str = "",
    snapshot_sha256: str = "",
) -> dict[str, Any]:
    locator = _find_literal(
        facts,
        literal,
        action_id=action_id,
        line_exact=line_exact,
        source_ref=source_ref,
        snapshot_sha256=snapshot_sha256,
    )
    if locator is None:
        raise ExecutorProvenanceError(
            f"{pointer} is not present in an exact fragment from the bound fact scope"
        )
    return _binding(pointer, literal, "exact_utf8_fragment", locator)


def _literal_requirement_binding(
    pointer: str,
    value: str,
    requirement: str,
) -> dict[str, Any] | None:
    if not _requirement_contains(requirement, value):
        return None
    return _binding(
        pointer,
        value,
        "literal_current_requirement",
        {
            "requirement_sha256": _sha256_text(requirement),
            "literal_sha256": _sha256_text(value),
        },
    )


def _top_level_json_key_locator(
    fact: Mapping[str, Any],
    path: str,
    key: str,
) -> dict[str, Any] | None:
    """Locate one key only after the complete canonical top-level object is seen."""

    result = _fact_projection(fact)
    observation = result["observation"]
    if str(fact.get("operation") or "") != "read_json":
        return None
    if observation.get("projection_complete") is not True:
        return None
    metadata = result.get("metadata")
    if not isinstance(metadata, Mapping):
        return None
    canonical_size = metadata.get("canonical_size_bytes")
    if (
        isinstance(canonical_size, bool)
        or not isinstance(canonical_size, int)
        or canonical_size < 2
    ):
        return None
    expected_source_ref = f"{path}#canonical-json"
    for fragment in _fragments(fact):
        content = str(fragment["content"])
        if (
            fragment["source_ref"] != expected_source_ref
            or fragment["start_byte"] != 0
            or fragment["end_byte"] != canonical_size
            or fragment["snapshot_sha256"] != _sha256_text(content)
        ):
            continue
        try:
            value = json.loads(content)
        except json.JSONDecodeError:
            continue
        if not isinstance(value, dict) or key not in value:
            continue
        decoder = json.JSONDecoder()
        depth = 0
        index = 0
        while index < len(content):
            character = content[index]
            if character == '"':
                try:
                    decoded, end = decoder.raw_decode(content, idx=index)
                except json.JSONDecodeError:
                    break
                after = end
                while after < len(content) and content[after].isspace():
                    after += 1
                if (
                    depth == 1
                    and decoded == key
                    and after < len(content)
                    and content[after] == ":"
                ):
                    marker_end = after + 1
                    start_byte = len(content[:index].encode("utf-8"))
                    end_byte = len(content[:marker_end].encode("utf-8"))
                    return {
                        "action_id": str(fact.get("action_id") or ""),
                        "parent_span_id": str(fragment["span_id"]),
                        "source_ref": expected_source_ref,
                        "snapshot_sha256": str(fragment["snapshot_sha256"]),
                        "start_byte": start_byte,
                        "end_byte": end_byte,
                        "content_sha256": _sha256_text(content[index:marker_end]),
                        "match_mode": "complete_canonical_top_level_json_key",
                    }
                index = end
                continue
            if character in "{[":
                depth += 1
            elif character in "}]":
                depth -= 1
                if depth < 0:
                    break
            index += 1
    return None


def _rmw_bindings(
    operation: str,
    arguments: Mapping[str, Any],
    facts: Sequence[Mapping[str, Any]],
    requirement: str,
) -> list[dict[str, Any]]:
    path = arguments.get("path")
    base_sha256 = arguments.get("base_sha256")
    if not isinstance(path, str) or not path or not _is_sha256(base_sha256):
        raise ExecutorProvenanceError(
            f"{operation} requires a path and lowercase base_sha256"
        )
    selected_fact: Mapping[str, Any] | None = None
    artifact: dict[str, Any] | None = None
    required_read_operations = (
        ("read_json",)
        if operation == "patch_json"
        else ("read_file", "search_text")
    )
    for fact in reversed(facts):
        if str(fact.get("operation") or "") not in required_read_operations:
            continue
        artifact = _artifact_identity(fact, path, str(base_sha256))
        if artifact is not None:
            selected_fact = fact
            break
    if selected_fact is None or artifact is None:
        raise ExecutorProvenanceError(
            f"{operation} base_sha256 is not the observed artifact identity for {path!r}"
        )
    action_id = str(selected_fact.get("action_id") or "")
    bindings = [
        _binding("/path", path, str(artifact["authority"]), artifact),
        _binding(
            "/base_sha256",
            base_sha256,
            str(artifact["authority"]),
            artifact,
        ),
    ]
    if operation == "replace_text":
        old = arguments.get("old")
        if not isinstance(old, str) or not old:
            raise ExecutorProvenanceError("replace_text /old must be non-empty")
        bindings.append(
            _require_literal(
                facts,
                old,
                pointer="/old",
                action_id=action_id,
                source_ref=path,
                snapshot_sha256=str(base_sha256),
            )
        )
        if "size_bytes" in artifact and int(
            bindings[-1]["locator"]["end_byte"]
        ) > int(artifact["size_bytes"]):
            raise ExecutorProvenanceError(
                "replace_text /old lies outside the bound source artifact"
            )
        new = arguments.get("new")
        if not isinstance(new, str):
            raise ExecutorProvenanceError("replace_text /new must be a string")
        requirement_binding = _literal_requirement_binding(
            "/new", new, requirement
        )
        if requirement_binding is not None:
            bindings.append(requirement_binding)
    elif operation == "remove_line":
        text = arguments.get("text")
        if not isinstance(text, str):
            raise ExecutorProvenanceError("remove_line /text must be a string")
        bindings.append(
            _require_literal(
                facts,
                text,
                pointer="/text",
                action_id=action_id,
                line_exact=True,
                source_ref=path,
                snapshot_sha256=str(base_sha256),
            )
        )
        if "size_bytes" in artifact and int(
            bindings[-1]["locator"]["end_byte"]
        ) > int(artifact["size_bytes"]):
            raise ExecutorProvenanceError(
                "remove_line /text lies outside the bound source artifact"
            )
    else:
        updates = arguments.get("updates")
        if not isinstance(updates, Mapping) or not updates:
            raise ExecutorProvenanceError("patch_json /updates must be a non-empty object")
        for key in updates:
            if not isinstance(key, str):
                raise ExecutorProvenanceError("patch_json update keys must be strings")
            locator = _top_level_json_key_locator(selected_fact, path, key)
            if locator is None:
                raise ExecutorProvenanceError(
                    f"/updates/{_pointer_token(key)} key is not a structurally verified "
                    "top-level key in the complete canonical JSON fragment"
                )
            bindings.append(
                _binding(
                    f"/updates/{_pointer_token(key)}#key",
                    key,
                    "exact_canonical_json_key",
                    locator,
                )
            )
    return bindings


def _continuation_binding(
    operation: str,
    arguments: Mapping[str, Any],
    facts: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    pointer: str
    field: str
    selected_value: Any
    if operation in READ_OPERATIONS:
        selected_value = arguments.get("start_byte", 0)
        if isinstance(selected_value, bool) or not isinstance(selected_value, int):
            raise ExecutorProvenanceError(f"{operation} /start_byte must be an integer")
        if selected_value == 0:
            return []
        pointer, field = "/start_byte", "next_start_byte"
    else:
        selected_value = arguments.get("start_after", "")
        if not isinstance(selected_value, str):
            raise ExecutorProvenanceError(f"{operation} /start_after must be a string")
        if not selected_value:
            return []
        pointer, field = "/start_after", "next_cursor"
    path = str(arguments.get("path") or ".")
    for fact in reversed(facts):
        if str(fact.get("operation") or "") != operation:
            continue
        prior_arguments = fact.get("arguments")
        if not isinstance(prior_arguments, Mapping):
            continue
        if str(prior_arguments.get("path") or ".") != path:
            continue
        result = _fact_projection(fact)
        metadata = result.get("metadata")
        if not isinstance(metadata, Mapping) or metadata.get(field) != selected_value:
            continue
        locator = {
            "action_id": str(fact.get("action_id") or ""),
            "result_pointer": f"/metadata/{field}",
            "raw_result_sha256": str(result["observation"].get("raw_result_sha256") or ""),
            "source_operation": operation,
            "source_path": path,
        }
        return [_binding(pointer, selected_value, "harness_continuation", locator)]
    raise ExecutorProvenanceError(
        f"{operation} {pointer} does not equal the bound same-source {field}"
    )


def _requirement_contains(requirement: str, literal: str) -> bool:
    if not literal or literal not in requirement:
        return False
    token_character = r"A-Za-z0-9_.\-/"
    return (
        re.search(
            rf"(?<![{token_character}]){re.escape(literal)}(?![{token_character}])",
            requirement,
        )
        is not None
    )


def _structured_path_locator(
    facts: Sequence[Mapping[str, Any]], path: str
) -> dict[str, Any] | None:
    for fact in reversed(facts):
        result = _fact_projection(fact)
        structured = result.get("structured_output")
        if not isinstance(structured, Mapping):
            continue
        operation = str(fact.get("operation") or "")
        item_key = "matches" if operation == "search_text" else "entries"
        for index, item in enumerate(structured.get(item_key) or ()):
            if not isinstance(item, Mapping) or item.get("path") != path:
                continue
            locator: dict[str, Any] = {
                "action_id": str(fact.get("action_id") or ""),
                "result_pointer": f"/structured_output/{item_key}/{index}/path",
                "raw_result_sha256": str(result["observation"].get("raw_result_sha256") or ""),
                "source_operation": operation,
            }
            if operation == "search_text":
                line_text = item.get("line_text")
                line_sha = str(item.get("line_text_sha256") or "")
                snapshot_sha = str(item.get("source_snapshot_sha256") or "")
                span_id = str(item.get("source_span_id") or "")
                try:
                    start_byte = int(item["line_text_start_byte"])
                    end_byte = int(item["line_text_end_byte"])
                except (KeyError, TypeError, ValueError) as exc:
                    raise ExecutorProvenanceError(
                        "search_text path item lacks an exact source-line locator"
                    ) from exc
                identity = {
                    "source_ref": path,
                    "snapshot_sha256": snapshot_sha,
                    "start_byte": start_byte,
                    "end_byte": end_byte,
                    "content_sha256": line_sha,
                }
                if (
                    not isinstance(line_text, str)
                    or line_sha != _sha256_text(line_text)
                    or not _is_sha256(snapshot_sha)
                    or end_byte - start_byte != len(line_text.encode("utf-8"))
                    or span_id != f"OBS-SPAN-{canonical_digest(identity)[:20]}"
                ):
                    raise ExecutorProvenanceError(
                        "search_text path item failed its exact source-line identity"
                    )
                locator.update(
                    {
                        "source_span_id": span_id,
                        "source_ref": path,
                        "snapshot_sha256": snapshot_sha,
                        "start_byte": start_byte,
                        "end_byte": end_byte,
                        "content_sha256": line_sha,
                    }
                )
            return locator
    return None


def _path_discovery_binding(
    operation: str,
    arguments: Mapping[str, Any],
    facts: Sequence[Mapping[str, Any]],
    requirement: str,
    execution_state: Mapping[str, Any],
) -> list[dict[str, Any]]:
    if operation not in {"read_file", "read_json", "file_digest"}:
        return []
    path = arguments.get("path")
    if not isinstance(path, str) or not path:
        return []
    target_contract = execution_state.get("target_contract")
    if isinstance(target_contract, Mapping) and target_contract.get(
        "schema_version"
    ) == executor_args_v7.TARGET_CONTRACT_SCHEMA_VERSION:
        compatible = target_contract.get("argument_targets_by_operation")
        operation_paths = (
            ((compatible.get(operation) or {}).get("path") or {}).get("compatible_paths")
            if isinstance(compatible, Mapping)
            else None
        )
        if (
            isinstance(operation_paths, list)
            and path in operation_paths
            and all(isinstance(item, str) for item in operation_paths)
        ):
            descriptors = target_contract.get("target_descriptors")
            descriptor = next(
                (
                    dict(item)
                    for item in descriptors or ()
                    if isinstance(item, Mapping) and item.get("path") == path
                ),
                None,
            )
            if descriptor is None:
                raise ExecutorProvenanceError(
                    "Controller target contract names a path without its Harness descriptor"
                )
            return [
                _binding(
                    "/path",
                    path,
                    "controller_harness_target_contract",
                    {
                        "target_contract_sha256": canonical_digest(target_contract),
                        "phase": str(target_contract.get("phase") or ""),
                        "descriptor": descriptor,
                    },
                )
            ]
    discovery_facts = [
        fact
        for fact in facts
        if str(fact.get("operation") or "") in {"search_text", "list_directory"}
    ]
    if not discovery_facts:
        return []
    locator = _structured_path_locator(discovery_facts, path)
    if locator is not None:
        return [_binding("/path", path, "literal_structured_path", locator)]
    literal_locator = _find_literal(facts, path)
    if literal_locator is not None:
        return [_binding("/path", path, "exact_utf8_fragment", literal_locator)]
    if _requirement_contains(requirement, path):
        return [
            _binding(
                "/path",
                path,
                "literal_current_requirement",
                {
                    "requirement_sha256": _sha256_text(requirement),
                    "literal_sha256": _sha256_text(path),
                },
            )
        ]
    raise ExecutorProvenanceError(
        f"/path {path!r} is not an exact item in the bound discovery observation"
    )


def _same_command_family(previous: Sequence[str], current: Sequence[str]) -> bool:
    if not previous or not current or previous[0] != current[0]:
        return False
    if len(previous) >= 2 and len(current) >= 2:
        return previous[1] == current[1]
    return True


def _command_repair_bindings(
    operation: str,
    arguments: Mapping[str, Any],
    facts: Sequence[Mapping[str, Any]],
    requirement: str,
    execution_state: Mapping[str, Any],
) -> list[dict[str, Any]]:
    del execution_state
    if operation not in COMMAND_OPERATIONS:
        return []
    argv = arguments.get("argv")
    if not isinstance(argv, list) or any(not isinstance(item, str) for item in argv):
        return []
    prior_fact: Mapping[str, Any] | None = None
    prior_argv: list[str] = []
    for fact in reversed(facts):
        if str(fact.get("operation") or "") not in COMMAND_OPERATIONS:
            continue
        result = _fact_projection(fact)
        prior_arguments = fact.get("arguments")
        candidate = (
            list(prior_arguments.get("argv") or ())
            if isinstance(prior_arguments, Mapping)
            else []
        )
        if (
            result.get("success") is False
            and all(isinstance(item, str) for item in candidate)
            and _same_command_family(candidate, argv)
        ):
            prior_fact, prior_argv = fact, candidate
            break
    if prior_fact is None:
        return []
    bindings: list[dict[str, Any]] = []
    for index, item in enumerate(argv):
        if index < len(prior_argv) and item == prior_argv[index]:
            continue
        pointer = f"/argv/{index}"
        locator = _find_literal((prior_fact,), item)
        if locator is not None:
            bindings.append(_binding(pointer, item, "exact_command_stream", locator))
            continue
        if _requirement_contains(requirement, item):
            bindings.append(
                _binding(
                    pointer,
                    item,
                    "literal_current_requirement",
                    {
                        "requirement_sha256": _sha256_text(requirement),
                        "literal_sha256": _sha256_text(item),
                    },
                )
            )
            continue
        raise ExecutorProvenanceError(
            f"{pointer} changed during command repair but is absent from exact stderr/stdout"
        )
    return bindings


def validate_executor_argument_provenance(
    operation: str,
    arguments: Mapping[str, Any],
    *,
    current_requirement: str,
    immutable_goal: str = "",
    fact_records: Sequence[Mapping[str, Any]],
    execution_state: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Validate source-derived fields and return their exact evidence locators."""

    selected_operation = str(operation or "").strip()
    selected_arguments = dict(arguments)
    selected_requirement = "\n".join(item for item in (str(immutable_goal or "").strip(),
        str(current_requirement or "").strip()) if item)
    selected_execution_state = dict(execution_state or {})
    facts = tuple(dict(item) for item in fact_records)
    action_ids = tuple(str(item.get("action_id") or "") for item in facts)
    if any(not item for item in action_ids) or len(set(action_ids)) != len(action_ids):
        raise ExecutorProvenanceError(
            "Executor fact scope requires unique non-empty action IDs"
        )
    for fact in facts:
        _fact_projection(fact)

    bindings: list[dict[str, Any]] = []
    if selected_operation in RMW_OPERATIONS:
        bindings.extend(
            _rmw_bindings(
                selected_operation,
                selected_arguments,
                facts,
                selected_requirement,
            )
        )
    if selected_operation in READ_OPERATIONS | PAGED_OPERATIONS:
        bindings.extend(
            _continuation_binding(selected_operation, selected_arguments, facts)
        )
    bindings.extend(
        _path_discovery_binding(
            selected_operation,
            selected_arguments,
            facts,
            selected_requirement,
            selected_execution_state,
        )
    )
    bindings.extend(
        _command_repair_bindings(
            selected_operation,
            selected_arguments,
            facts,
            selected_requirement,
            selected_execution_state,
        )
    )
    return {
        "schema_version": EXECUTOR_ARGUMENT_PROVENANCE_VERSION,
        "operation": selected_operation,
        "fact_action_ids": list(action_ids),
        "fact_projection_sha256": canonical_digest(facts),
        "execution_state_sha256": canonical_digest(selected_execution_state),
        "checked_argument_count": len(bindings),
        "bindings": bindings,
        "summary_fact_authority": False,
        "passed": True,
    }


__all__ = [
    "EXECUTOR_ARGUMENT_PROVENANCE_VERSION",
    "ExecutorProvenanceError",
    "validate_executor_argument_provenance",
]

rwkv_lh/runtime/role_config.py:
"""Small, fail-closed environment binding for replaceable model roles."""

from __future__ import annotations

import os


def role_env_name(role: str, suffix: str) -> str:
    return f"RWKV_LH_{role.strip().upper()}_{suffix.strip().upper()}"


def role_env(
    role: str,
    suffix: str,
    *,
    legacy: str = "",
    default: str = "",
) -> str:
    """Resolve one role setting without silently mixing old and new bindings."""

    canonical = role_env_name(role, suffix)
    canonical_present = canonical in os.environ
    legacy_present = bool(legacy) and legacy in os.environ
    canonical_value = os.environ.get(canonical, "").strip()
    legacy_value = os.environ.get(legacy, "").strip() if legacy else ""
    if canonical_present and legacy_present and canonical_value != legacy_value:
        raise ValueError(
            f"conflicting role settings: {canonical} and {legacy} must match"
        )
    if canonical_present:
        return canonical_value
    if legacy_present:
        return legacy_value
    return str(default).strip()


def role_float(
    role: str,
    suffix: str,
    *,
    legacy: str = "",
    default: float,
) -> float:
    name = role_env_name(role, suffix)
    value = role_env(role, suffix, legacy=legacy, default=str(default))
    try:
        return float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{name} must be a number") from exc


def role_int(
    role: str,
    suffix: str,
    *,
    legacy: str = "",
    default: int,
) -> int:
    name = role_env_name(role, suffix)
    value = role_env(role, suffix, legacy=legacy, default=str(default))
    try:
        return int(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{name} must be an integer") from exc


def role_bool(
    role: str,
    suffix: str,
    *,
    legacy: str = "",
    default: bool,
) -> bool:
    name = role_env_name(role, suffix)
    value = role_env(
        role,
        suffix,
        legacy=legacy,
        default=str(default),
    ).casefold()
    if value in {"1", "true", "yes", "on"}:
        return True
    if value in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"{name} must be a boolean")


__all__ = [
    "role_bool",
    "role_env",
    "role_env_name",
    "role_float",
    "role_int",
]

"""Current Native request identity contract, independent of model/role schemas.

The deployed journal binds each request ID to an operation and canonical body.
Preparing the same non-generation operation again preserves its identity;
generation must use the durable ID allocated by its ModelSession boundary.
"""
from __future__ import annotations

import hashlib
import json
import re
from typing import Any, Mapping

NATIVE_REQUEST_RECOVERY_VERSION = "rwkv-lh.native-request-recovery.v1"
NATIVE_REQUEST_OPERATIONS = frozenset({
    "create", "append", "fork", "generate", "commit", "rollback", "import", "release",
})
_REQUEST_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}\Z")


def native_result_digest(value: Mapping[str, Any]) -> str:
    encoded = json.dumps(dict(value), ensure_ascii=False, sort_keys=True,
        separators=(",", ":"), allow_nan=False).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def native_request_digest(operation: str, payload: Mapping[str, Any]) -> str:
    if operation not in NATIVE_REQUEST_OPERATIONS:
        raise ValueError("unsupported Native request operation")
    return native_result_digest({"operation": operation, "payload": dict(payload)})


def prepare_native_request(operation: str, payload: Mapping[str, Any]) -> dict[str, Any]:
    if operation not in NATIVE_REQUEST_OPERATIONS:
        raise ValueError("unsupported Native request operation")
    prepared = dict(payload)
    version = prepared.setdefault("recovery_protocol", NATIVE_REQUEST_RECOVERY_VERSION)
    if version != NATIVE_REQUEST_RECOVERY_VERSION:
        raise ValueError("unsupported Native request recovery protocol")
    if "request_id" not in prepared:
        if operation == "generate":
            raise ValueError("Native generation requires its durable request ID")
        prepared["request_id"] = "NR-" + native_request_digest(operation, prepared)
    request_id = prepared["request_id"]
    if not isinstance(request_id, str) or not _REQUEST_ID.fullmatch(request_id):
        raise ValueError("invalid Native request ID")
    native_request_digest(operation, prepared)
    return prepared

"""Durable Native request results; an uncertain operation is never executed again.

The journal stores request digests, original results and service-owned recovery
metadata. It never stores request headers, request bodies or exception text.
The service must export every referenced State before returning its result.
"""
from __future__ import annotations

import asyncio
import hashlib
import json
import os
import re
import sqlite3
import time
from contextlib import contextmanager
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Awaitable, Callable, Mapping
from uuid import uuid4

from rwkv_lh.runtime.native_request_protocol import (
    NATIVE_REQUEST_RECOVERY_VERSION, NATIVE_REQUEST_OPERATIONS,
    native_result_digest, native_request_digest, prepare_native_request,
)


class NativeRequestConflict(ValueError):
    """A request ID is already bound to a different operation or payload."""


class NativeRequestInProgress(RuntimeError):
    """A durable claim exists but this process has no waiter for it."""


class NativeRequestOutcomeUnknown(RuntimeError):
    """An operation may have executed; executing it again is prohibited."""


class NativeStateRetired(ValueError):
    """An explicitly retired handle cannot authorize a new operation."""


def _json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)



@dataclass(frozen=True)
class NativeRequestResult:
    body: Mapping[str, Any]
    status_code: int = 200
    recovery_metadata: Mapping[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class NativeRequestRecord:
    request_id: str
    operation: str
    request_digest: str
    status: str
    body: Mapping[str, Any] | None = None
    status_code: int | None = None
    recovery_metadata: Mapping[str, Any] = field(default_factory=dict)

    def to_response(self) -> dict[str, Any]:
        response = {
            "schema_version": NATIVE_REQUEST_RECOVERY_VERSION,
            "request_id": self.request_id,
            "operation": self.operation,
            "request_digest": self.request_digest,
            "status": self.status,
        }
        if self.status == "completed":
            assert self.body is not None
            response.update(http_status=self.status_code, result=dict(self.body),
                            result_sha256=native_result_digest(self.body))
        return response


class NativeRequestJournal:
    """SQLite claims survive process loss; shielded work survives HTTP loss.

    A completed result is replayable after restart. A pending row owned by a
    different journal instance is unknown, because no durable result proves
    whether its side effects completed. Neither state authorizes a second call.
    """

    def __init__(self, path: str | Path) -> None:
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd = os.open(self.path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
        os.fchmod(fd, 0o600)
        os.close(fd)
        self.owner_id = uuid4().hex
        self._tasks: dict[str, asyncio.Task[NativeRequestRecord]] = {}
        with self._connect() as connection:
            connection.execute("PRAGMA journal_mode=WAL")
            tables = {row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if ("native_requests" in tables and "native_request_inputs" not in tables
                    and connection.execute("SELECT 1 FROM native_requests LIMIT 1").fetchone()):
                raise RuntimeError("Native lifecycle requires a fresh journal; historical input pins are unavailable")
            connection.execute("""CREATE TABLE IF NOT EXISTS native_requests (
                request_id TEXT PRIMARY KEY, operation TEXT NOT NULL,
                request_digest TEXT NOT NULL, status TEXT NOT NULL,
                owner_id TEXT NOT NULL, result_json TEXT, result_sha256 TEXT,
                status_code INTEGER, recovery_json TEXT, created REAL NOT NULL,
                updated REAL NOT NULL)""")
            connection.execute("""CREATE TABLE IF NOT EXISTS native_request_states (
                state_ref TEXT PRIMARY KEY, metadata_json TEXT NOT NULL,
                metadata_sha256 TEXT NOT NULL, updated_request_id TEXT NOT NULL)""")
            connection.execute("""CREATE TABLE IF NOT EXISTS native_request_mutations (
                request_id TEXT PRIMARY KEY, state_ref TEXT NOT NULL)""")
            connection.execute("""CREATE TABLE IF NOT EXISTS native_request_inputs (
                request_id TEXT NOT NULL, kind TEXT NOT NULL, resource TEXT NOT NULL,
                PRIMARY KEY(request_id,kind,resource))""")
            connection.execute("""CREATE TABLE IF NOT EXISTS native_state_retirements (
                state_ref TEXT PRIMARY KEY, store_key TEXT, cache_dropped INTEGER NOT NULL DEFAULT 0)""")
            connection.execute("""CREATE TABLE IF NOT EXISTS native_state_gc (
                store_key TEXT PRIMARY KEY)""")

    @contextmanager
    def _connect(self):
        connection = sqlite3.connect(self.path, timeout=30)
        connection.row_factory = sqlite3.Row
        try:
            connection.execute("PRAGMA synchronous=FULL")
            with connection:
                yield connection
        finally:
            connection.close()

    def _record(self, row: sqlite3.Row) -> NativeRequestRecord:
        status = row["status"]
        if status == "pending" and row["owner_id"] != self.owner_id:
            status = "unknown"
        body = json.loads(row["result_json"]) if row["result_json"] is not None else None
        metadata = json.loads(row["recovery_json"] or "{}")
        if status == "completed" and (not isinstance(body, dict)
                or not isinstance(metadata, dict)
                or native_result_digest({"body": body, "status_code": row["status_code"],
                                         "recovery_metadata": metadata}) != row["result_sha256"]):
            raise RuntimeError("Native request result integrity mismatch")
        return NativeRequestRecord(
            row["request_id"], row["operation"], row["request_digest"], status,
            body, row["status_code"], metadata,
        )

    def lookup(self, request_id: str, request_digest: str | None = None) -> NativeRequestRecord | None:
        with self._connect() as connection:
            row = connection.execute("SELECT * FROM native_requests WHERE request_id=?", (request_id,)).fetchone()
        if row is None:
            return None
        if request_digest is not None and row["request_digest"] != request_digest:
            raise NativeRequestConflict("Native request ID has a different payload")
        return self._record(row)

    def lookup_state_metadata(self, state_ref: str, *, allow_request_id: str = "") -> dict[str, Any] | None:
        with self._connect() as connection:
            uncertain = connection.execute("""SELECT r.request_id FROM native_request_mutations m
                JOIN native_requests r ON r.request_id=m.request_id WHERE m.state_ref=?
                AND r.status IN ('pending', 'unknown') AND r.request_id != ? LIMIT 1""",
                (state_ref, allow_request_id)).fetchone()
            if uncertain is not None:
                raise NativeRequestOutcomeUnknown("Native State has an unresolved mutation")
            row = connection.execute("SELECT * FROM native_request_states WHERE state_ref=?", (state_ref,)).fetchone()
        if row is None:
            return None
        metadata = json.loads(row["metadata_json"])
        if (not isinstance(metadata, dict) or metadata.get("state_ref") != state_ref
                or native_result_digest(metadata) != row["metadata_sha256"]):
            raise RuntimeError("Native State recovery metadata integrity mismatch")
        return metadata

    @staticmethod
    def _state_rows(connection) -> list[dict[str, Any]]:
        result = []
        for row in connection.execute("SELECT * FROM native_request_states"):
            metadata = json.loads(row["metadata_json"])
            if (not isinstance(metadata, dict) or metadata.get("state_ref") != row["state_ref"]
                    or native_result_digest(metadata) != row["metadata_sha256"]):
                raise RuntimeError("Native State recovery metadata integrity mismatch")
            result.append(metadata)
        return result

    @staticmethod
    def _retired(metadata: Mapping[str, Any]) -> bool:
        return metadata.get("dropped") is True or metadata.get("released") is True

    @staticmethod
    def _store_key(metadata: Mapping[str, Any]) -> str | None:
        exported = metadata.get("export_record")
        key = exported.get("store_key") if isinstance(exported, dict) else None
        if key is not None and (not isinstance(key, str) or not re.fullmatch(r"[0-9a-f]{64}", key)):
            raise RuntimeError("Native State export has an invalid store key")
        return key

    def validate_release(self, refs: set[str], *, allow_request_id: str) -> None:
        """Called under the service execution lock before any batch mutation."""
        with self._connect() as connection:
            states = self._state_rows(connection)
            by_ref = {value["state_ref"]: value for value in states}
            for value in states:
                if (not self._retired(value) and value.get("committed") is False
                        and value.get("parent_state_ref") in refs):
                    raise NativeRequestConflict("a live candidate still requires the parent State")
            keys = {self._store_key(by_ref[ref]) for ref in refs if ref in by_ref}
            keys.discard(None)
            for row in connection.execute("""SELECT i.kind,i.resource FROM native_request_inputs i
                    JOIN native_requests r ON r.request_id=i.request_id
                    WHERE r.status IN ('pending','unknown') AND r.request_id != ?""", (allow_request_id,)):
                if (row["kind"] == "state" and row["resource"] in refs
                        or row["kind"] == "blob" and row["resource"] in keys):
                    raise NativeRequestOutcomeUnknown("a pending or unknown request still requires this State")

    def import_aliases_for(self, originals: set[str]) -> list[dict[str, Any]]:
        with self._connect() as connection:
            states = self._state_rows(connection)
        by_ref = {value["state_ref"]: value for value in states}
        aliases = []
        for value in states:
            origin = value.get("import_origin_state_ref")
            if origin not in originals or value["state_ref"] in originals:
                continue
            original = by_ref[origin]
            if (all(value.get(key) == original.get(key) for key in ("state_digest", "cache_binding_digest"))
                    and self._store_key(value) == self._store_key(original)):
                aliases.append(value)
        return aliases

    def pending_retirements(self) -> list[str]:
        with self._connect() as connection:
            return [row[0] for row in connection.execute(
                "SELECT state_ref FROM native_state_retirements WHERE cache_dropped=0 ORDER BY state_ref")]

    def mark_cache_dropped(self, state_ref: str) -> None:
        with self._connect() as connection:
            connection.execute("UPDATE native_state_retirements SET cache_dropped=1 WHERE state_ref=?", (state_ref,))

    def reclaimable_store_keys(self) -> list[str]:
        """Only current owners/pins retain tensors, never historical receipts."""
        with self._connect() as connection:
            states = self._state_rows(connection)
            by_ref = {value["state_ref"]: value for value in states}
            protected = {self._store_key(value) for value in states if not self._retired(value)}
            for row in connection.execute("""SELECT i.kind,i.resource FROM native_request_inputs i
                    JOIN native_requests r ON r.request_id=i.request_id WHERE r.status IN ('pending','unknown')"""):
                if row["kind"] == "blob":
                    protected.add(row["resource"])
                elif row["resource"] in by_ref:
                    protected.add(self._store_key(by_ref[row["resource"]]))
            return [row[0] for row in connection.execute("SELECT store_key FROM native_state_gc ORDER BY store_key")
                    if row[0] not in protected]

    def mark_blob_deleted(self, store_key: str) -> None:
        with self._connect() as connection:
            connection.execute("DELETE FROM native_state_gc WHERE store_key=?", (store_key,))

    def gc_pending_count(self) -> int:
        with self._connect() as connection:
            return connection.execute("SELECT COUNT(*) FROM native_state_gc").fetchone()[0]

    @classmethod
    def _update_state_metadata(cls, connection, request_id, metadata):
        states = metadata.get("states", [])
        dropped = metadata.get("dropped_state_refs", [])
        released = metadata.get("released_state_refs", [])
        if (not isinstance(states, list) or not isinstance(dropped, list) or not isinstance(released, list)
                or any(not isinstance(value, dict) or not isinstance(value.get("state_ref"), str)
                       or not value["state_ref"] for value in states)
                or any(not isinstance(ref, str) or not ref for ref in dropped + released)):
            raise ValueError("invalid Native State recovery metadata")
        refs = [value["state_ref"] for value in states] + dropped + released
        if len(refs) != len(set(refs)):
            raise ValueError("duplicate Native State recovery metadata")
        values = states + [{"state_ref": ref, "dropped": True} for ref in dropped] + [
            {"state_ref": ref, "released": True} for ref in released]
        for value in values:
            ref = value["state_ref"]
            previous = connection.execute("SELECT * FROM native_request_states WHERE state_ref=?", (ref,)).fetchone()
            if previous is not None:
                old = json.loads(previous["metadata_json"])
                if native_result_digest(old) != previous["metadata_sha256"]:
                    raise RuntimeError("Native State recovery metadata integrity mismatch")
                if cls._retired(old) and not cls._retired(value):
                    raise ValueError("a retired Native State cannot be resurrected")
                if old.get("committed") is True and value.get("committed") is False:
                    raise ValueError("a committed Native State cannot become a candidate")
                if cls._retired(value):
                    value = {**old, **value}
                    key = cls._store_key(old)
                    connection.execute("""INSERT INTO native_state_retirements (state_ref,store_key)
                        VALUES (?,?) ON CONFLICT(state_ref) DO NOTHING""", (ref, key))
                    if key and not cls._retired(old):
                        connection.execute("INSERT OR IGNORE INTO native_state_gc (store_key) VALUES (?)", (key,))
            connection.execute("""INSERT INTO native_request_states
                (state_ref, metadata_json, metadata_sha256, updated_request_id) VALUES (?, ?, ?, ?)
                ON CONFLICT(state_ref) DO UPDATE SET metadata_json=excluded.metadata_json,
                metadata_sha256=excluded.metadata_sha256, updated_request_id=excluded.updated_request_id""",
                (ref, _json(value), native_result_digest(value), request_id))

    @staticmethod
    def _input_resources(operation: str, payload: Mapping[str, Any]) -> set[tuple[str, str]]:
        resources = set()
        for field in ("parent_state_ref", "candidate_state_ref"):
            value = payload.get(field)
            if isinstance(value, str) and value:
                resources.add(("state", value))
        if operation == "release" and isinstance(payload.get("states"), list):
            for value in payload["states"]:
                if isinstance(value, dict) and isinstance(value.get("state_ref"), str) and value["state_ref"]:
                    resources.add(("state", value["state_ref"]))
        exported = payload.get("export_record") if operation == "import" else None
        if isinstance(exported, dict):
            for kind, field in (("state", "state_ref"), ("blob", "store_key")):
                value = exported.get(field)
                if isinstance(value, str) and value:
                    resources.add((kind, value))
        return resources

    def _claim(self, operation: str, payload: Mapping[str, Any]) -> tuple[NativeRequestRecord, bool]:
        if dict(payload) != prepare_native_request(operation, payload):
            raise ValueError("Native request requires recovery protocol and request ID")
        request_id = payload["request_id"]
        digest = native_request_digest(operation, payload)
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute("SELECT * FROM native_requests WHERE request_id=?", (request_id,)).fetchone()
            if row is not None:
                if row["request_digest"] != digest or row["operation"] != operation:
                    raise NativeRequestConflict("Native request ID has a different payload")
                return self._record(row), False
            now = time.time()
            resources = self._input_resources(operation, payload)
            for kind, resource in resources:
                if kind == "state":
                    row = connection.execute("SELECT metadata_json FROM native_request_states WHERE state_ref=?", (resource,)).fetchone()
                    if row is not None and self._retired(json.loads(row[0])) and operation != "release":
                        raise NativeStateRetired("State handle was explicitly retired")
            mutation_ref = payload.get("candidate_state_ref") if operation in {"commit", "rollback"} else None
            if isinstance(mutation_ref, str) and mutation_ref:
                uncertain = connection.execute("""SELECT r.request_id FROM native_request_mutations m
                    JOIN native_requests r ON r.request_id=m.request_id WHERE m.state_ref=?
                    AND r.status IN ('pending', 'unknown') LIMIT 1""", (mutation_ref,)).fetchone()
                if uncertain is not None:
                    raise NativeRequestOutcomeUnknown("Native State already has an unresolved mutation")
            connection.execute("""INSERT INTO native_requests
                (request_id, operation, request_digest, status, owner_id, created, updated)
                VALUES (?, ?, ?, 'pending', ?, ?, ?)""", (request_id, operation, digest, self.owner_id, now, now))
            connection.executemany("INSERT INTO native_request_inputs (request_id,kind,resource) VALUES (?,?,?)",
                                   [(request_id, kind, resource) for kind, resource in sorted(resources)])
            if isinstance(mutation_ref, str) and mutation_ref:
                connection.execute("INSERT INTO native_request_mutations (request_id,state_ref) VALUES (?,?)",
                                   (request_id, mutation_ref))
        return NativeRequestRecord(request_id, operation, digest, "pending"), True

    async def _run(self, claimed: NativeRequestRecord, invoke: Callable[[], Awaitable[NativeRequestResult | Mapping[str, Any]]], execution_lock=None) -> NativeRequestRecord:
        if execution_lock is not None:
            async with execution_lock:
                return await self._run(claimed, invoke)
        try:
            result = await invoke()
            if isinstance(result, Mapping):
                result = NativeRequestResult(result)
            if not isinstance(result, NativeRequestResult) or not isinstance(result.body, Mapping):
                raise TypeError("Native request callback returned an invalid result")
            if isinstance(result.status_code, bool) or not isinstance(result.status_code, int) or not 200 <= result.status_code <= 599:
                raise ValueError("Native request result has an invalid HTTP status")
            body_json, metadata_json = _json(dict(result.body)), _json(dict(result.recovery_metadata))
            result_digest = native_result_digest({"body": dict(result.body), "status_code": result.status_code,
                                                  "recovery_metadata": dict(result.recovery_metadata)})
            with self._connect() as connection:
                connection.execute("BEGIN IMMEDIATE")
                self._update_state_metadata(connection, claimed.request_id, result.recovery_metadata)
                changed = connection.execute("""UPDATE native_requests SET status='completed', result_json=?,
                    result_sha256=?, status_code=?, recovery_json=?, updated=?
                    WHERE request_id=? AND owner_id=? AND status='pending'""",
                    (body_json, result_digest, result.status_code, metadata_json,
                     time.time(), claimed.request_id, self.owner_id))
                if changed.rowcount != 1:
                    raise RuntimeError("Native request completion lost its durable claim")
            record = self.lookup(claimed.request_id, claimed.request_digest)
            assert record is not None
            return record
        except BaseException:
            with self._connect() as connection:
                connection.execute("""UPDATE native_requests SET status='unknown', updated=?
                    WHERE request_id=? AND owner_id=? AND status='pending'""",
                    (time.time(), claimed.request_id, self.owner_id))
            raise

    async def execute(self, operation: str, payload: Mapping[str, Any],
                      invoke: Callable[[], Awaitable[NativeRequestResult | Mapping[str, Any]]], *,
                      execution_lock: asyncio.Lock | None = None) -> NativeRequestRecord:
        claimed, created = self._claim(operation, payload)
        if claimed.status == "completed":
            return claimed
        if claimed.status == "unknown":
            raise NativeRequestOutcomeUnknown("Native request outcome is unknown; reexecution is prohibited")
        task = self._tasks.get(claimed.request_id)
        if created:
            task = asyncio.create_task(self._run(claimed, invoke, execution_lock))
            self._tasks[claimed.request_id] = task

            def done(completed: asyncio.Task[NativeRequestRecord]) -> None:
                self._tasks.pop(claimed.request_id, None)
                if not completed.cancelled():
                    completed.exception()  # Retrieve detached failures without logging their text.
            task.add_done_callback(done)
        if task is None:
            raise NativeRequestInProgress("Native request is pending in another execution context")
        return await asyncio.shield(task)

rwkv_lh/runtime/supervisor_vllm_rwkv.py:
"""Native vllm-rwkv text transport for the existing Goal Supervisor contracts.

The System/User/Bot rendering matches vllm.tokenizers.rwkv_defaults. Planner
uses its empty fake_think prefix; Stage Checker retains open_think. The role
payload and system instruction still come from the existing Supervisor builder.
"""
from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from typing import Any

from rwkv_lh.runtime.openai_compat import OpenAICompatibleRWKVClient
from rwkv_lh.runtime.protocol import CompletionResponse, RWKVProtocolError, TextCompletionRequest

BACKEND_PROFILE = "vllm-rwkv-native"
TRANSPORT = "vllm_rwkv_completions"
STATE_PROFILE_ID = "zero"
STATE_PROFILE_SHA256 = "0" * 64


@dataclass(frozen=True)
class NativeSupervisorEnvelope:
    input_envelope: str
    generation_prefill: str
    generation_mode: str


# These are exact deployed tokenizer prefixes; the model supplies the final >.
PLANNER_ENVELOPE = NativeSupervisorEnvelope(
    "rwkv_native_bot_fake_think", "<think></think", "fake_think",
)
STAGE_REVIEW_ENVELOPE = NativeSupervisorEnvelope(
    "rwkv_native_bot_open_think", "<think", "open_think",
)


def envelope_for_phase(phase: str) -> NativeSupervisorEnvelope:
    if phase == "goal_plan":
        return PLANNER_ENVELOPE
    if phase == "goal_stage_review":
        return STAGE_REVIEW_ENVELOPE
    raise ValueError(f"unsupported native Supervisor phase: {phase!r}")


def build_completion_payload(
    *, phase: str, model: str, system_prompt: str, payload_text: str, max_tokens: int,
) -> dict[str, Any]:
    envelope = envelope_for_phase(phase)
    prompt = (
        f"System✿{system_prompt}✿\nUser✿{payload_text}✿\nBot✿{envelope.generation_prefill}"
    )
    body = TextCompletionRequest(
        prompt=prompt, max_tokens=max_tokens, temperature=0.1,
        top_p=1.0, top_k=0, presence_penalty=0.0, frequency_penalty=0.0,
        penalty_decay=0.996, stop=("✿",), stop_token_ids=(0,),
        add_special_tokens=True, return_token_ids=True,
    ).payload(model, sampler_mode="native")
    # Each ordinary completion starts independently from explicit zero State.
    # No Executor sampling context, checkpoint or native State handle is used.
    body["vllm_xargs"] = {
        "rwkv_state_profile": STATE_PROFILE_ID,
        "rwkv_state_profile_sha256": STATE_PROFILE_SHA256,
    }
    return body


def decode_completion(
    data: Mapping[str, Any], *, phase: str, latency_ms: float, attempts: int,
) -> CompletionResponse:
    envelope = envelope_for_phase(phase)
    choices = data.get("choices")
    if not isinstance(choices, list) or len(choices) != 1 or not isinstance(choices[0], Mapping):
        raise RWKVProtocolError("native Supervisor requires exactly one completion choice")
    choice = choices[0]
    if choice.get("finish_reason") != "stop":
        raise RWKVProtocolError(
            f"native Supervisor completion did not finish: {choice.get('finish_reason')!r}"
        )
    raw = choice.get("text")
    if not isinstance(raw, str) or not raw.startswith(">"):
        raise RWKVProtocolError(
            f"native Supervisor text must continue the sent {envelope.generation_prefill} prefill"
        )
    if envelope.generation_mode == "fake_think" and not raw[1:].lstrip().startswith("{"):
        raise RWKVProtocolError(
            "native Planner no-CoT completion must continue the empty thinking prefix with one JSON object"
        )
    if data.get("usage") is not None and not isinstance(data["usage"], Mapping):
        raise RWKVProtocolError("native Supervisor usage must be an object")
    for name, tokens in (
        ("prompt_token_ids", data.get("prompt_token_ids")),
        ("token_ids", choice.get("token_ids")),
    ):
        if tokens is not None and (
            not isinstance(tokens, list)
            or any(not isinstance(token, int) or isinstance(token, bool) or token < 0 for token in tokens)
        ):
            raise RWKVProtocolError(f"{name} must be non-negative integer token IDs")
    try:
        return OpenAICompatibleRWKVClient._completion_response(data, latency_ms, attempts)
    except (ValueError, TypeError, OverflowError) as exc:
        raise RWKVProtocolError("native Supervisor response metadata is invalid") from exc

rwkv_lh/runtime/openai_compat.py:
"""Structured OpenAI-compatible client for local and remote RWKV servers."""

from __future__ import annotations

import hashlib
import json
import math
import threading
import time
from urllib.parse import quote, urlencode
from collections.abc import Callable, Mapping, Sequence
from typing import Any

import requests

from rwkv_lh.runtime.protocol import (
    ChatCompletionRequest,
    CompletionResponse,
    HealthStatus,
    RWKVHTTPError,
    RWKVOutcomeUnknownError,
    RWKVProtocolError,
    RWKVRequestNotRecorded,
    RWKVTransportError,
    RuntimeCapabilities,
    TextCompletionRequest,
    TokenUsage,
    normalize_stop,
    normalize_stop_token_ids,
)
from rwkv_lh.runtime.native_state import (
    NATIVE_STATE_PROTOCOL_VERSION,
    NativeStateCacheBinding,
    NativeStateCandidate,
    NativeStateSnapshot,
)
from rwkv_lh.runtime.native_request_protocol import (
    NATIVE_REQUEST_RECOVERY_VERSION,
    native_request_digest,
    native_result_digest,
    prepare_native_request,
)
from rwkv_lh.runtime.sampling import get_request_sampling
from rwkv_lh.runtime.settings import RuntimeSettings, get_runtime_settings


AuditHook = Callable[[Mapping[str, Any]], None]
_RETRYABLE_STATUS = {425, 429, 500, 502, 503, 504}


class OpenAICompatibleRWKVClient:
    """Thread-safe, pooled client with explicit request and response contracts."""

    backend_name = "openai_compatible_rwkv"

    def __init__(
        self,
        settings: RuntimeSettings | None = None,
        *,
        audit_hook: AuditHook | None = None,
    ):
        self.settings = settings or get_runtime_settings()
        self.audit_hook = audit_hook
        self._audit_subscribers: list[AuditHook] = []
        self._main_session = self._new_session()
        self._thread_sessions = threading.local()

    @property
    def model_name(self) -> str:
        return self.settings.model

    def _new_session(self) -> requests.Session:
        session = requests.Session()
        session.trust_env = self.settings.trust_environment_proxies
        # Retry only connection establishment (the request was never sent, so
        # this is always safe); read/status retries stay at the application
        # layer where journal receipts decide what may be replayed.
        adapter = requests.adapters.HTTPAdapter(
            max_retries=requests.adapters.Retry(
                total=None, connect=2, read=0, status=0, redirect=0,
                backoff_factor=0.2,
            )
        )
        session.mount("http://", adapter)
        session.mount("https://", adapter)
        if self.settings.proxy_url:
            session.proxies.update(
                {
                    "http": self.settings.proxy_url,
                    "https": self.settings.proxy_url,
                }
            )
        return session

    def _session(self) -> requests.Session:
        session = getattr(self._thread_sessions, "session", None)
        if session is None:
            session = (
                self._main_session
                if threading.current_thread() is threading.main_thread()
                else self._new_session()
            )
            self._thread_sessions.session = session
        return session

    def _headers(self) -> dict[str, str]:
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
        }
        if self.settings.api_key:
            headers["Authorization"] = f"Bearer {self.settings.api_key}"
        if self.settings.cf_access_client_id:
            headers["CF-Access-Client-Id"] = self.settings.cf_access_client_id
            headers["CF-Access-Client-Secret"] = (
                self.settings.cf_access_client_secret
            )
        return headers

    def _text_payload(self, request: TextCompletionRequest) -> dict[str, Any]:
        if self.settings.backend_profile in {
            "vllm-rwkv-rapid",
            "vllm-rwkv-native",
        }:
            sampler_mode = (
                "native"
                if self.settings.backend_profile == "vllm-rwkv-native"
                else "rapid"
            )
            return self._attach_state_profile(
                request.payload(self.model_name, sampler_mode=sampler_mode)
            )
        unsupported: list[str] = []
        if request.min_tokens:
            unsupported.append("min_tokens")
        if request.stop_token_ids:
            unsupported.append("stop_token_ids")
        if request.return_token_ids:
            unsupported.append("return_token_ids")
        if request.seed is not None:
            unsupported.append("seed")
        if unsupported:
            raise ValueError(
                "rwkv-lightning-native does not support: "
                + ", ".join(unsupported)
            )
        return self._attach_state_profile(
            {
                "contents": [request.prompt],
                "max_tokens": int(request.max_tokens),
                "stop_tokens": list(request.stop),
                "temperature": float(request.temperature),
                "top_k": int(request.top_k),
                "top_p": float(request.top_p),
                "alpha_presence": float(request.presence_penalty),
                "alpha_frequency": float(request.frequency_penalty),
                "alpha_decay": float(request.penalty_decay),
                "stream": False,
            }
        )

    def _attach_state_profile(self, payload: dict[str, Any]) -> dict[str, Any]:
        profile_id = self.settings.state_profile_id
        if not profile_id:
            return payload
        if self.settings.state_profile_delivery == "process_attested":
            return payload
        if self.settings.backend_profile not in {
            "vllm-rwkv-rapid",
            "vllm-rwkv-native",
        }:
            raise ValueError("RWKV state profiles require a vllm-rwkv backend")
        payload["vllm_xargs"] = {
            "rwkv_state_profile": profile_id,
            "rwkv_state_profile_sha256": self.settings.state_profile_sha256,
        }
        return payload

    def _generation_path(self) -> str:
        if self.settings.backend_profile == "rwkv-lightning-native":
            return "/chat/completions"
        return "/completions"

    def add_audit_hook(self, hook: AuditHook | None) -> None:
        """Subscribe an owning session without replacing a caller's observer."""
        if hook is None:
            return
        try:
            known = hook in self._audit_subscribers
        except Exception:
            # A subscriber with a throwing __eq__ must not break wiring.
            known = False
        if not known:
            self._audit_subscribers.append(hook)

    def _emit(self, event: Mapping[str, Any]) -> None:
        hooks = list(self._audit_subscribers)
        if self.audit_hook is not None:
            try:
                known = self.audit_hook in hooks
            except Exception:
                known = False
            if not known:
                hooks.insert(0, self.audit_hook)
        for hook in hooks:
            try:
                hook(dict(event))
            except Exception:
                # One observer must not suppress another or change requests.
                continue

    def _request_json(
        self,
        method: str,
        path: str,
        *,
        payload: Mapping[str, Any] | None = None,
        generation: bool = False,
        native_mutation: bool = False,
    ) -> tuple[dict[str, Any], float, int]:
        endpoint = self.settings.base_url + path
        # A Native mutation may already have a durable result. Recover through
        # its read-only journal endpoint instead of submitting it a second time.
        attempts = 1 if native_mutation else self.settings.retry_attempts
        headers = self._headers()
        if native_mutation:
            # A stale pooled keep-alive connection (or an idle tunnel hop) can
            # die before the request reaches the application, which fails the
            # heavyweight mutation with an unknown outcome. Forcing a fresh
            # connection removes that failure mode for a negligible cost.
            headers["Connection"] = "close"
        last_error: Exception | None = None
        for attempt in range(1, attempts + 1):
            started = time.perf_counter()
            try:
                response = self._session().request(
                    method,
                    endpoint,
                    headers=headers,
                    json=dict(payload) if payload is not None else None,
                    timeout=(
                        self.settings.connect_timeout_seconds,
                        self.settings.read_timeout_seconds,
                    ),
                    verify=self.settings.verify_tls,
                )
                latency_ms = round((time.perf_counter() - started) * 1000, 1)
                if response.status_code >= 400:
                    detail = response.text[:1000].replace("\n", " ")
                    error = RWKVHTTPError(
                        response.status_code,
                        detail,
                        retryable=response.status_code in _RETRYABLE_STATUS,
                    )
                    if error.retryable and attempt < attempts:
                        self._backoff(attempt, response.headers.get("Retry-After"))
                        last_error = error
                        continue
                    raise error
                try:
                    data = json.loads(response.content.decode("utf-8"))
                except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                    raise RWKVProtocolError(
                        "server returned invalid UTF-8 JSON"
                    ) from exc
                if not isinstance(data, dict):
                    raise RWKVProtocolError("server returned a non-object JSON response")
                return data, latency_ms, attempt
            except requests.ConnectTimeout as exc:
                last_error = RWKVTransportError(f"{type(exc).__name__}: {exc}")
                if attempt >= attempts:
                    raise last_error from exc
                self._backoff(attempt, None)
            except (requests.ReadTimeout, requests.ConnectionError) as exc:
                if generation:
                    raise RWKVOutcomeUnknownError(
                        "generation may have completed before the connection "
                        f"failed: {type(exc).__name__}: {exc}"
                    ) from exc
                last_error = RWKVTransportError(f"{type(exc).__name__}: {exc}")
                if attempt >= attempts:
                    raise last_error from exc
                self._backoff(attempt, None)
            except requests.Timeout as exc:
                if generation:
                    raise RWKVOutcomeUnknownError(
                        "generation outcome is unknown after timeout: "
                        f"{type(exc).__name__}: {exc}"
                    ) from exc
                last_error = RWKVTransportError(f"{type(exc).__name__}: {exc}")
                if attempt >= attempts:
                    raise last_error from exc
                self._backoff(attempt, None)
            except requests.RequestException as exc:
                if generation:
                    raise RWKVOutcomeUnknownError(
                        "generation outcome is unknown after transport failure: "
                        f"{type(exc).__name__}: {exc}"
                    ) from exc
                last_error = RWKVTransportError(f"{type(exc).__name__}: {exc}")
                if attempt >= attempts:
                    raise last_error from exc
                self._backoff(attempt, None)
        raise last_error or RWKVTransportError("model request failed")

    def _backoff(self, attempt: int, retry_after: str | None) -> None:
        if retry_after:
            try:
                delay = max(0.0, min(float(retry_after), 30.0))
            except ValueError:
                delay = self.settings.retry_backoff_seconds * (2 ** (attempt - 1))
        else:
            delay = self.settings.retry_backoff_seconds * (2 ** (attempt - 1))
        if delay > 0:
            time.sleep(delay)

    @staticmethod
    def _completion_response(data: Mapping[str, Any], latency_ms: float, attempts: int) -> CompletionResponse:
        choices = data.get("choices")
        if not isinstance(choices, list) or not choices or not isinstance(choices[0], Mapping):
            raise RWKVProtocolError("response has no valid choices[0]")
        choice = choices[0]
        message = choice.get("message") if isinstance(choice.get("message"), Mapping) else {}
        content = choice.get("text")
        if content is None:
            content = message.get("content", "")
        if content is None:
            content = ""
        if not isinstance(content, str):
            raise RWKVProtocolError("response content must be a string")
        usage = TokenUsage.from_mapping(data.get("usage") if isinstance(data.get("usage"), Mapping) else {})
        metadata: dict[str, Any] = {"http_attempts": attempts}
        if data.get("prompt_token_ids") is not None:
            if not isinstance(data["prompt_token_ids"], list) or any(
                not isinstance(item, int) or isinstance(item, bool) or item < 0
                for item in data["prompt_token_ids"]
            ):
                raise RWKVProtocolError("prompt_token_ids must be non-negative integers")
            metadata["prompt_token_ids"] = list(data["prompt_token_ids"])
        if isinstance(choice.get("token_ids"), list):
            if any(
                not isinstance(item, int) or isinstance(item, bool) or item < 0
                for item in choice["token_ids"]
            ):
                raise RWKVProtocolError("token_ids must be non-negative integers")
            metadata["token_ids"] = list(choice["token_ids"])
        return CompletionResponse(
            content=content,
            role=str(message.get("role") or "assistant"),
            finish_reason=str(choice.get("finish_reason") or ""),
            usage=usage.to_dict(),
            response_id=str(data.get("id") or ""),
            model=str(data.get("model") or ""),
            latency_ms=latency_ms,
            metadata=metadata,
        )

    def text_completion(
        self,
        prompt: str,
        max_tokens: int = 768,
        stop: Sequence[str] | None = None,
        *,
        temperature: float | None = None,
        seed: int | None = None,
        min_tokens: int = 0,
        stop_token_ids: Sequence[int] | None = None,
    ) -> CompletionResponse:
        sampling = get_request_sampling()
        request = TextCompletionRequest(
            prompt=str(prompt),
            max_tokens=max(1, int(max_tokens)),
            temperature=(
                sampling.temperature if temperature is None else float(temperature)
            ),
            top_p=sampling.top_p,
            top_k=sampling.top_k,
            presence_penalty=sampling.presence_penalty,
            frequency_penalty=sampling.frequency_penalty,
            penalty_decay=sampling.penalty_decay,
            min_tokens=int(min_tokens),
            stop=normalize_stop(stop),
            stop_token_ids=normalize_stop_token_ids(stop_token_ids),
            request_id=sampling.request_id,
            seed=sampling.seed if seed is None else seed,
            add_special_tokens=True,
            return_token_ids=self.settings.return_token_ids,
        )
        payload = self._text_payload(request)
        generation_path = self._generation_path()
        started = time.perf_counter()
        self._emit(
            {
                "type": "runtime_request_started",
                "endpoint": generation_path,
                "backend_profile": self.settings.backend_profile,
                "model": self.model_name,
                "temperature": request.temperature,
                "top_p": request.top_p,
                "top_k": request.top_k,
                "presence_penalty": request.presence_penalty,
                "frequency_penalty": request.frequency_penalty,
                "penalty_decay": request.penalty_decay,
                "min_tokens": request.min_tokens,
                "stop_token_ids": list(request.stop_token_ids),
                "request_id": request.request_id,
                "seed": request.seed,
                "max_tokens": request.max_tokens,
                "state_profile_id": self.settings.state_profile_id,
                "state_profile_sha256": self.settings.state_profile_sha256,
            }
        )
        try:
            data, latency_ms, attempts = self._request_json(
                "POST", generation_path, payload=payload, generation=True
            )
            response = self._completion_response(data, latency_ms, attempts)
            self._emit(
                {
                    "type": "runtime_request_returned",
                    "endpoint": generation_path,
                    "backend_profile": self.settings.backend_profile,
                    "model": self.model_name,
                    "temperature": request.temperature,
                    "request_id": request.request_id,
                    "latency_ms": response.latency_ms,
                    "finish_reason": response.finish_reason,
                    "raw_output": response.content,
                    "raw_output_sha256": self._raw_output_sha256(response.content),
                    "raw_token_ids": list(response.metadata.get("token_ids") or []),
                    "response_id": response.response_id,
                    "usage": response.usage,
                    "http_attempts": attempts,
                }
            )
            return response
        except RWKVOutcomeUnknownError as exc:
            self._emit(
                {
                    "type": "runtime_request_unknown",
                    "endpoint": generation_path,
                    "backend_profile": self.settings.backend_profile,
                    "model": self.model_name,
                    "temperature": request.temperature,
                    "request_id": request.request_id,
                    "duration_ms": round((time.perf_counter() - started) * 1000, 1),
                    "error": f"{type(exc).__name__}: {exc}"[:1000],
                }
            )
            raise
        except Exception as exc:
            self._emit(
                {
                    "type": "runtime_request_failed",
                    "endpoint": generation_path,
                    "backend_profile": self.settings.backend_profile,
                    "model": self.model_name,
                    "temperature": request.temperature,
                    "request_id": request.request_id,
                    "duration_ms": round((time.perf_counter() - started) * 1000, 1),
                    "error": f"{type(exc).__name__}: {exc}"[:1000],
                }
            )
            raise

    def chat_completion(
        self,
        messages: Sequence[Mapping[str, Any]],
        *,
        max_tokens: int = 768,
        stop: Sequence[str] | None = None,
        temperature: float | None = None,
        seed: int | None = None,
        min_tokens: int = 0,
        stop_token_ids: Sequence[int] | None = None,
    ) -> CompletionResponse:
        sampling = get_request_sampling()
        request = ChatCompletionRequest(
            messages=tuple(dict(item) for item in messages),
            max_tokens=max(1, int(max_tokens)),
            temperature=(
                sampling.temperature if temperature is None else float(temperature)
            ),
            top_p=sampling.top_p,
            top_k=sampling.top_k,
            presence_penalty=sampling.presence_penalty,
            frequency_penalty=sampling.frequency_penalty,
            penalty_decay=sampling.penalty_decay,
            min_tokens=int(min_tokens),
            stop=normalize_stop(stop),
            stop_token_ids=normalize_stop_token_ids(stop_token_ids),
            request_id=sampling.request_id,
            seed=sampling.seed if seed is None else seed,
            add_special_tokens=False,
            return_token_ids=self.settings.return_token_ids,
        )
        if self.settings.backend_profile == "rwkv-lightning-native":
            rendered = "".join(
                f"{str(item.get('role') or 'user').title()}: "
                f"{str(item.get('content') or '')}\n"
                for item in request.messages
            )
            native_request = TextCompletionRequest(
                prompt=rendered,
                max_tokens=request.max_tokens,
                temperature=request.temperature,
                top_p=request.top_p,
                top_k=request.top_k,
                presence_penalty=request.presence_penalty,
                frequency_penalty=request.frequency_penalty,
                penalty_decay=request.penalty_decay,
                min_tokens=request.min_tokens,
                stop=request.stop,
                stop_token_ids=request.stop_token_ids,
                request_id=request.request_id,
                seed=request.seed,
                return_token_ids=request.return_token_ids,
            )
            payload = self._text_payload(native_request)
        else:
            sampler_mode = (
                "native"
                if self.settings.backend_profile == "vllm-rwkv-native"
                else "rapid"
            )
            payload = request.payload(
                self.model_name,
                sampler_mode=sampler_mode,
            )
            payload = self._attach_state_profile(payload)
        data, latency_ms, attempts = self._request_json(
            "POST", "/chat/completions", payload=payload, generation=True
        )
        return self._completion_response(data, latency_ms, attempts)

    @staticmethod
    def _raw_output_sha256(content: str) -> str:
        return hashlib.sha256(content.encode("utf-8")).hexdigest()

    def health(self) -> HealthStatus:
        started = time.perf_counter()
        try:
            data, latency_ms, _ = self._request_json("GET", "/models")
            models = tuple(
                str(item.get("id"))
                for item in data.get("data", [])
                if isinstance(item, Mapping) and item.get("id")
            )
            model_available = self.model_name in models
            return HealthStatus(
                available=model_available,
                endpoint=self.settings.base_url,
                model=self.model_name,
                models=models,
                latency_ms=latency_ms,
                error=(
                    "configured model is absent from /models: "
                    f"{self.model_name}"
                    if not model_available
                    else ""
                ),
            )
        except Exception as exc:
            return HealthStatus(
                available=False,
                endpoint=self.settings.base_url,
                model=self.model_name,
                latency_ms=round((time.perf_counter() - started) * 1000, 1),
                error=f"{type(exc).__name__}: {exc}"[:500],
            )

    def capabilities(self) -> RuntimeCapabilities:
        """Negotiate explicit RWKV extensions without inferring from caches.

        A server must expose `/capabilities` and affirm each state operation.
        OpenAI-compatible endpoints, cached tokens, or tool parser presence do
        not imply a resumable recurrent-state handle.
        """

        try:
            data, _, _ = self._request_json("GET", "/capabilities")
            return RuntimeCapabilities.from_mapping(
                data,
                source=self.settings.base_url + "/capabilities",
            )
        except Exception as exc:
            return RuntimeCapabilities(
                source="prompt_replay_fallback",
                error=f"{type(exc).__name__}: {exc}"[:500],
            )

    @staticmethod
    def _native_snapshot(
        value: Mapping[str, Any],
        *,
        expected_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot:
        raw = value.get("snapshot")
        selected = raw if isinstance(raw, Mapping) else value
        export_record = selected.get("export_record")
        if not isinstance(export_record, Mapping):
            raise RWKVProtocolError("native state response has no export record")
        snapshot = NativeStateSnapshot(
            state_ref=str(selected.get("state_ref") or ""),
            state_digest=str(selected.get("state_digest") or ""),
            export_record=dict(export_record),
            state_format_version=str(selected.get("state_format_version") or ""),
            server_build=str(selected.get("server_build") or ""),
            tokenizer_build=str(selected.get("tokenizer_build") or ""),
            cache_binding_digest=str(selected.get("cache_binding_digest") or ""),
            metadata=selected.get("metadata") or {},
            protocol_version=str(
                selected.get("protocol_version") or NATIVE_STATE_PROTOCOL_VERSION
            ),
        )
        if snapshot.cache_binding_digest != expected_binding.digest:
            raise RWKVProtocolError("native state response cache binding mismatch")
        return snapshot

    def _native_payload(
        self,
        cache_binding: NativeStateCacheBinding,
        **values: Any,
    ) -> dict[str, Any]:
        return self._attach_state_profile(
            {
                "schema_version": NATIVE_STATE_PROTOCOL_VERSION,
                "model": self.model_name,
                "cache_binding": cache_binding.to_dict(),
                **values,
            }
        )

    def state_request_result(
        self, *, request_id: str, operation: str, request_digest: str,
    ) -> dict[str, Any]:
        """Read an existing request receipt without submitting model work."""
        path = "/state/requests/" + quote(request_id, safe="") + "?" + urlencode({"request_digest": request_digest})
        try:
            result, _, _ = self._request_json("GET", path)
        except RWKVHTTPError as exc:
            if exc.status_code == 404:
                # The journal claims a row before any execution starts, so an
                # unrecorded request id proves the request never executed.
                return {"status": "not_recorded"}
            raise
        expected = {"schema_version": NATIVE_REQUEST_RECOVERY_VERSION,
            "request_id": request_id, "operation": operation, "request_digest": request_digest}
        if any(result.get(key) != value for key, value in expected.items()):
            raise RWKVProtocolError("Native request query returned a different identity")
        if result.get("status") not in {"pending", "unknown", "completed"}:
            raise RWKVProtocolError("Native request query returned an invalid status")
        if result["status"] == "completed":
            body, status = result.get("result"), result.get("http_status")
            if (not isinstance(body, dict) or native_result_digest(body) != result.get("result_sha256")
                    or type(status) is not int or not 200 <= status <= 599):
                raise RWKVProtocolError("Native request query returned an invalid result")
        return result

    def recover_native_request(
        self, operation: str, payload: Mapping[str, Any], *, max_wait_seconds: float | None = None,
        original_error: Exception | None = None,
    ) -> dict[str, Any]:
        """An uncertain State mutation is resolved by exact receipt queries only."""
        prepared = prepare_native_request(operation, payload)
        digest = native_request_digest(operation, prepared)
        wait = self.settings.read_timeout_seconds if max_wait_seconds is None else max_wait_seconds
        if type(wait) not in (int, float) or not math.isfinite(wait) or wait < 0:
            raise ValueError("Native result query wait must be non-negative")
        deadline = time.monotonic() + wait
        original = f"; original error: {type(original_error).__name__}: {str(original_error)[:500]}" if original_error is not None else ""
        status = "unknown"
        not_recorded_confirmations = 0
        while True:
            try:
                result = self.state_request_result(request_id=prepared["request_id"],
                    operation=operation, request_digest=digest)
            except (RWKVProtocolError, ValueError, TypeError) as exc:
                raise RWKVOutcomeUnknownError(
                    f"Native result query failed identity validation{original}"
                ) from (original_error or exc)
            except RWKVHTTPError as exc:
                if not exc.retryable:
                    raise RWKVOutcomeUnknownError(
                        f"Native {operation} outcome remains unknown; "
                        f"request_id={prepared['request_id']}; receipt query: {exc}{original}"
                    ) from (original_error or exc)
                result = {"status": "unavailable"}
            except RWKVTransportError:
                result = {"status": "unavailable"}
            status = result["status"]
            if status == "completed":
                if result["http_status"] >= 400:
                    raise RWKVHTTPError(result["http_status"], "stored Native request failure")
                self._emit({"type": "native_request_recovered", "operation": operation,
                    "request_id": prepared["request_id"], "request_digest": digest})
                return dict(result["result"])
            if status == "not_recorded":
                # One backoff plus a second confirmation guards against the
                # original POST bytes still being in flight toward the journal.
                not_recorded_confirmations += 1
                if not_recorded_confirmations >= 2:
                    raise RWKVRequestNotRecorded(
                        f"Native {operation} was never recorded by the server journal; "
                        f"request_id={prepared['request_id']}; it never executed and may be "
                        f"resubmitted{original}"
                    ) from original_error
            if status == "unknown" or time.monotonic() >= deadline:
                break
            time.sleep(min(max(0.01, self.settings.retry_backoff_seconds),
                max(0.0, deadline - time.monotonic())))
        raise RWKVOutcomeUnknownError(
            f"Native {operation} outcome remains {status}; "
            f"request_id={prepared['request_id']}{original}"
        ) from original_error

    def _native_request(self, operation: str, payload: Mapping[str, Any]) -> dict[str, Any]:
        prepared = prepare_native_request(operation, payload)
        digest = native_request_digest(operation, prepared)
        self._emit({"type": "native_request_prepared", "operation": operation,
            "request_id": prepared["request_id"], "request_digest": digest})
        resubmits = max(1, int(self.settings.native_resubmit_attempts))
        for attempt in range(1, resubmits + 1):
            first_error: Exception
            try:
                data, _, _ = self._request_json("POST", "/state/" + operation,
                    payload=prepared, generation=True, native_mutation=True)
                return data
            except RWKVHTTPError as exc:
                if not exc.retryable:
                    raise
                first_error = exc
            except (RWKVTransportError, RWKVProtocolError) as exc:
                first_error = exc
            # The original failure is audited before recovery so a later
            # receipt-query result can never erase the first cause.
            self._emit({"type": "native_request_transport_error", "operation": operation,
                "request_id": prepared["request_id"], "request_digest": digest,
                "error_type": type(first_error).__name__,
                "error_message": str(first_error)[:500],
                "attempt": attempt, "will_recover": True})
            try:
                return self.recover_native_request(operation, prepared, original_error=first_error)
            except RWKVRequestNotRecorded:
                if attempt >= resubmits:
                    raise
                self._emit({"type": "native_request_resubmitted", "operation": operation,
                    "request_id": prepared["request_id"], "request_digest": digest,
                    "attempt": attempt + 1})
                self._backoff(attempt, None)
        raise RWKVTransportError("native request submission loop exited unexpectedly")

    def state_create(
        self,
        *,
        lane_id: str,
        text: str,
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot:
        data = self._native_request(
            "create", self._native_payload(
                cache_binding,
                lane_id=str(lane_id),
                delta=str(text),
            ),
        )
        return self._native_snapshot(data, expected_binding=cache_binding)

    def state_append(
        self,
        *,
        parent_state_ref: str,
        lane_id: str,
        text: str,
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot:
        data = self._native_request(
            "append", self._native_payload(
                cache_binding,
                parent_state_ref=str(parent_state_ref),
                lane_id=str(lane_id),
                delta=str(text),
            ),
        )
        return self._native_snapshot(data, expected_binding=cache_binding)

    def state_fork(
        self,
        *,
        parent_state_ref: str,
        lane_id: str,
        text: str,
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot:
        data = self._native_request(
            "fork", self._native_payload(
                cache_binding,
                parent_state_ref=str(parent_state_ref),
                lane_id=str(lane_id),
                delta=str(text),
            ),
        )
        return self._native_snapshot(data, expected_binding=cache_binding)

    def state_generate(
        self,
        *,
        parent_state_ref: str,
        request_id: str,
        max_tokens: int,
        stop: Sequence[str],
        sampling: Mapping[str, Any],
        parent_cache_binding_digest: str,
    ) -> NativeStateCandidate:
        data = self._native_request(
            "generate", self._attach_state_profile(
                {
                    "schema_version": NATIVE_STATE_PROTOCOL_VERSION,
                    "model": self.model_name,
                    "parent_state_ref": str(parent_state_ref),
                    "parent_cache_binding_digest": str(
                        parent_cache_binding_digest
                    ),
                    "request_id": str(request_id),
                    "max_tokens": max(1, int(max_tokens)),
                    "stop": [str(item) for item in stop],
                    "sampling": dict(sampling),
                    "return_token_ids": self.settings.return_token_ids,
                }
            ),
        )
        raw = data.get("candidate")
        selected = raw if isinstance(raw, Mapping) else data
        metadata = selected.get("metadata")
        candidate = NativeStateCandidate(
            state_ref=str(selected.get("state_ref") or ""),
            state_digest=str(selected.get("state_digest") or ""),
            content=str(selected.get("content") or ""),
            finish_reason=str(selected.get("finish_reason") or ""),
            metadata=dict(metadata) if isinstance(metadata, Mapping) else {},
            parent_state_digest=str(selected.get("parent_state_digest") or ""),
            parent_cache_binding_digest=str(
                selected.get("parent_cache_binding_digest") or ""
            ),
        )
        if candidate.parent_cache_binding_digest != parent_cache_binding_digest:
            raise RWKVProtocolError("native candidate parent cache binding mismatch")
        return candidate

    def state_commit(
        self,
        *,
        candidate_state_ref: str,
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot:
        data = self._native_request(
            "commit", self._native_payload(
                cache_binding,
                candidate_state_ref=str(candidate_state_ref),
            ),
        )
        return self._native_snapshot(data, expected_binding=cache_binding)

    def state_rollback(
        self,
        *,
        candidate_state_ref: str,
        parent_state_ref: str,
    ) -> None:
        self._native_request(
            "rollback", {
                "schema_version": NATIVE_STATE_PROTOCOL_VERSION,
                "model": self.model_name,
                "candidate_state_ref": str(candidate_state_ref),
                "parent_state_ref": str(parent_state_ref),
            },
        )

    def state_import(
        self,
        *,
        export_record: Mapping[str, Any],
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot:
        data = self._native_request(
            "import", self._native_payload(
                cache_binding,
                export_record=dict(export_record),
            ),
        )
        return self._native_snapshot(data, expected_binding=cache_binding)

    def close(self) -> None:
        self._main_session.close()
        session = getattr(self._thread_sessions, "session", None)
        if session is not None and session is not self._main_session:
            session.close()


__all__ = ["OpenAICompatibleRWKVClient"]

rwkv_lh/runtime/native_state.py:
"""Versioned contracts for a disposable RWKV recurrent-state cache service."""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass, field
from typing import Any, Mapping, Protocol, Sequence

from rwkv_lh.runtime.protocol import RuntimeCapabilities


NATIVE_STATE_PROTOCOL_VERSION = "rwkv-lh.native-state.v1"
NATIVE_STATE_LIFECYCLE_VERSION = "rwkv-lh.native-state-lifecycle.v1"


def _canonical_digest(value: Mapping[str, Any]) -> str:
    payload = json.dumps(
        dict(value),
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


@dataclass(frozen=True)
class NativeStateCacheBinding:
    """Identity of one derived cache entry; it grants no execution authority."""

    lane_id: str
    lane_kind: str
    model: str
    model_sha256: str
    state_profile_id: str
    state_profile_sha256: str
    state_chain_digest: str
    delta_digest: str
    event_ids_digest: str
    parent_state_digest: str = ""
    cache_role: str = "disposable_acceleration"

    def __post_init__(self) -> None:
        if not self.lane_id or not self.lane_kind or not self.model:
            raise ValueError("native cache binding identity is incomplete")
        for name in (
            "state_chain_digest",
            "delta_digest",
            "event_ids_digest",
        ):
            value = str(getattr(self, name) or "")
            if len(value) != 64 or any(item not in "0123456789abcdef" for item in value):
                raise ValueError(f"native cache binding {name} must be lowercase SHA-256")
        for name in (
            "model_sha256",
            "state_profile_sha256",
            "parent_state_digest",
        ):
            value = str(getattr(self, name) or "")
            if value and (
                len(value) != 64
                or any(item not in "0123456789abcdef" for item in value)
            ):
                raise ValueError(f"native cache binding {name} must be empty or SHA-256")
        if self.cache_role != "disposable_acceleration":
            raise ValueError("native state may only be registered as disposable cache")

    @property
    def digest(self) -> str:
        return _canonical_digest(self.to_dict())

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": "rwkv-lh.native-state-cache-binding.v1",
            "lane_id": self.lane_id,
            "lane_kind": self.lane_kind,
            "model": self.model,
            "model_sha256": self.model_sha256,
            "state_profile_id": self.state_profile_id,
            "state_profile_sha256": self.state_profile_sha256,
            "state_chain_digest": self.state_chain_digest,
            "delta_digest": self.delta_digest,
            "event_ids_digest": self.event_ids_digest,
            "parent_state_digest": self.parent_state_digest,
            "cache_role": self.cache_role,
            "authoritative": False,
        }

    @classmethod
    def from_mapping(cls, value: Mapping[str, Any]) -> "NativeStateCacheBinding":
        if value.get("schema_version") != "rwkv-lh.native-state-cache-binding.v1":
            raise ValueError("unsupported native state cache binding")
        if value.get("authoritative") is not False:
            raise ValueError("native state cache binding cannot be authoritative")
        return cls(
            lane_id=str(value.get("lane_id") or ""),
            lane_kind=str(value.get("lane_kind") or ""),
            model=str(value.get("model") or ""),
            model_sha256=str(value.get("model_sha256") or ""),
            state_profile_id=str(value.get("state_profile_id") or ""),
            state_profile_sha256=str(value.get("state_profile_sha256") or ""),
            state_chain_digest=str(value.get("state_chain_digest") or ""),
            delta_digest=str(value.get("delta_digest") or ""),
            event_ids_digest=str(value.get("event_ids_digest") or ""),
            parent_state_digest=str(value.get("parent_state_digest") or ""),
            cache_role=str(value.get("cache_role") or ""),
        )


@dataclass(frozen=True)
class NativeStateSnapshot:
    state_ref: str
    state_digest: str
    export_record: Mapping[str, Any]
    state_format_version: str
    server_build: str
    tokenizer_build: str
    cache_binding_digest: str
    protocol_version: str = NATIVE_STATE_PROTOCOL_VERSION
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not isinstance(self.metadata, Mapping):
            raise ValueError("native snapshot metadata must be a mapping")
        token_ids = self.metadata.get("prompt_token_ids")
        if token_ids is not None and (not isinstance(token_ids, (list, tuple))
                or any(type(token) is not int or token < 0 for token in token_ids)):
            raise ValueError("native snapshot prompt_token_ids must be non-negative integers")
        required = {
            "state_ref": self.state_ref,
            "state_digest": self.state_digest,
            "state_format_version": self.state_format_version,
            "server_build": self.server_build,
            "tokenizer_build": self.tokenizer_build,
            "cache_binding_digest": self.cache_binding_digest,
        }
        missing = [name for name, value in required.items() if not str(value).strip()]
        if missing:
            raise ValueError(f"native state snapshot is missing: {', '.join(missing)}")
        if self.protocol_version != NATIVE_STATE_PROTOCOL_VERSION:
            raise ValueError(
                f"unsupported native state protocol: {self.protocol_version}"
            )
        if not isinstance(self.export_record, Mapping) or not self.export_record:
            raise ValueError("native state snapshot requires a durable export record")
        for name in ("state_digest", "cache_binding_digest"):
            value = str(getattr(self, name) or "")
            if len(value) != 64 or any(
                item not in "0123456789abcdef" for item in value
            ):
                raise ValueError(f"native snapshot {name} must be lowercase SHA-256")


@dataclass(frozen=True)
class NativeStateCandidate:
    state_ref: str
    state_digest: str
    content: str
    finish_reason: str = "stop"
    metadata: Mapping[str, Any] = field(default_factory=dict)
    parent_state_digest: str = ""
    parent_cache_binding_digest: str = ""

    def __post_init__(self) -> None:
        if not self.state_ref or not self.state_digest:
            raise ValueError("native candidate requires a state ref and digest")
        if not isinstance(self.content, str):
            raise TypeError("native candidate content must be a string")
        if not isinstance(self.metadata, Mapping):
            raise TypeError("native candidate metadata must be a mapping")
        for name in (
            "state_digest",
            "parent_state_digest",
            "parent_cache_binding_digest",
        ):
            value = str(getattr(self, name) or "")
            if len(value) != 64 or any(item not in "0123456789abcdef" for item in value):
                raise ValueError(f"native candidate {name} must be lowercase SHA-256")
        token_ids = self.metadata.get("token_ids", ())
        if not isinstance(token_ids, (list, tuple)) or any(
            not isinstance(item, int) or isinstance(item, bool) or item < 0
            for item in token_ids
        ):
            raise ValueError("native candidate token_ids must be non-negative integers")


class NativeRWKVStateClient(Protocol):
    """Adapter boundary; implementations must preserve immutable fork lineage."""

    model_name: str

    def capabilities(self) -> RuntimeCapabilities: ...

    def state_create(
        self,
        *,
        lane_id: str,
        text: str,
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot: ...

    def state_append(
        self,
        *,
        parent_state_ref: str,
        lane_id: str,
        text: str,
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot: ...

    def state_fork(
        self,
        *,
        parent_state_ref: str,
        lane_id: str,
        text: str,
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot: ...

    def state_generate(
        self,
        *,
        parent_state_ref: str,
        request_id: str,
        max_tokens: int,
        stop: Sequence[str],
        sampling: Mapping[str, Any],
        parent_cache_binding_digest: str,
    ) -> NativeStateCandidate: ...

    def state_commit(
        self,
        *,
        candidate_state_ref: str,
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot: ...

    def state_rollback(
        self,
        *,
        candidate_state_ref: str,
        parent_state_ref: str,
    ) -> None: ...

    def state_import(
        self,
        *,
        export_record: Mapping[str, Any],
        cache_binding: NativeStateCacheBinding,
    ) -> NativeStateSnapshot: ...


__all__ = [
    "NATIVE_STATE_PROTOCOL_VERSION",
    "NativeStateCacheBinding",
    "NativeRWKVStateClient",
    "NativeStateCandidate",
    "NativeStateSnapshot",
]

rwkv_lh/runtime/stack.py:
"""Owned multi-process deployment for Router, remote RWKV and product services."""

from __future__ import annotations

import fcntl
import hashlib
import json
