"""Opt-in HTTP lifecycle for RWKV recurrent-state cache entries."""

from __future__ import annotations

import asyncio
import hashlib
import json
import os
import re
import time
from collections import OrderedDict
from dataclasses import asdict, dataclass, replace
from typing import Any
from uuid import uuid4

import vllm
from fastapi import FastAPI, HTTPException, Request
from starlette.datastructures import State
from vllm import TokensPrompt
from vllm.engine.protocol import EngineClient
from vllm.sampling_params import RequestOutputKind, SamplingParams

from rwkv_lh.inference.native_source_identity import verify_native_source_identity
from rwkv_lh.runtime.native_request_recovery import (
    NATIVE_REQUEST_RECOVERY_VERSION,
    NativeRequestConflict,
    NativeRequestInProgress,
    NativeRequestJournal,
    NativeRequestOutcomeUnknown,
    NativeRequestResult,
    NativeStateRetired,
    prepare_native_request,
)
from rwkv_lh.runtime.native_state import NATIVE_STATE_LIFECYCLE_VERSION, NATIVE_STATE_PROTOCOL_VERSION

PROTOCOL_VERSION = NATIVE_STATE_PROTOCOL_VERSION
EXPORT_VERSION = "rwkv-lh.native-state-export.v1"
STATE_FORMAT_VERSION = "rwkv7-native-state-cache.v1"
_SHA256_ZERO = "0" * 64


def _digest(value: Any) -> str:
    encoded = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


@dataclass(frozen=True)
class _StateRecord:
    state_ref: str
    state_digest: str
    cache_binding_digest: str
    state_profile_id: str
    state_profile_sha256: str
    pending_token_id: int
    processed_token_count: int
    parent_state_ref: str = ""
    committed: bool = True
    export_record: dict[str, Any] | None = None
    import_origin_state_ref: str = ""
    input_token_ids: list[int] | None = None
    input_bos_token_count: int | None = None


class RWKVNativeStateService:
    """API-process metadata for worker-owned disposable state snapshots."""

    def __init__(self, engine_client: EngineClient | None, args: Any) -> None:
        self.engine_client = engine_client
        self.args = args
        self.lock = asyncio.Lock()
        self.request_lock = asyncio.Lock()
        self._active_request_id = ""
        journal_path = getattr(args, "rwkv_native_request_journal", None) or os.getenv("RWKV_NATIVE_REQUEST_JOURNAL")
        self.journal = NativeRequestJournal(journal_path) if journal_path else None
        self.records: OrderedDict[str, _StateRecord] = OrderedDict()
        self.registry_capacity = 4096
        self.ready = False
        self.error = "engine client is unavailable"
        self.model_name = ""
        self.server_build = str(getattr(vllm, "__version__", "unknown"))
        self.tokenizer_build = ""
        self.worker_capabilities: dict[str, Any] = {}
        self.source_identity: dict[str, Any] = {}
        self.gc_last_error = ""

    async def initialize(self) -> None:
        if self.engine_client is None:
            return
        try:
            self.source_identity = verify_native_source_identity(engine_file=getattr(vllm, "__file__", None))
            self.model_name = str(self.engine_client.model_config.served_model_name)
            tokenizer = self.engine_client.renderer.get_tokenizer()
            self.tokenizer_build = _digest(
                {
                    "class": f"{type(tokenizer).__module__}.{type(tokenizer).__name__}",
                    "name": str(getattr(tokenizer, "name_or_path", "")),
                    "vocab_size": int(getattr(tokenizer, "vocab_size", 0)),
                }
            )
            results = await self._collective("capabilities")
            capabilities = self._consensus(results)
            if capabilities.get("source_identity") != self.source_identity:
                raise RuntimeError("worker Native source identity differs from the verified API source identity")
            if capabilities.get("state_format_version") != STATE_FORMAT_VERSION:
                raise RuntimeError("worker state format is incompatible")
            if not capabilities.get("store_configured"):
                raise RuntimeError("worker state store is not configured")
            if self.journal is None:
                raise RuntimeError("RWKV_NATIVE_REQUEST_JOURNAL must name a persistent journal")
            if capabilities.get("store_persistent") is not True:
                raise RuntimeError("request recovery requires persistent worker state storage (capacity=0)")
            if capabilities.get("state_lifecycle_protocol") != NATIVE_STATE_LIFECYCLE_VERSION:
                raise RuntimeError("worker State lifecycle protocol is unavailable")
            self.worker_capabilities = capabilities
            self.server_build = f"{getattr(vllm, '__version__', 'unknown')}+native.{self.source_identity['identity_sha256']}"
            self.ready = True
            self.error = ""
            await self._collect_garbage()
        except Exception as exc:
            self.error = f"{type(exc).__name__}: {exc}"[:500]

    async def _collective(
        self,
        action: str,
        payload: dict[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        if self.engine_client is None:
            raise RuntimeError("RWKV native state requires an engine")
        results = await self.engine_client.collective_rpc(
            "rwkv_native_state_action",
            args=(action, payload or {}),
        )
        if not isinstance(results, list) or not results:
            raise RuntimeError("RWKV native state workers returned no result")
        if any(not isinstance(item, dict) for item in results):
            raise RuntimeError("RWKV native state worker result is invalid")
        return results

    @staticmethod
    def _consensus(results: list[dict[str, Any]]) -> dict[str, Any]:
        comparable = [
            {key: value for key, value in item.items() if key != "worker_rank"}
            for item in results
        ]
        if any(item != comparable[0] for item in comparable[1:]):
            raise RuntimeError("RWKV native state workers disagree")
        return comparable[0]

    def capabilities(self) -> dict[str, Any]:
        enabled = self.ready
        return {
            "schema_version": PROTOCOL_VERSION,
            "model": self.model_name,
            "prompt_replay": False,
            "tools": {"native_tool_calls": False},
            "recurrent_state": {
                "protocol": PROTOCOL_VERSION if enabled else "",
                "create": enabled,
                "resume": enabled,
                "fork": enabled,
                "commit": enabled,
                "rollback": enabled,
                "release": enabled,
                "state_lifecycle_protocol": NATIVE_STATE_LIFECYCLE_VERSION if enabled else "",
                "export": enabled,
                "import": enabled,
                "chunked_prefill": enabled,
                "full_input_token_ids": enabled,
                "request_recovery": enabled and self.journal is not None,
                "request_recovery_protocol": NATIVE_REQUEST_RECOVERY_VERSION if enabled and self.journal is not None else "",
                "authoritative": False,
                "cache_role": "disposable_acceleration",
                "state_format_version": STATE_FORMAT_VERSION,
                "pending_token_policy": "state_before_exactly_one_pending_token",
                "cache_capacity_per_worker": self.worker_capabilities.get(
                    "cache_capacity", 0
                ),
                "persistent_store": self.worker_capabilities.get("store_persistent") is True,
                "gc_pending_blobs": self.journal.gc_pending_count() if self.journal is not None else 0,
                "gc_last_error": self.gc_last_error,
            },
            "max_model_len": int(
                getattr(
                    getattr(self.engine_client, "model_config", None),
                    "max_model_len",
                    0,
                )
                or 0
            ),
            "server_build": self.server_build,
            "tokenizer_build": self.tokenizer_build,
            "error": self.error,
        }

    def _require_ready(self) -> None:
        if not self.ready:
            raise HTTPException(status_code=503, detail=self.error)

    def _validate_model(self, payload: dict[str, Any]) -> None:
        if payload.get("schema_version") != PROTOCOL_VERSION:
            raise HTTPException(status_code=400, detail="unsupported state protocol")
        if payload.get("model") != self.model_name:
            raise HTTPException(status_code=409, detail="served model mismatch")

    @staticmethod
    def _binding(payload: dict[str, Any]) -> tuple[dict[str, Any], str]:
        binding = payload.get("cache_binding")
        if not isinstance(binding, dict):
            raise HTTPException(status_code=400, detail="cache_binding is required")
        if (
            binding.get("schema_version") != "rwkv-lh.native-state-cache-binding.v1"
            or binding.get("authoritative") is not False
            or binding.get("cache_role") != "disposable_acceleration"
        ):
            raise HTTPException(status_code=400, detail="cache binding is invalid")
        return binding, _digest(binding)

    @staticmethod
    def _profile(payload: dict[str, Any], binding: dict[str, Any]) -> tuple[str, str]:
        xargs = payload.get("vllm_xargs")
        values = xargs if isinstance(xargs, dict) else {}
        requested_id = values.get("rwkv_state_profile")
        requested_sha256 = values.get("rwkv_state_profile_sha256")
        if (requested_id is None) != (requested_sha256 is None):
            raise HTTPException(status_code=400, detail="state profile is incomplete")
        profile_id = str(
            requested_id
            if requested_id is not None
            else binding.get("state_profile_id") or "zero"
        )
        profile_sha256 = str(
            requested_sha256
            if requested_sha256 is not None
            else binding.get("state_profile_sha256") or _SHA256_ZERO
        )
        if profile_id != str(
            binding.get("state_profile_id") or "zero"
        ) or profile_sha256 != str(binding.get("state_profile_sha256") or _SHA256_ZERO):
            raise HTTPException(status_code=409, detail="state profile mismatch")
        return profile_id, profile_sha256

    def _tokens(self, text: str, *, initial: bool) -> list[int]:
        assert self.engine_client is not None
        tokenizer = self.engine_client.renderer.get_tokenizer()
        token_ids = tokenizer.encode(text, add_special_tokens=initial)
        if not isinstance(token_ids, list) or any(
            not isinstance(item, int) or item < 0 for item in token_ids
        ):
            raise RuntimeError("tokenizer returned invalid token IDs")
        return token_ids

    @staticmethod
    def _new_ref() -> str:
        return f"WKV-{uuid4().hex}"

    def _remember(self, record: _StateRecord) -> None:
        self.records[record.state_ref] = record
        self.records.move_to_end(record.state_ref)
        while len(self.records) > self.registry_capacity:
            self.records.popitem(last=False)

    def _record(self, state_ref: str) -> _StateRecord:
        if self.journal is not None:
            try:
                metadata = self.journal.lookup_state_metadata(state_ref, allow_request_id=self._active_request_id)
            except NativeRequestOutcomeUnknown as exc:
                raise HTTPException(status_code=503, detail="State has an unresolved mutation") from exc
            if metadata is not None:
                if metadata.get("dropped") is True or metadata.get("released") is True:
                    self.records.pop(state_ref, None)
                    raise HTTPException(status_code=410, detail="state cache was retired")
                record = _StateRecord(**metadata)
                exported = record.export_record
                expected = {
                    "schema_version": EXPORT_VERSION, "protocol_version": PROTOCOL_VERSION,
                    "state_format_version": STATE_FORMAT_VERSION, "model": self.model_name,
                    "server_build": self.server_build, "tokenizer_build": self.tokenizer_build,
                    "state_digest": record.state_digest, "cache_binding_digest": record.cache_binding_digest,
                    "state_profile_id": record.state_profile_id, "state_profile_sha256": record.state_profile_sha256,
                    "pending_token_id": record.pending_token_id, "processed_token_count": record.processed_token_count,
                }
                if not isinstance(exported, dict) or any(exported.get(key) != value for key, value in expected.items()):
                    raise HTTPException(status_code=409, detail="durable state recovery identity mismatch")
                self._remember(record)
        record = self.records.get(state_ref)
        if record is None:
            raise HTTPException(status_code=410, detail="state cache reference expired")
        self._input_evidence(record)
        self.records.move_to_end(state_ref)
        return record

    async def _ensure_loaded(self, record: _StateRecord) -> None:
        try:
            result = self._consensus(
                await self._collective("get", {"state_ref": record.state_ref})
            )
            self._validate_worker_record(record, result)
            return
        except Exception:
            pass
        export_record = record.export_record
        if not isinstance(export_record, dict):
            raise HTTPException(status_code=410, detail="state cache entry was evicted")
        await self._import_workers(record, export_record)

    async def _recover_current_states(self, record) -> None:
        """Replay original response bytes while loading only the latest State facts."""
        assert self.journal is not None
        async with self.request_lock:
            for old in record.recovery_metadata.get("states", []):
                try:
                    latest = self.journal.lookup_state_metadata(old["state_ref"])
                except NativeRequestOutcomeUnknown as exc:
                    raise HTTPException(status_code=503, detail="State has an unresolved mutation") from exc
                if latest is not None and (latest.get("dropped") is True or latest.get("released") is True):
                    continue
                await self._ensure_loaded(self._record(old["state_ref"]))

    async def _collect_garbage(self) -> None:
        """Deletion follows durable retirement; a crash leaves a retryable queue."""
        if self.journal is None:
            return
        async with self.request_lock:
            try:
                for ref in self.journal.pending_retirements():
                    await self._collective("drop", {"state_ref": ref})
                    self.records.pop(ref, None)
                    self.journal.mark_cache_dropped(ref)
                for key in self.journal.reclaimable_store_keys():
                    # All executing operations use request_lock. Queued inputs
                    # were durably pinned before waiting for this same lock.
                    result = self._consensus(await self._collective("delete_export", {"store_key": key}))
                    if result.get("store_key") != key or result.get("deleted") is not True:
                        raise RuntimeError("worker did not confirm durable State deletion")
                    self.journal.mark_blob_deleted(key)
                self.gc_last_error = ""
            except Exception as exc:
                # The immutable operation receipt is already durable. Keep its
                # result queryable and expose deferred GC instead of resampling.
                self.gc_last_error = type(exc).__name__

    async def dispatch(self, operation: str, payload: dict[str, Any]) -> dict[str, Any]:
        self._require_ready()
        self._validate_model(payload)
        if self.journal is None:
            raise HTTPException(status_code=503, detail="persistent request journal is unavailable")
        try:
            if prepare_native_request(operation, payload) != payload:
                raise ValueError("request identity is incomplete")
        except ValueError as exc:
            raise HTTPException(status_code=400, detail="invalid request recovery identity") from exc

        async def invoke():
            self._active_request_id = payload["request_id"]
            try:
                try:
                    if operation == "fork":
                        body = await self.append(payload, fork=True)
                    else:
                        method = self.import_state if operation == "import" else getattr(self, operation)
                        body = await method(payload)
                except HTTPException as exc:
                    return NativeRequestResult({"detail": exc.detail}, status_code=exc.status_code)
                if operation == "rollback":
                    metadata = {"states": [], "dropped_state_refs": [payload["candidate_state_ref"]]}
                elif operation == "release":
                    metadata = {"states": [], "released_state_refs": sorted(
                        body["released_state_refs"] + body.get("released_alias_state_refs", []))}
                else:
                    selected = body.get("candidate", body)
                    current = self.records[selected["state_ref"]]
                    if current.export_record is None:
                        raise RuntimeError("Native result has no durable State export")
                    metadata = {"states": [asdict(current)], "dropped_state_refs": []}
                return NativeRequestResult(body, recovery_metadata=metadata)
            finally:
                self._active_request_id = ""

        try:
            record = await self.journal.execute(operation, payload, invoke, execution_lock=self.request_lock)
        except NativeRequestConflict as exc:
            raise HTTPException(status_code=409, detail="request ID has a different payload") from exc
        except NativeStateRetired as exc:
            raise HTTPException(status_code=410, detail="State handle was explicitly retired") from exc
        except (NativeRequestInProgress, NativeRequestOutcomeUnknown) as exc:
            raise HTTPException(status_code=503, detail="request outcome requires result query") from exc
        if record.status_code >= 400:
            raise HTTPException(status_code=record.status_code, detail=record.body.get("detail", "Native request failed"))
        await self._collect_garbage()
        await self._recover_current_states(record)
        return dict(record.body)

    async def request_result(self, request_id: str, request_digest: str) -> dict[str, Any]:
        self._require_ready()
        if self.journal is None:
            raise HTTPException(status_code=503, detail="persistent request journal is unavailable")
        try:
            record = self.journal.lookup(request_id, request_digest)
        except NativeRequestConflict as exc:
            raise HTTPException(status_code=409, detail="request ID has a different payload") from exc
        if record is None:
            raise HTTPException(status_code=404, detail="request ID is not recorded")
        if record.status == "completed":
            await self._collect_garbage()
            await self._recover_current_states(record)
        return record.to_response()

    async def _seed(self, record: _StateRecord) -> None:
        result = self._consensus(
            await self._collective(
                "seed",
                {
                    "state_ref": record.state_ref,
                    "state_digest": record.state_digest,
                    "cache_binding_digest": record.cache_binding_digest,
                    "state_profile_id": record.state_profile_id,
                    "state_profile_sha256": record.state_profile_sha256,
                    "pending_token_id": record.pending_token_id,
                },
            )
        )
        self._validate_worker_record(record, result)

    async def _clone(self, source: _StateRecord, target: _StateRecord) -> None:
        await self._ensure_loaded(source)
        result = self._consensus(
            await self._collective(
                "clone",
                {
                    "source_ref": source.state_ref,
                    "source_digest": source.state_digest,
                    "source_cache_binding_digest": source.cache_binding_digest,
                    "target_ref": target.state_ref,
                    "target_digest": target.state_digest,
                    "target_cache_binding_digest": target.cache_binding_digest,
                },
            )
        )
        self._validate_worker_record(target, result)

    @staticmethod
    def _validate_worker_record(record: _StateRecord, result: dict[str, Any]) -> None:
        expected = {
            "state_ref": record.state_ref,
            "state_digest": record.state_digest,
            "cache_binding_digest": record.cache_binding_digest,
            "state_profile_id": record.state_profile_id,
            "state_profile_sha256": record.state_profile_sha256,
            "pending_token_id": record.pending_token_id,
            "authoritative": False,
        }
        if any(result.get(key) != value for key, value in expected.items()):
            raise RuntimeError("RWKV native state worker metadata mismatch")

    def _xargs(
        self,
        source: _StateRecord,
        target: _StateRecord,
        pending_token_id: int | None,
    ) -> dict[str, Any]:
        values: dict[str, Any] = {
            "rwkv_state_profile": source.state_profile_id,
            "rwkv_state_profile_sha256": source.state_profile_sha256,
            "rwkv_native_state_read_ref": source.state_ref,
            "rwkv_native_state_read_digest": source.state_digest,
            "rwkv_native_state_read_binding_digest": source.cache_binding_digest,
            "rwkv_native_state_write_ref": target.state_ref,
            "rwkv_native_state_write_digest": target.state_digest,
            "rwkv_native_state_write_binding_digest": target.cache_binding_digest,
        }
        if pending_token_id is not None:
            values["rwkv_native_state_write_pending_token_id"] = pending_token_id
        return values

    async def _generate_tokens(
        self,
        *,
        source: _StateRecord,
        target: _StateRecord,
        prompt_token_ids: list[int],
        request_id: str,
        max_tokens: int,
        stop: list[str],
        sampling: dict[str, Any],
        pending_token_id: int | None,
    ) -> tuple[str, list[int], str]:
        assert self.engine_client is not None
        await self._ensure_loaded(source)
        params = SamplingParams(
            max_tokens=max_tokens,
            temperature=float(sampling.get("temperature", 0.05)),
            top_p=float(sampling.get("top_p", 1.0)),
            top_k=int(sampling.get("top_k", 0)),
            presence_penalty=float(sampling.get("presence_penalty", 0.0)),
            frequency_penalty=float(sampling.get("frequency_penalty", 0.0)),
            penalty_decay=float(sampling.get("penalty_decay", 0.996)),
            stop=stop or None,
            output_kind=RequestOutputKind.FINAL_ONLY,
            extra_args=self._xargs(source, target, pending_token_id),
        )
        final = None
        captured = None
        async for output in self.engine_client.generate(
            TokensPrompt(prompt_token_ids=prompt_token_ids),
            params,
            request_id,
        ):
            final = output
            outputs = getattr(output, "outputs", None)
            selected = outputs[0] if outputs else None
            selected_token_ids = getattr(selected, "token_ids", None)
            if (
                captured is None
                and selected_token_ids
                and getattr(selected, "finish_reason", None) is not None
            ):
                # Capture while the engine iterator is paused on its terminal
                # output.  Resuming/exhausting it may let the scheduler discard
                # the recurrent row before a following utility RPC runs,
                # especially for text-stop termination.
                captured = self._consensus(
                    await self._collective(
                        "capture",
                        {
                            "request_id": request_id,
                            "state_ref": target.state_ref,
                            "sampled_token_id": int(selected_token_ids[-1]),
                        },
                    )
                )
        if final is None or not final.outputs:
            raise RuntimeError("RWKV native generation returned no output")
        selected = final.outputs[0]
        if not isinstance(selected.finish_reason, str) or not selected.finish_reason:
            raise RuntimeError("RWKV native generation returned no valid finish reason")
        token_ids = [int(item) for item in selected.token_ids]
        if not token_ids:
            raise RuntimeError("RWKV native generation returned no token IDs")
        result = captured
        if result is None:
            result = self._consensus(
                await self._collective(
                    "capture",
                    {
                        "request_id": request_id,
                        "state_ref": target.state_ref,
                        "sampled_token_id": token_ids[-1],
                    },
                )
            )
        actual = replace(
            target,
            pending_token_id=int(result["pending_token_id"]),
            processed_token_count=int(result["processed_token_count"]),
        )
        self._validate_worker_record(actual, result)
        return str(selected.text), token_ids, selected.finish_reason

    async def _materialize_delta(
        self,
        source: _StateRecord,
        target: _StateRecord,
        delta_tokens: list[int],
    ) -> _StateRecord:
        if not delta_tokens:
            target = replace(
                target,
                pending_token_id=source.pending_token_id,
                processed_token_count=source.processed_token_count,
            )
            await self._clone(source, target)
            return target
        # Tokenize the logical delta once. Intermediate cache entries are private;
        # only the complete logical operation receives the caller's binding.
        window = int(self.engine_client.model_config.max_model_len)
        chunk_size = min(4096, window - 1)
        if chunk_size < 1:
            raise HTTPException(status_code=503, detail="no Native prefill capacity")
        current = source
        temporary_refs: set[str] = set()
        completed = False
        try:
            for offset in range(0, len(delta_tokens), chunk_size):
                chunk = delta_tokens[offset:offset + chunk_size]
                last = offset + len(chunk) == len(delta_tokens)
                step = replace(target, pending_token_id=chunk[-1])
                if not last:
                    ref = self._new_ref()
                    step = replace(
                        step, state_ref=ref,
                        state_digest=_digest({"logical_target": target.state_digest,
                                              "prefill_offset": offset}),
                        cache_binding_digest=_digest({"logical_binding": target.cache_binding_digest,
                                                       "prefill_offset": offset}),
                    )
                    temporary_refs.add(ref)
                await self._generate_tokens(
                    source=current, target=step,
                    prompt_token_ids=[current.pending_token_id, *chunk[:-1]],
                    request_id=f"native-materialize-{uuid4().hex}",
                    max_tokens=1, stop=[],
                    sampling={"temperature": 0.05, "top_k": 1},
                    pending_token_id=step.pending_token_id,
                )
                metadata = self._consensus(
                    await self._collective("get", {"state_ref": step.state_ref}))
                expected_count = current.processed_token_count + len(chunk)
                if (int(metadata["pending_token_id"]) != step.pending_token_id
                        or int(metadata["processed_token_count"]) != expected_count):
                    raise RuntimeError("RWKV native prefill boundary mismatch")
                step = replace(step, processed_token_count=expected_count)
                if current.state_ref in temporary_refs:
                    await self._collective("drop", {"state_ref": current.state_ref})
                    temporary_refs.remove(current.state_ref)
                current = step
            completed = True
            return current
        finally:
            if not completed:
                temporary_refs.add(target.state_ref)
            for ref in temporary_refs:
                await self._collective("drop", {"state_ref": ref})

    async def _export(self, record: _StateRecord) -> _StateRecord:
        self._input_evidence(record)
        store_key = record.state_digest
        results = await self._collective(
            "export",
            {"state_ref": record.state_ref, "store_key": store_key},
        )
        self._consensus(results)
        export_record = {
            "schema_version": EXPORT_VERSION,
            "protocol_version": PROTOCOL_VERSION,
            "state_format_version": STATE_FORMAT_VERSION,
            "model": self.model_name,
            "state_ref": record.state_ref,
            "state_digest": record.state_digest,
            "cache_binding_digest": record.cache_binding_digest,
            "state_profile_id": record.state_profile_id,
            "state_profile_sha256": record.state_profile_sha256,
            "pending_token_id": record.pending_token_id,
            "processed_token_count": record.processed_token_count,
            "store_key": store_key,
            "server_build": self.server_build,
            "tokenizer_build": self.tokenizer_build,
            "authoritative": False,
            "cache_role": "disposable_acceleration",
        }
        return replace(record, export_record=export_record)

    async def _import_workers(
        self, record: _StateRecord, export_record: dict[str, Any]
    ) -> None:
        result = self._consensus(
            await self._collective(
                "import",
                {
                    "state_ref": record.state_ref,
                    "state_digest": record.state_digest,
                    "cache_binding_digest": record.cache_binding_digest,
                    "state_profile_id": record.state_profile_id,
                    "state_profile_sha256": record.state_profile_sha256,
                    "pending_token_id": record.pending_token_id,
                    "processed_token_count": record.processed_token_count,
                    "store_key": export_record["store_key"],
                },
            )
        )
        self._validate_worker_record(record, result)

    def _snapshot(self, record: _StateRecord) -> dict[str, Any]:
        if record.export_record is None:
            raise RuntimeError("RWKV native state has no export record")
        return {
            "state_ref": record.state_ref,
            "state_digest": record.state_digest,
            "export_record": record.export_record,
            "state_format_version": STATE_FORMAT_VERSION,
            "server_build": self.server_build,
            "tokenizer_build": self.tokenizer_build,
            "cache_binding_digest": record.cache_binding_digest,
            "protocol_version": PROTOCOL_VERSION,
        }

    @staticmethod
    def _input_evidence(record: _StateRecord) -> dict[str, Any]:
        ids = record.input_token_ids
        if ids is None or record.input_bos_token_count is None:
            return {"prompt_token_ids_scope": "unavailable"}
        if (any(type(item) is not int or item < 0 for item in ids)
                or type(record.input_bos_token_count) is not int
                or not 0 <= record.input_bos_token_count <= len(ids)
                or len(ids) != record.processed_token_count + 1
                or not ids or ids[-1] != record.pending_token_id):
            raise RuntimeError("Native token evidence differs from the consumed worker State")
        return {"prompt_token_ids": list(ids), "prompt_token_ids_scope": "full_context",
                "input_bos_token_count": record.input_bos_token_count}

    async def create(self, payload: dict[str, Any]) -> dict[str, Any]:
        self._require_ready()
        self._validate_model(payload)
        binding, binding_digest = self._binding(payload)
        if binding.get("model") != self.model_name:
            raise HTTPException(status_code=409, detail="cache binding model mismatch")
        profile_id, profile_sha256 = self._profile(payload, binding)
        token_ids = self._tokens(str(payload.get("delta") or ""), initial=True)
        plain_ids = self._tokens(str(payload.get("delta") or ""), initial=False)
        bos_count = len(token_ids) - len(plain_ids)
        if bos_count < 0 or token_ids[bos_count:] != plain_ids:
            raise HTTPException(status_code=409, detail="initial token encoding has an unsupported special-token layout")
        if not token_ids:
            raise HTTPException(status_code=400, detail="initial state delta is empty")
        state_ref = self._new_ref()
        state_digest = _digest(
            {
                "protocol": PROTOCOL_VERSION,
                "model": self.model_name,
                "cache_binding_digest": binding_digest,
                "token_ids": token_ids,
            }
        )
        target = _StateRecord(
            state_ref=state_ref,
            state_digest=state_digest,
            cache_binding_digest=binding_digest,
            state_profile_id=profile_id,
            state_profile_sha256=profile_sha256,
            pending_token_id=token_ids[-1],
            processed_token_count=0,
            input_token_ids=list(token_ids),
            input_bos_token_count=bos_count,
        )
        async with self.lock:
            if len(token_ids) == 1:
                await self._seed(target)
            else:
                temporary = replace(
                    target,
                    state_ref=self._new_ref(),
                    state_digest=_digest({"temporary": state_ref}),
                    cache_binding_digest=_digest({"temporary_binding": state_ref}),
                    pending_token_id=token_ids[0],
                )
                await self._seed(temporary)
                try:
                    target = await self._materialize_delta(
                        temporary,
                        target,
                        token_ids[1:],
                    )
                finally:
                    await self._collective("drop", {"state_ref": temporary.state_ref})
            target = await self._export(target)
            self._remember(target)
            return self._snapshot(target)

    async def append(
        self, payload: dict[str, Any], *, fork: bool = False
    ) -> dict[str, Any]:
        self._require_ready()
        self._validate_model(payload)
        binding, binding_digest = self._binding(payload)
        if binding.get("model") != self.model_name:
            raise HTTPException(status_code=409, detail="cache binding model mismatch")
        profile_id, profile_sha256 = self._profile(payload, binding)
        parent = self._record(str(payload.get("parent_state_ref") or ""))
        if not parent.committed:
            raise HTTPException(status_code=409, detail="parent state is a candidate")
        if (
            profile_id != parent.state_profile_id
            or profile_sha256 != parent.state_profile_sha256
        ):
            raise HTTPException(status_code=409, detail="parent state profile mismatch")
        delta_tokens = self._tokens(str(payload.get("delta") or ""), initial=False)
        target = _StateRecord(
            state_ref=self._new_ref(),
            state_digest=_digest(
                {
                    "protocol": PROTOCOL_VERSION,
                    "model": self.model_name,
                    "cache_binding_digest": binding_digest,
                    "parent_state_digest": parent.state_digest,
                    "delta_token_ids": delta_tokens,
                    "fork": fork,
                }
            ),
            cache_binding_digest=binding_digest,
            state_profile_id=profile_id,
            state_profile_sha256=profile_sha256,
            pending_token_id=parent.pending_token_id,
            processed_token_count=parent.processed_token_count,
            parent_state_ref=parent.state_ref,
            input_token_ids=([*parent.input_token_ids, *delta_tokens]
                             if parent.input_token_ids is not None else None),
            input_bos_token_count=parent.input_bos_token_count,
        )
        async with self.lock:
            target = await self._materialize_delta(parent, target, delta_tokens)
            target = await self._export(target)
            self._remember(target)
            return self._snapshot(target)

    async def generate(self, payload: dict[str, Any]) -> dict[str, Any]:
        self._require_ready()
        self._validate_model(payload)
        parent = self._record(str(payload.get("parent_state_ref") or ""))
        parent_binding = str(payload.get("parent_cache_binding_digest") or "")
        if parent_binding != parent.cache_binding_digest:
            raise HTTPException(status_code=409, detail="parent cache binding mismatch")
        request_id = str(payload.get("request_id") or uuid4().hex)
        target = _StateRecord(
            state_ref=self._new_ref(),
            state_digest=_digest(
                {
                    "protocol": PROTOCOL_VERSION,
                    "parent_state_digest": parent.state_digest,
                    "request_id": request_id,
                }
            ),
            cache_binding_digest=parent.cache_binding_digest,
            state_profile_id=parent.state_profile_id,
            state_profile_sha256=parent.state_profile_sha256,
            pending_token_id=parent.pending_token_id,
            processed_token_count=parent.processed_token_count,
            parent_state_ref=parent.state_ref,
            committed=False,
        )
        sampling = payload.get("sampling")
        stop = payload.get("stop")
        evidence = self._input_evidence(parent)
        input_evidence = evidence if payload.get("return_token_ids") is True else {}
        async with self.lock:
            # The sampler can advance beyond a frontend text-stop before its
            # terminal output/capture reaches us. Its live row is private work,
            # never the State identity of that output. Materialize the published
            # cache from the parent and returned IDs through the same exact
            # token-consumption primitive used by append. This is deterministic
            # cache construction, not another role decision or a resample.
            scratch = replace(
                target, state_ref=self._new_ref(),
                state_digest=_digest({"sampling_scratch": target.state_digest}),
            )
            published = False
            try:
                content, token_ids, finish_reason = await self._generate_tokens(
                    source=parent, target=scratch,
                    prompt_token_ids=[parent.pending_token_id],
                    request_id=f"native-generate-{request_id}",
                    max_tokens=max(1, int(payload.get("max_tokens") or 1)),
                    stop=[str(item) for item in stop] if isinstance(stop, list) else [],
                    sampling=dict(sampling) if isinstance(sampling, dict) else {},
                    pending_token_id=None,
                )
                if not token_ids or any(type(token) is not int or token < 0 for token in token_ids):
                    raise RuntimeError("Native generation returned invalid token IDs")
                captured = self._consensus(await self._collective("get", {"state_ref": scratch.state_ref}))
                target = replace(
                    target,
                    input_token_ids=([*parent.input_token_ids, *token_ids]
                                     if parent.input_token_ids is not None else None),
                    input_bos_token_count=parent.input_bos_token_count,
                )
                started = time.monotonic()
                target = await self._materialize_delta(parent, target, token_ids)
                materialization = {
                    "method": "verified_parent_and_returned_token_ids",
                    "semantic_samples": 1,
                    "consumed_delta_tokens": len(token_ids),
                    "prefill_requests": (len(token_ids) - 1) // min(4096, int(self.engine_client.model_config.max_model_len) - 1) + 1,
                    "wall_seconds": time.monotonic() - started,
                    "sampler_processed_token_count": int(captured["processed_token_count"]),
                    "published_processed_token_count": target.processed_token_count,
                }
                target = await self._export(target)
                self._remember(target)
                published = True
            finally:
                await self._collective("drop", {"state_ref": scratch.state_ref})
                if not published:
                    await self._collective("drop", {"state_ref": target.state_ref})
        return {
            "candidate": {
                "state_ref": target.state_ref,
                "state_digest": target.state_digest,
                "content": content,
                "finish_reason": finish_reason,
                "metadata": {
                    "token_ids": token_ids,
                    "response_id": request_id,
                    "state_materialization": materialization,
                    **input_evidence,
                },
                "parent_state_digest": parent.state_digest,
                "parent_cache_binding_digest": parent.cache_binding_digest,
            }
        }

    async def commit(self, payload: dict[str, Any]) -> dict[str, Any]:
        self._require_ready()
        self._validate_model(payload)
        binding, binding_digest = self._binding(payload)
        if binding.get("model") != self.model_name:
            raise HTTPException(status_code=409, detail="cache binding model mismatch")
        candidate = self._record(str(payload.get("candidate_state_ref") or ""))
        if candidate.committed:
            raise HTTPException(status_code=409, detail="state is already committed")
        if (
            str(binding.get("parent_state_digest") or "")
            != self._record(candidate.parent_state_ref).state_digest
        ):
            raise HTTPException(status_code=409, detail="candidate lineage mismatch")
        async with self.lock:
            await self._ensure_loaded(candidate)
            result = self._consensus(
                await self._collective(
                    "rebind",
                    {
                        "state_ref": candidate.state_ref,
                        "state_digest": candidate.state_digest,
                        "old_cache_binding_digest": candidate.cache_binding_digest,
                        "new_cache_binding_digest": binding_digest,
                    },
                )
            )
            candidate = replace(
                candidate,
                cache_binding_digest=binding_digest,
                committed=True,
            )
            self._validate_worker_record(candidate, result)
            candidate = await self._export(candidate)
            self._remember(candidate)
            return self._snapshot(candidate)

    async def rollback(self, payload: dict[str, Any]) -> dict[str, Any]:
        self._require_ready()
        self._validate_model(payload)
        candidate = self._record(str(payload.get("candidate_state_ref") or ""))
        parent_ref = str(payload.get("parent_state_ref") or "")
        if candidate.committed or candidate.parent_state_ref != parent_ref:
            raise HTTPException(status_code=409, detail="candidate lineage mismatch")
        # GPU and disk deletion happen only after this result and the tombstone
        # commit together in the journal. An uncertain result cannot lose State.
        return {"rolled_back": True, "parent_state_ref": parent_ref}

    async def release(self, payload: dict[str, Any]) -> dict[str, Any]:
        self._require_ready()
        self._validate_model(payload)
        if payload.get("lifecycle_protocol") != NATIVE_STATE_LIFECYCLE_VERSION:
            raise HTTPException(status_code=400, detail="unsupported State lifecycle protocol")
        states = payload.get("states")
        release_aliases = payload.get("release_import_aliases", False)
        if not isinstance(release_aliases, bool):
            raise HTTPException(status_code=400, detail="release_import_aliases must be boolean")
        if not isinstance(states, list) or not states:
            raise HTTPException(status_code=400, detail="State release requires a nonempty identity batch")
        refs = set()
        assert self.journal is not None
        for identity in states:
            if (not isinstance(identity, dict)
                    or set(identity) != {"state_ref", "state_digest", "cache_binding_digest"}
                    or not isinstance(identity["state_ref"], str)
                    or not re.fullmatch(r"WKV-[0-9a-f]{32}", identity["state_ref"])
                    or any(not isinstance(identity[key], str) or not re.fullmatch(r"[0-9a-f]{64}", identity[key])
                           for key in ("state_digest", "cache_binding_digest"))):
                raise HTTPException(status_code=400, detail="invalid State release identity")
            ref = identity["state_ref"]
            if ref in refs:
                raise HTTPException(status_code=400, detail="duplicate State release identity")
            refs.add(ref)
            try:
                current = self.journal.lookup_state_metadata(ref, allow_request_id=self._active_request_id)
            except NativeRequestOutcomeUnknown as exc:
                raise HTTPException(status_code=503, detail="State has an unresolved mutation") from exc
            if current is None:
                raise HTTPException(status_code=410, detail="State release handle is unknown")
            if any(current.get(key) != value for key, value in identity.items()):
                raise HTTPException(status_code=409, detail="State release identity mismatch")
            if current.get("committed") is not True or current.get("dropped") is True:
                raise HTTPException(status_code=409, detail="uncommitted candidates require rollback")
        alias_refs = set()
        if release_aliases:
            for alias in self.journal.import_aliases_for(refs):
                if alias.get("committed") is not True or alias.get("dropped") is True:
                    raise HTTPException(status_code=409, detail="uncommitted imported State requires rollback")
                alias_refs.add(alias["state_ref"])
        try:
            self.journal.validate_release(refs | alias_refs, allow_request_id=self._active_request_id)
        except NativeRequestConflict as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc
        except NativeRequestOutcomeUnknown as exc:
            raise HTTPException(status_code=503, detail=str(exc)) from exc
        body = {"released_state_refs": sorted(refs)}
        if release_aliases:
            body["released_alias_state_refs"] = sorted(alias_refs)
        return body

    async def import_state(self, payload: dict[str, Any]) -> dict[str, Any]:
        self._require_ready()
        self._validate_model(payload)
        binding, binding_digest = self._binding(payload)
        if binding.get("model") != self.model_name:
            raise HTTPException(status_code=409, detail="cache binding model mismatch")
        export_record = payload.get("export_record")
        if not isinstance(export_record, dict):
            raise HTTPException(status_code=400, detail="export_record is required")
        # Import creates an alias, not an escape from explicit retirement.
        original_ref = export_record.get("state_ref")
        if not isinstance(original_ref, str) or not original_ref:
            raise HTTPException(status_code=400, detail="export record requires its original State handle")
        original = self._record(original_ref)
        if not original.committed:
            raise HTTPException(status_code=409, detail="only committed State exports may create import aliases")
        if original.export_record != export_record:
            raise HTTPException(status_code=409, detail="export differs from the current State identity")
        expected = {
            "schema_version": EXPORT_VERSION,
            "protocol_version": PROTOCOL_VERSION,
            "state_format_version": STATE_FORMAT_VERSION,
            "model": self.model_name,
            "cache_binding_digest": binding_digest,
            "server_build": self.server_build,
            "tokenizer_build": self.tokenizer_build,
            "authoritative": False,
            "cache_role": "disposable_acceleration",
        }
        if any(export_record.get(key) != value for key, value in expected.items()):
            raise HTTPException(status_code=409, detail="export record is incompatible")
        profile_id, profile_sha256 = self._profile(payload, binding)
        record = _StateRecord(
            state_ref=self._new_ref(),
            state_digest=str(export_record.get("state_digest") or ""),
            cache_binding_digest=binding_digest,
            state_profile_id=profile_id,
            state_profile_sha256=profile_sha256,
            pending_token_id=int(export_record.get("pending_token_id")),
            processed_token_count=int(export_record.get("processed_token_count")),
            export_record=dict(export_record),
            import_origin_state_ref=original.import_origin_state_ref or original.state_ref,
            input_token_ids=list(original.input_token_ids) if original.input_token_ids is not None else None,
            input_bos_token_count=original.input_bos_token_count,
        )
        async with self.lock:
            await self._import_workers(record, export_record)
            self._remember(record)
        return self._snapshot(record)


class RWKVNativeStateEndpointPlugin:
    """Register the explicit RWKV-LH native-state protocol under ``/v1``."""

    name = "rwkv_lh_native_state"
    required_tasks = ("generate",)

    def attach_router(self, app: FastAPI) -> None:
        @app.get("/v1/capabilities")
        async def capabilities(raw_request: Request):
            return raw_request.app.state.rwkv_native_state.capabilities()

        @app.post("/v1/state/create")
        async def create(payload: dict[str, Any], raw_request: Request):
            return await raw_request.app.state.rwkv_native_state.dispatch("create", payload)

        @app.post("/v1/state/append")
        async def append(payload: dict[str, Any], raw_request: Request):
            return await raw_request.app.state.rwkv_native_state.dispatch("append", payload)

        @app.post("/v1/state/fork")
        async def fork(payload: dict[str, Any], raw_request: Request):
            return await raw_request.app.state.rwkv_native_state.dispatch("fork", payload)

        @app.post("/v1/state/generate")
        async def generate(payload: dict[str, Any], raw_request: Request):
            return await raw_request.app.state.rwkv_native_state.dispatch("generate", payload)

        @app.post("/v1/state/commit")
        async def commit(payload: dict[str, Any], raw_request: Request):
            return await raw_request.app.state.rwkv_native_state.dispatch("commit", payload)

        @app.post("/v1/state/rollback")
        async def rollback(payload: dict[str, Any], raw_request: Request):
            return await raw_request.app.state.rwkv_native_state.dispatch("rollback", payload)

        @app.post("/v1/state/import")
        async def import_state(payload: dict[str, Any], raw_request: Request):
            return await raw_request.app.state.rwkv_native_state.dispatch("import", payload)

        @app.post("/v1/state/release")
        async def release(payload: dict[str, Any], raw_request: Request):
            return await raw_request.app.state.rwkv_native_state.dispatch("release", payload)

        @app.get("/v1/state/requests/{request_id}")
        async def request_result(request_id: str, request_digest: str, raw_request: Request):
            return await raw_request.app.state.rwkv_native_state.request_result(request_id, request_digest)

    async def init_state(
        self,
        engine_client: EngineClient | None,
        state: State,
        args: Any,
    ) -> None:
        service = RWKVNativeStateService(engine_client, args)
        state.rwkv_native_state = service
        await service.initialize()


__all__ = ["RWKVNativeStateEndpointPlugin", "RWKVNativeStateService"]

rwkv_lh/inference/native_source_identity:
"""Fail-closed Native identity from actual uploaded engine and project contents."""
from __future__ import annotations

import os
from pathlib import Path
from typing import Any

from rwkv_lh.inference.uploaded_sources import (
    ENGINE_SCHEMA,
    PROJECT_SCHEMA,
    verify_manifest,
)
from rwkv_lh.model_io import canonical_digest


def verify_native_source_identity(
    *, engine_file: str | Path | None, project_file: str | Path | None = None,
) -> dict[str, Any]:
    configuration = {}
    for scope in ("ENGINE", "PROJECT"):
        for suffix in ("MANIFEST", "MANIFEST_SHA256"):
            key = f"RWKV_NATIVE_{scope}_SOURCE_{suffix}"
            value = os.environ.get(key)
            if not value:
                raise RuntimeError(f"Native source configuration requires {key}")
            configuration[key] = value
    if engine_file is None:
        raise RuntimeError("Native source verification requires the loaded engine module path")
    identities = {}
    for scope, schema, loaded in (
        ("ENGINE", ENGINE_SCHEMA, Path(engine_file)),
        ("PROJECT", PROJECT_SCHEMA, Path(project_file) if project_file is not None else Path(__file__)),
    ):
        verified = verify_manifest(
            Path(configuration[f"RWKV_NATIVE_{scope}_SOURCE_MANIFEST"]),
            configuration[f"RWKV_NATIVE_{scope}_SOURCE_MANIFEST_SHA256"],
            expected_schema=schema, required_files=(loaded,),
        )
        identities[f"{scope.lower()}_manifest_sha256"] = verified["manifest_sha256"]
    identity = {"schema_version": "rwkv-lh.native-source-identity.v1", **identities}
    return {**identity, "identity_sha256": canonical_digest(identity)}

rwkv_lh/inference/vllm_rwkv_state_profil:
"""Fail-closed RWKV7 initial-state profiles for vLLM-RWKV.

This module deliberately contains no request generation or output processing.
It only validates a pinned manifest, preloads immutable WKV tensors, and
resolves an explicitly pinned profile identity for each request.  Portable
RWKV-PEFT ``time_state`` tensors use ``[head, value, key]`` while the pinned
FLA recurrent runtime consumes ``[head, key, value]``.  The loader performs
that boundary conversion exactly once.
"""

from __future__ import annotations

import hashlib
import json
import re
from dataclasses import dataclass
from pathlib import Path

import torch


RWKV7_STATE_PROFILE_MANIFEST_SCHEMA = "vllm.rwkv7-state-profiles.v1"
RWKV7_STATE_PROFILE_XARG = "rwkv_state_profile"
RWKV7_STATE_PROFILE_SHA256_XARG = "rwkv_state_profile_sha256"
RWKV7_ZERO_STATE_PROFILE = "zero"
RWKV7_PEFT_STATE_LAYOUT = "[layer,head,value,key]"
RWKV7_RUNTIME_STATE_LAYOUT = "[layer,head,key,value]"
RWKV7_PROFILE_TO_RUNTIME_CONVERSION = "transpose(-2,-1)"
_PROFILE_ID_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$")
_SHA256_PATTERN = re.compile(r"^[0-9a-f]{64}$")


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


@dataclass(frozen=True)
class RWKV7InitialStateProfile:
    profile_id: str
    state_sha256: str
    wkv_state: torch.Tensor | None


class RWKV7InitialStateProfiles:
    """Immutable initial WKV states selected by registered request identities."""

    def __init__(
        self,
        profiles: dict[str, RWKV7InitialStateProfile],
        default_profile_id: str,
        *,
        manifest_sha256: str | None = None,
        requires_explicit_request_profile: bool = False,
    ) -> None:
        self._profiles = dict(profiles)
        self.default_profile_id = default_profile_id
        self.manifest_sha256 = manifest_sha256
        self.requires_explicit_request_profile = requires_explicit_request_profile
        if default_profile_id not in self._profiles:
            raise ValueError("RWKV7 default state profile is not registered")

    @classmethod
    def zero_only(cls) -> "RWKV7InitialStateProfiles":
        return cls(
            {
                RWKV7_ZERO_STATE_PROFILE: RWKV7InitialStateProfile(
                    profile_id=RWKV7_ZERO_STATE_PROFILE,
                    state_sha256="0" * 64,
                    wkv_state=None,
                )
            },
            RWKV7_ZERO_STATE_PROFILE,
        )

    @classmethod
    def load(
        cls,
        manifest_path: str,
        manifest_sha256: str | None,
        *,
        model_artifact: str,
        model_revision: str,
        total_num_layers: int,
        total_num_heads: int,
        layer_offset: int,
        num_layers: int,
        tp_size: int,
        tp_rank: int,
        num_heads: int,
        head_size: int,
        device: torch.device,
        dtype: torch.dtype,
    ) -> "RWKV7InitialStateProfiles":
        path = Path(manifest_path).resolve()
        if not path.is_file():
            raise FileNotFoundError(
                f"RWKV7 state-profile manifest does not exist: {path}"
            )
        expected_manifest_sha256 = str(manifest_sha256 or "").lower()
        if not _SHA256_PATTERN.fullmatch(expected_manifest_sha256):
            raise ValueError(
                "VLLM_RWKV7_STATE_PROFILE_MANIFEST_SHA256 must pin the manifest"
            )
        actual_manifest_sha256 = sha256_file(path)
        if actual_manifest_sha256 != expected_manifest_sha256:
            raise ValueError(
                "RWKV7 state-profile manifest SHA-256 mismatch: "
                f"expected {expected_manifest_sha256}, got {actual_manifest_sha256}"
            )

        manifest = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(manifest, dict):
            raise TypeError("RWKV7 state-profile manifest must be an object")
        if manifest.get("schema_version") != RWKV7_STATE_PROFILE_MANIFEST_SCHEMA:
            raise ValueError("unsupported RWKV7 state-profile manifest schema")
        if manifest.get("model_artifact") != model_artifact:
            raise ValueError("RWKV7 state-profile model artifact mismatch")
        if manifest.get("model_revision") != model_revision:
            raise ValueError("RWKV7 state-profile model revision mismatch")

        entries = manifest.get("profiles")
        if not isinstance(entries, list) or not entries:
            raise ValueError("RWKV7 state-profile manifest requires profiles")
        profiles = cls.zero_only()._profiles
        expected_keys = {
            f"blocks.{layer}.att.time_state" for layer in range(total_num_layers)
        }
        for entry in entries:
            if not isinstance(entry, dict):
                raise TypeError("RWKV7 state-profile entries must be objects")
            profile_id = entry.get("id")
            if not isinstance(profile_id, str) or not _PROFILE_ID_PATTERN.fullmatch(
                profile_id
            ):
                raise ValueError("RWKV7 state-profile ID is invalid")
            if profile_id == RWKV7_ZERO_STATE_PROFILE or profile_id in profiles:
                raise ValueError(f"duplicate RWKV7 state-profile ID: {profile_id}")
            if entry.get("format") != "rwkv-peft-time-state.v1":
                raise ValueError("unsupported RWKV7 state-profile format")
            state_sha256 = str(entry.get("sha256") or "").lower()
            if not _SHA256_PATTERN.fullmatch(state_sha256):
                raise ValueError(f"RWKV7 state-profile {profile_id!r} lacks SHA-256")
            state_path_value = entry.get("path")
            if not isinstance(state_path_value, str) or not state_path_value:
                raise ValueError(f"RWKV7 state-profile {profile_id!r} lacks path")
            state_path = Path(state_path_value)
            if not state_path.is_absolute():
                state_path = path.parent / state_path
            state_path = state_path.resolve()
            if not state_path.is_file():
                raise FileNotFoundError(
                    f"RWKV7 state-profile does not exist: {state_path}"
                )
            actual_state_sha256 = sha256_file(state_path)
            if actual_state_sha256 != state_sha256:
                raise ValueError(f"RWKV7 state-profile {profile_id!r} SHA-256 mismatch")

            checkpoint = torch.load(
                state_path,
                map_location="cpu",
                weights_only=True,
            )
            if not isinstance(checkpoint, dict) or set(checkpoint) != expected_keys:
                raise ValueError(f"RWKV7 state-profile {profile_id!r} key set mismatch")
            layer_tensors: list[torch.Tensor] = []
            for global_layer in range(layer_offset, layer_offset + num_layers):
                key = f"blocks.{global_layer}.att.time_state"
                value = checkpoint[key]
                if not isinstance(value, torch.Tensor):
                    raise TypeError(
                        f"RWKV7 state-profile {profile_id!r} value is not a tensor"
                    )
                expected_shape = (total_num_heads, head_size, head_size)
                if tuple(value.shape) != expected_shape:
                    raise ValueError(
                        f"RWKV7 state-profile {profile_id!r} shape mismatch for {key}"
                    )
                if value.dtype != torch.bfloat16:
                    raise ValueError(
                        f"RWKV7 state-profile {profile_id!r} dtype mismatch for {key}"
                    )
                if (
                    not torch.isfinite(value).all().item()
                    or not torch.count_nonzero(value).item()
                ):
                    raise ValueError(
                        f"RWKV7 state-profile {profile_id!r} has invalid values in {key}"
                    )
                layer_tensors.append(value.detach())
            initial = torch.stack(layer_tensors, dim=0)
            if tp_size <= 0 or not 0 <= tp_rank < tp_size:
                raise ValueError("RWKV7 state-profile TP identity is invalid")
            if initial.shape[1] % tp_size:
                raise ValueError("RWKV7 state-profile heads are not TP divisible")
            heads_per_rank = initial.shape[1] // tp_size
            initial = initial.narrow(1, tp_rank * heads_per_rank, heads_per_rank)
            # RWKV-PEFT trains and saves time_state as [H,V,K].  Both the
            # training FLA wrapper and the pinned vLLM recurrent API consume
            # [B,H,K,V].  Equal K/V sizes make a missing transpose invisible
            # to shape validation, so keep this conversion explicit here.
            initial = initial.transpose(-2, -1).contiguous()
            expected_runtime_shape = (
                num_layers,
                num_heads,
                head_size,
                head_size,
            )
            if tuple(initial.shape) != expected_runtime_shape:
                raise ValueError(
                    f"RWKV7 state-profile {profile_id!r} runtime shape mismatch"
                )
            profiles[profile_id] = RWKV7InitialStateProfile(
                profile_id=profile_id,
                state_sha256=state_sha256,
                wkv_state=initial.contiguous().to(device=device, dtype=dtype),
            )

        default_profile_id = manifest.get("default_profile", RWKV7_ZERO_STATE_PROFILE)
        if not isinstance(default_profile_id, str):
            raise TypeError("RWKV7 default state-profile ID must be a string")
        if default_profile_id != RWKV7_ZERO_STATE_PROFILE:
            raise ValueError("RWKV7 state-profile manifest default must be zero")
        return cls(
            profiles,
            default_profile_id,
            manifest_sha256=actual_manifest_sha256,
            requires_explicit_request_profile=True,
        )

    def resolve(self, profile_id: str | None) -> RWKV7InitialStateProfile:
        resolved_id = profile_id or self.default_profile_id
        profile = self._profiles.get(resolved_id)
        if profile is None:
            raise ValueError(f"unknown RWKV7 state-profile ID: {resolved_id!r}")
        return profile

    def identities(self) -> dict[str, str]:
        return {
            profile_id: profile.state_sha256
            for profile_id, profile in sorted(self._profiles.items())
        }


def resolve_request_profile(
    profiles: RWKV7InitialStateProfiles,
    sampling_params: object | None,
) -> RWKV7InitialStateProfile:
    """Resolve a request profile before the caller allocates recurrent state."""

    requested_profile_id = None
    requested_profile_sha256 = None
    extra_args = (
        getattr(sampling_params, "extra_args", None)
        if sampling_params is not None
        else None
    )
    if extra_args is not None:
        if not isinstance(extra_args, dict):
            raise TypeError("RWKV7 sampling extra_args must be a dictionary")
        requested_profile_id = extra_args.get(RWKV7_STATE_PROFILE_XARG)
        requested_profile_sha256 = extra_args.get(
            RWKV7_STATE_PROFILE_SHA256_XARG
        )
        if requested_profile_id is not None and not isinstance(
            requested_profile_id, str
        ):
            raise TypeError("RWKV7 state-profile request value must be a string")
        if requested_profile_sha256 is not None and not isinstance(
            requested_profile_sha256, str
        ):
            raise TypeError("RWKV7 state-profile SHA-256 must be a string")
    if bool(requested_profile_id) != bool(requested_profile_sha256):
        raise ValueError("RWKV7 request state-profile ID and SHA-256 are both required")
    if profiles.requires_explicit_request_profile and not requested_profile_id:
        raise ValueError(
            "RWKV7 request must explicitly select a registered state-profile pair"
        )
    profile = profiles.resolve(requested_profile_id)
    if (
        requested_profile_sha256 is not None
        and requested_profile_sha256 != profile.state_sha256
    ):
        raise ValueError("RWKV7 request state-profile SHA-256 mismatch")
    return profile


__all__ = [
    "RWKV7InitialStateProfile",
    "RWKV7InitialStateProfiles",
    "RWKV7_STATE_PROFILE_MANIFEST_SCHEMA",
    "RWKV7_STATE_PROFILE_SHA256_XARG",
    "RWKV7_STATE_PROFILE_XARG",
    "RWKV7_ZERO_STATE_PROFILE",
    "RWKV7_PEFT_STATE_LAYOUT",
    "RWKV7_PROFILE_TO_RUNTIME_CONVERSION",
    "RWKV7_RUNTIME_STATE_LAYOUT",
    "resolve_request_profile",
    "sha256_file",
]

rwkv_lh/retrieval/providers.py:
"""Provider adapters extracted as a retrieval kernel, without agent semantics."""

from __future__ import annotations

import json
import hashlib
import os
import re
import threading
from dataclasses import dataclass, field
from html.parser import HTMLParser
from typing import Any, Callable, Mapping, Protocol, Sequence
from urllib.parse import parse_qs, quote, unquote, urlencode, urlparse
from xml.etree import ElementTree

import requests

from rwkv_lh.retrieval.fetch import (
    FetchPolicyError,
    FetchResponse,
    PublicHttpFetcher,
    validate_public_url,
)


@dataclass(frozen=True)
class RetrievedSource:
    url: str
    raw: bytes
    media_type: str
    source_type: str
    title: str = ""
    published: str = ""
    structured_fields: Mapping[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class WebSearchResult(Sequence[RetrievedSource]):
    sources: tuple[RetrievedSource, ...]
    provider_attempts: tuple[Mapping[str, Any], ...] = ()

    def __getitem__(self, index: int | slice) -> RetrievedSource | tuple[RetrievedSource, ...]:
        return self.sources[index]

    def __len__(self) -> int:
        return len(self.sources)


class ProviderSearchError(RuntimeError):
    def __init__(
        self,
        message: str,
        *,
        provider_attempts: Sequence[Mapping[str, Any]] = (),
    ) -> None:
        super().__init__(message)
        self.provider_attempts = tuple(dict(item) for item in provider_attempts)


class WebProvider(Protocol):
    provider_name: str

    def search(self, query: str, max_results: int) -> WebSearchResult: ...


class ConnectorProvider(Protocol):
    provider_name: str
    supported_operations: Sequence[str]

    def lookup(self, operation: str, query: str) -> Sequence[RetrievedSource]: ...


class _SearchLinks(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.links: list[tuple[str, str]] = []
        self._href = ""
        self._parts: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag.casefold() != "a":
            return
        attributes = dict(attrs)
        classes = str(attributes.get("class") or "")
        if "result__a" in classes or "result-link" in classes:
            self._href = str(attributes.get("href") or "")
            self._parts = []

    def handle_data(self, data: str) -> None:
        if self._href:
            self._parts.append(str(data or ""))

    def handle_endtag(self, tag: str) -> None:
        if tag.casefold() == "a" and self._href:
            self.links.append((self._href, " ".join("".join(self._parts).split())))
            self._href = ""
            self._parts = []


def _public_result_url(value: str) -> str:
    selected = str(value or "").strip()
    parsed = urlparse(selected)
    if parsed.netloc.casefold().endswith("duckduckgo.com"):
        target = parse_qs(parsed.query).get("uddg", [""])[0]
        if target:
            selected = unquote(target)
    return selected


class KeylessWebProvider:
    """Exact URL fetch plus bounded keyless discovery; it never plans queries.

    The discovery path is deliberately multi-source.  The original deployment
    depended only on DuckDuckGo HTML, which is unreachable in the target local
    network.  Bing RSS is the local primary and the original DuckDuckGo HTML
    parser remains a bounded fallback.  Both receive the exact model query.
    """

    provider_name = "keyless-public-web-multi-source-v1"

    def __init__(self, fetcher: PublicHttpFetcher | None = None) -> None:
        self.fetcher = fetcher or PublicHttpFetcher()

    @staticmethod
    def _explicit_url(query: str) -> str:
        match = re.search(r"https?://[^\s<>\]\[()]+", str(query or ""))
        return match.group(0).rstrip(".,;:!?，。；：！？") if match else ""

    @staticmethod
    def _source(
        response: FetchResponse,
        *,
        title: str = "",
        structured_fields: Mapping[str, Any] | None = None,
    ) -> RetrievedSource:
        return RetrievedSource(
            url=response.url,
            raw=response.body,
            media_type=response.media_type,
            source_type="public_web_page",
            title=title,
            structured_fields=dict(structured_fields or {}),
        )

    @staticmethod
    def _bing_rss_links(payload: bytes) -> list[tuple[str, str]]:
        root = ElementTree.fromstring(payload)
        links: list[tuple[str, str]] = []
        for item in root.findall(".//item"):
            url = str(item.findtext("link") or "").strip()
            title = " ".join(str(item.findtext("title") or "").split())
            if url:
                links.append((url, title))
        return links

    def _discover(
        self, query: str
    ) -> tuple[str, list[tuple[str, str]], tuple[Mapping[str, Any], ...]]:
        attempts = (
            (
                "bing-rss",
                "https://cn.bing.com/search?"
                + urlencode({"q": query, "format": "rss"}),
                lambda response: self._bing_rss_links(response.body),
            ),
            (
                "duckduckgo-html",
                "https://html.duckduckgo.com/html/?" + urlencode({"q": query}),
                self._duckduckgo_links,
            ),
        )
        failures: list[str] = []
        provider_attempts: list[dict[str, Any]] = []
        for provider, url, parse_links in attempts:
            try:
                response = self.fetcher.fetch(url)
                links = list(parse_links(response))
            except Exception as exc:
                failures.append(f"{provider}:{type(exc).__name__}:{str(exc)[:200]}")
                provider_attempts.append(
                    {
                        "provider": provider,
                        "status": "error",
                        "error_type": type(exc).__name__,
                        "message": str(exc)[:500],
                    }
                )
                continue
            if links:
                provider_attempts.append({"provider": provider, "status": "ok"})
                return provider, links, tuple(provider_attempts)
            failures.append(f"{provider}:no_results")
            provider_attempts.append({"provider": provider, "status": "no_results"})
        raise ProviderSearchError(
            "public web discovery failed: " + "; ".join(failures),
            provider_attempts=provider_attempts,
        )

    @staticmethod
    def _duckduckgo_links(response: FetchResponse) -> list[tuple[str, str]]:
        parser = _SearchLinks()
        parser.feed(response.body.decode("utf-8", errors="replace"))
        return parser.links

    def search(self, query: str, max_results: int) -> WebSearchResult:
        selected_query = str(query or "").strip()
        if not selected_query:
            raise ValueError("web search query must be non-empty")
        limit = max(1, min(int(max_results), 10))
        direct = self._explicit_url(selected_query)
        if direct:
            return WebSearchResult(
                sources=(
                    self._source(
                        self.fetcher.fetch(direct),
                        structured_fields={"discovery_provider": "direct_url"},
                    ),
                ),
                provider_attempts=({"provider": "direct_url", "status": "ok"},),
            )
        discovery_provider, links, provider_attempts = self._discover(selected_query)
        sources: list[RetrievedSource] = []
        seen: set[str] = set()
        for rank, (href, title) in enumerate(links, start=1):
            url = _public_result_url(href)
            if not url or url in seen:
                continue
            seen.add(url)
            try:
                sources.append(
                    self._source(
                        self.fetcher.fetch(url),
                        title=title,
                        structured_fields={
                            "discovery_provider": discovery_provider,
                            "discovery_rank": rank,
                        },
                    )
                )
            except Exception:
                continue
            if len(sources) >= limit:
                break
        return WebSearchResult(
            sources=tuple(sources),
            provider_attempts=provider_attempts,
        )


def _configured_tavily_keys() -> tuple[str, ...]:
    values = [os.environ.get("TAVILY_API_KEY", "")]
    values.extend(re.split(r"[,;\s]+", os.environ.get("TAVILY_API_KEYS", "")))
    return tuple(
        dict.fromkeys(value.strip() for value in values if value.strip())
    )


def _credential_id(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()[:16]


class TavilyWebProvider:
    """Prefer direct pages, with explicitly marked Tavily extraction on timeout."""

    provider_name = "tavily-search-api"
    _TRANSIENT_PAGE_STATUS_CODES = frozenset({408, 425, 429, 500, 502, 503, 504})
    _MAX_EXTRACTED_PAGE_BYTES = 1_000_000

    def __init__(
        self,
        fetcher: PublicHttpFetcher | None = None,
        *,
        api_keys: Sequence[str] | None = None,
        url_validator: Callable[[str], str] = validate_public_url,
    ) -> None:
        self.fetcher = fetcher or PublicHttpFetcher()
        self._api_keys = tuple(api_keys) if api_keys is not None else None
        self._url_validator = url_validator
        self._disabled_credentials: set[str] = set()
        self._health_lock = threading.Lock()

    def _keys(self) -> tuple[str, ...]:
        values = self._api_keys if self._api_keys is not None else _configured_tavily_keys()
        with self._health_lock:
            return tuple(
                value
                for value in values
                if _credential_id(value) not in self._disabled_credentials
            )

    @staticmethod
    def _status_code(exc: Exception) -> int | None:
        response = getattr(exc, "response", None)
        try:
            return int(getattr(response, "status_code", 0)) or None
        except (TypeError, ValueError):
            return None

    def _disable(self, key: str) -> None:
        with self._health_lock:
            self._disabled_credentials.add(_credential_id(key))

    @staticmethod
    def _canonical_directory_retry(url: str) -> str:
        """Return one narrow slash variant for extensionless discovered pages.

        Some HTTP servers emit an empty 301/302 response and urllib3 releases
        its socket before the connected-peer check can inspect it.  We never
        weaken that SSRF check.  For a Tavily-discovered, extensionless path we
        may instead request the conventional trailing-slash URL as a fresh,
        independently DNS- and peer-validated request.
        """

        parsed = urlparse(url)
        segment = parsed.path.rsplit("/", 1)[-1]
        if (
            parsed.scheme in {"http", "https"}
            and parsed.path
            and not parsed.path.endswith("/")
            and segment
            and "." not in segment
            and not parsed.query
            and not parsed.fragment
        ):
            return url + "/"
        return ""

    @classmethod
    def _is_transient_page_error(cls, exc: Exception) -> bool:
        """Select only transport failures that are safe to repeat once.

        Fetch policy failures are security or resource-bound decisions, not
        availability failures, and must never enter the generic retry path.
        """

        if isinstance(exc, FetchPolicyError):
            return False
        status_code = cls._status_code(exc)
        if status_code is not None:
            return status_code in cls._TRANSIENT_PAGE_STATUS_CODES
        return isinstance(
            exc,
            (
                requests.exceptions.Timeout,
                requests.exceptions.ConnectionError,
                TimeoutError,
                ConnectionError,
            ),
        )

    @classmethod
    def _safe_page_failure(
        cls,
        *,
        url: str,
        rank: int,
        attempt: str,
        exc: Exception,
    ) -> dict[str, Any]:
        """Create a correlatable failure record without retaining URL secrets."""

        parsed = urlparse(url)
        status_code = cls._status_code(exc)
        value: dict[str, Any] = {
            "discovery_rank": rank,
            "attempt": attempt,
            "scheme": parsed.scheme.casefold()[:16],
            "host": str(parsed.hostname or "")[:253],
            "url_sha256": hashlib.sha256(url.encode("utf-8")).hexdigest(),
            "error_type": type(exc).__name__,
            "status_code": status_code,
        }
        if isinstance(exc, FetchPolicyError):
            value["category"] = "fetch_policy"
            value["policy_reason"] = str(exc)[:240]
        elif status_code is not None:
            value["category"] = (
                "transient_http"
                if status_code in cls._TRANSIENT_PAGE_STATUS_CODES
                else "http"
            )
        elif isinstance(
            exc, (requests.exceptions.Timeout, TimeoutError)
        ):
            value["category"] = "transport_timeout"
        elif isinstance(
            exc, (requests.exceptions.ConnectionError, ConnectionError)
        ):
            value["category"] = "transport_connection"
        else:
            value["category"] = "page_fetch"
        return value

    def search(self, query: str, max_results: int) -> WebSearchResult:
        selected_query = str(query or "").strip()
        if not selected_query:
            raise ValueError("web search query must be non-empty")
        keys = self._keys()
        if not keys:
            return WebSearchResult(
                sources=(),
                provider_attempts=(
                    {
                        "provider": self.provider_name,
                        "status": "disabled",
                        "error_type": "provider_not_configured",
                    },
                ),
            )
        limit = max(1, min(int(max_results), 10))
        credential_attempts: list[dict[str, Any]] = []
        payload: Mapping[str, Any] | None = None
        response_body = b""
        successful_credential_id = ""
        for key in keys:
            identity = _credential_id(key)
            try:
                response = self.fetcher.post_json(
                    "https://api.tavily.com/search",
                    {
                        "query": selected_query,
                        "search_depth": "basic",
                        "max_results": limit,
                        "include_answer": False,
                        "include_raw_content": "markdown",
                        "include_images": False,
                        "topic": "general",
                    },
                    headers={"Authorization": f"Bearer {key}"},
                )
                response_body = response.body
                value = json.loads(response_body.decode("utf-8"))
                if not isinstance(value, Mapping):
                    raise ValueError("Tavily response must be a JSON object")
                payload = value
                successful_credential_id = identity
                credential_attempts.append(
                    {
                        "status": "ok",
                        "credential_id": identity,
                    }
                )
                break
            except Exception as exc:
                status_code = self._status_code(exc)
                credential_attempts.append(
                    {
                        "status": "error",
                        "credential_id": identity,
                        "status_code": status_code,
                        "error_type": type(exc).__name__,
                        "message": str(exc)[:500],
                    }
                )
                if status_code in {401, 402, 403, 432}:
                    self._disable(key)
                    continue
                if status_code == 429:
                    continue
                break
        if payload is None:
            return WebSearchResult(
                sources=(),
                provider_attempts=(
                    {
                        "provider": self.provider_name,
                        "status": "error",
                        "credential_attempt_count": len(credential_attempts),
                        "credential_attempts": credential_attempts,
                    },
                ),
            )

        sources: list[RetrievedSource] = []
        fetch_failures = 0
        canonical_directory_retries = 0
        page_transport_retries = 0
        direct_page_commits = 0
        provider_extracted_page_commits = 0
        provider_extracted_page_rejections = 0
        host_circuit_open_skips = 0
        host_circuit_validation_failures = 0
        transient_unavailable_hosts: set[str] = set()
        page_fetch_attempt_failures: list[dict[str, Any]] = []
        response_sha256 = hashlib.sha256(response_body).hexdigest()
        request_id = str(payload.get("request_id") or "")[:128]
        for rank, item in enumerate(payload.get("results") or [], start=1):
            if not isinstance(item, Mapping):
                continue
            url = str(item.get("url") or "").strip()
            if not url:
                continue
            page: FetchResponse | None = None
            extracted_content_eligible = False
            direct_page_attempted = True
            host = str(urlparse(url).hostname or "").casefold()
            if host and host in transient_unavailable_hosts:
                direct_page_attempted = False
                try:
                    self._url_validator(url)
                except Exception as exc:
                    host_circuit_validation_failures += 1
                    page_fetch_attempt_failures.append(
                        self._safe_page_failure(
                            url=url,
                            rank=rank,
                            attempt="host_circuit_public_url_validation",
                            exc=exc,
                        )
                    )
                else:
                    host_circuit_open_skips += 1
                    extracted_content_eligible = True
            else:
                try:
                    page = self.fetcher.fetch(url)
                except FetchPolicyError as exc:
                    page_fetch_attempt_failures.append(
                        self._safe_page_failure(
                            url=url,
                            rank=rank,
                            attempt="initial",
                            exc=exc,
                        )
                    )
                    retry_url = (
                        self._canonical_directory_retry(url)
                        if str(exc) == "retrieval peer address is unavailable"
                        else ""
                    )
                    try:
                        if retry_url:
                            page = self.fetcher.fetch(retry_url)
                            canonical_directory_retries += 1
                    except Exception as retry_exc:
                        page_fetch_attempt_failures.append(
                            self._safe_page_failure(
                                url=retry_url,
                                rank=rank,
                                attempt="canonical_directory_retry",
                                exc=retry_exc,
                            )
                        )
                except Exception as exc:
                    page_fetch_attempt_failures.append(
                        self._safe_page_failure(
                            url=url,
                            rank=rank,
                            attempt="initial",
                            exc=exc,
                        )
                    )
                    if self._is_transient_page_error(exc):
                        page_transport_retries += 1
                        try:
                            page = self.fetcher.fetch(url)
                        except Exception as retry_exc:
                            page_fetch_attempt_failures.append(
                                self._safe_page_failure(
                                    url=url,
                                    rank=rank,
                                    attempt="transport_retry",
                                    exc=retry_exc,
                                )
                            )
                            extracted_content_eligible = self._is_transient_page_error(
                                retry_exc
                            )
                            if extracted_content_eligible and host:
                                transient_unavailable_hosts.add(host)
            if page is not None:
                direct_page_commits += 1
                sources.append(
                    KeylessWebProvider._source(
                        page,
                        title=str(item.get("title") or ""),
                        structured_fields={
                            "discovery_provider": self.provider_name,
                            "discovery_rank": rank,
                            "discovery_score": item.get("score"),
                            "discovery_url": url,
                            "evidence_transport": "direct_public_http",
                            "provider_response_sha256": response_sha256,
                            "provider_request_id": request_id,
                        },
                    )
                )
            else:
                if direct_page_attempted:
                    fetch_failures += 1
                raw_content = item.get("raw_content")
                encoded = (
                    raw_content.encode("utf-8")
                    if isinstance(raw_content, str) and raw_content.strip()
                    else b""
                )
                if extracted_content_eligible and (
                    0 < len(encoded) <= self._MAX_EXTRACTED_PAGE_BYTES
                ):
                    provider_extracted_page_commits += 1
                    sources.append(
                        RetrievedSource(
                            url=url,
                            raw=encoded,
                            media_type="text/markdown; charset=utf-8",
                            source_type="tavily_extracted_public_web_page",
                            title=str(item.get("title") or ""),
                            published=str(item.get("published_date") or ""),
                            structured_fields={
                                "discovery_provider": self.provider_name,
                                "discovery_rank": rank,
                                "discovery_score": item.get("score"),
                                "discovery_url": url,
                                "evidence_transport": "tavily_extracted_markdown",
                                "extracted_content_sha256": hashlib.sha256(
                                    encoded
                                ).hexdigest(),
                                "provider_response_sha256": response_sha256,
                                "provider_request_id": request_id,
                            },
                        )
                    )
                elif extracted_content_eligible:
                    provider_extracted_page_rejections += 1
            if len(sources) >= limit:
                break
        provider_attempt = {
            "provider": self.provider_name,
            "status": "ok",
            "credential_id": successful_credential_id,
            "credential_attempt_count": len(credential_attempts),
            "credential_attempts": credential_attempts,
            "response_sha256": response_sha256,
            "request_id": request_id,
            "discovered_result_count": len(payload.get("results") or []),
            "committed_page_count": len(sources),
            "direct_page_commit_count": direct_page_commits,
            "provider_extracted_page_commit_count": provider_extracted_page_commits,
            "provider_extracted_page_rejection_count": provider_extracted_page_rejections,
            "host_circuit_open_host_count": len(transient_unavailable_hosts),
            "host_circuit_open_skip_count": host_circuit_open_skips,
            "host_circuit_validation_failure_count": host_circuit_validation_failures,
            "page_fetch_failure_count": fetch_failures,
            "page_fetch_attempt_failure_count": len(page_fetch_attempt_failures),
            "page_fetch_attempt_failures": page_fetch_attempt_failures,
            "page_transport_retry_count": page_transport_retries,
            "canonical_directory_retry_count": canonical_directory_retries,
        }
        return WebSearchResult(
            sources=tuple(sources),
            provider_attempts=(provider_attempt,),
        )


class LocalWebProvider:
    """Project-owned provider order: direct URL, Tavily, Bing RSS, DDG."""

    provider_name = "local-web-tavily-bing-ddg-v1"

    def __init__(
        self,
        fetcher: PublicHttpFetcher | None = None,
        *,
        tavily: TavilyWebProvider | None = None,
        keyless: KeylessWebProvider | None = None,
    ) -> None:
        shared = fetcher or PublicHttpFetcher()
        self.tavily = tavily or TavilyWebProvider(shared)
        self.keyless = keyless or KeylessWebProvider(shared)

    def search(self, query: str, max_results: int) -> WebSearchResult:
        selected_query = str(query or "").strip()
        if KeylessWebProvider._explicit_url(selected_query):
            return self.keyless.search(selected_query, max_results)
        tavily = self.tavily.search(selected_query, max_results)
        if tavily.sources:
            return tavily
        attempts = list(tavily.provider_attempts)
        try:
            keyless = self.keyless.search(selected_query, max_results)
        except ProviderSearchError as exc:
            attempts.extend(exc.provider_attempts)
            raise ProviderSearchError(
                "all local web discovery providers failed",
                provider_attempts=attempts,
            ) from exc
        return WebSearchResult(
            sources=keyless.sources,
            provider_attempts=tuple(attempts) + keyless.provider_attempts,
        )


def _json_source(response: FetchResponse, source_type: str) -> RetrievedSource:
    parsed = json.loads(response.body.decode("utf-8"))
    canonical = json.dumps(parsed, ensure_ascii=False, sort_keys=True).encode("utf-8")

    def bounded(value: Any, *, depth: int = 0) -> Any:
        if depth >= 3:
            return None
        if value is None or isinstance(value, (bool, int, float)):
            return value
        if isinstance(value, str):
            return value[:2000]
        if isinstance(value, Mapping):
            priority = (
                "full_name",
                "default_branch",
                "html_url",
                "tag_name",
                "published_at",
                "sha",
                "name",
                "version",
                "info",
                "message",
                "current",
                "current_units",
                "timezone",
                "latitude",
                "longitude",
                "DOI",
                "title",
                "published",
                "author",
                "url",
            )
            keys = [key for key in priority if key in value]
            keys.extend(key for key in value if key not in keys)
            return {
                str(key)[:200]: projected
                for key in keys[:32]
                if (item := value[key]) is not None
                if (projected := bounded(item, depth=depth + 1)) is not None
            }
        if isinstance(value, list):
            return [
                projected
                for item in value[:8]
                if (projected := bounded(item, depth=depth + 1)) is not None
            ]
        return str(value)[:500]

    structured = bounded(parsed)
    return RetrievedSource(
        url=response.url,
        raw=canonical,
        media_type="application/json",
        source_type=source_type,
        structured_fields=(
            structured if isinstance(structured, Mapping) else {"value": structured}
        ),
    )


class PublicConnectorProvider:
    """Typed public lookups that are actually configured in this local runtime."""

    provider_name = "public-structured-connectors"
    supported_operations = (
        "github_repository",
        "github_release",
        "github_commit",
        "package_release",
        "scholarly_record",
        "weather",
    )

    def __init__(self, fetcher: PublicHttpFetcher | None = None) -> None:
        self.fetcher = fetcher or PublicHttpFetcher()

    @staticmethod
    def _github_repository(query: str) -> str:
        text = str(query or "").strip()
        match = re.search(r"(?:github\.com/)?([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+)", text)
        if not match:
            raise ValueError("GitHub lookup requires owner/repository")
        return f"{match.group(1)}/{match.group(2).removesuffix('.git')}"

    @staticmethod
    def _package(query: str) -> str:
        text = " ".join(str(query or "").split()).strip()
        parsed = urlparse(text)
        if parsed.netloc.casefold().endswith("pypi.org"):
            parts = [part for part in parsed.path.split("/") if part]
            if len(parts) >= 2:
                return parts[1]
        match = re.search(r"(?:PyPI\s+)?([A-Za-z0-9_.-]+)$", text, re.IGNORECASE)
        if not match:
            raise ValueError("package lookup requires one exact package identifier")
        return match.group(1)

    def lookup(self, operation: str, query: str) -> Sequence[RetrievedSource]:
        selected = str(operation or "").strip()
        if selected in {"github_repository", "github_release", "github_commit"}:
            repository = self._github_repository(query)
            suffix = ""
            if selected == "github_release":
                suffix = "/releases/latest"
            elif selected == "github_commit":
                suffix = "/commits/HEAD"
            response = self.fetcher.fetch(
                f"https://api.github.com/repos/{repository}{suffix}",
                headers={"Accept": "application/vnd.github+json"},
            )
            return (_json_source(response, selected),)
        if selected == "github_code":
            raise ValueError("github_code requires an authenticated connector not configured")
        if selected == "package_release":
            package = self._package(query)
            response = self.fetcher.fetch(
                f"https://pypi.org/pypi/{quote(package, safe='')}/json"
            )
            return (_json_source(response, "pypi_release"),)
        if selected == "scholarly_record":
            response = self.fetcher.fetch(
                "https://api.crossref.org/works?"
                + urlencode({"query.bibliographic": str(query), "rows": 5})
            )
            return (_json_source(response, "crossref_works"),)
        if selected in {"weather", "weather_alerts"}:
            geocode = self.fetcher.fetch(
                "https://geocoding-api.open-meteo.com/v1/search?"
                + urlencode({"name": str(query), "count": 1, "language": "en"})
            )
            geocode_value = json.loads(geocode.body.decode("utf-8"))
            rows = geocode_value.get("results") if isinstance(geocode_value, Mapping) else []
            row = rows[0] if isinstance(rows, list) and rows else None
            if not isinstance(row, Mapping):
                return ()
            if selected == "weather_alerts":
                raise ValueError("weather_alerts provider is not configured for this region")
            response = self.fetcher.fetch(
                "https://api.open-meteo.com/v1/forecast?"
                + urlencode(
                    {
                        "latitude": row["latitude"],
                        "longitude": row["longitude"],
                        "current": "temperature_2m,precipitation,weather_code,wind_speed_10m",
                        "timezone": "auto",
                    }
                )
            )
            return (_json_source(response, "weather_observation"),)
        raise ValueError(f"unsupported connector operation: {selected}")


__all__ = [
    "ConnectorProvider",
    "KeylessWebProvider",
    "LocalWebProvider",
    "ProviderSearchError",
    "PublicConnectorProvider",
    "RetrievedSource",
    "TavilyWebProvider",
    "WebProvider",
    "WebSearchResult",
]

rwkv_lh/retrieval/policy.py:
"""Fail-closed network and egress policy contracts.

The policy accepts or rejects one already model-authored call.  It never
selects another tool, rewrites a query or removes sensitive values.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any, Mapping


class NetworkPolicyMode(str, Enum):
    OFFLINE = "offline"
    AUTO_PUBLIC = "auto_public"
    EXPLICIT_EGRESS = "explicit_egress"


class EgressProvenance(str, Enum):
    USER_PUBLIC_LITERAL = "user_public_literal"
    MODEL_PUBLIC_QUERY = "model_public_query"
    WORKSPACE_PUBLIC = "workspace_public"
    WORKSPACE_SENSITIVE = "workspace_sensitive"
    SECRET = "secret"
    TOOL_UNTRUSTED = "tool_untrusted"
    UNKNOWN = "unknown"


@dataclass(frozen=True)
class NetworkPolicyDecision:
    allowed: bool
    reason: str
    tool: str
    mode: NetworkPolicyMode
    rejected_fields: tuple[str, ...] = ()
    controller_rewritten: bool = False

    def to_dict(self) -> dict[str, Any]:
        return {
            "allowed": self.allowed,
            "reason": self.reason,
            "tool": self.tool,
            "mode": self.mode.value,
            "rejected_fields": list(self.rejected_fields),
            "controller_rewritten": self.controller_rewritten,
        }


@dataclass(frozen=True)
class NetworkPolicy:
    mode: NetworkPolicyMode = NetworkPolicyMode.OFFLINE
    explicit_approval: bool = False

    def __post_init__(self) -> None:
        if not isinstance(self.mode, NetworkPolicyMode):
            object.__setattr__(self, "mode", NetworkPolicyMode(str(self.mode)))

    def authorize(
        self,
        *,
        tool: str,
        arguments: Mapping[str, Any],
        provenance: Mapping[str, EgressProvenance | str],
    ) -> NetworkPolicyDecision:
        operation = str(tool or "").strip()
        if self.mode == NetworkPolicyMode.OFFLINE:
            return NetworkPolicyDecision(
                False,
                "network_disabled",
                operation,
                self.mode,
            )

        outbound_fields = tuple(
            key
            for key, value in arguments.items()
            if isinstance(value, str) and value.strip()
        )
        missing = tuple(key for key in outbound_fields if key not in provenance)
        if missing:
            return NetworkPolicyDecision(
                False,
                "egress_provenance_missing",
                operation,
                self.mode,
                missing,
            )

        normalized: dict[str, EgressProvenance] = {}
        invalid: list[str] = []
        for key in outbound_fields:
            try:
                raw_label = provenance[key]
                normalized[key] = (
                    raw_label
                    if isinstance(raw_label, EgressProvenance)
                    else EgressProvenance(str(raw_label))
                )
            except (TypeError, ValueError):
                invalid.append(key)
        if invalid:
            return NetworkPolicyDecision(
                False,
                "egress_provenance_invalid",
                operation,
                self.mode,
                tuple(invalid),
            )

        forbidden = tuple(
            key
            for key, label in normalized.items()
            if label
            in {
                EgressProvenance.WORKSPACE_SENSITIVE,
                EgressProvenance.SECRET,
                EgressProvenance.TOOL_UNTRUSTED,
                EgressProvenance.UNKNOWN,
            }
        )
        if forbidden:
            return NetworkPolicyDecision(
                False,
                "sensitive_egress_forbidden",
                operation,
                self.mode,
                forbidden,
            )

        if self.mode == NetworkPolicyMode.AUTO_PUBLIC:
            non_public = tuple(
                key
                for key, label in normalized.items()
                if label
                not in {
                    EgressProvenance.USER_PUBLIC_LITERAL,
                    EgressProvenance.MODEL_PUBLIC_QUERY,
                }
            )
            if non_public:
                return NetworkPolicyDecision(
                    False,
                    "auto_public_rejects_workspace_egress",
                    operation,
                    self.mode,
                    non_public,
                )

        if (
            self.mode == NetworkPolicyMode.EXPLICIT_EGRESS
            and any(
                label == EgressProvenance.WORKSPACE_PUBLIC
                for label in normalized.values()
            )
            and not self.explicit_approval
        ):
            return NetworkPolicyDecision(
                False,
                "explicit_egress_approval_required",
                operation,
                self.mode,
                tuple(
                    key
                    for key, label in normalized.items()
                    if label == EgressProvenance.WORKSPACE_PUBLIC
                ),
            )

        return NetworkPolicyDecision(
            True,
            "allowed",
            operation,
            self.mode,
        )


__all__ = [
    "EgressProvenance",
    "NetworkPolicy",
    "NetworkPolicyDecision",
    "NetworkPolicyMode",
]

rwkv_lh/retrieval/chunk.py:
"""Exact-offset deterministic chunks for immutable clean snapshots."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class TextChunk:
    index: int
    start_char: int
    end_char: int
    text: str


def chunk_text(
    text: str,
    *,
    max_chars: int = 6000,
    overlap_chars: int = 400,
    max_chunks: int = 32,
) -> tuple[TextChunk, ...]:
    """Split text at exact source offsets while keeping bounds hard."""

    source = str(text or "")
    if not source:
        return ()
    if max_chars < 256 or overlap_chars < 0 or overlap_chars >= max_chars:
        raise ValueError("invalid chunk bounds")
    chunks: list[TextChunk] = []
    start = 0
    while start < len(source) and len(chunks) < max_chunks:
        hard_end = min(len(source), start + max_chars)
        end = hard_end
        if hard_end < len(source):
            floor = start + max_chars // 2
            boundaries = [
                source.rfind("\n\n", floor, hard_end),
                source.rfind("\n", floor, hard_end),
                source.rfind("。", floor, hard_end),
                source.rfind(". ", floor, hard_end),
                source.rfind(" ", floor, hard_end),
            ]
            selected = max(boundaries)
            if selected >= floor:
                end = selected + (2 if source[selected:selected + 2] in {"\n\n", ". "} else 1)
        if end <= start:
            end = hard_end
        chunks.append(TextChunk(len(chunks), start, end, source[start:end]))
        if end >= len(source):
            break
        start = max(start + 1, end - overlap_chars)
    return tuple(chunks)


__all__ = ["TextChunk", "chunk_text"]

rwkv_lh/retrieval/contracts.py:
"""Versioned, content-addressed contracts for external evidence.

Titles, URLs and provider labels route evidence; only exact spans or literal
structured fields are factual material.  These value objects intentionally do
not own task completion, planning or persistence semantics.
"""

from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass, field
from typing import Any, Mapping, Sequence

from rwkv_lh.model_io import canonical_digest


EXTERNAL_EVIDENCE_SCHEMA_VERSION = "rwkv-lh.external-evidence.v1"
EVIDENCE_RECORD_SCHEMA_VERSION = "rwkv-lh.evidence-record.v1"
EVIDENCE_SPAN_SCHEMA_VERSION = "rwkv-lh.evidence-span.v1"
SOURCE_OBJECT_SCHEMA_VERSION = "rwkv-lh.source-object.v1"

_SHA256_RE = re.compile(r"^[0-9a-f]{64}$")


class ExternalEvidenceRequestMismatch(ValueError):
    """An internally valid envelope belongs to a different tool request."""


def _text(name: str, value: Any, *, max_chars: int) -> str:
    result = str(value or "").strip()
    if not result:
        raise ValueError(f"{name} must be non-empty")
    if len(result) > max_chars:
        raise ValueError(f"{name} exceeds {max_chars} characters")
    return result


def _literal_text(name: str, value: Any, *, max_chars: int) -> str:
    """Validate exact evidence text without normalizing its bytes."""

    result = "" if value is None else str(value)
    if not result.strip():
        raise ValueError(f"{name} must be non-empty")
    if len(result) > max_chars:
        raise ValueError(f"{name} exceeds {max_chars} characters")
    return result


def _mapping_items(name: str, value: Any) -> tuple[Mapping[str, Any], ...]:
    if value is None:
        return ()
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes, bytearray)):
        raise ValueError(f"{name} must be an array of objects")
    if any(not isinstance(item, Mapping) for item in value):
        raise ValueError(f"{name} must contain only objects")
    return tuple(value)


def _sha256(name: str, value: Any) -> str:
    result = str(value or "").strip().casefold()
    if not _SHA256_RE.fullmatch(result):
        raise ValueError(f"{name} must be a lowercase SHA-256 digest")
    return result


def external_evidence_request_digest(
    tool: str,
    arguments: Mapping[str, Any],
) -> str:
    operation = _text("evidence tool", tool, max_chars=128)
    return canonical_digest({"tool": operation, "arguments": dict(arguments)})


def validate_external_evidence_request(
    envelope: "ExternalEvidenceEnvelope",
    *,
    tool: str,
    arguments: Mapping[str, Any],
) -> "ExternalEvidenceEnvelope":
    """Bind one envelope to the exact currently selected tool invocation."""

    operation = _text("evidence tool", tool, max_chars=128)
    expected_digest = external_evidence_request_digest(operation, arguments)
    if envelope.tool != operation:
        raise ExternalEvidenceRequestMismatch(
            "external evidence tool does not match the selected operation"
        )
    if envelope.request_digest != expected_digest:
        raise ExternalEvidenceRequestMismatch(
            "external evidence request digest does not match current arguments"
        )
    return envelope


@dataclass(frozen=True)
class SourceObject:
    source_object_id: str
    source_object_type: str
    source_record_id: str = ""
    schema_version: str = SOURCE_OBJECT_SCHEMA_VERSION

    @classmethod
    def create(
        cls,
        *,
        source_object_id: str,
        source_object_type: str,
        source_record_id: str = "",
    ) -> "SourceObject":
        return cls(
            source_object_id=_text(
                "source_object_id", source_object_id, max_chars=4096
            ),
            source_object_type=_text(
                "source_object_type", source_object_type, max_chars=128
            ),
            source_record_id=str(source_record_id or "").strip()[:1024],
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": self.schema_version,
            "source_object_id": self.source_object_id,
            "source_object_type": self.source_object_type,
            "source_record_id": self.source_record_id,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "SourceObject":
        if str(value.get("schema_version") or SOURCE_OBJECT_SCHEMA_VERSION) != (
            SOURCE_OBJECT_SCHEMA_VERSION
        ):
            raise ValueError("unsupported source object schema")
        return cls.create(
            source_object_id=str(value.get("source_object_id") or ""),
            source_object_type=str(value.get("source_object_type") or ""),
            source_record_id=str(value.get("source_record_id") or ""),
        )


@dataclass(frozen=True)
class EvidenceSpan:
    span_id: str
    text: str
    locator: Mapping[str, Any] = field(default_factory=dict)
    schema_version: str = EVIDENCE_SPAN_SCHEMA_VERSION

    @classmethod
    def create(
        cls,
        *,
        text: str,
        locator: Mapping[str, Any] | None = None,
    ) -> "EvidenceSpan":
        literal = _literal_text("evidence span text", text, max_chars=16_000)
        locator_value = dict(locator or {})
        content_digest = str(locator_value.get("content_sha256") or "")
        if content_digest and content_digest != hashlib.sha256(
            literal.encode("utf-8")
        ).hexdigest():
            raise ValueError("evidence span content_sha256 does not match its text")
        if "start_char" in locator_value and "end_char" in locator_value:
            start_char = locator_value["start_char"]
            end_char = locator_value["end_char"]
            if (
                isinstance(start_char, bool)
                or isinstance(end_char, bool)
                or not isinstance(start_char, int)
                or not isinstance(end_char, int)
                or start_char < 0
                or end_char - start_char != len(literal)
            ):
                raise ValueError("evidence span character range does not match its text")
        if "start_byte" in locator_value and "end_byte" in locator_value:
            start_byte = locator_value["start_byte"]
            end_byte = locator_value["end_byte"]
            if (
                isinstance(start_byte, bool)
                or isinstance(end_byte, bool)
                or not isinstance(start_byte, int)
                or not isinstance(end_byte, int)
                or start_byte < 0
                or end_byte - start_byte != len(literal.encode("utf-8"))
            ):
                raise ValueError("evidence span byte range does not match its text")
        identity = {"text": literal, "locator": locator_value}
        return cls(
            span_id=f"SPAN-{canonical_digest(identity)[:20]}",
            text=literal,
            locator=locator_value,
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": self.schema_version,
            "span_id": self.span_id,
            "text": self.text,
            "locator": dict(self.locator),
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "EvidenceSpan":
        if str(value.get("schema_version") or EVIDENCE_SPAN_SCHEMA_VERSION) != (
            EVIDENCE_SPAN_SCHEMA_VERSION
        ):
            raise ValueError("unsupported evidence span schema")
        locator_value = value.get("locator", {})
        if not isinstance(locator_value, Mapping):
            raise ValueError("evidence span locator must be an object")
        span = cls.create(
            text=value.get("text"),
            locator=locator_value,
        )
        supplied = str(value.get("span_id") or "")
        if supplied and supplied != span.span_id:
            raise ValueError("evidence span id does not match its content")
        return span


@dataclass(frozen=True)
class EvidenceRecord:
    evidence_record_id: str
    source_object: SourceObject
    snapshot_digest: str
    exact_spans: tuple[EvidenceSpan, ...]
    url: str = ""
    title: str = ""
    published: str = ""
    retrieved_at: str = ""
    structured_fields: Mapping[str, Any] = field(default_factory=dict)
    schema_version: str = EVIDENCE_RECORD_SCHEMA_VERSION

    @classmethod
    def create(
        cls,
        *,
        source_object: SourceObject,
        snapshot_digest: str,
        exact_spans: Sequence[EvidenceSpan],
        url: str = "",
        title: str = "",
        published: str = "",
        retrieved_at: str = "",
        structured_fields: Mapping[str, Any] | None = None,
    ) -> "EvidenceRecord":
        spans = tuple(exact_spans)
        structured = dict(structured_fields or {})
        if not spans and not structured:
            raise ValueError(
                "evidence record requires exact spans or literal structured fields"
            )
        digest = _sha256("snapshot_digest", snapshot_digest)
        for span in spans:
            locator_digest = str(span.locator.get("snapshot_digest") or "")
            if locator_digest and locator_digest != digest:
                raise ValueError(
                    "evidence span locator belongs to another snapshot"
                )
        url_value = str(url or "").strip()[:4096]
        title_value = str(title or "").strip()[:1000]
        published_value = str(published or "").strip()[:128]
        retrieved_value = str(retrieved_at or "").strip()[:128]
        payload = {
            "source_object": source_object.to_dict(),
            "snapshot_digest": digest,
            "exact_spans": [item.to_dict() for item in spans],
            "structured_fields": structured,
            "url": url_value,
            "title": title_value,
            "published": published_value,
            "retrieved_at": retrieved_value,
        }
        return cls(
            evidence_record_id=f"E-{canonical_digest(payload)[:20]}",
            source_object=source_object,
            snapshot_digest=digest,
            exact_spans=spans,
            url=url_value,
            title=title_value,
            published=published_value,
            retrieved_at=retrieved_value,
            structured_fields=structured,
        )

    def verify_snapshot(self, snapshot_text: str) -> bool:
        snapshot = str(snapshot_text)
        if (
            hashlib.sha256(snapshot.encode("utf-8")).hexdigest()
            != self.snapshot_digest
        ):
            return False
        snapshot_bytes = snapshot.encode("utf-8")
        for span in self.exact_spans:
            locator = span.locator
            if "start_byte" in locator and "end_byte" in locator:
                try:
                    observed = snapshot_bytes[
                        int(locator["start_byte"]) : int(locator["end_byte"])
                    ].decode("utf-8")
                except (TypeError, ValueError, UnicodeDecodeError):
                    return False
                if observed != span.text:
                    return False
                continue
            if "start_char" in locator and "end_char" in locator:
                try:
                    observed = snapshot[
                        int(locator["start_char"]) : int(locator["end_char"])
                    ]
                except (TypeError, ValueError):
                    return False
                if observed != span.text:
                    return False
                continue
            if span.text not in snapshot:
                return False
        return True

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": self.schema_version,
            "evidence_record_id": self.evidence_record_id,
            "source_object": self.source_object.to_dict(),
            "snapshot_digest": self.snapshot_digest,
            "exact_spans": [item.to_dict() for item in self.exact_spans],
            "url": self.url,
            "title": self.title,
            "published": self.published,
            "retrieved_at": self.retrieved_at,
            "structured_fields": dict(self.structured_fields),
            "fact_authority": "exact_spans_or_structured_fields_only",
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "EvidenceRecord":
        if str(value.get("schema_version") or EVIDENCE_RECORD_SCHEMA_VERSION) != (
            EVIDENCE_RECORD_SCHEMA_VERSION
        ):
            raise ValueError("unsupported evidence record schema")
        source_value = value.get("source_object")
        if not isinstance(source_value, Mapping):
            raise ValueError("evidence record requires a source_object")
        span_values = _mapping_items("exact_spans", value.get("exact_spans"))
        structured_fields = value.get("structured_fields", {})
        if not isinstance(structured_fields, Mapping):
            raise ValueError("structured_fields must be an object")
        record = cls.create(
            source_object=SourceObject.from_dict(source_value),
            snapshot_digest=str(value.get("snapshot_digest") or ""),
            exact_spans=tuple(
                EvidenceSpan.from_dict(item)
                for item in span_values
            ),
            url=str(value.get("url") or ""),
            title=str(value.get("title") or ""),
            published=str(value.get("published") or ""),
            retrieved_at=str(value.get("retrieved_at") or ""),
            structured_fields=structured_fields,
        )
        supplied = str(value.get("evidence_record_id") or "")
        if supplied and supplied != record.evidence_record_id:
            raise ValueError("evidence record id does not match its content")
        return record


@dataclass(frozen=True)
class ExternalEvidenceEnvelope:
    route_id: str
    tool: str
    request_digest: str
    status: str
    records: tuple[EvidenceRecord, ...]
    as_of: str
    provider_attempts: tuple[Mapping[str, Any], ...] = ()
    truncated: bool = False
    action_id: str = ""
    schema_version: str = EXTERNAL_EVIDENCE_SCHEMA_VERSION

    @classmethod
    def create(
        cls,
        *,
        tool: str,
        request: Mapping[str, Any],
        status: str,
        records: Sequence[EvidenceRecord],
        as_of: str,
        provider_attempts: Sequence[Mapping[str, Any]] = (),
        truncated: bool = False,
        action_id: str = "",
    ) -> "ExternalEvidenceEnvelope":
        operation = _text("evidence tool", tool, max_chars=128)
        request_value = dict(request)
        request_digest = external_evidence_request_digest(operation, request_value)
        status_value = str(status or "").strip()
        if status_value not in {
            "evidence_committed",
            "no_evidence",
            "provider_unavailable",
        }:
            raise ValueError(f"unsupported external evidence status: {status_value}")
        record_values = tuple(records)
        if status_value == "evidence_committed" and not record_values:
            raise ValueError("evidence_committed requires at least one record")
        if status_value != "evidence_committed" and record_values:
            raise ValueError(f"{status_value} must not contain evidence records")
        route_payload = {
            "tool": operation,
            "request_digest": request_digest,
            "as_of": str(as_of or "").strip(),
        }
        return cls(
            route_id=f"ROUTE-{canonical_digest(route_payload)[:20]}",
            tool=operation,
            request_digest=request_digest,
            status=status_value,
            records=record_values,
            as_of=_text("as_of", as_of, max_chars=128),
            provider_attempts=tuple(dict(item) for item in provider_attempts),
            truncated=bool(truncated),
            action_id=str(action_id or "").strip(),
        )

    def bind_action(self, action_id: str) -> "ExternalEvidenceEnvelope":
        identifier = _text("action_id", action_id, max_chars=128)
        if self.action_id and self.action_id != identifier:
            raise ValueError("external evidence is already bound to another action")
        return ExternalEvidenceEnvelope(
            route_id=self.route_id,
            tool=self.tool,
            request_digest=self.request_digest,
            status=self.status,
            records=self.records,
            as_of=self.as_of,
            provider_attempts=self.provider_attempts,
            truncated=self.truncated,
            action_id=identifier,
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": self.schema_version,
            "action_id": self.action_id,
            "route_id": self.route_id,
            "tool": self.tool,
            "request_digest": self.request_digest,
            "as_of": self.as_of,
            "status": self.status,
            "records": [item.to_dict() for item in self.records],
            "provider_attempts": [dict(item) for item in self.provider_attempts],
            "truncated": self.truncated,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> "ExternalEvidenceEnvelope":
        if str(value.get("schema_version") or "") != EXTERNAL_EVIDENCE_SCHEMA_VERSION:
            raise ValueError("unsupported external evidence schema")
        record_values = _mapping_items("records", value.get("records"))
        attempt_values = _mapping_items(
            "provider_attempts", value.get("provider_attempts")
        )
        envelope = cls(
            route_id=_text("route_id", value.get("route_id"), max_chars=128),
            tool=_text("tool", value.get("tool"), max_chars=128),
            request_digest=_sha256(
                "request_digest", value.get("request_digest")
            ),
            status=str(value.get("status") or ""),
            records=tuple(
                EvidenceRecord.from_dict(item)
                for item in record_values
            ),
            as_of=_text("as_of", value.get("as_of"), max_chars=128),
            provider_attempts=tuple(
                dict(item)
                for item in attempt_values
            ),
            truncated=bool(value.get("truncated", False)),
            action_id=str(value.get("action_id") or "").strip(),
        )
        if envelope.status not in {
            "evidence_committed",
            "no_evidence",
            "provider_unavailable",
        }:
            raise ValueError("external evidence status is invalid")
        if envelope.status == "evidence_committed" and not envelope.records:
            raise ValueError("evidence_committed requires records")
        if envelope.status != "evidence_committed" and envelope.records:
            raise ValueError(
                f"{envelope.status} must not contain evidence records"
            )
        expected_route_id = (
            "ROUTE-"
            + canonical_digest(
                {
                    "tool": envelope.tool,
                    "request_digest": envelope.request_digest,
                    "as_of": envelope.as_of,
                }
            )[:20]
        )
        if envelope.route_id != expected_route_id:
            raise ValueError("route id does not match its content")
        if len(envelope.action_id) > 128:
            raise ValueError("action_id exceeds 128 characters")
        return envelope


__all__ = [
    "EVIDENCE_RECORD_SCHEMA_VERSION",
    "EVIDENCE_SPAN_SCHEMA_VERSION",
    "EXTERNAL_EVIDENCE_SCHEMA_VERSION",
    "SOURCE_OBJECT_SCHEMA_VERSION",
    "EvidenceRecord",
    "EvidenceSpan",
    "ExternalEvidenceEnvelope",
    "ExternalEvidenceRequestMismatch",
    "SourceObject",
    "external_evidence_request_digest",
    "validate_external_evidence_request",
]

rwkv_lh/retrieval/clean.py:
"""Deterministic bounded cleanup for untrusted retrieved documents."""

from __future__ import annotations

import json
import re
from html import unescape
from html.parser import HTMLParser
from typing import Any


_BLOCK = {
    "article", "aside", "blockquote", "br", "dd", "div", "dl", "dt",
    "figcaption", "figure", "h1", "h2", "h3", "h4", "h5", "h6",
    "header", "hr", "li", "main", "p", "pre", "section", "table",
    "td", "th", "tr", "ul", "ol",
}
_SKIP = {"script", "style", "noscript", "svg", "template", "form"}


class _ReadableHTML(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.parts: list[str] = []
        self.skip_depth = 0
        self.title_parts: list[str] = []
        self.in_title = False

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        selected = tag.casefold()
        if self.skip_depth:
            if selected not in {"meta", "link", "img", "br", "hr", "input"}:
                self.skip_depth += 1
            return
        if selected in _SKIP:
            self.skip_depth = 1
            return
        if selected == "title":
            self.in_title = True
        if selected in _BLOCK:
            self.parts.append("\n")

    def handle_endtag(self, tag: str) -> None:
        selected = tag.casefold()
        if self.skip_depth:
            self.skip_depth -= 1
            return
        if selected == "title":
            self.in_title = False
        if selected in _BLOCK:
            self.parts.append("\n")

    def handle_data(self, data: str) -> None:
        if self.skip_depth:
            return
        value = unescape(str(data or ""))
        if self.in_title:
            self.title_parts.append(value)
            return
        self.parts.append(value)

    def result(self) -> tuple[str, str]:
        text = "".join(self.parts).replace("\r\n", "\n").replace("\r", "\n")
        lines = [re.sub(r"[ \t]+", " ", line).strip() for line in text.splitlines()]
        compact: list[str] = []
        for line in lines:
            if line:
                compact.append(line)
            elif compact and compact[-1] != "":
                compact.append("")
        cleaned = "\n".join(compact).strip()
        title = re.sub(r"\s+", " ", "".join(self.title_parts)).strip()
        return cleaned, title


def clean_document(payload: bytes, media_type: str) -> tuple[str, str]:
    """Return clean UTF-8 text and a best-effort title without authoring facts."""

    if len(payload) > 8_000_000:
        raise ValueError("retrieved payload exceeds the cleanup bound")
    text = payload.decode("utf-8", errors="replace")
    selected_type = str(media_type or "").split(";", 1)[0].strip().casefold()
    if selected_type in {"application/json", "application/ld+json"}:
        try:
            parsed: Any = json.loads(text)
        except json.JSONDecodeError:
            return text.strip(), ""
        return json.dumps(parsed, ensure_ascii=False, sort_keys=True, indent=2), ""
    if selected_type in {"text/html", "application/xhtml+xml"} or "<html" in text[:1000].casefold():
        parser = _ReadableHTML()
        parser.feed(text)
        parser.close()
        return parser.result()
    return text.replace("\r\n", "\n").replace("\r", "\n").strip(), ""


__all__ = ["clean_document"]

rwkv_lh/retrieval/actions.py:
"""Optional retrieval and deterministic tool extensions for ActionHarness.

The extensions are not installed into the default Harness implicitly.  A
caller must provide a backend, a network policy and an explicit provenance
resolver, then pass the returned mapping to ``ActionHarness(actions=...)``.
"""

from __future__ import annotations

import ast
import math
import operator
from dataclasses import dataclass
from datetime import date, datetime, timezone
from typing import Any, Callable, Mapping, Protocol, Sequence
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from rwkv_lh.harness import ActionDefinition, ActionResult
from rwkv_lh.model_io import canonical_digest, canonical_json
from rwkv_lh.retrieval.contracts import (
    ExternalEvidenceEnvelope,
    ExternalEvidenceRequestMismatch,
    external_evidence_request_digest,
    validate_external_evidence_request,
)
from rwkv_lh.retrieval.policy import (
    EgressProvenance,
    NetworkPolicy,
)
from rwkv_lh.schema import GoalState


class RetrievalBackend(Protocol):
    """Execute one already-selected retrieval operation."""

    provider_name: str

    def execute(
        self,
        tool: str,
        arguments: Mapping[str, Any],
    ) -> ExternalEvidenceEnvelope: ...

    def recover(
        self,
        tool: str,
        arguments: Mapping[str, Any],
    ) -> ExternalEvidenceEnvelope | None: ...


ProvenanceResolver = Callable[
    [GoalState, str, Mapping[str, Any]],
    Mapping[str, EgressProvenance | str],
]
NetworkPolicyResolver = Callable[[GoalState], NetworkPolicy]


@dataclass
class FrozenRetrievalBackend:
    """A deterministic, network-free backend used before live integration."""

    responses: Mapping[str, ExternalEvidenceEnvelope]
    provider_name: str = "frozen-fixture"

    @staticmethod
    def request_key(tool: str, arguments: Mapping[str, Any]) -> str:
        return external_evidence_request_digest(tool, arguments)

    def execute(
        self,
        tool: str,
        arguments: Mapping[str, Any],
    ) -> ExternalEvidenceEnvelope:
        key = self.request_key(tool, arguments)
        envelope = self.responses.get(key)
        if envelope is None:
            raise KeyError(f"frozen retrieval fixture has no request {key}")
        return validate_external_evidence_request(
            envelope,
            tool=tool,
            arguments=arguments,
        )

    def recover(
        self,
        tool: str,
        arguments: Mapping[str, Any],
    ) -> ExternalEvidenceEnvelope | None:
        key = self.request_key(tool, arguments)
        envelope = self.responses.get(key)
        if envelope is None:
            return None
        return validate_external_evidence_request(
            envelope,
            tool=tool,
            arguments=arguments,
        )


_BINARY_OPERATORS: dict[type[ast.operator], Callable[[Any, Any], Any]] = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_UNARY_OPERATORS: dict[type[ast.unaryop], Callable[[Any], Any]] = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


def _safe_number(value: Any) -> int | float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("calculator accepts only real numeric literals")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("calculator result must be finite")
    if abs(value) > 10**100:
        raise ValueError("calculator magnitude exceeds the fixed bound")
    return value


def _evaluate_expression(expression: str) -> int | float:
    text = str(expression or "").strip()
    if not text or len(text) > 256:
        raise ValueError("calculator expression must contain 1-256 characters")
    parsed = ast.parse(text, mode="eval")

    def evaluate(node: ast.AST, *, depth: int = 0) -> int | float:
        if depth > 32:
            raise ValueError("calculator expression is too deeply nested")
        if isinstance(node, ast.Expression):
            return evaluate(node.body, depth=depth + 1)
        if isinstance(node, ast.Constant):
            return _safe_number(node.value)
        if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY_OPERATORS:
            return _safe_number(
                _UNARY_OPERATORS[type(node.op)](
                    evaluate(node.operand, depth=depth + 1)
                )
            )
        if isinstance(node, ast.BinOp) and type(node.op) in _BINARY_OPERATORS:
            left = evaluate(node.left, depth=depth + 1)
            right = evaluate(node.right, depth=depth + 1)
            if isinstance(node.op, ast.Pow) and abs(right) > 1000:
                raise ValueError("calculator exponent exceeds the fixed bound")
            return _safe_number(_BINARY_OPERATORS[type(node.op)](left, right))
        raise ValueError("calculator expression contains an unsupported operation")

    return evaluate(parsed)


def _deterministic_output(tool: str, arguments: Mapping[str, Any], value: Any) -> str:
    return canonical_json(
        {
            "contract": "rwkv-lh.deterministic-result.v1",
            "tool": tool,
            "arguments_digest": canonical_digest(dict(arguments)),
            "value": value,
        }
    )


def build_retrieval_actions(
    *,
    backend: RetrievalBackend,
    network_policy: NetworkPolicy,
    provenance_resolver: ProvenanceResolver,
    network_policy_resolver: NetworkPolicyResolver | None = None,
    connector_operations: Sequence[str] | None = None,
    include_network_actions: bool = False,
    clock: Callable[[], datetime] | None = None,
) -> dict[
    str,
    tuple[
        ActionDefinition,
        Callable[[GoalState, dict[str, Any]], ActionResult],
    ]
    | tuple[
        ActionDefinition,
        Callable[[GoalState, dict[str, Any]], ActionResult],
        Callable[[GoalState, dict[str, Any]], ActionResult | None],
    ],
]:
    """Build deterministic tools and policy-gated network tools when exposed.

    ``include_network_actions`` keeps the two network definitions visible for a
    fixed full-menu Selector even when the registration policy is offline.  A
    product runtime supplies ``network_policy_resolver`` so authorization is
    derived from the immutable Goal; the registration policy then controls only
    which definitions exist and cannot become a second per-run authority.
    """

    if not callable(provenance_resolver):
        raise TypeError("retrieval actions require an explicit provenance resolver")
    if network_policy_resolver is not None and not callable(network_policy_resolver):
        raise TypeError("network policy resolver must be callable")
    now = clock or (lambda: datetime.now(timezone.utc))
    configured_connector_operations = tuple(
        dict.fromkeys(
            str(item).strip()
            for item in (
                connector_operations
                if connector_operations is not None
                else (
                    "github_repository",
                    "github_release",
                    "github_commit",
                    "github_code",
                    "package_release",
                    "scholarly_record",
                    "weather",
                    "weather_alerts",
                )
            )
            if str(item).strip()
        )
    )

    def policy_for(goal: GoalState) -> NetworkPolicy:
        selected = (
            network_policy_resolver(goal)
            if network_policy_resolver is not None
            else network_policy
        )
        if not isinstance(selected, NetworkPolicy):
            raise TypeError("network policy resolver must return NetworkPolicy")
        return selected

    def request_binding_failure(
        tool: str,
        decision,
        error: ExternalEvidenceRequestMismatch,
        *,
        recovered: bool,
    ) -> ActionResult:
        metadata = {
            "network_policy": decision.to_dict(),
            "provider": str(backend.provider_name),
            "request_binding_valid": False,
        }
        if recovered:
            metadata["committed_snapshot_recovery_attempted"] = True
        return ActionResult(
            tool,
            False,
            metadata=metadata,
            error={
                "type": type(error).__name__,
                "message": str(error),
            },
        )

    def envelope_result(
        tool: str,
        arguments: Mapping[str, Any],
        envelope: ExternalEvidenceEnvelope,
        decision,
        *,
        recovered: bool = False,
    ) -> ActionResult:
        try:
            validate_external_evidence_request(
                envelope,
                tool=tool,
                arguments=arguments,
            )
        except ExternalEvidenceRequestMismatch as exc:
            return request_binding_failure(
                tool,
                decision,
                exc,
                recovered=recovered,
            )
        external = envelope.to_dict()
        metadata = {
            "external_evidence": external,
            "network_policy": decision.to_dict(),
            "provider": str(backend.provider_name),
        }
        if recovered:
            metadata["recovered_committed_snapshot"] = True
        if envelope.status == "provider_unavailable":
            return ActionResult(
                tool,
                False,
                output=canonical_json(external),
                metadata=metadata,
                error={
                    "type": "RetrievalProviderUnavailable",
                    "message": "all selected retrieval providers were unavailable",
                },
                outcome_type="provider_unavailable",
            )
        return ActionResult(
            tool,
            True,
            output=canonical_json(external),
            evidence=[item.to_dict() for item in envelope.records],
            metadata=metadata,
        )

    def network_handler(
        tool: str,
    ) -> Callable[[GoalState, dict[str, Any]], ActionResult]:
        def execute(goal: GoalState, arguments: dict[str, Any]) -> ActionResult:
            labels = provenance_resolver(goal, tool, arguments)
            decision = policy_for(goal).authorize(
                tool=tool,
                arguments=arguments,
                provenance=labels,
            )
            if not decision.allowed:
                return ActionResult(
                    tool,
                    False,
                    output=canonical_json(
                        {
                            "contract": "rwkv-lh.network-policy-result.v1",
                            "decision": decision.to_dict(),
                        }
                    ),
                    metadata={"network_policy": decision.to_dict()},
                    error={
                        "type": "NetworkPolicyRejected",
                        "message": decision.reason,
                        "rejected_fields": list(decision.rejected_fields),
                    },
                )
            try:
                envelope = backend.execute(tool, arguments)
            except ExternalEvidenceRequestMismatch as exc:
                return request_binding_failure(
                    tool,
                    decision,
                    exc,
                    recovered=False,
                )
            except Exception as exc:
                return ActionResult(
                    tool,
                    False,
                    metadata={
                        "network_policy": decision.to_dict(),
                        "provider": str(backend.provider_name),
                    },
                    error={
                        "type": type(exc).__name__,
                        "message": str(exc)[:2000],
                    },
                )
            return envelope_result(tool, arguments, envelope, decision)

        return execute

    def network_recovery_handler(
        tool: str,
    ) -> Callable[[GoalState, dict[str, Any]], ActionResult | None]:
        def recover(
            goal: GoalState,
            arguments: dict[str, Any],
        ) -> ActionResult | None:
            labels = provenance_resolver(goal, tool, arguments)
            decision = policy_for(goal).authorize(
                tool=tool,
                arguments=arguments,
                provenance=labels,
            )
            if not decision.allowed:
                return ActionResult(
                    tool,
                    False,
                    metadata={"network_policy": decision.to_dict()},
                    error={
                        "type": "NetworkPolicyRejected",
                        "message": decision.reason,
                        "rejected_fields": list(decision.rejected_fields),
                    },
                )
            recover_method = getattr(backend, "recover", None)
            if not callable(recover_method):
                return None
            try:
                envelope = recover_method(tool, arguments)
            except ExternalEvidenceRequestMismatch as exc:
                return request_binding_failure(
                    tool,
                    decision,
                    exc,
                    recovered=True,
                )
            if envelope is None:
                return None
            return envelope_result(
                tool,
                arguments,
                envelope,
                decision,
                recovered=True,
            )

        return recover

    def calculator_handler(
        _goal: GoalState,
        arguments: dict[str, Any],
    ) -> ActionResult:
        try:
            value = _evaluate_expression(str(arguments.get("expression") or ""))
        except Exception as exc:
            return ActionResult(
                "calculator",
                False,
                error={"type": type(exc).__name__, "message": str(exc)[:2000]},
            )
        return ActionResult(
            "calculator",
            True,
            output=_deterministic_output("calculator", arguments, value),
            metadata={"deterministic": True},
        )

    def date_diff_handler(
        _goal: GoalState,
        arguments: dict[str, Any],
    ) -> ActionResult:
        try:
            left = date.fromisoformat(str(arguments.get("date_a") or ""))
            right = date.fromisoformat(str(arguments.get("date_b") or ""))
            value = abs((right - left).days)
        except Exception as exc:
            return ActionResult(
                "date_diff",
                False,
                error={"type": type(exc).__name__, "message": str(exc)[:2000]},
            )
        return ActionResult(
            "date_diff",
            True,
            output=_deterministic_output("date_diff", arguments, value),
            metadata={"deterministic": True, "unit": "calendar_days"},
        )

    def current_time_handler(
        _goal: GoalState,
        arguments: dict[str, Any],
    ) -> ActionResult:
        timezone_name = str(arguments.get("timezone") or "UTC")
        try:
            zone = ZoneInfo(timezone_name)
            observed = now()
            if observed.tzinfo is None:
                raise ValueError("current_time clock must return an aware datetime")
            value = observed.astimezone(zone).isoformat(timespec="seconds")
        except (ValueError, ZoneInfoNotFoundError) as exc:
            return ActionResult(
                "current_time",
                False,
                error={"type": type(exc).__name__, "message": str(exc)[:2000]},
            )
        return ActionResult(
            "current_time",
            True,
            output=_deterministic_output("current_time", arguments, value),
            metadata={"deterministic": False, "observed_timezone": timezone_name},
        )

    web_search = ActionDefinition(
        "web_search",
        (
            "Search/fetch a public exact URL or the general web and return "
            "content-addressed exact evidence records."
        ),
        True,
        False,
        False,
        60.0,
        {
            "query": {"type": "string", "minLength": 1},
            "max_results": {
                "type": "integer",
                "minimum": 1,
                "maximum": 10,
                "default": 5,
            },
        },
        required_arguments=("query",),
        capability_class="network.public_web",
        network_access="public_web",
        data_boundary="public_external",
        side_effect_class="external_read_only",
        result_schema="rwkv-lh.external-evidence.v1",
        cache_policy="per_run_immutable_snapshot",
        recovery_policy="resume_committed_snapshot_or_do_not_replay_unknown",
        evidence_output=True,
    )
    connector_lookup = ActionDefinition(
        "connector_lookup",
        (
            "Query one structured public source for an exact repository, package, "
            "scholarly record, weather observation, or alert."
        ),
        True,
        False,
        False,
        60.0,
        {
            "operation": {
                "type": "string",
                "enum": list(configured_connector_operations),
            },
            "query": {"type": "string", "minLength": 1},
        },
        required_arguments=("operation", "query"),
        capability_class="network.structured_source",
        network_access="structured_source",
        data_boundary="public_external",
        side_effect_class="external_read_only",
        result_schema="rwkv-lh.external-evidence.v1",
        cache_policy="per_run_immutable_snapshot",
        recovery_policy="resume_committed_snapshot_or_do_not_replay_unknown",
        evidence_output=True,
    )
    calculator = ActionDefinition(
        "calculator",
        "Safely evaluate one complete arithmetic expression with known operands.",
        True,
        False,
        True,
        5.0,
        {"expression": {"type": "string", "minLength": 1}},
        required_arguments=("expression",),
        capability_class="deterministic.compute",
        data_boundary="model_literal",
        side_effect_class="read_only",
        result_schema="rwkv-lh.deterministic-result.v1",
        cache_policy="content_addressed",
    )
    date_diff = ActionDefinition(
        "date_diff",
        "Calculate the absolute calendar-day distance between two known ISO dates.",
        True,
        False,
        True,
        5.0,
        {
            "date_a": {"type": "string", "minLength": 10},
            "date_b": {"type": "string", "minLength": 10},
            "source_a": {"type": "string", "default": ""},
            "source_b": {"type": "string", "default": ""},
        },
        required_arguments=("date_a", "date_b"),
        capability_class="deterministic.compute",
        data_boundary="observed_fact",
        side_effect_class="read_only",
        result_schema="rwkv-lh.deterministic-result.v1",
        cache_policy="content_addressed",
    )
    current_time = ActionDefinition(
        "current_time",
        "Observe the current clock reading for one IANA timezone.",
        True,
        False,
        False,
        5.0,
        {"timezone": {"type": "string", "default": "UTC", "minLength": 1}},
        capability_class="deterministic.clock",
        data_boundary="local_clock",
        side_effect_class="read_only_time_sensitive",
        result_schema="rwkv-lh.deterministic-result.v1",
        cache_policy="never",
        recovery_policy="do_not_replay_unknown",
    )

    actions = {
        "calculator": (calculator, calculator_handler),
        "date_diff": (date_diff, date_diff_handler),
        "current_time": (current_time, current_time_handler),
    }
    if network_policy.mode.value != "offline" or include_network_actions:
        actions = {
            "web_search": (
                web_search,
                network_handler("web_search"),
                network_recovery_handler("web_search"),
            ),
            "connector_lookup": (
                connector_lookup,
                network_handler("connector_lookup"),
                network_recovery_handler("connector_lookup"),
            ),
            **actions,
        }
    return actions


__all__ = [
    "FrozenRetrievalBackend",
    "NetworkPolicyResolver",
    "ProvenanceResolver",
    "RetrievalBackend",
    "build_retrieval_actions",
]

rwkv_lh/retrieval/runtime.py:
"""Product wiring for immutable per-run retrieval policy and provenance."""

from __future__ import annotations

import os
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, Iterable, Mapping

from rwkv_lh.harness import ActionHarness
from rwkv_lh.retrieval.actions import build_retrieval_actions
from rwkv_lh.retrieval.gateway import build_live_retrieval_backend
from rwkv_lh.retrieval.policy import EgressProvenance, NetworkPolicy, NetworkPolicyMode
from rwkv_lh.schema import GoalState


RETRIEVAL_RUNTIME_SCHEMA_VERSION = "rwkv-lh.retrieval-runtime.v1"
_SKIP_PARTS = {".git", ".hg", ".svn", "__pycache__", "node_modules"}
_SECRET_PATTERN = re.compile(
    r"(?:-----BEGIN [A-Z ]*PRIVATE KEY-----|"
    r"\b(?:api[_-]?key|access[_-]?token|secret|password|passwd)\s*[:=]\s*\S+|"
    r"\bBearer\s+[A-Za-z0-9._~+/=-]{8,}|"
    r"\b(?:sk[-_]|ghp_|github_pat_)[A-Za-z0-9_-]{12,})",
    re.IGNORECASE,
)


def _relative_public_path(value: str) -> str:
    text = str(value or "").replace("\\", "/").strip().strip("/")
    path = Path(text)
    if not text or path.is_absolute() or ".." in path.parts or "\x00" in text:
        raise ValueError("public workspace paths must be workspace-relative")
    return path.as_posix()


@dataclass(frozen=True)
class RetrievalRuntimeConfig:
    mode: NetworkPolicyMode = NetworkPolicyMode.OFFLINE
    explicit_approval: bool = False
    public_workspace_paths: tuple[str, ...] = ()
    schema_version: str = RETRIEVAL_RUNTIME_SCHEMA_VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.mode, NetworkPolicyMode):
            object.__setattr__(self, "mode", NetworkPolicyMode(str(self.mode)))
        normalized = tuple(
            dict.fromkeys(_relative_public_path(item) for item in self.public_workspace_paths)
        )
        object.__setattr__(self, "public_workspace_paths", normalized)
        if self.mode != NetworkPolicyMode.EXPLICIT_EGRESS and self.explicit_approval:
            raise ValueError("workspace egress approval requires explicit_egress mode")
        if self.schema_version != RETRIEVAL_RUNTIME_SCHEMA_VERSION:
            raise ValueError(f"unsupported retrieval runtime schema: {self.schema_version}")

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": self.schema_version,
            "mode": self.mode.value,
            "explicit_approval": self.explicit_approval,
            "public_workspace_paths": list(self.public_workspace_paths),
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any] | None) -> "RetrievalRuntimeConfig":
        selected = dict(value or {})
        if not selected:
            return cls()
        return cls(
            schema_version=str(
                selected.get("schema_version") or RETRIEVAL_RUNTIME_SCHEMA_VERSION
            ),
            mode=NetworkPolicyMode(str(selected.get("mode") or "offline")),
            explicit_approval=bool(selected.get("explicit_approval", False)),
            public_workspace_paths=tuple(
                str(item) for item in selected.get("public_workspace_paths") or []
            ),
        )


class WorkspaceProvenanceResolver:
    """Conservatively label outbound strings without changing model arguments."""

    def __init__(
        self,
        config: RetrievalRuntimeConfig,
        *,
        max_scan_bytes: int = 4_000_000,
        max_file_bytes: int = 1_000_000,
        untrusted_text_provider: Callable[[], Iterable[str]] | None = None,
        goal_bound: bool = False,
    ) -> None:
        self.config = config
        self.max_scan_bytes = max(0, int(max_scan_bytes))
        self.max_file_bytes = max(0, int(max_file_bytes))
        self.untrusted_text_provider = untrusted_text_provider
        self.goal_bound = bool(goal_bound)

    @staticmethod
    def _unapproved_fragments(text: str, public_text: str) -> set[str]:
        # Classify copied lexical units as well as whole argument strings.
        # Padding, case changes and URL punctuation cannot launder a private
        # word into MODEL_PUBLIC_QUERY. Words explicitly supplied by the user
        # retain their public provenance when combined into a new query.
        public = set(re.findall(r"\w+", public_text.casefold()))
        return {word for word in re.findall(r"\w+", text.casefold())
                if len(word.encode("utf-8")) >= 3 and word not in public}

    def _matches_untrusted_text(self, needle: str, *, public_text: str = "") -> bool:
        if self.untrusted_text_provider is None or len(needle.encode("utf-8")) < 3:
            return False
        try:
            values = self.untrusted_text_provider()
        except Exception:
            # Provenance uncertainty must reject at the policy boundary.
            return True
        fragments = self._unapproved_fragments(needle, public_text)
        for value in values:
            candidate = str(value or "").strip()
            if len(candidate.encode("utf-8")) < 3:
                continue
            if (needle in candidate or candidate in needle
                    or fragments.intersection(re.findall(r"\w+", candidate.casefold()))):
                return True
        return False

    def _workspace_matches(
        self,
        goal: GoalState,
        needle: str,
    ) -> tuple[bool, bool, bool]:
        if len(needle.encode("utf-8")) < 3 or self.max_scan_bytes == 0:
            return False, False, False
        root = Path(goal.workspace_root).resolve()
        if not root.is_dir():
            return False, False, False
        config = retrieval_policy_from_goal(goal) if self.goal_bound else self.config
        public_roots = tuple(Path(item) for item in config.public_workspace_paths)
        public_match = False
        sensitive_match = False
        complete = True
        scanned = 0
        paths: list[Path] = []

        def traversal_error(_error: OSError) -> None:
            nonlocal complete
            complete = False

        try:
            for directory, directory_names, file_names in os.walk(
                root,
                topdown=True,
                onerror=traversal_error,
                followlinks=False,
            ):
                directory_names.sort()
                file_names.sort()
                retained_directories: list[str] = []
                for name in directory_names:
                    path = Path(directory) / name
                    try:
                        skipped = name in _SKIP_PARTS or path.is_symlink()
                    except OSError:
                        skipped = True
                    if skipped:
                        complete = False
                    else:
                        retained_directories.append(name)
                directory_names[:] = retained_directories
                paths.extend(Path(directory) / name for name in file_names)
        except OSError:
            complete = False
        needle_bytes = needle.encode("utf-8")
        fragments = self._unapproved_fragments(needle, goal.request)
        for path in paths:
            try:
                is_file = path.is_file()
            except OSError:
                complete = False
                continue
            if not is_file:
                complete = False
                continue
            try:
                resolved = path.resolve()
                relative = resolved.relative_to(root)
                size = resolved.stat().st_size
            except (OSError, ValueError):
                complete = False
                continue
            if size > self.max_file_bytes or scanned + size > self.max_scan_bytes:
                complete = False
                continue
            scanned += size
            try:
                content = resolved.read_bytes()
            except OSError:
                complete = False
                continue
            if needle_bytes not in content and not fragments.intersection(
                re.findall(r"\w+", content.decode("utf-8", errors="replace").casefold())
            ):
                continue
            declared_public = any(
                relative == public_root or public_root in relative.parents
                for public_root in public_roots
            )
            if declared_public:
                public_match = True
            else:
                sensitive_match = True
                break
        return public_match, sensitive_match, complete

    def __call__(
        self,
        goal: GoalState,
        _tool: str,
        arguments: Mapping[str, Any],
    ) -> Mapping[str, EgressProvenance]:
        labels: dict[str, EgressProvenance] = {}
        for key, value in arguments.items():
            if not isinstance(value, str) or not value.strip():
                continue
            text = value.strip()
            if key == "operation":
                labels[key] = EgressProvenance.MODEL_PUBLIC_QUERY
                continue
            if _SECRET_PATTERN.search(text):
                labels[key] = EgressProvenance.SECRET
                continue
            # A literal supplied by the user remains user-authorized public input
            # even after the same string is echoed by an external provider. Secret
            # detection stays above this branch and therefore cannot be downgraded.
            if text in goal.request:
                labels[key] = EgressProvenance.USER_PUBLIC_LITERAL
                continue
            if self._matches_untrusted_text(text, public_text=goal.request):
                labels[key] = EgressProvenance.TOOL_UNTRUSTED
                continue
            public_match, sensitive_match, complete = self._workspace_matches(
                goal,
                text,
            )
            if sensitive_match:
                labels[key] = EgressProvenance.WORKSPACE_SENSITIVE
            elif not complete:
                labels[key] = EgressProvenance.UNKNOWN
            elif public_match:
                labels[key] = EgressProvenance.WORKSPACE_PUBLIC
            else:
                labels[key] = EgressProvenance.MODEL_PUBLIC_QUERY
        return labels


def retrieval_policy_from_goal(goal: GoalState) -> RetrievalRuntimeConfig:
    value = goal.runtime_policy.get("retrieval")
    return RetrievalRuntimeConfig.from_dict(value if isinstance(value, Mapping) else None)


def network_policy_from_goal(goal: GoalState) -> NetworkPolicy:
    """Resolve the one execution policy persisted with this Goal."""

    config = retrieval_policy_from_goal(goal)
    return NetworkPolicy(
        mode=config.mode,
        explicit_approval=config.explicit_approval,
    )


def operation_allowed_by_retrieval_policy(
    goal: GoalState,
    *,
    network_access: str,
) -> bool:
    """Return whether an operation may enter this run's model-visible menu.

    Stable Selector deployments keep all class definitions registered so the
    head's class order never changes.  Registration is not authorization: an
    offline Goal must remove network classes from its eligible menu before
    selection, while the complete logits and frozen class identity remain intact.
    """

    access = str(network_access or "none").strip()
    if access == "none":
        return True
    if access not in {"public_web", "structured_source"}:
        raise ValueError(f"unsupported operation network_access: {access}")
    return retrieval_policy_from_goal(goal).mode != NetworkPolicyMode.OFFLINE


def runtime_policy_document(
    config: RetrievalRuntimeConfig,
    *,
    supervisor_mode: str = "stateful_goal",
    execution_mode: str = "bounded",
) -> dict[str, Any]:
    from rwkv_lh.run_lifecycle import (
        RUN_LIFECYCLE_POLICY_KEY,
        run_lifecycle_policy_document,
    )

    selected_supervisor = str(supervisor_mode or "stateful_goal").strip()
    if selected_supervisor not in {"stateful_goal", "none", "contract_graph"}:
        raise ValueError(
            "supervisor mode must be stateful_goal, none, or contract_graph"
        )
    return {
        "retrieval": config.to_dict(),
        "supervisor": {"mode": selected_supervisor},
        RUN_LIFECYCLE_POLICY_KEY: run_lifecycle_policy_document(execution_mode),
    }


def build_product_harness(
    *,
    config: RetrievalRuntimeConfig,
    snapshot_root: str | Path,
    sandbox_commands: bool = True,
    stable_network_menu: bool = False,
    untrusted_text_provider: Callable[[], Iterable[str]] | None = None,
) -> ActionHarness:
    backend = build_live_retrieval_backend(Path(snapshot_root))
    actions = build_retrieval_actions(
        backend=backend,
        network_policy=NetworkPolicy(
            mode=config.mode,
            explicit_approval=config.explicit_approval,
        ),
        provenance_resolver=WorkspaceProvenanceResolver(
            config,
            untrusted_text_provider=untrusted_text_provider,
            goal_bound=True,
        ),
        network_policy_resolver=network_policy_from_goal,
        connector_operations=backend.connector_operations,
        include_network_actions=stable_network_menu,
    )
    return ActionHarness(sandbox_commands=sandbox_commands, actions=actions)


__all__ = [
    "RETRIEVAL_RUNTIME_SCHEMA_VERSION",
    "RetrievalRuntimeConfig",
    "WorkspaceProvenanceResolver",
    "build_product_harness",
    "network_policy_from_goal",
    "operation_allowed_by_retrieval_policy",
    "retrieval_policy_from_goal",
    "runtime_policy_document",
]

rwkv_lh/retrieval/fetch.py:
"""Bounded HTTP fetch with redirect-by-redirect SSRF validation."""

from __future__ import annotations

import ipaddress
import json
import socket
from dataclasses import dataclass
from typing import Any, Callable, Iterable, Mapping
from urllib.parse import urljoin, urlparse

import requests


class FetchPolicyError(ValueError):
    pass


@dataclass(frozen=True)
class FetchResponse:
    url: str
    status_code: int
    media_type: str
    body: bytes
    headers: Mapping[str, str]


Resolver = Callable[[str], Iterable[str]]


def _system_resolver(host: str) -> tuple[str, ...]:
    return tuple(
        dict.fromkeys(
            item[4][0]
            for item in socket.getaddrinfo(host, None, type=socket.SOCK_STREAM)
        )
    )


def validate_public_url(url: str, *, resolver: Resolver = _system_resolver) -> str:
    selected = str(url or "").strip()
    parsed = urlparse(selected)
    if parsed.scheme.casefold() not in {"http", "https"}:
        raise FetchPolicyError("retrieval URL must use http or https")
    if parsed.username or parsed.password or not parsed.hostname:
        raise FetchPolicyError("retrieval URL authority is invalid")
    if parsed.port not in {None, 80, 443}:
        raise FetchPolicyError("retrieval URL uses a disallowed port")
    try:
        addresses = tuple(resolver(parsed.hostname))
    except OSError as exc:
        raise FetchPolicyError(f"retrieval hostname resolution failed: {exc}") from exc
    if not addresses:
        raise FetchPolicyError("retrieval hostname has no addresses")
    for raw in addresses:
        address = ipaddress.ip_address(raw)
        if not address.is_global:
            raise FetchPolicyError("retrieval URL resolves to a non-public address")
    return selected


def validate_public_peer(response: Any) -> str:
    """Validate the connected peer, closing the DNS-check/connect TOCTOU gap."""
    raw = getattr(response, "raw", None)
    candidates = (
        getattr(getattr(raw, "_connection", None), "sock", None),
        getattr(getattr(raw, "connection", None), "sock", None),
        getattr(
            getattr(getattr(getattr(raw, "_fp", None), "fp", None), "raw", None),
            "_sock",
            None,
        ),
    )
    peer_socket = next((item for item in candidates if item is not None), None)
    if peer_socket is None:
        raise FetchPolicyError("retrieval peer address is unavailable")
    try:
        raw_address = str(peer_socket.getpeername()[0])
        address = ipaddress.ip_address(raw_address)
    except (AttributeError, IndexError, TypeError, ValueError, OSError) as exc:
        raise FetchPolicyError("retrieval peer address is invalid") from exc
    if not address.is_global:
        raise FetchPolicyError("retrieval connection reached a non-public address")
    return address.compressed


class PublicHttpFetcher:
    def __init__(
        self,
        *,
        timeout_seconds: float = 20.0,
        connect_timeout_seconds: float = 5.0,
        max_bytes: int = 4_000_000,
        max_redirects: int = 4,
        resolver: Resolver = _system_resolver,
        session: requests.Session | None = None,
    ) -> None:
        self.timeout_seconds = max(1.0, min(float(timeout_seconds), 60.0))
        self.connect_timeout_seconds = max(
            1.0, min(float(connect_timeout_seconds), 60.0)
        )
        self.max_bytes = max(1024, min(int(max_bytes), 16_000_000))
        self.max_redirects = max(0, min(int(max_redirects), 8))
        self.resolver = resolver
        self.session = session or requests.Session()
        self.session.trust_env = False
        self.session.headers.update(
            {
                "User-Agent": "RWKV-LH-Retrieval/0.1 (+local evidence runtime)",
                "Accept": "text/html,application/json,text/plain,application/xml;q=0.8,*/*;q=0.2",
            }
        )

    def _consume(self, response: Any, *, current: str) -> FetchResponse:
        validate_public_peer(response)
        response.raise_for_status()
        media_type = str(
            response.headers.get("Content-Type") or "application/octet-stream"
        )
        chunks: list[bytes] = []
        observed = 0
        for chunk in response.iter_content(chunk_size=64 * 1024):
            if not chunk:
                continue
            observed += len(chunk)
            if observed > self.max_bytes:
                raise FetchPolicyError("retrieved response exceeds the byte bound")
            chunks.append(bytes(chunk))
        return FetchResponse(
            url=str(response.url or current),
            status_code=int(response.status_code),
            media_type=media_type,
            body=b"".join(chunks),
            headers={str(key): str(value) for key, value in response.headers.items()},
        )

    def fetch(
        self,
        url: str,
        *,
        headers: Mapping[str, str] | None = None,
    ) -> FetchResponse:
        current = validate_public_url(url, resolver=self.resolver)
        for redirect in range(self.max_redirects + 1):
            response = self.session.get(
                current,
                headers=dict(headers or {}),
                timeout=(self.connect_timeout_seconds, self.timeout_seconds),
                stream=True,
                allow_redirects=False,
            )
            try:
                validate_public_peer(response)
                if response.status_code in {301, 302, 303, 307, 308}:
                    location = str(response.headers.get("Location") or "").strip()
                    if not location or redirect >= self.max_redirects:
                        raise FetchPolicyError("retrieval redirect bound exceeded")
                    current = validate_public_url(
                        urljoin(current, location), resolver=self.resolver
                    )
                    continue
                return self._consume(response, current=current)
            finally:
                response.close()
        raise FetchPolicyError("retrieval redirect loop")

    def post_json(
        self,
        url: str,
        payload: Mapping[str, Any],
        *,
        headers: Mapping[str, str] | None = None,
    ) -> FetchResponse:
        """POST bounded JSON to one validated origin without forwarding secrets.

        API credentials must never be replayed across redirects, so provider
        POSTs reject redirects instead of following them.
        """

        current = validate_public_url(url, resolver=self.resolver)
        selected_headers = {
            "Content-Type": "application/json",
            **dict(headers or {}),
        }
        response = self.session.post(
            current,
            data=json.dumps(dict(payload), ensure_ascii=False).encode("utf-8"),
            headers=selected_headers,
            timeout=(self.connect_timeout_seconds, self.timeout_seconds),
            stream=True,
            allow_redirects=False,
        )
        try:
            validate_public_peer(response)
            if response.status_code in {301, 302, 303, 307, 308}:
                raise FetchPolicyError("retrieval API redirects are not allowed")
            return self._consume(response, current=current)
        finally:
            response.close()


__all__ = [
    "FetchPolicyError",
    "FetchResponse",
    "PublicHttpFetcher",
    "validate_public_peer",
    "validate_public_url",
]

rwkv_lh/goal_state_protocols/__init__.py:
"""Shared strict primitives for the five G1J per-stage StateTune protocols."""

from __future__ import annotations

import json
from collections.abc import Mapping, Sequence
from typing import Any

from rwkv_lh.model_io import ModelCommand, parse_model_command


ZERO_STATE_SHA256 = "0" * 64
ROLE_STATE_IDS = {
    "selector_intent": "selector-intent-2p9-v1",
    "executor_args": "executor-args-v1",
    "auditor_step": "auditor-step-v1",
    "finalizer_answer": "finalizer-answer-v1",
    "auditor_final": "auditor-final-v1",
}


def _mapping(value: Any, name: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise ValueError(f"{name} must be an object")
    return value


def _exact_fields(
    value: Any,
    fields: Sequence[str],
    name: str,
) -> Mapping[str, Any]:
    selected = _mapping(value, name)
    if tuple(selected) != tuple(fields) or set(selected) != set(fields):
        raise ValueError(f"{name} fields/order must be exactly {tuple(fields)!r}")
    return selected


def _exact_field_set(
    value: Any,
    fields: Sequence[str],
    name: str,
) -> Mapping[str, Any]:
    selected = _mapping(value, name)
    if set(selected) != set(fields):
        raise ValueError(f"{name} fields must be exactly {tuple(fields)!r}")
    return selected


def _nonempty(value: Any, name: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{name} must be a non-empty string")
    return value


def _strings(
    value: Any,
    name: str,
    *,
    nonempty: bool = False,
    sorted_unique: bool = False,
) -> tuple[str, ...]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)):
        raise ValueError(f"{name} must be an array")
    selected = tuple(_nonempty(item, f"{name} item") for item in value)
    if nonempty and not selected:
        raise ValueError(f"{name} must not be empty")
    if len(set(selected)) != len(selected):
        raise ValueError(f"{name} must contain unique values")
    if sorted_unique and selected != tuple(sorted(selected)):
        raise ValueError(f"{name} must be sorted")
    return selected


def _objects(value: Any, name: str, *, nonempty: bool = False) -> tuple[Mapping[str, Any], ...]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)):
        raise ValueError(f"{name} must be an array")
    selected = tuple(_mapping(item, f"{name} item") for item in value)
    if nonempty and not selected:
        raise ValueError(f"{name} must not be empty")
    return selected


def _nonnegative_int(value: Any, name: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError(f"{name} must be a non-negative integer")
    return value


def _render(prefix: str, payload: Mapping[str, Any]) -> str:
    return prefix + json.dumps(
        dict(payload),
        ensure_ascii=False,
        sort_keys=False,
        separators=(",", ":"),
    )


def _strict_command(target: str, operation: str) -> ModelCommand:
    if not isinstance(target, str) or not target:
        raise ValueError("target must be a non-empty string")
    command = parse_model_command(target)
    if command.name != operation:
        raise ValueError(f"target must call {operation!r}")
    if target != command.canonical:
        raise ValueError("target must be canonical direct-call JSON")
    return command


_AUDIT_FIELDS = (
    "verdict",
    "step_id",
    "step_complete",
    "evidence_refs",
    "gaps",
    "reason",
)


def _audit_decision(
    value: Any,
    *,
    allowed_verdicts: Sequence[str],
) -> Mapping[str, Any]:
    decision = _exact_field_set(value, _AUDIT_FIELDS, "decision")
    verdict = _nonempty(decision["verdict"], "decision.verdict")
    if verdict not in set(allowed_verdicts):
        raise ValueError(f"decision.verdict must be one of {tuple(allowed_verdicts)!r}")
    if not isinstance(decision["step_id"], str):
        raise ValueError("decision.step_id must be a string")
    if not isinstance(decision["step_complete"], bool):
        raise ValueError("decision.step_complete must be boolean")
    _strings(decision["evidence_refs"], "decision.evidence_refs")
    _strings(decision["gaps"], "decision.gaps")
    _nonempty(decision["reason"], "decision.reason")
    return decision


def _audit_target(target: str, *, allowed_verdicts: Sequence[str]) -> ModelCommand:
    command = _strict_command(target, "audit_decision")
    _audit_decision(command.arguments, allowed_verdicts=allowed_verdicts)
    return command


__all__ = ["ROLE_STATE_IDS", "ZERO_STATE_SHA256"]

rwkv_lh/goal_state_protocols/feedback.py:
"""Shared feedback value contract; no model role or completion authority."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from copy import deepcopy
from typing import Any

from rwkv_lh.goal_state_protocols import _exact_fields, _nonempty, _nonnegative_int, _objects, _strings

SCHEMA_VERSION = "rwkv-lh.role-feedback.v2"
FIELDS = ("schema_version", "kind", "source_role", "recipient_roles", "boundary_id",
          "source_id", "plan_revision", "step_id", "step_revision", "issues", "diagnosis", "rejected_output")
ISSUE_FIELDS = ("code", "criterion", "repair_scope", "evidence_refs")
ROLES = frozenset({"selector_intent", "executor_args", "auditor_step", "finalizer_answer", "auditor_final", "planner"})


def validate_feedback(value: Any, *, recipient: str | None = None) -> Mapping[str, Any] | None:
    if value is None:
        return None
    packet = _exact_fields(value, FIELDS, "feedback")
    if packet["schema_version"] != SCHEMA_VERSION:
        raise ValueError("unsupported feedback schema")
    if packet["kind"] not in {"semantic", "protocol"} or packet["source_role"] not in ROLES:
        raise ValueError("invalid feedback kind or source role")
    recipients = _strings(packet["recipient_roles"], "feedback.recipient_roles", nonempty=True, sorted_unique=True)
    if not set(recipients) <= ROLES or (recipient is not None and recipient not in recipients):
        raise ValueError("feedback belongs to another role")
    for name in ("boundary_id", "source_id"):
        _nonempty(packet[name], f"feedback.{name}")
    for name in ("plan_revision", "step_revision"):
        _nonnegative_int(packet[name], f"feedback.{name}")
    if not isinstance(packet["step_id"], str) or not isinstance(packet["rejected_output"], str):
        raise ValueError("feedback step and rejected output must be strings")
    if bool(packet["step_id"]) != bool(packet["step_revision"]):
        raise ValueError("feedback step revision binding is incomplete")
    if not isinstance(packet["diagnosis"], str):
        raise ValueError("feedback diagnosis must be text")
    scopes, codes = set(), []
    for issue in _objects(packet["issues"], "feedback.issues", nonempty=True):
        item = _exact_fields(issue, ISSUE_FIELDS, "feedback issue")
        codes.append(_nonempty(item["code"], "feedback issue code"))
        _nonempty(item["criterion"], "feedback issue criterion")
        if item["repair_scope"] not in {"step", "answer", "execution", "protocol"}:
            raise ValueError("invalid feedback repair scope")
        scopes.add(item["repair_scope"])
        _strings(item["evidence_refs"], "feedback issue evidence_refs", sorted_unique=True)
    if codes != sorted(set(codes)):
        raise ValueError("feedback issues must have sorted unique codes")
    if packet["kind"] == "protocol":
        expected = (packet["source_role"],)
        if scopes != {"protocol"}:
            raise ValueError("protocol feedback cannot carry semantic authority")
    else:
        if packet["source_role"] == "auditor_step" and scopes == {"step"}:
            expected = ("executor_args", "selector_intent")
        elif packet["source_role"] == "auditor_final" and scopes <= {"answer", "execution"}:
            expected = ("planner",) if "execution" in scopes else ("finalizer_answer",)
        else:
            raise ValueError("semantic feedback scope differs from its source role")
    if recipients != expected:
        raise ValueError("feedback recipients differ from the declared repair scope")
    return packet


def build_feedback(*, kind: str, source_role: str, boundary_id: str, source_id: str,
                   plan_revision: int, step_id: str = "", step_revision: int = 0,
                   issues: Sequence[Mapping[str, Any]], diagnosis: str = "", rejected_output: str = "") -> dict[str, Any]:
    ordered = sorted((deepcopy(dict(item)) for item in issues), key=lambda item: item["code"])
    scopes = {item["repair_scope"] for item in ordered}
    recipients = ([source_role] if kind == "protocol" else ["planner"] if "execution" in scopes
                  else ["finalizer_answer"] if "answer" in scopes else ["executor_args", "selector_intent"])
    packet = {"schema_version": SCHEMA_VERSION, "kind": kind, "source_role": source_role,
              "recipient_roles": recipients, "boundary_id": boundary_id, "source_id": source_id,
              "plan_revision": plan_revision, "step_id": step_id, "step_revision": step_revision,
              "issues": ordered, "diagnosis": diagnosis, "rejected_output": rejected_output}
    validate_feedback(packet)
    return packet


def semantic_feedback(*, source_role: str, boundary_id: str, source_id: str, plan_revision: int,
                      step_id: str = "", step_revision: int = 0, gap_codes: Sequence[str],
                      gap_catalog: Sequence[Mapping[str, Any]], evidence_refs: Sequence[str],
                      diagnosis: str = "", rejected_output: str = "") -> dict[str, Any] | None:
    if not gap_codes:
        return None
    catalog = {item["code"]: item for item in gap_catalog}
    if not set(gap_codes) <= set(catalog):
        raise ValueError("feedback gaps are absent from the audited input")
    issues = [{"code": code, "criterion": catalog[code]["criterion"],
               "repair_scope": "step" if source_role == "auditor_step" else catalog[code]["repair_scope"],
               "evidence_refs": sorted(set(evidence_refs))} for code in gap_codes]
    return build_feedback(kind="semantic", source_role=source_role, boundary_id=boundary_id,
                          source_id=source_id, plan_revision=plan_revision, step_id=step_id,
                          step_revision=step_revision, issues=issues, diagnosis=diagnosis, rejected_output=rejected_output)

rwkv_lh/goal_state_protocols/execution_f:
"""Shared durable action rejection facts; no planning or completion authority."""
from collections.abc import Mapping, Sequence
from copy import deepcopy

from rwkv_lh.goal_state_protocols import _exact_fields, _nonempty, _nonnegative_int

FIELDS = ("event_id", "selection_id", "step_id", "step_revision", "selected_operation",
          "rejected_arguments", "error_kind", "error", "action_executed")


def validate_rejections(value):
    if not isinstance(value, list):
        raise ValueError("recent_rejections must be an array")
    identifiers = set()
    for item in value:
        record = _exact_fields(item, FIELDS, "action rejection")
        for name in ("event_id", "selection_id", "step_id", "selected_operation", "error"):
            _nonempty(record[name], name)
        if _nonnegative_int(record["step_revision"], "step_revision") < 1:
            raise ValueError("rejection must bind a positive step revision")
        if not isinstance(record["rejected_arguments"], Mapping) or not isinstance(record["error_kind"], str):
            raise ValueError("invalid rejection arguments or error kind")
        if record["event_id"] in identifiers or record["action_executed"] is not False:
            raise ValueError("rejection is duplicated or claims an executed action")
        identifiers.add(record["event_id"])
    return value


def build_rejections(records: Sequence[Mapping]) -> list[dict]:
    result = [deepcopy(dict(record)) for record in records]
    validate_rejections(result)
    return result

rwkv_lh/goal_state_protocols/role_trace_:
"""Extract auditable role samples from frozen production checkpoints.

This module is a dataset consumer, not a sixth role protocol. It never runs a
model, invents scenarios, reads benchmark answer keys, or creates formal dataset
versions. Missing observations are exclusions; contradictory evidence rejects
the batch. The CLI publishes immutable candidate/audit artifacts only.
"""

from __future__ import annotations

import argparse
from dataclasses import dataclass
import gzip
import hashlib
import json
from pathlib import Path
import sqlite3
from typing import Any, Mapping, Sequence

from rwkv_lh.goal_state_protocols import (
    auditor_final, auditor_step_v7, executor_args_v7, finalizer_answer, selector_intent_v7,
)
from rwkv_lh.goal_loop_protocol import action_mutates_root, action_observes_root
from rwkv_lh.model_io import JSON_CALL_STOP_SUFFIXES, parse_model_command_with_trace
from rwkv_lh.schema import ActionStatus, CausalEvent, ModelCheckpoint, RunState
from rwkv_lh.store import LongHorizonStore
from rwkv_lh.token_budget import VOCAB_PATH, tokenizer


SOURCE_REGISTRATION_SCHEMA = "rwkv-lh.role-trace-source-registration.v1"
EXTRACTION_SCHEMA = "rwkv-lh.role-trace-extraction.v1"
ROOT = Path(__file__).resolve().parents[2]
ZERO_SHA = "0" * 64
ROLE_MODULES = {
    "selector_intent": selector_intent_v7,
    "executor_args": executor_args_v7,
    "auditor_step": auditor_step_v7,
    "finalizer_answer": finalizer_answer,
    "auditor_final": auditor_final,
}
REQUIRED_ARTIFACTS = frozenset({"sqlite", "model_trace", "event_log", "state_timeline", "causal_ledger", "run_protocol", "source_tree_manifest"})
CASE_ARTIFACT_PATHS = {
    "sqlite": "state/long_horizon.db", "model_trace": "model_trace.json",
    "event_log": "event_log.json", "state_timeline": "state_timeline.json.gz",
    "causal_ledger": "causal_ledger.json",
}
SOURCE_CODE_PATHS = tuple(sorted({
    *(str(path.relative_to(ROOT)) for path in (ROOT / "rwkv_lh").rglob("*.py")
      if not path.name.startswith("role_trace_")),
    str(VOCAB_PATH.relative_to(ROOT)),
}))
EQUIVALENCE_WAIVER_SCHEMA = "rwkv-lh.role-trace-source-equivalence.v1"
# The vocabulary and the five role protocol modules define sample semantics
# directly; their identity may never be waived, only re-frozen.
NON_WAIVABLE_PATHS = frozenset({
    str(VOCAB_PATH.relative_to(ROOT)),
    *(str(Path(module.__file__).resolve().relative_to(ROOT)) for module in ROLE_MODULES.values()),
})


class DatasetIntegrityError(ValueError):
    """Frozen evidence disagrees: no samples from this batch may be published."""


class SampleExcluded(ValueError):
    """A boundary lacks sufficient evidence for a legitimate training label."""

    def __init__(self, message: str, *, review_candidate: Mapping | None = None):
        super().__init__(message)
        self.review_candidate = dict(review_candidate) if review_candidate is not None else None


def _digest(value: bytes | str) -> str:
    return hashlib.sha256(value.encode("utf-8") if isinstance(value, str) else value).hexdigest()


def _canonical(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)


def _is_sha(value: Any) -> bool:
    return isinstance(value, str) and len(value) == 64 and all(c in "0123456789abcdef" for c in value)


def _validate_frozen_scope(record: Mapping, protocol: Any, source_manifest: Any,
                           waiver: Mapping[str, tuple[str, str]] | None = None) -> list[str]:
    from rwkv_lh.stateful_goal_loop import STATEFUL_GOAL_LOOP_ARCHITECTURE

    if not isinstance(protocol, Mapping) or protocol.get("schema_version") != "rwkv-lh.round-run-protocol.v1":
        raise DatasetIntegrityError("source requires the frozen production run protocol")
    if protocol.get("architecture") != STATEFUL_GOAL_LOOP_ARCHITECTURE or protocol.get("round") != record["source_run_id"]:
        raise DatasetIntegrityError("frozen run architecture/round differs from source registration")
    cases = protocol.get("selected_case_ids")
    if not isinstance(cases, list) or len(cases) != len(set(cases)) or protocol.get("selected_case_count") != len(cases) or record["run_id"] not in cases:
        raise DatasetIntegrityError("source case is outside the frozen development selection")
    resources = protocol.get("source_resources")
    if not isinstance(resources, list) or not any(isinstance(item, Mapping) and item.get("role") == "visible_tasks" and item.get("suite") == record["suite"] and _is_sha(item.get("sha256")) for item in resources):
        raise DatasetIntegrityError("source suite lacks a frozen visible development scope")
    # Only metadata are read; the registered resources (especially answer keys)
    # are never opened by the extractor.
    if not isinstance(source_manifest, list) or protocol.get("code", {}).get("source_tree_manifest_sha256") != _digest(_canonical(source_manifest)):
        raise DatasetIntegrityError("frozen source manifest SHA mismatch")
    paths = [item.get("path") for item in source_manifest if isinstance(item, Mapping)]
    if len(paths) != len(source_manifest) or len(paths) != len(set(paths)):
        raise DatasetIntegrityError("frozen source manifest contains duplicate/malformed paths")
    hashes = {item["path"]: item.get("sha256") for item in source_manifest}
    waived = []
    for path in SOURCE_CODE_PATHS:
        current = _digest((ROOT / path).read_bytes())
        if hashes.get(path) == current:
            continue
        # The whole-tree SHA is a coarse proxy; a double-reviewed equivalence
        # waiver may relax it for an exactly pinned (frozen, current) pair.
        # Role protocol hashes, checkpoint byte rebuilds and token replay
        # remain unconditional downstream.
        if waiver is not None and waiver.get(path) == (hashes.get(path), current):
            waived.append(path)
            continue
        raise DatasetIntegrityError(f"source production builder/State implementation differs: {path}")
    return waived


def _pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise DatasetIntegrityError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def _json(data: bytes | str) -> Any:
    try:
        return json.loads(data, object_pairs_hook=_pairs,
                          parse_constant=lambda item: (_ for _ in ()).throw(ValueError(item)))
    except (UnicodeError, ValueError) as exc:
        raise DatasetIntegrityError(f"invalid JSON: {exc}") from exc


def _source_path(path: Path) -> Path:
    # Check both spelling and resolved target before opening even a manifest.
    for candidate in (path.absolute(), path.resolve()):
        parts = [part.casefold() for part in candidate.parts]
        if any("holdout" in part or part in {"acceptance", "acceptance_tests", "sealed"}
               for part in parts):
            raise DatasetIntegrityError("protected source is not a development trace")
        if any(part.startswith("confirmation") for part in parts):
            raise DatasetIntegrityError("protected confirmation samples are not source traces")
    return path.resolve()


def validate_output_path(path: Path) -> Path:
    output = _source_path(Path(path))
    if "datasets" in output.parts or not any(output.is_relative_to(ROOT / "data" / directory)
               for directory in ("experiments", "test_runs")):
        raise DatasetIntegrityError("audit output must be under data/experiments or data/test_runs")
    if output.exists():
        raise DatasetIntegrityError("audit output already exists; overwrite is forbidden")
    return output


def read_artifact(record: Mapping[str, Any], base_dir: Path) -> bytes:
    if not isinstance(record, Mapping) or set(record) != {"path", "sha256"}:
        raise DatasetIntegrityError("artifact requires exact path and SHA fields")
    digest = record["sha256"]
    if not isinstance(digest, str) or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
        raise DatasetIntegrityError("artifact SHA must be lowercase SHA-256")
    path = _source_path(Path(base_dir) / str(record["path"]))
    value = path.read_bytes()
    if _digest(value) != digest:
        raise DatasetIntegrityError(f"artifact SHA mismatch: {path}")
    return value


def read_registration(path: Path) -> dict[str, Any]:
    path = _source_path(Path(path))
    value = _json(path.read_bytes())
    if not isinstance(value, dict) or value.get("schema_version") != SOURCE_REGISTRATION_SCHEMA:
        raise DatasetIntegrityError("unsupported source registration schema")
    if (set(value) - {"schema_version", "source_runs", "coverage_scope"}
            or not isinstance(value.get("source_runs"), list)):
        raise DatasetIntegrityError("source registration fields are invalid")
    identities = set()
    for run in value["source_runs"]:
        if not isinstance(run, dict):
            raise DatasetIntegrityError("source run must be an object")
        key = (run.get("source_run_id"), run.get("run_id"))
        if key in identities:
            raise DatasetIntegrityError("duplicate source run or conflicting project family")
        identities.add(key)
    return value


def read_equivalence_waiver(path: Path, sha256: str) -> dict[str, tuple[str, str]]:
    """Parse a double-reviewed source-equivalence waiver into {path: (frozen, current)}.

    A waiver relaxes only the coarse whole-tree SHA proxy for exactly pinned
    byte pairs. It can never cover the vocabulary or a role protocol module,
    and it does not touch the unconditional semantic defenses (per-role
    protocol SHA, checkpoint byte rebuild, timeline recomputation, raw token
    replay), which still reject on any observable divergence.
    """
    value = _json(read_artifact({"path": str(path), "sha256": sha256}, ROOT))
    if not isinstance(value, dict) or value.get("schema_version") != EQUIVALENCE_WAIVER_SCHEMA:
        raise DatasetIntegrityError("unsupported source equivalence waiver schema")
    if set(value) != {"schema_version", "decision", "reviewers", "entries"}:
        raise DatasetIntegrityError("source equivalence waiver fields are invalid")
    if value["decision"] != "accept":
        raise DatasetIntegrityError("source equivalence waiver is not an accepted review")
    reviewers = value["reviewers"]
    if (not isinstance(reviewers, list) or len(reviewers) != 2
            or any(not isinstance(item, str) or not item.strip() for item in reviewers)
            or len({item.strip() for item in reviewers}) != 2):
        raise DatasetIntegrityError("source equivalence waiver requires exactly two distinct reviewers")
    entries = value["entries"]
    if not isinstance(entries, list) or not entries:
        raise DatasetIntegrityError("source equivalence waiver lists no entries")
    waiver: dict[str, tuple[str, str]] = {}
    for entry in entries:
        if not isinstance(entry, Mapping) or set(entry) != {"path", "frozen_sha256", "current_sha256", "rationale", "evidence_refs"}:
            raise DatasetIntegrityError("waiver entry fields are invalid")
        target = entry["path"]
        if target in waiver:
            raise DatasetIntegrityError(f"duplicate waiver entry: {target}")
        if target not in SOURCE_CODE_PATHS or target in NON_WAIVABLE_PATHS:
            raise DatasetIntegrityError(f"waiver cannot cover this path: {target}")
        if (not _is_sha(entry["frozen_sha256"]) or not _is_sha(entry["current_sha256"])
                or entry["frozen_sha256"] == entry["current_sha256"]):
            raise DatasetIntegrityError(f"waiver entry requires distinct frozen/current SHA-256: {target}")
        refs = entry["evidence_refs"]
        if (not isinstance(entry["rationale"], str) or not entry["rationale"].strip()
                or not isinstance(refs, list) or not refs or len(refs) != len(set(refs))
                or any(not isinstance(ref, str) or not ref.strip() for ref in refs)):
            raise DatasetIntegrityError(f"waiver entry requires a rationale and unique evidence refs: {target}")
        waiver[target] = (entry["frozen_sha256"], entry["current_sha256"])
    return waiver


@dataclass(frozen=True)
class SourceRun:
    registration: Mapping[str, Any]
    final_state: RunState
    snapshots: Mapping[str, RunState]
    model_trace: Sequence[Mapping[str, Any]]
    reviews: Sequence[Mapping[str, Any]]
    collection_contract: Mapping[str, Any] | None = None
    waived_paths: tuple[str, ...] = ()


def _json_changes(before: Any, after: Any, path: str = "$") -> list[dict[str, Any]]:
    """Recompute the runner's structural delta without using it as authority."""
    if isinstance(before, dict) and isinstance(after, dict):
        changes = []
        for key in sorted(set(before) | set(after)):
            child = f"{path}.{key}"
            if key not in before:
                changes.append({"op": "add", "path": child, "after": after[key]})
            elif key not in after:
                changes.append({"op": "remove", "path": child})
            else:
                changes.extend(_json_changes(before[key], after[key], child))
        return changes
    if isinstance(before, list) and isinstance(after, list):
        shared = min(len(before), len(after))
        changes = [change for i in range(shared)
                   for change in _json_changes(before[i], after[i], f"{path}[{i}]")]
        changes.extend({"op": "remove", "path": f"{path}[{i}]"} for i in range(shared, len(before)))
        changes.extend({"op": "add", "path": f"{path}[{i}]", "after": after[i]}
                       for i in range(shared, len(after)))
        return changes
    return [] if before == after else [{"op": "replace", "path": path, "after": after}]


def load_source_run(record: Mapping[str, Any], *, base_dir: Path,
                    coverage_scope_sha256: str | None = None,
                    equivalence_waiver: Mapping[str, tuple[str, str]] | None = None) -> SourceRun:
    if record.get("source_kind") != "production_trace":
        raise DatasetIntegrityError("only production_trace may supply role data")
    if record.get("collection_mode") not in {"all_zero", "role_stage"}:
        raise DatasetIntegrityError("source collection must be all_zero or frozen role_stage")
    artifacts = record.get("artifacts")
    if not isinstance(artifacts, dict) or not REQUIRED_ARTIFACTS <= set(artifacts):
        raise DatasetIntegrityError("complete SQLite, trace, event, timeline and ledger artifacts are required")
    if set(artifacts) - REQUIRED_ARTIFACTS - {"human_reviews"}:
        raise DatasetIntegrityError("unknown source artifact")
    for key in ("run_id", "source_run_id", "project_family", "suite"):
        if not isinstance(record.get(key), str) or not record[key].strip():
            raise DatasetIntegrityError(f"source {key} must be nonempty")
    if any(word in record["suite"].casefold() for word in ("holdout", "acceptance", "confirmation", "fixture")):
        raise DatasetIntegrityError("protected or fixture suite cannot supply training traces")
    if set(record.get("protocol_sha256", {})) != set(ROLE_MODULES):
        raise DatasetIntegrityError("source must freeze the five current protocol hashes")
    for role, module in ROLE_MODULES.items():
        if record["protocol_sha256"][role] != _digest(Path(module.__file__).read_bytes()):
            raise DatasetIntegrityError(f"source protocol SHA mismatch: {role}")
    raw = {name: read_artifact(item, base_dir) for name, item in artifacts.items()}
    protocol = _json(raw["run_protocol"])
    waived = _validate_frozen_scope(record, protocol, _json(raw["source_tree_manifest"]),
                                    waiver=equivalence_waiver)
    if coverage_scope_sha256 is not None and protocol.get("role_data_scope_sha256") != coverage_scope_sha256:
        raise DatasetIntegrityError("coverage scope was not pinned in the frozen source run protocol")
    contract = protocol.get("role_data_collection")
    if (contract is None) != (record["collection_mode"] == "all_zero"):
        raise DatasetIntegrityError("source collection mode differs from frozen role-stage contract")
    if contract is not None:
        from rwkv_lh.role_trace_stages import validate_collection_contract
        try:
            contract = validate_collection_contract(contract)
        except ValueError as exc:
            raise DatasetIntegrityError(str(exc)) from exc
    path = _source_path(Path(base_dir) / artifacts["sqlite"]["path"])
    if any(Path(str(path) + suffix).exists() and Path(str(path) + suffix).stat().st_size
           for suffix in ("-wal", "-journal")):
        raise DatasetIntegrityError("SQLite is not a frozen standalone snapshot (active WAL/journal)")
    with sqlite3.connect(path.as_uri() + "?mode=ro&immutable=1", uri=True) as connection:
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA query_only=ON")
        if connection.execute("PRAGMA quick_check").fetchone()[0] != "ok":
            raise DatasetIntegrityError("SQLite integrity check failed")
        run_rows = connection.execute("SELECT state_json FROM runs WHERE run_id=?", (record["run_id"],)).fetchall()
        if len(run_rows) != 1:
            raise DatasetIntegrityError("source run is absent or ambiguous in SQLite")
        final_state = RunState.from_dict(LongHorizonStore._deserialize(run_rows[0]["state_json"]))
        rows = connection.execute("SELECT * FROM checkpoints WHERE run_id=? ORDER BY revision", (record["run_id"],)).fetchall()
        event_rows = connection.execute("SELECT * FROM events WHERE run_id=? ORDER BY revision", (record["run_id"],)).fetchall()
    if _digest(path.read_bytes()) != _digest(raw["sqlite"]):
        raise DatasetIntegrityError("SQLite changed during extraction")
    if not rows or not final_state.causal_order:
        raise DatasetIntegrityError("source lacks durable checkpoints/causal facts")
    try:
        timeline = _json(gzip.decompress(raw["state_timeline"]))
    except (OSError, EOFError) as exc:
        raise DatasetIntegrityError("invalid compressed state timeline") from exc
    events = _json(raw["event_log"])
    trace = _json(raw["model_trace"])
    ledger = _json(raw["causal_ledger"])
    if not isinstance(trace, list) or any(not isinstance(item, dict) for item in trace):
        raise DatasetIntegrityError("model trace must be an event array")
    if not isinstance(events, list) or len(events) != len(event_rows):
        raise DatasetIntegrityError("event log differs from SQLite")
    for exported, sql in zip(events, event_rows):
        causal = LongHorizonStore._deserialize(sql["data_json"])
        if exported.get("revision") != sql["revision"] or exported.get("type") != sql["type"] or exported.get("causal_event") != causal or exported.get("data") != causal.get("payload"):
            raise DatasetIntegrityError("event log/SQLite causal event mismatch")
    if not isinstance(timeline, list) or len(timeline) != len(rows):
        raise DatasetIntegrityError("state timeline/checkpoint count mismatch")
    snapshots = {}
    causal_at_revision = {
        row["revision"]: CausalEvent.from_dict(LongHorizonStore._deserialize(row["data_json"]))
        for row in event_rows
    }
    previous = None
    previous_revision = -1
    for row, exported in zip(rows, timeline):
        snapshot = RunState.from_dict(LongHorizonStore._deserialize(row["state_json"]))
        state_dict = snapshot.to_dict()
        if snapshot.run_id != final_state.run_id or row["revision"] != snapshot.revision or row["revision"] <= previous_revision:
            raise DatasetIntegrityError("snapshot run/revision identity mismatch")
        expected_event = causal_at_revision.get(snapshot.revision)
        if (expected_event is None or not snapshot.causal_order
            or snapshot.causal_order[-1] != expected_event.event_id
            or len(snapshot.causal_order) != expected_event.sequence):
            raise DatasetIntegrityError("snapshot contains future or missing causal facts at its SQLite revision")
        if snapshot.causal_order != final_state.causal_order[:len(snapshot.causal_order)]:
            raise DatasetIntegrityError("snapshot is not a causal prefix of final state")
        if any(snapshot.causal_records[key].to_dict() != final_state.causal_records[key].to_dict() for key in snapshot.causal_order):
            raise DatasetIntegrityError("immutable causal event changed between snapshots")
        expected_changes = [] if previous is None else _json_changes(previous, state_dict)
        if exported.get("revision") != snapshot.revision or exported.get("state_sha256") != _digest(_canonical(state_dict)) or exported.get("changes_from_previous") != expected_changes or exported.get("change_digest") != _digest(_canonical({"changes": expected_changes})):
            raise DatasetIntegrityError("state timeline cannot be exactly recomputed from SQLite")
        if previous is None and (exported.get("snapshot_kind") != "initial_exact" or exported.get("state") != state_dict):
            raise DatasetIntegrityError("initial state timeline snapshot mismatch")
        if snapshot.causal_order:
            snapshots[snapshot.causal_order[-1]] = snapshot
        previous, previous_revision = state_dict, snapshot.revision
    if previous != final_state.to_dict():
        raise DatasetIntegrityError("final SQLite state is not the final retained checkpoint")
    if not isinstance(ledger, dict) or ledger.get("causal_events") != [final_state.causal_records[key].to_dict() for key in final_state.causal_order]:
        raise DatasetIntegrityError("causal ledger differs from authoritative SQLite")
    if ledger.get("policy", {}).get("hidden_acceptance_included") is not False:
        raise DatasetIntegrityError("causal ledger lacks development-only boundary attestation")
    reviews = _json(raw["human_reviews"]) if "human_reviews" in raw else []
    if not isinstance(reviews, list) or any(not isinstance(review, Mapping) for review in reviews):
        raise DatasetIntegrityError("human reviews must be an array")
    from rwkv_lh.role_trace_stages import validate_collection_states
    try:
        validate_collection_states(final_state, trace, contract)
    except ValueError as exc:
        raise DatasetIntegrityError(str(exc)) from exc
    return SourceRun(dict(record), final_state, snapshots, trace, reviews, contract, tuple(waived))


def register_case(case_dir: Path, *, run_id: str, source_run_id: str, project_family: str, suite: str) -> dict:
    case_dir = _source_path(Path(case_dir))
    record = {
        "run_id": run_id, "source_run_id": source_run_id, "project_family": project_family,
        "suite": suite, "source_kind": "production_trace", "collection_mode": "all_zero",
        "protocol_sha256": {role: _digest(Path(module.__file__).read_bytes()) for role, module in ROLE_MODULES.items()},
        "artifacts": {},
    }
    for key, relative in CASE_ARTIFACT_PATHS.items():
        path = _source_path(case_dir / relative)
        record["artifacts"][key] = {"path": str(path), "sha256": _digest(path.read_bytes())}
    for key, name in (("run_protocol", "RUN_PROTOCOL.json"), ("source_tree_manifest", "source_tree_manifest.json")):
        path = _source_path(case_dir.parent.parent / name)
        record["artifacts"][key] = {"path": str(path), "sha256": _digest(path.read_bytes())}
    protocol = _json(read_artifact(record["artifacts"]["run_protocol"], case_dir))
    record["collection_mode"] = "role_stage" if protocol.get("role_data_collection") is not None else "all_zero"
    load_source_run(record, base_dir=case_dir)
    return {"schema_version": SOURCE_REGISTRATION_SCHEMA, "source_runs": [record]}


def validate_raw_generation(raw: Mapping[str, Any]) -> tuple[str, list[int]]:
    if raw.get("finish_reason") != "stop":
        raise SampleExcluded("finish_reason is not natural stop")
    ids = raw.get("raw_token_ids")
    if not isinstance(ids, list) or not ids:
        raise SampleExcluded("raw generated token IDs are missing")
    if any(type(item) is not int or item < 0 for item in ids):
        raise DatasetIntegrityError("invalid raw token ID")
    text = raw.get("raw_output")
    if not isinstance(text, str) or raw.get("raw_output_sha256") != _digest(text):
        raise DatasetIntegrityError("raw generation text/SHA mismatch")
    try:
        stream = tokenizer().decode_bytes(ids).decode("utf-8")
    except (KeyError, ValueError, UnicodeError) as exc:
        raise DatasetIntegrityError("raw token stream cannot be decoded") from exc
    if stream != text and not any(stream == text + suffix for suffix in JSON_CALL_STOP_SUFFIXES):
        raise DatasetIntegrityError("raw token stream differs from output and attested stop suffix")
    if raw.get("state_profile_id") != "zero" or raw.get("state_profile_sha256") != ZERO_SHA:
        raise DatasetIntegrityError("generation is not explicitly bound to zero State")
    if raw.get("postprocessed") is not False:
        raise DatasetIntegrityError("raw generation cannot be postprocessed")
    return stream, ids


def _events(source: SourceRun) -> list[CausalEvent]:
    return [source.final_state.causal_records[key] for key in source.final_state.causal_order]


def _parse_original_command(raw: Mapping[str, Any]):
    from types import SimpleNamespace
    from rwkv_lh.model_session import _restore_attested_stop_suffix

    # Keep the full token stream as the target. Parse exactly the production
    # transport-visible text, restoring only the already attested Markdown fence.
    parsed_text, _ = _restore_attested_stop_suffix(SimpleNamespace(
        raw_output=raw["raw_output"], raw_token_ids=tuple(raw["raw_token_ids"]),
        finish_reason=raw["finish_reason"],
    ))
    return parse_model_command_with_trace(parsed_text)[0]


def _successful_progress(action, rebuilt: Mapping[str, Any]) -> bool:
    return (
        action.status is ActionStatus.SUCCEEDED and bool((action.result or {}).get("success"))
        and (any(action_observes_root(action, root) for root in rebuilt.get("missing_read_roots", []))
             or any(action_mutates_root(action, root) for root in rebuilt.get("missing_write_roots", [])))
    )


def _action_authority(source: SourceRun, rebuilt: Mapping, request_id: str, selection_id: str = "") -> list[str]:
    decisions = source.final_state.decisions
    matching = []
    for action in source.final_state.actions.values():
        decision = decisions.get(action.decision_id)
        if ((request_id and action.request_id == request_id)
            or (selection_id and decision is not None and decision.tool_selection_id == selection_id)):
            if _successful_progress(action, rebuilt):
                matching.append(action.action_id)
    return matching


def _validate_protocol_identity(payload: Mapping, role: str) -> None:
    module = ROLE_MODULES[role]
    if payload.get("protocol_schema_version") != module.INPUT_SCHEMA_VERSION or payload.get("protocol_sha256") != _digest(Path(module.__file__).read_bytes()):
        raise DatasetIntegrityError(f"runtime attestation protocol mismatch: {role}")


def _review_authority(source: SourceRun, row: Mapping[str, Any]) -> list[str]:
    matching = [review for review in source.reviews
                if review.get("request_id") == row["request_id"] and review.get("role") == row["role"]]
    if not matching:
        return []
    purpose = matching[0].get("purpose")
    semantic = purpose in {"semantic_label", "trace_correction"}
    if row["role"] in {"auditor_step", "auditor_final", "finalizer_answer"} and not semantic:
        raise DatasetIntegrityError("Auditor/Finalizer review must bind semantic label evidence")
    if semantic and row["role"] not in {"selector_intent", "auditor_step", "auditor_final", "finalizer_answer"}:
        raise DatasetIntegrityError("reviewed semantic corrections cannot bypass Executor execution evidence")
    reviewers = set()
    for review in matching:
        if (review.get("input_sha256") != _digest(row["input_text"])
            or review.get("target_sha256") != _digest(row["target_text"])
            or review.get("decision") != "accept" or review.get("purpose") != purpose
            or purpose not in {"failure_recovery_positive", "semantic_label", "trace_correction"}):
            raise DatasetIntegrityError("human review does not bind exact input/target recovery evidence")
        if semantic:
            for key in ("source_run_id", "run_id", "boundary_event_id", "original_output_record_sha256"):
                if review.get(key) != row.get(key) or not row.get(key):
                    raise DatasetIntegrityError(f"human review does not bind exact {key}")
            refs = review.get("evidence_refs")
            if (not isinstance(refs, list) or any(not isinstance(ref, str) for ref in refs)
                    or len(refs) != len(set(refs))
                    or not set(refs) <= set(row["available_evidence_refs"])
                    or not isinstance(review.get("rationale"), str) or not review["rationale"].strip()):
                raise DatasetIntegrityError("human review requires visible evidence and a rationale")
            if purpose == "trace_correction" and (
                review.get("target_text") != row["target_text"]
                or row["target_text"] == row["original_target_text"]
            ):
                raise DatasetIntegrityError("reviewed correction must bind distinct explicit target bytes")
        identity = review.get("reviewer_id")
        if not isinstance(identity, str) or not identity.strip():
            raise DatasetIntegrityError("human reviewer identity is missing")
        reviewers.add(identity)
    if len(reviewers) != 2 or len({reviewer.strip() for reviewer in reviewers}) != 2 or len(matching) != 2:
        raise DatasetIntegrityError("human_double_review requires exactly two distinct reviewers")
    if not semantic and not row["coverage"].get("failed_last_action"):
        raise DatasetIntegrityError("human reviews only label failure recovery positives")
    return sorted(reviewers)


def _review_target(source: SourceRun, role: str, request_id: str, original: str) -> str:
    corrections = [review for review in source.reviews if review.get("role") == role
                   and review.get("request_id") == request_id and review.get("purpose") == "trace_correction"]
    if not corrections:
        return original
    targets = [review.get("target_text") for review in corrections]
    if any(not isinstance(target, str) or not target for target in targets) or len(set(targets)) != 1:
        raise DatasetIntegrityError("human corrections disagree or lack explicit target bytes")
    return targets[0]


def _has_review(source: SourceRun, role: str, request_id: str) -> bool:
    return any(review.get("request_id") == request_id and review.get("role") == role for review in source.reviews)


def _audit_acceptance(events: Sequence[CausalEvent], recorded: CausalEvent,
                      boundary: CausalEvent, canonical_target: str) -> CausalEvent | None:
    from rwkv_lh.goal_loop_protocol import GoalAuditDecision

    payload = recorded.payload
    audit, _ = GoalAuditDecision.parse_with_bindings(canonical_target, audit_id=payload["audit_id"])
    boundary_id = boundary.payload.get("audit_boundary_id")
    opened = [item for item in events if item.event_type == "goal_audit_boundary_opened"
              and item.subject_id == boundary_id and item.sequence < boundary.sequence]
    if len(opened) != 1 or not boundary_id or payload.get("audit_boundary_id") != boundary_id:
        raise DatasetIntegrityError("Auditor output boundary identity mismatch")
    if payload.get("audit") != audit.to_dict() or payload.get("audit_digest") != audit.digest:
        raise DatasetIntegrityError("recorded Auditor decision differs from raw target")
    accepted = [item for item in events if item.event_type == "goal_audit_accepted"
                and item.payload.get("request_id") == payload.get("request_id")]
    if not accepted:
        return None
    if len(accepted) != 1:
        raise DatasetIntegrityError("duplicate Auditor kernel acceptance")
    item = accepted[0]
    if (item.sequence <= recorded.sequence or item.payload.get("kernel_validated") is not True
        or item.payload.get("audit_boundary_id") != boundary_id
        or item.payload.get("boundary") != opened[0].payload.get("boundary")
        or item.payload.get("audit_id") != audit.audit_id
        or item.payload.get("audit_digest") != audit.digest
        or item.payload.get("audit") != audit.to_dict()):
        raise DatasetIntegrityError("Auditor kernel acceptance differs from this boundary and raw decision")
    return item


def _validate_decision_record(source: SourceRun, event: CausalEvent, checkpoint: ModelCheckpoint,
                              command: Any, generation: Mapping[str, Any]) -> None:
    raw = event.payload["raw_generation"]
    decision = source.final_state.decisions.get(str(event.payload.get("decision_id") or ""))
    if decision is None:
        raise SampleExcluded("missing durable command decision")
    if event.payload.get("decision") != decision.to_dict():
        raise DatasetIntegrityError("durable command decision differs from causal event")
    output_id = (generation["candidate_checkpoint_id"] if generation["outcome"] == "committed"
                 else checkpoint.checkpoint_id)
    output = source.final_state.model_states.get(output_id)
    if output is None:
        raise SampleExcluded("missing durable command output checkpoint")
    expected = {
        "request_id": raw["request_id"], "lane_id": checkpoint.lane_id,
        "input_checkpoint_id": checkpoint.checkpoint_id,
        # DecisionRecord stores the transcript digest even for native transport;
        # the physical State digest is checked separately in generation evidence.
        "input_digest": checkpoint.transcript_digest,
        "visible_event_ids": tuple(checkpoint.event_ids), "raw_output": raw["raw_output"],
        "command_digest": command.digest, "sampling": raw["sampling"],
        "model": checkpoint.model, "transport": checkpoint.transport,
        "accepted": True, "output_checkpoint_id": output_id, "output_digest": output.transcript_digest,
    }
    if any(getattr(decision, key) != value for key, value in expected.items()):
        raise DatasetIntegrityError("command decision is not bound to its original generation")
    if (event.payload.get("request_id") != raw["request_id"]
        or event.payload.get("operation") != command.name
        or event.payload.get("wire_command_digest") != command.digest):
        raise DatasetIntegrityError("accepted command event differs from raw command identity")


def _final_acceptance(source: SourceRun, events: Sequence[CausalEvent], recorded: CausalEvent,
                      request_id: str, text: str) -> CausalEvent | None:
    decision_id = recorded.payload.get("decision_id")
    if source.final_state.status.value != "completed" or source.final_state.final_decision_id != decision_id:
        return None
    if source.final_state.final_output != text:
        raise DatasetIntegrityError("completed Finalizer text differs from raw candidate")
    opened = [item for item in events if item.event_type == "goal_audit_boundary_opened"
              and item.payload.get("final_candidate") is True
              and item.payload.get("decision_id") == decision_id
              and item.sequence > recorded.sequence]
    if not opened:
        return None
    if len(opened) != 1:
        raise DatasetIntegrityError("Finalizer has duplicate final candidate audit boundaries")
    gate = opened[0]
    accepted = [item for item in events if item.event_type == "goal_audit_accepted"
                and item.payload.get("audit_boundary_id") == gate.subject_id]
    completed = [item for item in events if item.event_type == "run_completed"
                 and item.payload.get("decision_id") == decision_id]
    if not accepted or not completed:
        return None
    if len(accepted) != 1 or len(completed) != 1:
        raise DatasetIntegrityError("Finalizer completion/audit is not unique")
    audit, completion = accepted[0], completed[0]
    if (not recorded.sequence < gate.sequence < audit.sequence < completion.sequence
        or audit.payload.get("kernel_validated") is not True
        or audit.payload.get("audit", {}).get("verdict") != "ready_for_final"
        or completion.payload.get("audit_id") != audit.payload.get("audit_id")
        or completion.payload.get("audit_boundary_id") != gate.subject_id
        or completion.payload.get("request_id") != request_id
        or completion.payload.get("final_output") != text
        or completion.payload.get("final_output_sha256") != _digest(text)
        or completion.payload.get("rwkv_audit_accepted") is not True
        or completion.payload.get("controller_rewritten") is not False):
        raise DatasetIntegrityError("Finalizer completion is not bound to this candidate and final audit")
    audit_records = [item for item in events if item.event_type == "goal_audit_recorded"
                     and item.payload.get("request_id") == audit.payload.get("request_id")]
    audit_starts = [item for item in events if item.event_type == "goal_auditor_session_started"
                    and item.payload.get("audit_boundary_id") == gate.subject_id
                    and gate.sequence < item.sequence < audit.sequence]
    if len(audit_records) != 1:
        raise SampleExcluded("Finalizer lacks the raw final Auditor decision")
    audit_record = audit_records[0]
    bound_starts = [item for item in audit_starts if item.payload.get("checkpoint_id") == audit_record.payload.get("audit_checkpoint_id")]
    if len(bound_starts) != 1:
        raise SampleExcluded("Finalizer lacks the final Auditor input boundary")
    if audit_record.payload.get("parsed") is not True or audit_record.payload.get("auditor_role") != "auditor_final":
        raise DatasetIntegrityError("Finalizer completion refers to an unparsed or nonfinal audit")
    audit_raw = audit_record.payload.get("raw_generation", {})
    validate_raw_generation(audit_raw)
    audit_command = _parse_original_command(audit_raw)
    if _audit_acceptance(events, audit_record, bound_starts[0], audit_command.canonical) != audit:
        raise DatasetIntegrityError("Finalizer completion borrowed a different Auditor acceptance")
    return audit


def _sample(source: SourceRun, *, role: str, request_id: str, boundary: CausalEvent,
            checkpoint: ModelCheckpoint, rebuilt: Mapping, context: Mapping, target: str,
            target_ids: Sequence[int], authority: str, action_refs: Sequence[str], raw: Mapping,
            original_target: str | None = None) -> dict:
    original = target if original_target is None else original_target
    corrected = target != original
    row = {
        "schema_version": EXTRACTION_SCHEMA, "role": role, "request_id": request_id,
        "run_id": source.final_state.run_id, "source_run_id": source.registration["source_run_id"],
        "project_family": source.registration["project_family"],
        "input_protocol": ROLE_MODULES[role].INPUT_SCHEMA_VERSION,
        "protocol_sha256": source.registration["protocol_sha256"][role],
        "input_text": context["prompt_text"], "target_text": target,
        "protocol_prompt": rebuilt["protocol_prompt"], "protocol_source": rebuilt["prompt_source"],
        "coverage": dict(rebuilt["coverage"]), "boundary_event_id": boundary.event_id,
        "boundary_revision": source.snapshots[boundary.event_id].revision,
        "boundary_refs": list(rebuilt["boundary_refs"]),
        "input_checkpoint_id": checkpoint.checkpoint_id,
        "context": dict(context), "raw_output_token_ids": list(target_ids),
        "original_target_text": original, "original_output_record_sha256": _digest(_canonical(raw)),
        "target_origin": "human_trace_correction" if corrected else "raw_model_output",
        "target_token_ids": tokenizer().encode(target) if corrected else list(target_ids),
        "target_token_ids_source": "local_tokenizer_for_reviewed_target" if corrected else "raw_generation",
        "target_tokenizer_sha256": _digest(VOCAB_PATH.read_bytes()),
        "available_evidence_refs": list(rebuilt.get("evidence_refs", [])),
        "raw_output": dict(raw), "label_authority": authority,
        "label_evidence_action_ids": list(action_refs), "recomputed": True,
    }
    row["sample_id"] = "RT-" + _digest(_canonical({key: row[key] for key in ("source_run_id", "run_id", "request_id", "role", "boundary_event_id")}))
    reviewers = _review_authority(source, row)
    if reviewers:
        row["label_authority"] = "human_double_review"
        row["human_reviewers"] = reviewers
    elif authority == "human_double_review":
        raise SampleExcluded("missing two pinned human recovery reviews")
    return row


def extract_source(source: SourceRun, *, roles: Sequence[str] = tuple(ROLE_MODULES)) -> tuple[list[dict], list[dict]]:
    from rwkv_lh.role_trace_context import reconstruct_context, TraceContextError, bind_server_input_tokens
    from rwkv_lh.role_trace_inputs import rebuild_role_input
    from rwkv_lh.role_trace_generation import (
        GenerationEvidenceError, GenerationEvidenceMissing,
        validate_generation_evidence, validate_selector_generation,
    )

    if not set(roles) <= set(ROLE_MODULES) or not roles:
        raise DatasetIntegrityError("unknown or empty role selection")
    if source.collection_contract is not None and set(roles) != {source.collection_contract["target_role"]}:
        raise DatasetIntegrityError("role-stage extraction must select exactly the frozen target role")
    events = _events(source)
    samples, exclusions = [], []
    starts = {}
    returns = {}
    for event in source.model_trace:
        request_id = event.get("request_id")
        if not request_id:
            continue
        target = starts if event.get("type") == "model_session_generation_started" else returns if event.get("type") == "model_session_generation_returned" else None
        if target is not None:
            if request_id in target:
                raise DatasetIntegrityError("duplicate model request boundary")
            target[request_id] = event
    latest = {}
    consumed_requests = set()
    for event in events:
        payload = event.payload
        if event.event_type in {"goal_role_input_boundary", "tool_schema_disclosed", "goal_auditor_session_started", "goal_finalizer_session_started"}:
            latest[event.event_type] = event
        if event.event_type == "exact_tool_selection_staged" and "selector_intent" in roles:
            from rwkv_lh.exact_tool_selector.network_protocol import NETWORK_SELECTOR_MENU_ORDER_IDS, NetworkSelectorInput
            from rwkv_lh.exact_tool_selector.input_protocol import network_selector_input_protocol
            from rwkv_lh.exact_tool_selector.native_network_protocol import NativeNetworkToolSelection
            from rwkv_lh.model import LongHorizonModel
            selection = payload.get("selection", {})
            raw_ensemble = selection.get("raw_selection", {})
            lanes = raw_ensemble.get("lane_selections", {})
            if not lanes:
                exclusions.append({"event_id": event.event_id, "role": "selector_intent", "reason": "missing_three_menu_lane_records"})
                continue
            if set(lanes) != set(NETWORK_SELECTOR_MENU_ORDER_IDS):
                raise DatasetIntegrityError("Selector requires exactly the three registered menus")
            if len({row.get("trace_id") for row in lanes.values()}) != len(lanes) or len({row.get("selector_checkpoint_id") for row in lanes.values()}) != len(lanes):
                raise DatasetIntegrityError("Selector menus must have independent request/checkpoint identities")
            parsed_lanes = [NativeNetworkToolSelection.from_dict(lanes[menu]) for menu in NETWORK_SELECTOR_MENU_ORDER_IDS]
            ensemble_operation, ensemble_record = LongHorizonModel._selector_ensemble_choice(parsed_lanes, eligible_labels=parsed_lanes[0].eligible_labels)
            if raw_ensemble.get("selected_operation") != ensemble_operation or raw_ensemble.get("menu_order_ensemble") != ensemble_record:
                raise DatasetIntegrityError("Selector ensemble is inconsistent with raw lane votes")
            for menu, raw in lanes.items():
                request_id = str(raw.get("trace_id") or "")
                try:
                    boundary = latest.get("goal_role_input_boundary")
                    if boundary is None or boundary.event_id not in source.snapshots:
                        raise SampleExcluded("missing durable Selector input boundary")
                    checkpoint = source.final_state.model_states.get(str(raw.get("selector_checkpoint_id") or ""))
                    if checkpoint is None:
                        raise SampleExcluded("missing Selector checkpoint")
                    rebuilt = rebuild_role_input("selector_intent", source.snapshots[boundary.event_id], {"boundary_event_id": boundary.event_id, "menu_order_id": menu})
                    expected = rebuilt.get("expected_checkpoint_transcript") or rebuilt.get("full_input_text")
                    if expected is None or checkpoint.transcript != expected or checkpoint.transcript_digest != _digest(expected):
                        raise DatasetIntegrityError("Selector builder/checkpoint byte mismatch")
                    _validate_protocol_identity(raw_ensemble, "selector_intent")
                    if raw.get("profile_id") != "zero" or raw.get("profile_sha256") != ZERO_SHA:
                        raise DatasetIntegrityError("Selector is not explicitly zero State")
                    if checkpoint.state_profile_id != "zero" or checkpoint.state_profile_sha256 != ZERO_SHA or raw.get("model") != checkpoint.model or raw.get("model_sha256") != (checkpoint.native_state_metadata or {}).get("model_sha256"):
                        raise DatasetIntegrityError("Selector raw identity differs from checkpoint")
                    protocol = network_selector_input_protocol(selector_intent_v7.INPUT_SCHEMA_VERSION)
                    network = NetworkSelectorInput.create(
                        current_subtask=rebuilt["network_input"]["current_subtask"],
                        current_progress=rebuilt["network_input"]["current_progress"],
                        eligible_labels=rebuilt["network_input"]["eligible_labels"],
                        menu_order_id=menu,
                    )
                    if raw.get("input_digest") != protocol.input_digest(network) or raw.get("menu_digest") != protocol.menu_digest(network) or raw.get("eligible_labels") != list(network.eligible_labels):
                        raise DatasetIntegrityError("Selector input/menu/eligible labels differ from rebuilt boundary")
                    try:
                        validate_selector_generation(raw, checkpoint, network)
                    except GenerationEvidenceMissing as exc:
                        raise SampleExcluded(str(exc)) from exc
                    except GenerationEvidenceError as exc:
                        raise DatasetIntegrityError(str(exc)) from exc
                    module = ROLE_MODULES["selector_intent"]
                    operation = raw.get("selected_operation")
                    action_refs = _action_authority(source, rebuilt, "", str(selection.get("selection_id") or ""))
                    action_refs = [key for key in action_refs if source.final_state.actions[key].action_type == operation]
                    if action_refs:
                        authority = "executed_fixture"
                    elif rebuilt["eligible_operations"] == [operation]:
                        authority = "planner_contract"
                    elif _has_review(source, "selector_intent", request_id):
                        authority = "human_double_review"
                    else:
                        authority = "pending_human_review"
                    label_source = dict(rebuilt["prompt_source"])
                    label_source.update(selected_operation=operation,
                                        selection_authority=authority if authority != "pending_human_review" else "human_double_review",
                                        selection_verifier_id=boundary.event_id)
                    target = module.render_target(label_source)
                    ids = raw.get("decoder_trace", {}).get("token_ids")
                    if not isinstance(ids, list) or not ids:
                        raise SampleExcluded("missing Selector raw suffix token IDs")
                    try:
                        decoded = tokenizer().decode_bytes(ids).decode("utf-8")
                    except (KeyError, ValueError, UnicodeError) as exc:
                        raise DatasetIntegrityError("Selector suffix token stream cannot be decoded") from exc
                    if any(type(token) is not int or token < 0 for token in ids) or decoded != target:
                        raise DatasetIntegrityError("Selector suffix token trace differs from target")
                    context = {"prompt_text": expected, "prompt_sha256": _digest(expected), "transport": checkpoint.transport,
                               "initial_state": {"profile_id": "zero", "profile_sha256": ZERO_SHA, "model": checkpoint.model, "model_sha256": raw["model_sha256"]},
                               "token_ids": None, "token_ids_complete": False,
                               "local_tokenizer_sha256": _digest(VOCAB_PATH.read_bytes()),
                               "reconstructed_token_ids": tokenizer().encode(expected), "reconstructed_token_ids_include_bos": False,
                               "chain_evidence": [checkpoint.checkpoint_id], "menu_order_id": menu}
                    try:
                        # Selector is one fresh full-prompt forward even though
                        # its checkpoint transport is native_rwkv.
                        context = bind_server_input_tokens(context, {
                            **raw["decoder_trace"],
                            "prompt_token_ids_scope": "full_context" if raw["decoder_trace"].get("prompt_token_ids_scope") == "full_prompt" else "unspecified",
                        })
                    except TraceContextError as exc:
                        raise DatasetIntegrityError(str(exc)) from exc
                    reviewed_target = _review_target(source, "selector_intent", request_id, target)
                    if reviewed_target != target:
                        try:
                            reviewed_operation = module.parse_target(reviewed_target)
                            label_source.update(selected_operation=reviewed_operation, selection_authority="human_double_review")
                            if module.render_target(label_source) != reviewed_target:
                                raise ValueError("noncanonical Selector correction")
                        except ValueError as exc:
                            raise DatasetIntegrityError(f"Selector correction violates the original eligible contract: {exc}") from exc
                    row = _sample(source, role="selector_intent", request_id=request_id, boundary=boundary, checkpoint=checkpoint,
                                  rebuilt=rebuilt, context=context, target=reviewed_target, original_target=target,
                                  target_ids=ids, authority=authority, action_refs=action_refs, raw=raw)
                    if row["label_authority"] == "pending_human_review":
                        raise SampleExcluded("no unique contract or executed advancing label for Selector lane", review_candidate=row)
                    samples.append(row)
                except SampleExcluded as exc:
                    excluded = {"event_id": event.event_id, "request_id": request_id, "role": "selector_intent", "reason": str(exc)}
                    if exc.review_candidate is not None:
                        excluded["review_candidate"] = exc.review_candidate
                    exclusions.append(excluded)
            continue
        if event.event_type not in {"model_call_accepted", "model_call_rejected", "goal_audit_recorded"} or not isinstance(payload.get("raw_generation"), dict):
            continue
        role = (str(payload.get("auditor_role") or "auditor_step") if event.event_type == "goal_audit_recorded"
                else "finalizer_answer" if payload.get("model_role") == "finalizer_answer" else "executor_args")
        raw = payload["raw_generation"]
        request_id = str(raw.get("request_id") or "")
        consumed_requests.add(request_id)
        if role not in roles:
            continue
        try:
            has_review = _has_review(source, role, request_id)
            if event.event_type == "model_call_rejected":
                raise SampleExcluded("rejected generation is context only, not a positive label")
            start, returned = starts.get(request_id), returns.get(request_id)
            if start is None or returned is None:
                raise SampleExcluded("missing raw request/response boundary")
            if returned.get("raw_generation") != raw:
                raise DatasetIntegrityError("durable output differs from original model trace")
            boundary_kind = "tool_schema_disclosed" if role == "executor_args" else "goal_finalizer_session_started" if role == "finalizer_answer" else "goal_auditor_session_started"
            boundary = latest.get(boundary_kind)
            if boundary is None or boundary.event_id not in source.snapshots:
                raise SampleExcluded("missing exact retained role input snapshot")
            checkpoint_id = str(start.get("input_checkpoint_id") or "")
            if boundary.payload.get("checkpoint_id") != checkpoint_id:
                raise DatasetIntegrityError("generation input is not bound to its durable role boundary")
            checkpoint = source.snapshots[boundary.event_id].model_states.get(checkpoint_id)
            if checkpoint is None:
                raise SampleExcluded("missing input checkpoint")
            _validate_protocol_identity(boundary.payload, role)
            if checkpoint.state_profile_id != "zero" or checkpoint.state_profile_sha256 != ZERO_SHA:
                raise DatasetIntegrityError("input checkpoint is not zero State")
            rebuilt = rebuild_role_input(role, source.snapshots[boundary.event_id], {"boundary_event_id": boundary.event_id, "checkpoint_id": checkpoint_id})
            expected = rebuilt.get("expected_checkpoint_transcript")
            if expected is None or checkpoint.transcript != expected:
                raise DatasetIntegrityError("role builder/checkpoint byte mismatch")
            try:
                context = reconstruct_context(checkpoint_id, source.snapshots[boundary.event_id].model_states, source.model_trace)
            except TraceContextError as exc:
                if any(marker in str(exc).lower() for marker in ("mismatch", "digest", "identity", "cycle")):
                    raise DatasetIntegrityError(str(exc)) from exc
                raise SampleExcluded(str(exc)) from exc
            target, target_ids = validate_raw_generation(raw)
            try:
                generation = validate_generation_evidence(request_id, checkpoint, raw, source.model_trace, source.final_state.model_states)
            except GenerationEvidenceMissing as exc:
                raise SampleExcluded(str(exc)) from exc
            except GenerationEvidenceError as exc:
                raise DatasetIntegrityError(str(exc)) from exc
            context["generation_evidence"] = generation
            try:
                context = bind_server_input_tokens(context, raw)
            except TraceContextError as exc:
                raise DatasetIntegrityError(str(exc)) from exc
            if raw.get("response_model") != checkpoint.model:
                raise DatasetIntegrityError("raw response model differs from input checkpoint")
            if role in {"auditor_step", "auditor_final", "finalizer_answer"}:
                # Kernel acceptance proves protocol consistency, not semantic
                # truth. Failed runs and rejected audits can supply the exact
                # review input; no successful later phase is required.
                if role == "finalizer_answer":
                    original_command = _parse_original_command(raw)
                    _validate_decision_record(source, event, checkpoint, original_command, generation)
                    if source.final_state.status.value == "completed":
                        _final_acceptance(source, events, event, request_id, original_command.arguments["text"])
                else:
                    original_command = _parse_original_command(raw) if payload.get("parsed") is True else None
                    if original_command is not None:
                        _audit_acceptance(events, event, boundary, original_command.canonical)
                selected_target = _review_target(source, role, request_id, target)
                row = _sample(source, role=role, request_id=request_id, boundary=boundary,
                              checkpoint=checkpoint, rebuilt=rebuilt, context=context,
                              target=selected_target, original_target=target, target_ids=target_ids,
                              authority="pending_human_review", action_refs=rebuilt["evidence_refs"], raw=raw)
                if row["label_authority"] != "human_double_review":
                    raise SampleExcluded("Auditor/Finalizer semantic target requires independent double review",
                                         review_candidate=row)
                if selected_target == target:
                    if original_command is None:
                        raise DatasetIntegrityError("unparsed audit requires an explicit reviewed correction")
                    canonical_target = original_command.canonical
                else:
                    canonical_target = selected_target
                from rwkv_lh.role_trace_labels import validate_role_target
                try:
                    validate_role_target(role, rebuilt, canonical_target, verifier_id=boundary.event_id)
                except ValueError as exc:
                    raise DatasetIntegrityError(f"reviewed role target/source mismatch: {exc}") from exc
                samples.append(row)
                continue
            command = _parse_original_command(raw)
            if generation["outcome"] != "committed":
                raise DatasetIntegrityError("accepted Executor command lacks its committed generation State")
            _validate_decision_record(source, event, checkpoint, command, generation)
            from rwkv_lh.role_trace_labels import validate_role_target
            try:
                validate_role_target(role, rebuilt, command.canonical, verifier_id=boundary.event_id)
            except ValueError as exc:
                raise DatasetIntegrityError(f"role target/source mismatch: {exc}") from exc
            authority = "executed_fixture"
            actual_actions = [action for action in source.final_state.actions.values() if action.request_id == request_id]
            if not actual_actions:
                raise SampleExcluded("missing actual Executor execution; review cannot replace Harness evidence")
            if any(action.status is not ActionStatus.SUCCEEDED or not (action.result or {}).get("success") for action in actual_actions):
                raise SampleExcluded("failed action output remains negative context even with human review")
            if any(action.action_type != command.name or action.wire_arguments != command.arguments
                   for action in actual_actions):
                raise DatasetIntegrityError("executed action differs from raw Executor command")
            action_refs = _action_authority(source, rebuilt, request_id)
            if not action_refs and not has_review:
                raise SampleExcluded("Executor did not execute successfully and advance a missing root")
            if has_review:
                authority = "human_double_review"
                action_refs = [action.action_id for action in actual_actions]
            samples.append(_sample(source, role=role, request_id=request_id, boundary=boundary, checkpoint=checkpoint, rebuilt=rebuilt,
                                   context=context, target=target, target_ids=target_ids, authority=authority, action_refs=action_refs, raw=raw))
        except SampleExcluded as exc:
            excluded = {"event_id": event.event_id, "request_id": request_id, "role": role, "reason": str(exc)}
            if exc.review_candidate is not None:
                excluded["review_candidate"] = exc.review_candidate
            exclusions.append(excluded)
    for request_id, start in starts.items():
        if request_id not in consumed_requests:
            exclusions.append({"request_id": request_id, "role": start.get("model_role", "unknown"), "reason": "request_has_no_durable_role_output"})
    return samples, exclusions


def extract_registration(registration_path: Path, output_dir: Path, *, roles: Sequence[str] = tuple(ROLE_MODULES),
                         prior_regression: Mapping | None = None, expected_regression_fingerprint: str | None = None,
                         equivalence_waiver: Mapping[str, tuple[str, str]] | None = None,
                         equivalence_waiver_sha256: str | None = None) -> dict:
    from rwkv_lh.role_trace_artifacts import build_artifacts, write_artifacts, validate_coverage_requirements

    if (equivalence_waiver is None) != (equivalence_waiver_sha256 is None):
        raise DatasetIntegrityError("equivalence waiver requires both the reviewed document and its pinned SHA")
    output = validate_output_path(output_dir)
    registration_path = _source_path(Path(registration_path))
    registration = read_registration(registration_path)
    requirements, scope_sha = None, None
    if "coverage_scope" in registration:
        scope = _json(read_artifact(registration["coverage_scope"], registration_path.parent))
        if (not isinstance(scope, Mapping) or set(scope) != {"schema_version", "objective", "requirements"}
                or scope.get("schema_version") != "rwkv-lh.role-trace-coverage-scope.v1"
                or not isinstance(scope.get("objective"), str) or not scope["objective"].strip()):
            raise DatasetIntegrityError("invalid preregistered role coverage scope")
        try:
            requirements = validate_coverage_requirements(scope["requirements"], list(roles))
        except ValueError as exc:
            raise DatasetIntegrityError(str(exc)) from exc
        scope_sha = registration["coverage_scope"]["sha256"]
    samples, exclusions, source_rows = [], [], []
    waived_paths: set[str] = set()
    for record in registration["source_runs"]:
        source = load_source_run(record, base_dir=registration_path.parent, coverage_scope_sha256=scope_sha,
                                 equivalence_waiver=equivalence_waiver)
        waived_paths.update(source.waived_paths)
        rows, rejected = extract_source(source, roles=roles)
        if prior_regression is not None:
            from rwkv_lh.role_trace_artifacts import split_project_family
            kept = []
            for row in rows:
                if split_project_family(row["project_family"]) == "train":
                    kept.append(row)
                else:
                    rejected.append({"request_id": row["request_id"], "role": row["role"], "reason": "new_source_family_belongs_to_immutable_regression_split"})
            rows = kept
        samples.extend(rows)
        exclusions.extend({"run_id": source.final_state.run_id, **row} for row in rejected)
        source_rows.append({**dict(record), "role_data_collection": source.collection_contract})
    provenance = {
        "source_runs": source_rows, "source_registration_sha256": _digest(registration_path.read_bytes()),
        "extractor_sha256": _digest(Path(__file__).read_bytes()),
        "protocol_sha256": {role: _digest(Path(module.__file__).read_bytes()) for role, module in ROLE_MODULES.items()},
        "helper_sha256": {name: _digest((ROOT / "rwkv_lh" / name).read_bytes()) for name in ("role_trace_context.py", "role_trace_inputs.py", "role_trace_artifacts.py", "role_trace_labels.py", "role_trace_generation.py", "role_trace_stages.py")},
        "recomputed_rows": len(samples), "exclusions": exclusions,
        "requested_roles": list(roles),
        "coverage_scope_sha256": scope_sha,
        "equivalence_waiver_sha256": equivalence_waiver_sha256,
        "waived_paths": sorted(waived_paths),
        "server_input_token_ids_complete": all(row["context"].get("token_ids_complete") for row in samples) if samples else False,
        "output_kind": "candidate_audit_only", "training_started": False,
        "formal_dataset_version_created": False,
    }
    bundle = build_artifacts(samples, provenance=provenance, prior_regression=prior_regression,
                             expected_regression_fingerprint=expected_regression_fingerprint,
                             coverage_requirements=requirements)
    return write_artifacts(output, bundle)


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    subparsers = parser.add_subparsers(dest="command", required=True)
    register = subparsers.add_parser("register", help="Hash and verify one frozen production case")
    register.add_argument("--case-dir", type=Path, required=True)
    for name in ("run-id", "source-run-id", "project-family", "suite"):
        register.add_argument("--" + name, required=True)
    register.add_argument("--output", type=Path, required=True)
    extract = subparsers.add_parser("extract", help="Write an immutable role candidate audit")
    extract.add_argument("--registration", type=Path, required=True)
    extract.add_argument("--output", type=Path, required=True)
    extract.add_argument("--role", action="append", choices=tuple(ROLE_MODULES))
    extract.add_argument("--prior-regression", type=Path, help="Explicitly provided frozen regression artifact (never inferred)")
    extract.add_argument("--regression-sha256", help="Pinned SHA-256 from the prior freeze registration")
    extract.add_argument("--expected-regression-fingerprint", help="Pinned regression identity, independent of the supplied file")
    extract.add_argument("--equivalence-waiver", type=Path, help="Double-reviewed source equivalence waiver (never inferred)")
    extract.add_argument("--waiver-sha256", help="Pinned SHA-256 of the equivalence waiver document")
    args = parser.parse_args(argv)
    try:
        if args.command == "register":
            output = validate_output_path(args.output)
            value = register_case(args.case_dir, run_id=args.run_id, source_run_id=args.source_run_id,
                                  project_family=args.project_family, suite=args.suite)
            output.parent.mkdir(parents=True, exist_ok=True)
            with output.open("x", encoding="utf-8") as handle:
                handle.write(_canonical(value) + "\n")
            print(_canonical({"registration": str(output), "source_count": 1}))
            return 0
        prior = None
        if any((args.prior_regression, args.regression_sha256, args.expected_regression_fingerprint)):
            if not all((args.prior_regression, args.regression_sha256, args.expected_regression_fingerprint)):
                raise DatasetIntegrityError("regression reuse requires a file and both independent pins")
            prior = _json(read_artifact({"path": str(args.prior_regression.resolve()), "sha256": args.regression_sha256}, ROOT))
        waiver = None
        if any((args.equivalence_waiver, args.waiver_sha256)):
            if not all((args.equivalence_waiver, args.waiver_sha256)):
                raise DatasetIntegrityError("equivalence waiver requires a file and its independent pin")
            waiver = read_equivalence_waiver(args.equivalence_waiver.resolve(), args.waiver_sha256)
        manifest = extract_registration(args.registration, args.output, roles=args.role or tuple(ROLE_MODULES),
                                        prior_regression=prior, expected_regression_fingerprint=args.expected_regression_fingerprint,
                                        equivalence_waiver=waiver,
                                        equivalence_waiver_sha256=args.waiver_sha256 if waiver is not None else None)
        print(_canonical(manifest))
        return 0 if manifest.get("status") == "valid" else 2
    except (ValueError, OSError, sqlite3.Error) as exc:
        print(_canonical({"status": "rejected", "error": str(exc)}))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

rwkv_lh/exact_tool_selector/runtime_proj:
"""Project exactly one Planner-owned current subtask into the Selector lane."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from dataclasses import dataclass

from rwkv_lh.exact_tool_selector.network_protocol import NetworkSelectorInput


SELECTOR_CURRENT_SUBTASK_PROJECTION_VERSION = (
    "rwkv-lh.selector-current-subtask.v1"
)
_PHASES = {"observe", "mutate", "execute", "derive_evidence"}


@dataclass(frozen=True)
class SelectorStageContext:
    """The complete semantic input for one independent Selector evaluation."""

    current_subtask: Mapping[str, object]
    current_progress: Mapping[str, object] | None = None

    def __post_init__(self) -> None:
        normalized = dict(self.current_subtask)
        # Share the production validator with serving and StateTune data.
        progress = (
            None
            if self.current_progress is None
            else dict(self.current_progress)
        )
        validated = NetworkSelectorInput.create(
            current_subtask=normalized,
            current_progress=progress,
        )
        object.__setattr__(self, "current_subtask", validated.current_subtask)
        object.__setattr__(self, "current_progress", validated.current_progress)


def goal_frontier_selector_context(
    frontier: Mapping[str, object],
    *,
    current_progress: Mapping[str, object] | None = None,
) -> SelectorStageContext:
    """Reduce one Controller frontier to the six Planner-owned subtask fields.

    Raw action results, audit transcripts, arguments, and WKV state are absent.
    A caller may attach the bounded mechanical current-progress projection used
    by Selector Intent v3; it remains independent of any recurrent parent.
    """

    objective = str(frontier.get("objective") or "").strip()
    phase = str(
        frontier.get("effective_phase") or frontier.get("phase") or ""
    ).strip()
    if not objective:
        raise ValueError("Goal frontier Selector context requires an objective")
    if phase not in _PHASES:
        raise ValueError("Goal frontier Selector context has an invalid phase")

    def strings(name: str) -> list[str]:
        raw = frontier.get(name) or ()
        if isinstance(raw, (str, bytes)) or not isinstance(raw, Sequence):
            raise ValueError(f"Goal frontier {name} must be a string sequence")
        values = [str(item).strip() for item in raw]
        if any(not item for item in values):
            raise ValueError(f"Goal frontier {name} contains an empty value")
        return values

    current_subtask = {
        "objective": objective,
        "phase": phase,
        "read_roots": strings("read_roots"),
        "write_roots": strings("write_roots"),
        "success_evidence": strings("success_evidence"),
        "constraints": strings("constraints"),
    }
    if not current_subtask["success_evidence"]:
        raise ValueError("Goal frontier Selector context requires success evidence")
    return SelectorStageContext(
        current_subtask=current_subtask,
        current_progress=current_progress,
    )


def build_network_selector_input(
    stage_context: SelectorStageContext,
    *,
    eligible_labels: Sequence[str] | None = None,
    menu_order_id: str = "canonical",
) -> NetworkSelectorInput:
    """Build a fresh request; there is deliberately no parent-state argument."""

    values: dict[str, object] = {
        "current_subtask": dict(stage_context.current_subtask),
        "menu_order_id": menu_order_id,
    }
    if stage_context.current_progress is not None:
        values["current_progress"] = dict(stage_context.current_progress)
    if eligible_labels is not None:
        values["eligible_labels"] = tuple(str(item) for item in eligible_labels)
    return NetworkSelectorInput.create(**values)


__all__ = [
    "SELECTOR_CURRENT_SUBTASK_PROJECTION_VERSION",
    "SelectorStageContext",
    "build_network_selector_input",
    "goal_frontier_selector_context",
]

rwkv_lh/exact_tool_selector/network_prot:
"""Current 23-operation protocol for the fresh current-subtask Selector."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Any

from rwkv_lh.goal_state_protocols import selector_intent_v7
from rwkv_lh.model_io import canonical_digest, canonical_json

NETWORK_SELECTOR_INPUT_SCHEMA_VERSION = "rwkv-lh.exact-tool-selector-input.v5"
NETWORK_SELECTOR_MENU_SCHEMA_VERSION = "rwkv-lh.exact-tool-menu.v3"

NETWORK_EXACT_TOOL_LABELS = (
    "list_directory",
    "search_text",
    "read_file",
    "read_json",
    "file_digest",
    "write_file",
    "write_json",
    "patch_json",
    "replace_text",
    "remove_line",
    "append_file",
    "make_directory",
    "copy_file",
    "move_file",
    "delete_file",
    "bind_evidence",
    "check_command",
    "run_command",
    "web_search",
    "connector_lookup",
    "calculator",
    "date_diff",
    "current_time",
)
NETWORK_SELECTOR_MENU_ORDER_IDS = ("canonical", "rotate_8", "rotate_17")
_NETWORK_SELECTOR_MENU_ROTATIONS = {
    "canonical": 0,
    "rotate_8": 8,
    "rotate_17": 17,
}

# These mutually contrastive descriptions are the frozen G1J Selector-Intent
# menu. They identify operation semantics without exposing parameter schemas.
_NETWORK_TOOL_DESCRIPTIONS = {
    "list_directory": "Local metadata only: list bounded paths, types, and sizes; never file contents.",
    "search_text": "Local text only: find regex or literal lines; never search the public web.",
    "read_file": "Read a bounded byte range from one local non-JSON UTF-8 file.",
    "read_json": "Parse one local JSON file and read bounded canonical JSON.",
    "file_digest": "Observe one local file's SHA-256 and byte size without reading or changing it.",
    "write_file": "Create or replace one complete local non-JSON UTF-8 file.",
    "write_json": "Create or replace one complete local JSON value.",
    "patch_json": "Update named top-level JSON keys while preserving all unspecified keys.",
    "replace_text": "Replace one exact text occurrence inside a local UTF-8 file.",
    "remove_line": "Remove one complete exact line from a local UTF-8 file.",
    "append_file": "Append text after the existing bytes of a local file.",
    "make_directory": "Create one local workspace directory, not a file.",
    "copy_file": "Copy exact file bytes to a new path and keep the source.",
    "move_file": "Move or rename a file so the old source path disappears.",
    "delete_file": "Delete one explicitly scoped local workspace path.",
    "bind_evidence": "Bind an already observed local line span with its locator and exact quote.",
    "check_command": "Run a read-only local test, linter, status, or inspection argv.",
    "run_command": "Run a local argv that may intentionally modify workspace contents.",
    "web_search": "Search or fetch the public web; never search local workspace files.",
    "connector_lookup": "Query a structured public repository, package, paper, weather, or alert record.",
    "calculator": "Evaluate arithmetic using operands that are already known.",
    "date_diff": "Compute calendar-day distance between two already known ISO dates.",
    "current_time": "Observe the current clock time for one IANA timezone.",
}


def network_selector_label_order(
    menu_order_id: str = "canonical",
) -> tuple[str, ...]:
    """Return one of the three pre-registered deterministic menu orders."""

    selected_id = str(menu_order_id or "").strip()
    if selected_id not in _NETWORK_SELECTOR_MENU_ROTATIONS:
        raise ValueError(f"unknown network Selector menu order: {selected_id!r}")
    offset = _NETWORK_SELECTOR_MENU_ROTATIONS[selected_id]
    return NETWORK_EXACT_TOOL_LABELS[offset:] + NETWORK_EXACT_TOOL_LABELS[:offset]


def network_selector_tool_menu(
    menu_order_id: str = "canonical",
) -> tuple[dict[str, str], ...]:
    """Return one fixed 23-name permutation and no parameter schemas."""

    if set(_NETWORK_TOOL_DESCRIPTIONS) != set(NETWORK_EXACT_TOOL_LABELS):
        raise RuntimeError("network Selector descriptions differ from class order")
    return tuple(
        {"name": name, "description": _NETWORK_TOOL_DESCRIPTIONS[name]}
        for name in network_selector_label_order(menu_order_id)
    )


def network_selector_menu_digest(
    menu: Sequence[Mapping[str, str]] | None = None,
) -> str:
    selected = network_selector_tool_menu() if menu is None else menu
    return canonical_digest(
        {
            "schema_version": NETWORK_SELECTOR_MENU_SCHEMA_VERSION,
            "tools": [dict(item) for item in selected],
        }
    )


@dataclass(frozen=True)
class NetworkSelectorInput:
    """One independent current subtask consumed from the learned initial State."""

    current_subtask: Mapping[str, Any]
    menu: tuple[Mapping[str, str], ...]
    current_progress: Mapping[str, Any] | None = None
    eligible_labels: tuple[str, ...] = NETWORK_EXACT_TOOL_LABELS
    menu_order_id: str = "canonical"
    schema_version: str = NETWORK_SELECTOR_INPUT_SCHEMA_VERSION

    def __post_init__(self) -> None:
        if self.schema_version != NETWORK_SELECTOR_INPUT_SCHEMA_VERSION:
            raise ValueError(
                f"unsupported network Selector input schema: {self.schema_version}"
            )
        subtask = dict(self.current_subtask)
        expected_subtask_fields = {
            "objective",
            "phase",
            "read_roots",
            "write_roots",
            "success_evidence",
            "constraints",
        }
        if set(subtask) != expected_subtask_fields:
            raise ValueError("network Selector current subtask fields mismatch")
        if not str(subtask["objective"] or "").strip():
            raise ValueError("network Selector current subtask requires an objective")
        if subtask["phase"] not in {
            "observe",
            "mutate",
            "execute",
            "derive_evidence",
        }:
            raise ValueError("network Selector current subtask phase is invalid")
        for name in ("read_roots", "write_roots", "success_evidence", "constraints"):
            values = subtask[name]
            if not isinstance(values, list) or any(
                not isinstance(item, str) or not item.strip() for item in values
            ):
                raise ValueError(f"network Selector current subtask {name} is invalid")
        if not subtask["success_evidence"]:
            raise ValueError("network Selector current subtask requires success evidence")
        progress = (
            None
            if self.current_progress is None
            else dict(self.current_progress)
        )
        if progress is not None:
            # The single production Selector input contract.  Production,
            # StateTune data generation, and acceptance evaluation share this
            # current role validator; older progress shapes are rejected.
            progress = dict(
                selector_intent_v7.validate_progress(
                    progress,
                    read_roots=subtask["read_roots"],
                    write_roots=subtask["write_roots"],
                )
            )
            progress["last_action"] = (
                None
                if progress["last_action"] is None
                else dict(progress["last_action"])
            )
        if any(set(item) != {"name", "description"} for item in self.menu):
            raise ValueError(
                "network Selector menu may contain only name and description"
            )
        normalized = tuple(
            {
                "name": str(item.get("name") or ""),
                "description": str(item.get("description") or ""),
            }
            for item in self.menu
        )
        expected_menu_order = network_selector_label_order(self.menu_order_id)
        if tuple(item["name"] for item in normalized) != expected_menu_order:
            raise ValueError(
                "network Selector menu labels/order differ from the declared order"
            )
        if any(not item["description"].strip() for item in normalized):
            raise ValueError("network Selector menu descriptions must be non-empty")
        eligible = tuple(str(item) for item in self.eligible_labels)
        if not eligible or len(set(eligible)) != len(eligible):
            raise ValueError("network Selector eligible labels must be non-empty and unique")
        unknown = set(eligible) - set(NETWORK_EXACT_TOOL_LABELS)
        if unknown:
            raise ValueError(
                f"network Selector eligibility contains unknown labels: {sorted(unknown)}"
            )
        expected_order = tuple(
            label for label in NETWORK_EXACT_TOOL_LABELS if label in set(eligible)
        )
        if eligible != expected_order:
            raise ValueError("network Selector eligible labels differ from class order")
        object.__setattr__(self, "menu", normalized)
        object.__setattr__(self, "eligible_labels", eligible)
        object.__setattr__(self, "current_subtask", subtask)
        object.__setattr__(self, "current_progress", progress)

    @classmethod
    def create(
        cls,
        *,
        current_subtask: Mapping[str, Any],
        current_progress: Mapping[str, Any] | None = None,
        eligible_labels: Sequence[str] = NETWORK_EXACT_TOOL_LABELS,
        menu_order_id: str = "canonical",
    ) -> NetworkSelectorInput:
        return cls(
            current_subtask=dict(current_subtask),
            menu=network_selector_tool_menu(menu_order_id),
            current_progress=(
                None if current_progress is None else dict(current_progress)
            ),
            eligible_labels=tuple(str(item) for item in eligible_labels),
            menu_order_id=str(menu_order_id),
        )

    @property
    def menu_digest(self) -> str:
        return network_selector_menu_digest(self.menu)

    def bootstrap_payload(self) -> dict[str, Any]:
        return {
            "schema_version": NETWORK_SELECTOR_INPUT_SCHEMA_VERSION,
            "menu_schema_version": NETWORK_SELECTOR_MENU_SCHEMA_VERSION,
            "menu_digest": self.menu_digest,
            "tools": [dict(item) for item in self.menu],
        }

    def step_payload(self) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "schema_version": NETWORK_SELECTOR_INPUT_SCHEMA_VERSION,
            "current_subtask": dict(self.current_subtask),
        }
        if self.current_progress is not None:
            payload["current_progress"] = dict(self.current_progress)
        return payload

    def to_dict(self) -> dict[str, Any]:
        return {
            **self.bootstrap_payload(),
            **self.step_payload(),
            "eligible_labels": list(self.eligible_labels),
            "menu_order_id": self.menu_order_id,
        }

    def render_bootstrap(self) -> str:
        return "SelectorBootstrapV2: " + canonical_json(self.bootstrap_payload())

    def render_step(self) -> str:
        return "SelectorStepV2: " + canonical_json(self.step_payload())

    def render(self) -> str:
        return self.render_bootstrap() + "\n" + self.render_step()


def validate_network_label(label: str) -> str:
    selected = str(label or "")
    if selected not in NETWORK_EXACT_TOOL_LABELS:
        raise ValueError(f"unknown network Selector label: {selected!r}")
    return selected


__all__ = [
    "NETWORK_EXACT_TOOL_LABELS",
    "NETWORK_SELECTOR_INPUT_SCHEMA_VERSION",
    "NETWORK_SELECTOR_MENU_ORDER_IDS",
    "NETWORK_SELECTOR_MENU_SCHEMA_VERSION",
    "NetworkSelectorInput",
    "network_selector_label_order",
    "network_selector_menu_digest",
    "network_selector_tool_menu",
    "validate_network_label",
]

rwkv_lh/exact_tool_selector/native_netwo:
"""Native G1J Selector service using only the frozen LM head and token trie."""

from __future__ import annotations

import argparse
import hashlib
import json
import threading
from collections.abc import Mapping
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any, Protocol

from rwkv_lh.exact_tool_selector.input_protocol import (
    CURRENT_G1J_NETWORK_SELECTOR_INPUT_PROTOCOL,
    network_selector_input_protocol,
)
from rwkv_lh.exact_tool_selector.native_network_client import (
    NATIVE_SELECTOR_SERVICE_REQUEST_SCHEMA,
    NATIVE_SELECTOR_SERVICE_RESPONSE_SCHEMA,
    NATIVE_SELECTOR_WKV_MODE,
    NativeNetworkSelectorSettings,
)
from rwkv_lh.exact_tool_selector.native_network_protocol import (
    NATIVE_SELECTOR_DECODER_ID,
    NATIVE_SELECTOR_DECODER_PROTOCOL,
    NativeNetworkToolSelection,
)
from rwkv_lh.exact_tool_selector.network_protocol import (
    NETWORK_EXACT_TOOL_LABELS,
    NetworkSelectorInput,
)
from rwkv_lh.inference.vllm_rwkv import PersistentVLLMRWKVExtractor
from rwkv_lh.goal_state_protocols import selector_intent_v7
from rwkv_lh.model_io import canonical_digest
from rwkv_lh.state_router.local_backend import LocalVLLMRWKVSettings


NATIVE_SELECTOR_DECODER_MANIFEST_SCHEMA = (
    "rwkv-lh.native-selector-decoder-manifest.v1"
)
_REQUEST_KEYS = {
    "schema_version",
    "run_id",
    "trace_id",
    "input_digest",
    "menu_digest",
    "menu_order_id",
    "eligible_labels",
    "bootstrap",
    "step",
    "expected_identity",
}
_MANIFEST_KEYS = {
    "schema_version",
    "decoder_id",
    "decoder_protocol",
    "input_protocol",
    "target_prefix",
    "labels",
    "algorithm",
    "token_tie_break",
    "state_policy",
    "menu_aggregation",
    "downstream_decoder_trained",
    "generated_text",
}


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


class NativeNetworkSelectorServiceError(ValueError):
    """A native Selector request or artifact violated the frozen contract."""


class _NativeSuffixExtractor(Protocol):
    def select_suffix_choices(
        self,
        prompt: str,
        *,
        candidate_suffixes: Mapping[str, str],
    ) -> tuple[Mapping[str, Any], Mapping[str, Any]]: ...


def load_native_selector_decoder_manifest(
    path: Path,
    expected_sha256: str,
) -> dict[str, Any]:
    """Load the non-learned decoder identity and reject contract drift."""

    resolved = path.resolve()
    if not resolved.is_file() or _sha256_file(resolved) != expected_sha256:
        raise ValueError("native Selector decoder manifest SHA-256 mismatch")
    value = json.loads(resolved.read_text(encoding="utf-8"))
    if not isinstance(value, dict) or set(value) != _MANIFEST_KEYS:
        raise ValueError("native Selector decoder manifest fields mismatch")
    expected = {
        "schema_version": NATIVE_SELECTOR_DECODER_MANIFEST_SCHEMA,
        "decoder_id": NATIVE_SELECTOR_DECODER_ID,
        "decoder_protocol": NATIVE_SELECTOR_DECODER_PROTOCOL,
        "input_protocol": CURRENT_G1J_NETWORK_SELECTOR_INPUT_PROTOCOL,
        "target_prefix": selector_intent_v7.TARGET_PREFIX,
        "labels": list(NETWORK_EXACT_TOOL_LABELS),
        "algorithm": "eligible_token_sequence_trie_vocab_logit_argmax",
        "token_tie_break": "lowest_token_id",
        "state_policy": "fresh_initial_state_per_evaluation",
        "menu_aggregation": "majority_then_registered_class_order",
        "downstream_decoder_trained": False,
        "generated_text": False,
    }
    if value != expected:
        raise ValueError("native Selector decoder manifest identity mismatch")
    return value


class NativeNetworkSelectorService:
    """Select one eligible operation from a fresh G1J initial State."""

    def __init__(
        self,
        settings: NativeNetworkSelectorSettings,
        extractor: _NativeSuffixExtractor,
        decoder_manifest: Mapping[str, Any],
    ) -> None:
        expected_manifest = {
            "schema_version": NATIVE_SELECTOR_DECODER_MANIFEST_SCHEMA,
            "decoder_id": settings.decoder_id,
            "decoder_protocol": settings.decoder_protocol,
            "input_protocol": settings.input_protocol,
            "target_prefix": selector_intent_v7.TARGET_PREFIX,
            "labels": list(NETWORK_EXACT_TOOL_LABELS),
            "algorithm": "eligible_token_sequence_trie_vocab_logit_argmax",
            "token_tie_break": "lowest_token_id",
            "state_policy": "fresh_initial_state_per_evaluation",
            "menu_aggregation": "majority_then_registered_class_order",
            "downstream_decoder_trained": False,
            "generated_text": False,
        }
        if dict(decoder_manifest) != expected_manifest:
            raise ValueError("native Selector decoder manifest differs from settings")
        self.settings = settings
        self.input_protocol = network_selector_input_protocol(settings.input_protocol)
        self.extractor = extractor
        self._lock = threading.Lock()

    @staticmethod
    def _parse_prefixed_json(text: str, prefix: str) -> dict[str, Any]:
        if not text.startswith(prefix):
            raise NativeNetworkSelectorServiceError(
                f"native Selector input lacks {prefix.rstrip()!r}"
            )
        try:
            value = json.loads(text[len(prefix) :])
        except json.JSONDecodeError as exc:
            raise NativeNetworkSelectorServiceError(
                "native Selector rendered input is invalid JSON"
            ) from exc
        if not isinstance(value, dict):
            raise NativeNetworkSelectorServiceError(
                "native Selector rendered payload must be an object"
            )
        return value

    def _parse_bootstrap(self, text: str) -> dict[str, Any]:
        marker = self.input_protocol.task_marker
        if text.count(marker) != 1:
            raise NativeNetworkSelectorServiceError(
                "native Selector bootstrap must contain one menu and role"
            )
        menu_text, role_json = text.split(marker, 1)
        menu = self._parse_prefixed_json(
            menu_text, self.input_protocol.menu_prefix
        )
        role = self._parse_prefixed_json(
            self.input_protocol.task_prefix + role_json,
            self.input_protocol.task_prefix,
        )
        if set(role) != {"schema_version"} or role.get("schema_version") != (
            CURRENT_G1J_NETWORK_SELECTOR_INPUT_PROTOCOL
        ):
            raise NativeNetworkSelectorServiceError(
                "native Selector role fields changed"
            )
        return menu

    def _input(self, request: Mapping[str, Any]) -> NetworkSelectorInput:
        step_text = str(request["step"])
        step = self._parse_prefixed_json(
            step_text, self.input_protocol.step_prefix
        )
        if set(step) != {
            "schema_version",
            "role",
            "eligible_labels",
            "current_subtask",
            "current_progress",
            "current_question",
        }:
            raise NativeNetworkSelectorServiceError(
                "G1J Selector-Intent v7 prompt fields changed"
            )
        if (
            step.get("schema_version") != CURRENT_G1J_NETWORK_SELECTOR_INPUT_PROTOCOL
            or step.get("role") != "selector_intent"
            or list(step.get("eligible_labels") or ())
            != list(request.get("eligible_labels") or ())
            or not isinstance(step.get("current_subtask"), Mapping)
            or not isinstance(step.get("current_progress"), Mapping)
        ):
            raise NativeNetworkSelectorServiceError(
                "G1J Selector-Intent v7 prompt identity changed"
            )
        selector_input = NetworkSelectorInput.create(
            current_subtask=dict(step["current_subtask"]),
            current_progress=dict(step["current_progress"]),
            eligible_labels=tuple(request.get("eligible_labels") or ()),
            menu_order_id=str(request.get("menu_order_id") or ""),
        )
        bootstrap = self._parse_bootstrap(str(request["bootstrap"]))
        if self.input_protocol.bootstrap_payload(selector_input) != bootstrap:
            raise NativeNetworkSelectorServiceError(
                "native Selector bootstrap payload is not canonical"
            )
        if self.input_protocol.render_bootstrap(selector_input) != request["bootstrap"]:
            raise NativeNetworkSelectorServiceError(
                "native Selector bootstrap is not canonical"
            )
        if self.input_protocol.render_step(selector_input) != step_text:
            raise NativeNetworkSelectorServiceError(
                "native Selector step is not canonical"
            )
        if self.input_protocol.menu_digest(selector_input) != request["menu_digest"]:
            raise NativeNetworkSelectorServiceError(
                "native Selector menu digest mismatch"
            )
        if self.input_protocol.input_digest(selector_input) != request["input_digest"]:
            raise NativeNetworkSelectorServiceError(
                "native Selector input digest mismatch"
            )
        return selector_input

    def _validate_extractor_identity(self, identity: Mapping[str, Any]) -> None:
        expected = {
            "model_weights_sha256": self.settings.model_sha256,
            "wkv_mode": NATIVE_SELECTOR_WKV_MODE,
            "max_tokens": self.settings.context_tokens,
            "feature_protocol": "rwkv-lh.native-role-suffix-selection.v1",
            "fresh_initial_state": True,
            "one_prompt_forward": True,
            "post_prompt_state_clones": 0,
            "token_sequence_exact": True,
            "expected_label_supplied": False,
            "teacher_forcing_invoked": False,
            "unrestricted_generation_invoked": False,
            "generated_rwkv_text": False,
            "sampling_invoked": False,
            "downstream_decoder_trained": False,
        }
        if any(identity.get(key) != value for key, value in expected.items()):
            raise NativeNetworkSelectorServiceError(
                "native Selector extractor identity mismatch"
            )
        runtime = identity.get("runtime")
        if not isinstance(runtime, Mapping) or any(runtime.get(key) != value for key, value in {
            "wkv_mode": NATIVE_SELECTOR_WKV_MODE,
            "wkv_state_dtype": "torch.float32",
            "runtime_compute_dtype": "torch.float16",
        }.items()):
            raise NativeNetworkSelectorServiceError("native Selector arithmetic identity mismatch")
        state_profile = identity.get("state_profile")
        if self.settings.state_profile_id == "zero":
            if state_profile is not None:
                raise NativeNetworkSelectorServiceError(
                    "zero native Selector unexpectedly loaded a State profile"
                )
            return
        expected_profile = {
            "manifest_sha256": self.settings.state_profile_manifest_sha256,
            "id": self.settings.state_profile_id,
            "sha256": self.settings.state_profile_sha256,
        }
        if not isinstance(state_profile, Mapping) or any(
            state_profile.get(key) != value
            for key, value in expected_profile.items()
        ):
            raise NativeNetworkSelectorServiceError(
                "native Selector loaded State profile identity mismatch"
            )

    def select(self, request: Mapping[str, Any]) -> dict[str, Any]:
        if set(request) != _REQUEST_KEYS:
            raise NativeNetworkSelectorServiceError(
                "native Selector request fields mismatch"
            )
        if request.get("schema_version") != NATIVE_SELECTOR_SERVICE_REQUEST_SCHEMA:
            raise NativeNetworkSelectorServiceError(
                "unsupported native Selector request schema"
            )
        if request.get("expected_identity") != self.settings.runtime_identity():
            raise NativeNetworkSelectorServiceError(
                "native Selector expected runtime identity mismatch"
            )
        if not str(request.get("run_id") or "").strip() or not str(
            request.get("trace_id") or ""
        ).strip():
            raise NativeNetworkSelectorServiceError(
                "native Selector run/trace identity is missing"
            )
        request_digest = canonical_digest(dict(request))
        with self._lock:
            selector_input = self._input(request)
            full_text = (
                self.input_protocol.render_bootstrap(selector_input)
                + "\n"
                + self.input_protocol.render_step(selector_input)
            )
            suffixes = {
                label: selector_intent_v7.TARGET_PREFIX + label
                for label in selector_input.eligible_labels
            }
            decoder_trace, extractor_identity = self.extractor.select_suffix_choices(
                full_text,
                candidate_suffixes=suffixes,
            )
            self._validate_extractor_identity(extractor_identity)
            if (
                decoder_trace.get("schema_version")
                != "rwkv-lh.native-role-suffix-selection.v1"
                or list(decoder_trace.get("candidate_labels") or ())
                != list(selector_input.eligible_labels)
                or decoder_trace.get("selected_label")
                not in selector_input.eligible_labels
            ):
                raise NativeNetworkSelectorServiceError(
                    "native Selector decoder result is inconsistent"
                )
            suffix = request_digest[:24]
            selection = NativeNetworkToolSelection(
                selection_id=f"NSEL-{suffix}",
                trace_id=str(request["trace_id"]),
                selected_operation=str(decoder_trace["selected_label"]),
                input_digest=str(request["input_digest"]),
                menu_digest=str(request["menu_digest"]),
                selector_checkpoint_id=f"NSCP-{suffix}",
                input_token_count=int(decoder_trace["prompt_token_count"]),
                model=self.settings.model,
                model_sha256=self.settings.model_sha256,
                decoder_id=self.settings.decoder_id,
                decoder_sha256=self.settings.decoder_sha256,
                decoder_protocol=self.settings.decoder_protocol,
                profile_id=self.settings.state_profile_id,
                profile_sha256=self.settings.state_profile_sha256,
                decoder_trace=dict(decoder_trace),
                eligible_labels=selector_input.eligible_labels,
            )
            return {
                "schema_version": NATIVE_SELECTOR_SERVICE_RESPONSE_SCHEMA,
                "runtime_identity": self.settings.runtime_identity(),
                "selection": selection.raw_record(),
            }


def _handler(service: NativeNetworkSelectorService):
    class Handler(BaseHTTPRequestHandler):
        def _json(self, status: int, value: Mapping[str, Any]) -> None:
            payload = json.dumps(value, ensure_ascii=False).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            self.wfile.write(payload)

        def do_GET(self) -> None:  # noqa: N802
            if self.path != "/healthz":
                self._json(404, {"error": "not_found"})
                return
            self._json(
                200,
                {
                    "status": "ok",
                    "runtime_identity": service.settings.runtime_identity(),
                },
            )

        def do_POST(self) -> None:  # noqa: N802
            if self.path != service.input_protocol.endpoint:
                self._json(404, {"error": "not_found"})
                return
            try:
                length = int(self.headers.get("Content-Length") or "0")
                if length < 2 or length > 2_000_000:
                    raise NativeNetworkSelectorServiceError(
                        "invalid request body size"
                    )
                value = json.loads(self.rfile.read(length).decode("utf-8"))
                if not isinstance(value, Mapping):
                    raise NativeNetworkSelectorServiceError(
                        "request body must be an object"
                    )
                response = service.select(value)
            except (NativeNetworkSelectorServiceError, TypeError, ValueError) as exc:
                self._json(
                    400,
                    {"error": type(exc).__name__, "message": str(exc)[:2000]},
                )
                return
            except Exception as exc:
                self._json(
                    500,
                    {"error": type(exc).__name__, "message": str(exc)[:1000]},
                )
                return
            self._json(200, response)

        def log_message(self, format: str, *args: object) -> None:
            return

    return Handler


def _extractor_state_profile_settings(
    *,
    profile_manifest: Path | None,
    profile_manifest_sha256: str,
    profile_id: str,
    profile_sha256: str,
) -> dict[str, object]:
    zero_sha256 = "0" * 64
    if profile_manifest is None:
        if (
            profile_manifest_sha256 != zero_sha256
            or profile_id != "zero"
            or profile_sha256 != zero_sha256
        ):
            raise ValueError(
                "a manifest-free native Selector must use exact zero-State identity"
            )
        return {
            "state_profile_manifest": None,
            "state_profile_manifest_sha256": "",
            "state_profile_id": "",
            "state_profile_sha256": "",
        }
    return {
        "state_profile_manifest": profile_manifest,
        "state_profile_manifest_sha256": profile_manifest_sha256,
        "state_profile_id": profile_id,
        "state_profile_sha256": profile_sha256,
    }


def model_context_tokens(model_artifact: Path, requested: int | None) -> int:
    config = json.loads((model_artifact / "config.json").read_text(encoding="utf-8"))
    capacity = config.get("context_length")
    if type(capacity) is not int or capacity < 8 or config.get("max_position_embeddings") != capacity:
        raise ValueError("native Selector model context identity is invalid")
    value = capacity if requested is None else requested
    if type(value) is not int or not 8 <= value <= capacity:
        raise ValueError("native Selector context exceeds model capacity")
    return value


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=29621)
    parser.add_argument("--engine-root", type=Path, required=True)
    parser.add_argument("--engine-revision", required=True)
    parser.add_argument("--engine-python", type=Path, required=True)
    parser.add_argument("--engine-source-manifest", type=Path)
    parser.add_argument("--engine-source-manifest-sha256", default="")
    parser.add_argument("--model-artifact", type=Path, required=True)
    parser.add_argument("--model-name", required=True)
    parser.add_argument("--model-sha256", required=True)
    parser.add_argument("--context-tokens", type=int)
    parser.add_argument("--decoder-manifest", type=Path, required=True)
    parser.add_argument("--decoder-sha256", required=True)
    parser.add_argument(
        "--input-protocol", default=CURRENT_G1J_NETWORK_SELECTOR_INPUT_PROTOCOL
    )
    parser.add_argument("--profile-manifest", type=Path)
    parser.add_argument("--profile-manifest-sha256", default="0" * 64)
    parser.add_argument("--profile-id", default="zero")
    parser.add_argument("--profile-sha256", default="0" * 64)
    parser.add_argument("--runtime-temp", type=Path, required=True)
    args = parser.parse_args()

    manifest = load_native_selector_decoder_manifest(
        args.decoder_manifest,
        args.decoder_sha256,
    )
    settings = NativeNetworkSelectorSettings(
        base_url=f"http://{args.host}:{args.port}",
        model=args.model_name,
        model_sha256=args.model_sha256,
        decoder_id=NATIVE_SELECTOR_DECODER_ID,
        decoder_sha256=args.decoder_sha256,
        decoder_protocol=NATIVE_SELECTOR_DECODER_PROTOCOL,
        state_profile_id=args.profile_id,
        state_profile_sha256=args.profile_sha256,
        state_profile_manifest_sha256=args.profile_manifest_sha256,
        input_protocol=args.input_protocol,
        context_tokens=model_context_tokens(args.model_artifact, args.context_tokens),
    )
    extractor_profile_settings = _extractor_state_profile_settings(
        profile_manifest=args.profile_manifest,
        profile_manifest_sha256=args.profile_manifest_sha256,
        profile_id=args.profile_id,
        profile_sha256=args.profile_sha256,
    )
    extractor = PersistentVLLMRWKVExtractor(
        LocalVLLMRWKVSettings(
            engine_root=args.engine_root,
            engine_revision=args.engine_revision,
            engine_python=args.engine_python,
            engine_source_manifest=args.engine_source_manifest,
            engine_source_manifest_sha256=args.engine_source_manifest_sha256,
            model=args.model_artifact,
            batch_size=1,
            max_tokens=settings.context_tokens,
            wkv_mode=NATIVE_SELECTOR_WKV_MODE,
            runtime_temp=args.runtime_temp,
            compatibility_sha256="0" * 64,
            **extractor_profile_settings,
        )
    )
    service = NativeNetworkSelectorService(settings, extractor, manifest)
    extractor.load()
    server = ThreadingHTTPServer((args.host, args.port), _handler(service))
    server.serve_forever()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())


__all__ = [
    "NATIVE_SELECTOR_DECODER_MANIFEST_SCHEMA",
    "NativeNetworkSelectorService",
    "NativeNetworkSelectorServiceError",
    "load_native_selector_decoder_manifest",
]
